"use client";

import { useState, useEffect } from "react";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { DataTable } from "@/components/admin/DataTable";
import { CalendarCheck, Eye, Download, XCircle, CheckCircle2, Clock, Trash2, X as XIcon, RefreshCw } from "lucide-react";
import { toast, Toaster } from "sonner";
import { motion, AnimatePresence } from "framer-motion";
import { supabase } from "@/lib/supabase";

const defaultBookings = [
  { id: "BK-1002", type: "Doctor", patient: "Sarah Jenkins", provider: "Dr. Ahmed Rahman", date: "2026-08-24", time: "10:30 AM", status: "confirmed", amount: 1500 },
  { id: "BK-1003", type: "Hospital", patient: "Michael Chang", provider: "Square Hospital", date: "2026-08-25", time: "02:00 PM", status: "pending", amount: 5000 },
  { id: "BK-1004", type: "Doctor", patient: "Elena Rostova", provider: "Dr. Salma Begum", date: "2026-08-22", time: "04:00 PM", status: "completed", amount: 1200 },
  { id: "BK-1005", type: "Diagnostic", patient: "David Chen", provider: "Popular Diagnostic", date: "2026-08-26", time: "09:00 AM", status: "cancelled", amount: 850 },
];

export default function AdminBookingsPage() {
  const [bookings, setBookings] = useState<any[]>([]);
  const [selectedBooking, setSelectedBooking] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    loadBookings();
  }, []);

  const loadBookings = async () => {
    setIsLoading(true);
    try {
      // 1. Fetch from Supabase bookings table
      const { data: sbBookings, error } = await supabase
        .from("bookings")
        .select("*")
        .order("created_at", { ascending: false });

      // 2. Fetch local storage bookings
      const str = localStorage.getItem("oxpecker_bookings");
      let localData: any[] = str ? JSON.parse(str) : [];

      for (const d of defaultBookings) {
        if (!localData.find((b: any) => b.id === d.id)) {
          localData.push(d);
        }
      }

      let merged = [...localData];
      if (sbBookings && sbBookings.length > 0) {
        for (const b of sbBookings) {
          const idx = merged.findIndex((m: any) => m.id === b.id);
          const item = {
            id: b.id,
            type: "Doctor",
            patient: b.patient_name,
            provider: b.doctor_name || "Doctor",
            date: b.booking_date,
            time: b.booking_time,
            status: b.status,
            amount: b.total_fee || b.consultation_fee || 0
          };
          if (idx >= 0) {
            merged[idx] = { ...merged[idx], ...item };
          } else {
            merged.unshift(item);
          }
        }
      }

      localStorage.setItem("oxpecker_bookings", JSON.stringify(merged));
      setBookings(merged);
    } catch (e) {
      console.warn("Could not load from Supabase:", e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStatusUpdate = async (id: string, newStatus: string) => {
    try {
      await supabase.from("bookings").update({ status: newStatus }).eq("id", id);
    } catch (e) {
      console.warn("Supabase update error:", e);
    }

    const updated = bookings.map(b => b.id === id ? { ...b, status: newStatus } : b);
    setBookings(updated);
    localStorage.setItem("oxpecker_bookings", JSON.stringify(updated));
    toast.success(`Booking ${id} status updated to ${newStatus}`);
    if (selectedBooking?.id === id) {
      setSelectedBooking({ ...selectedBooking, status: newStatus });
    }
  };

  const handleDeleteBooking = async (id: string) => {
    if (confirm("Are you sure you want to permanently delete this booking?")) {
      try {
        await supabase.from("bookings").delete().eq("id", id);
      } catch (e) {
        console.warn("Supabase delete error:", e);
      }

      const updated = bookings.filter(b => b.id !== id);
      setBookings(updated);
      localStorage.setItem("oxpecker_bookings", JSON.stringify(updated));
      setSelectedBooking(null);
      toast.success("Booking deleted permanently.");
    }
  };

  const columns = [
    {
      key: "id",
      title: "Booking ID",
      sortable: true,
      render: (item: any) => <span className="font-mono text-slate-600 font-semibold text-xs bg-slate-100 px-2 py-1 rounded">{item.id}</span>
    },
    {
      key: "patient",
      title: "Patient",
      sortable: true,
      render: (item: any) => <span className="font-bold text-slate-800 text-sm">{item.patient}</span>
    },
    {
      key: "type",
      title: "Service & Provider",
      sortable: true,
      render: (item: any) => (
        <div>
          <div className="font-semibold text-slate-800 text-xs">{item.type}</div>
          <div className="text-xs text-slate-500">{item.provider}</div>
        </div>
      )
    },
    {
      key: "date",
      title: "Schedule",
      sortable: true,
      render: (item: any) => (
        <div>
          <div className="text-xs text-slate-800 font-medium">{item.date}</div>
          <div className="text-[11px] font-mono text-slate-500">{item.time}</div>
        </div>
      )
    },
    {
      key: "amount",
      title: "Amount",
      sortable: true,
      render: (item: any) => <span className="font-mono text-emerald-600 font-bold text-sm">৳ {item.amount}</span>
    },
    {
      key: "status",
      title: "Status",
      sortable: true,
      render: (item: any) => {
        if (item.status === "confirmed") return <span className="text-[11px] font-bold px-2.5 py-1 bg-sky-50 text-sky-700 rounded-lg border border-sky-200 capitalize">Confirmed</span>;
        if (item.status === "completed") return <span className="text-[11px] font-bold px-2.5 py-1 bg-emerald-50 text-emerald-700 rounded-lg border border-emerald-200 capitalize">Completed</span>;
        if (item.status === "pending") return <span className="text-[11px] font-bold px-2.5 py-1 bg-amber-50 text-amber-700 rounded-lg border border-amber-200 capitalize">Pending</span>;
        return <span className="text-[11px] font-bold px-2.5 py-1 bg-rose-50 text-rose-700 rounded-lg border border-rose-200 capitalize">Cancelled</span>;
      }
    }
  ];

  const actionsRender = (item: any) => (
    <div className="flex justify-end gap-1">
      <button
        onClick={() => setSelectedBooking(item)}
        className="px-3 py-1.5 text-xs font-bold bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg transition-colors border border-slate-200 flex items-center gap-1.5"
      >
        <Eye size={14} /> View
      </button>
    </div>
  );

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="relative h-full flex flex-col pb-24 space-y-6">
      <Toaster position="top-center" richColors />
      <AdminPageHeader
        title="Bookings & Appointments"
        description="Monitor, approve, modify, or cancel all platform bookings and appointments in real-time."
        icon={<CalendarCheck size={24} />}
        action={
          <button
            onClick={loadBookings}
            disabled={isLoading}
            className="flex items-center gap-2 h-11 px-4 bg-white hover:bg-slate-50 border border-slate-200 text-slate-700 font-bold rounded-xl transition-all shadow-sm text-sm"
          >
            <RefreshCw size={15} className={isLoading ? "animate-spin" : ""} />
            <span>Sync DB</span>
          </button>
        }
      />

      <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
        <DataTable
          columns={columns as any}
          data={bookings}
          searchPlaceholder="Search by ID, Patient, or Provider..."
          actions={actionsRender}
        />
      </div>

      {/* Booking Details Modal */}
      <AnimatePresence>
        {selectedBooking && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="w-full max-w-lg bg-white rounded-2xl shadow-xl overflow-hidden"
            >
              <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                <div>
                  <h2 className="text-lg font-bold text-slate-900">Booking Details</h2>
                  <p className="text-xs text-slate-500 font-mono mt-0.5">{selectedBooking.id}</p>
                </div>
                <button
                  onClick={() => setSelectedBooking(null)}
                  className="text-slate-400 hover:text-slate-700 p-1.5 rounded-lg hover:bg-slate-100 transition-colors"
                >
                  <XIcon size={18} />
                </button>
              </div>

              <div className="p-6 space-y-4">
                <div className="grid grid-cols-2 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <div>
                    <div className="text-xs text-slate-500 font-medium">Patient Name</div>
                    <div className="text-sm font-bold text-slate-800">{selectedBooking.patient}</div>
                  </div>
                  <div>
                    <div className="text-xs text-slate-500 font-medium">Provider / Doctor</div>
                    <div className="text-sm font-bold text-slate-800">{selectedBooking.provider}</div>
                  </div>
                  <div>
                    <div className="text-xs text-slate-500 font-medium">Schedule</div>
                    <div className="text-sm font-bold text-slate-800">{selectedBooking.date} at {selectedBooking.time}</div>
                  </div>
                  <div>
                    <div className="text-xs text-slate-500 font-medium">Total Amount</div>
                    <div className="text-sm font-bold text-emerald-600">৳ {selectedBooking.amount}</div>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-2">Update Status</label>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                    {["pending", "confirmed", "completed", "cancelled"].map(status => (
                      <button
                        key={status}
                        onClick={() => handleStatusUpdate(selectedBooking.id, status)}
                        className={`py-2 px-3 rounded-xl text-xs font-bold capitalize transition-all border ${
                          selectedBooking.status === status
                            ? "bg-slate-900 text-white border-slate-900 shadow-sm"
                            : "bg-white text-slate-600 border-slate-200 hover:bg-slate-50"
                        }`}
                      >
                        {status}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="pt-4 border-t border-slate-100 flex gap-3">
                  <button
                    onClick={() => handleDeleteBooking(selectedBooking.id)}
                    className="h-11 px-4 bg-rose-50 hover:bg-rose-100 text-rose-600 font-bold rounded-xl transition-colors text-sm flex items-center gap-1.5"
                  >
                    <Trash2 size={16} /> Delete
                  </button>
                  <button
                    onClick={() => setSelectedBooking(null)}
                    className="flex-1 h-11 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-colors text-sm"
                  >
                    Done
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { DataTable } from "@/components/admin/DataTable";
import { Pill, Plus, Edit2, Trash2, X as XIcon, Save, Search, RefreshCw } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast, Toaster } from "sonner";

export default function AdminMedicinesPage() {
  const [medicines, setMedicines] = useState<any[]>([]);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingMedicine, setEditingMedicine] = useState<any | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [formData, setFormData] = useState({ brandName: "", genericName: "", dosageForm: "Tablet", manufacturer: "", price: "" });

  useEffect(() => {
    loadMedicines();
  }, []);

  const loadMedicines = () => {
    setIsLoading(true);
    const local = localStorage.getItem("oxpecker_custom_medicines");
    const customMeds = local ? JSON.parse(local) : [];

    fetch("/data/medicines.json")
      .then(res => res.json())
      .then(data => {
        let finalData = data;
        if (Array.isArray(data) && Array.isArray(data[0])) {
          finalData = data.flat();
        }
        const initialList = Array.isArray(finalData) ? finalData.slice(0, 250) : [];
        setMedicines([...customMeds, ...initialList]);
        setIsLoading(false);
      })
      .catch(err => {
        console.error("Error fetching medicines:", err);
        setMedicines(customMeds);
        setIsLoading(false);
      });
  };

  const handleAddMedicine = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.brandName || !formData.genericName) {
      toast.error("Brand name and Generic name are required.");
      return;
    }
    const newMed = {
      id: `med-${Date.now()}`,
      ...formData,
      price: parseFloat(formData.price) || 0,
    };

    const local = localStorage.getItem("oxpecker_custom_medicines");
    const customMeds = local ? JSON.parse(local) : [];
    customMeds.unshift(newMed);
    localStorage.setItem("oxpecker_custom_medicines", JSON.stringify(customMeds));

    setMedicines([newMed, ...medicines]);
    setIsAddModalOpen(false);
    setFormData({ brandName: "", genericName: "", dosageForm: "Tablet", manufacturer: "", price: "" });
    toast.success("Medicine added successfully.");
  };

  const handleEditMedicine = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMedicine.brandName) {
      toast.error("Brand name is required.");
      return;
    }
    const updated = medicines.map(m => m.id === editingMedicine.id ? editingMedicine : m);
    setMedicines(updated);
    setEditingMedicine(null);
    toast.success("Medicine updated successfully.");
  };

  const handleDelete = (id: string) => {
    if (confirm("Are you sure you want to delete this medicine record?")) {
      const updated = medicines.filter(m => m.id !== id);
      setMedicines(updated);

      const local = localStorage.getItem("oxpecker_custom_medicines");
      if (local) {
        const customMeds = JSON.parse(local).filter((m: any) => m.id !== id);
        localStorage.setItem("oxpecker_custom_medicines", JSON.stringify(customMeds));
      }
      toast.success("Medicine deleted.");
    }
  };

  const filteredMedicines = medicines.filter(m => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return m.brandName?.toLowerCase().includes(q) || m.genericName?.toLowerCase().includes(q) || m.manufacturer?.toLowerCase().includes(q);
  });

  const columns = [
    {
      key: "brandName",
      title: "Brand Name",
      render: (item: any) => (
        <div>
          <div className="font-bold text-slate-800 text-sm">{item.brandName || "Unknown"}</div>
          <div className="text-xs text-slate-500 font-mono">{item.genericName || "N/A"}</div>
        </div>
      )
    },
    {
      key: "dosageForm",
      title: "Dosage Form",
      render: (item: any) => (
        <span className="text-xs font-semibold px-2 py-0.5 rounded bg-slate-100 text-slate-700 border border-slate-200">
          {item.dosageForm || "Tablet"}
        </span>
      )
    },
    {
      key: "manufacturer",
      title: "Manufacturer",
      render: (item: any) => <span className="text-xs text-slate-600 line-clamp-1">{item.manufacturer || "N/A"}</span>
    },
    {
      key: "price",
      title: "Unit Price",
      render: (item: any) => <span className="font-mono text-emerald-600 font-bold text-sm">৳{item.price || "0.00"}</span>
    },
    {
      key: "actions",
      title: "",
      render: (item: any) => (
        <div className="flex items-center justify-end gap-1">
          <button
            onClick={() => setEditingMedicine(item)}
            className="p-2 text-slate-400 hover:text-sky-600 hover:bg-sky-50 rounded-lg transition-colors"
            title="Edit Medicine"
          >
            <Edit2 size={15} />
          </button>
          <button
            onClick={() => handleDelete(item.id)}
            className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
            title="Delete Medicine"
          >
            <Trash2 size={15} />
          </button>
        </div>
      )
    }
  ];

  return (
    <motion.div
      initial={{ opacity: 0, y: 15 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-6 pb-24"
    >
      <Toaster position="top-center" richColors />
      <AdminPageHeader
        title="Medicines Master Database"
        description={`Manage ${medicines.length} verified pharmaceutical records, pricing, and generic compositions.`}
        icon={<Pill size={24} />}
        action={
          <button
            onClick={() => setIsAddModalOpen(true)}
            className="flex items-center gap-2 h-11 px-4 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-all shadow-sm text-sm"
          >
            <Plus size={16} /> Add Medicine
          </button>
        }
      />

      <div className="flex justify-between items-center gap-3">
        <div className="relative flex-1 max-w-md">
          <Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Search brand, generic or manufacturer..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 h-10 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
          />
        </div>
        <button
          onClick={loadMedicines}
          disabled={isLoading}
          className="flex items-center gap-1.5 px-3.5 h-10 border border-slate-200 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-50 bg-white transition-colors"
        >
          <RefreshCw size={14} className={isLoading ? "animate-spin" : ""} />
          <span>Reload</span>
        </button>
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        {isLoading ? (
          <div className="py-20 flex flex-col items-center justify-center">
            <div className="w-8 h-8 border-3 border-slate-100 border-t-sky-600 rounded-full animate-spin"></div>
            <p className="mt-3 text-slate-500 text-xs font-medium">Loading registered medicine records...</p>
          </div>
        ) : (
          <DataTable
            columns={columns as any}
            data={filteredMedicines}
            searchPlaceholder="Search database..."
          />
        )}
      </div>

      {/* Add Modal */}
      <AnimatePresence>
        {isAddModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                <h3 className="text-lg font-bold text-slate-900">Add New Medicine</h3>
                <button onClick={() => setIsAddModalOpen(false)} className="text-slate-400 hover:text-slate-700 p-1.5 rounded-lg hover:bg-slate-100 transition-colors"><XIcon size={18} /></button>
              </div>
              <form onSubmit={handleAddMedicine} className="p-6 space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Brand Name</label>
                  <input required type="text" value={formData.brandName} onChange={e => setFormData({ ...formData, brandName: e.target.value })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900" placeholder="e.g. Napa Extra" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Generic Name</label>
                  <input required type="text" value={formData.genericName} onChange={e => setFormData({ ...formData, genericName: e.target.value })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900" placeholder="e.g. Paracetamol + Caffeine" />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1">Dosage Form</label>
                    <select value={formData.dosageForm} onChange={e => setFormData({ ...formData, dosageForm: e.target.value })} className="w-full h-11 px-3 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white">
                      {["Tablet", "Capsule", "Syrup", "Injection", "Suspension", "Eye Drop", "Ointment"].map(f => <option key={f} value={f}>{f}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1">Unit Price (৳)</label>
                    <input type="number" step="0.01" value={formData.price} onChange={e => setFormData({ ...formData, price: e.target.value })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 font-mono" placeholder="2.50" />
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Manufacturer</label>
                  <input type="text" value={formData.manufacturer} onChange={e => setFormData({ ...formData, manufacturer: e.target.value })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900" placeholder="e.g. Beximco Pharmaceuticals" />
                </div>
                <div className="pt-2 flex gap-3">
                  <button type="button" onClick={() => setIsAddModalOpen(false)} className="flex-1 h-11 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl transition-colors text-sm">Cancel</button>
                  <button type="submit" className="flex-1 h-11 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-colors text-sm">Save Medicine</button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Edit Modal */}
      <AnimatePresence>
        {editingMedicine && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                <h3 className="text-lg font-bold text-slate-900">Edit Medicine</h3>
                <button onClick={() => setEditingMedicine(null)} className="text-slate-400 hover:text-slate-700 p-1.5 rounded-lg hover:bg-slate-100 transition-colors"><XIcon size={18} /></button>
              </div>
              <form onSubmit={handleEditMedicine} className="p-6 space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Brand Name</label>
                  <input required type="text" value={editingMedicine.brandName || ""} onChange={e => setEditingMedicine({ ...editingMedicine, brandName: e.target.value })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Generic Name</label>
                  <input type="text" value={editingMedicine.genericName || ""} onChange={e => setEditingMedicine({ ...editingMedicine, genericName: e.target.value })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900" />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1">Dosage Form</label>
                    <select value={editingMedicine.dosageForm || "Tablet"} onChange={e => setEditingMedicine({ ...editingMedicine, dosageForm: e.target.value })} className="w-full h-11 px-3 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white">
                      {["Tablet", "Capsule", "Syrup", "Injection", "Suspension", "Eye Drop", "Ointment"].map(f => <option key={f} value={f}>{f}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1">Unit Price (৳)</label>
                    <input type="number" step="0.01" value={editingMedicine.price || ""} onChange={e => setEditingMedicine({ ...editingMedicine, price: parseFloat(e.target.value) || 0 })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 font-mono" />
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Manufacturer</label>
                  <input type="text" value={editingMedicine.manufacturer || ""} onChange={e => setEditingMedicine({ ...editingMedicine, manufacturer: e.target.value })} className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900" />
                </div>
                <div className="pt-2 flex gap-3">
                  <button type="button" onClick={() => setEditingMedicine(null)} className="flex-1 h-11 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl transition-colors text-sm">Cancel</button>
                  <button type="submit" className="flex-1 h-11 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-colors text-sm flex items-center justify-center gap-1.5"><Save size={15} /> Save Changes</button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { ShieldCheck, Save, Camera, Eye, EyeOff, User, Mail, Lock, Phone, KeyRound, CheckCircle2 } from "lucide-react";
import { useAuth } from "@/context/AuthContext";
import { apiGetProfile, apiUpdateProfile, compressAndResizeImage } from "@/lib/api";
import { toast, Toaster } from "sonner";
import Image from "next/image";
import { supabase } from "@/lib/supabase";

export default function SuperAdminProfilePage() {
  const { user, updateUser } = useAuth();
  const [formData, setFormData] = useState<any>({
    name: "",
    email: "",
    password: "",
    phone: "",
    title: "Supreme System Administrator"
  });
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    loadAdminProfile();
  }, []);

  const loadAdminProfile = async () => {
    setIsLoading(true);
    try {
      const res = await apiGetProfile();
      const prof = res.data.profile || {};
      setFormData({
        name: prof.name || user?.name || "Supreme Admin",
        email: prof.email || user?.email || "admin@oxpecker.equisaas-bd.com",
        password: prof.password || "supremeadmin",
        phone: prof.phone || "+880 1700-000000",
        title: "Supreme System Administrator"
      });
      if (prof.image) setImagePreview(prof.image);
      else if (user?.image) setImagePreview(user.image);
    } catch (e) {
      toast.error("Failed to load admin profile from database.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      // 99% WebP Canvas compression
      const compressedUrl = await compressAndResizeImage(file, 400, 400, 0.75);
      setImagePreview(compressedUrl);
      setFormData((prev: any) => ({ ...prev, image: compressedUrl }));
      toast.success("Profile photo compressed & updated! Click Save Changes.");
    } catch (err) {
      toast.error("Failed to process image.");
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const { data: updated, error } = await supabase
        .from("profiles")
        .update({
          name: formData.name.trim(),
          password: formData.password.trim(),
          phone: formData.phone.trim(),
          image: formData.image || imagePreview || undefined
        })
        .eq("email", formData.email)
        .select()
        .single();

      if (error) throw error;

      toast.success("Super Admin profile updated in Supabase database!");
      if (user) {
        updateUser({
          ...user,
          name: formData.name.trim(),
          image: formData.image || imagePreview || user.image
        });
      }
      loadAdminProfile();
    } catch (err: any) {
      toast.error(err.message || "Failed to update profile.");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6 pb-24">
      <Toaster position="top-center" richColors />

      <AdminPageHeader
        title="Super Admin Profile & Master Credentials"
        description="Manage your Supreme Administrator profile details, credentials, and avatar. Synchronized live with Supabase cloud database."
        icon={<ShieldCheck size={24} className="text-amber-500" />}
      />

      <div className="max-w-3xl bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm">
        {/* Banner */}
        <div className="bg-slate-900 px-8 py-10 text-white flex flex-col sm:flex-row items-center gap-6 relative">
          <div className="relative group">
            <div className="w-24 h-24 rounded-full bg-slate-800 flex items-center justify-center overflow-hidden border-2 border-white/50 shadow-lg relative">
              {imagePreview ? (
                <Image src={imagePreview} alt="Admin" fill className="object-cover" />
              ) : (
                <span className="text-3xl font-bold text-white">{(formData.name || "S").charAt(0).toUpperCase()}</span>
              )}
            </div>
            <label
              htmlFor="admin-avatar-upload"
              className="absolute inset-0 bg-black/50 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 cursor-pointer transition-opacity text-white"
              title="Change Profile Photo"
            >
              <Camera size={24} />
            </label>
            <input
              id="admin-avatar-upload"
              type="file"
              accept="image/*"
              onChange={handleImageChange}
              className="hidden"
            />
          </div>

          <div className="text-center sm:text-left">
            <h1 className="text-2xl font-extrabold flex items-center justify-center sm:justify-start gap-2">
              {formData.name}
              <ShieldCheck size={20} className="text-amber-400" />
            </h1>
            <p className="text-slate-300 text-sm mt-1 font-medium">{formData.title}</p>
            <p className="text-xs text-slate-400 mt-1 font-mono">{formData.email}</p>
          </div>
        </div>

        {/* Form */}
        <form onSubmit={handleSave} className="p-8 space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Master Administrator Name</label>
              <div className="relative">
                <User size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  required
                  value={formData.name}
                  onChange={e => setFormData({ ...formData, name: e.target.value })}
                  className="w-full h-11 pl-10 pr-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Email Address (Primary Admin)</label>
              <div className="relative">
                <Mail size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="email"
                  disabled
                  value={formData.email}
                  className="w-full h-11 pl-10 pr-4 border border-slate-100 rounded-xl text-sm bg-slate-50 text-slate-500 cursor-not-allowed"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Admin Account Password</label>
              <div className="relative">
                <Lock size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type={showPassword ? "text" : "password"}
                  required
                  value={formData.password}
                  onChange={e => setFormData({ ...formData, password: e.target.value })}
                  className="w-full h-10 pl-10 pr-10 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white font-mono"
                />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700">
                  {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Contact Phone Number</label>
              <div className="relative">
                <Phone size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  value={formData.phone}
                  onChange={e => setFormData({ ...formData, phone: e.target.value })}
                  className="w-full h-11 pl-10 pr-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
                />
              </div>
            </div>
          </div>

          <div className="p-4 bg-amber-50/70 border border-amber-200 rounded-2xl flex items-start gap-3 text-amber-800 text-xs">
            <KeyRound size={18} className="shrink-0 text-amber-600 mt-0.5" />
            <div>
              <div className="font-bold mb-0.5">God-Level Privileges Active</div>
              <div>Changes to your name, password, or avatar sync directly to Supabase cloud database. Your credentials allow full CRUD access across all platform entities.</div>
            </div>
          </div>

          <div className="pt-2 flex justify-end">
            <button
              type="submit"
              disabled={isSaving}
              className="flex items-center gap-2 px-8 h-12 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-all shadow-md text-sm disabled:opacity-70"
            >
              {isSaving ? (
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <Save size={16} />
              )}
              Save Admin Profile
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import {
  Settings, Database, RotateCcw, AlertTriangle, CheckCircle2,
  Download, Shield, Server, RefreshCw, Radio
} from "lucide-react";
import { toast, Toaster } from "sonner";
import { supabase } from "@/lib/supabase";

export default function AdminSettingsPage() {
  const [isResetting, setIsResetting] = useState(false);
  const [dbStatus, setDbStatus] = useState<"checking" | "connected" | "error">("checking");
  const [profileCount, setProfileCount] = useState<number | null>(null);

  useEffect(() => {
    checkDatabase();
  }, []);

  const checkDatabase = async () => {
    setDbStatus("checking");
    try {
      const { count, error } = await supabase
        .from("profiles")
        .select("*", { count: "exact", head: true });

      if (error) {
        setDbStatus("error");
      } else {
        setDbStatus("connected");
        setProfileCount(count ?? 0);
      }
    } catch {
      setDbStatus("error");
    }
  };

  const handleExportBackup = () => {
    const data = {
      users: JSON.parse(localStorage.getItem("oxpecker_users") || "[]"),
      bookings: JSON.parse(localStorage.getItem("oxpecker_bookings") || "[]"),
      timestamp: new Date().toISOString(),
      platform: "Oxpecker AI",
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `oxpecker-backup-${new Date().toISOString().split("T")[0]}.json`;
    a.click();
    toast.success("Database snapshot downloaded successfully.");
  };

  const handleResetDatabase = () => {
    if (!confirm("Are you sure you want to reset all local cached data? This will re-seed default accounts.")) return;
    setIsResetting(true);

    const keysToRemove = [
      "oxpecker_user",
      "oxpecker_users",
      "oxpecker_bookings",
      "oxpecker_invites",
      "oxpecker_assistants",
      "oxpecker_chat_history"
    ];

    keysToRemove.forEach(key => localStorage.removeItem(key));

    setTimeout(() => {
      setIsResetting(false);
      toast.success("Local state reset. Re-seeding defaults...");
      window.location.reload();
    }, 1200);
  };

  return (
    <div className="max-w-[1200px] mx-auto space-y-6 pb-24">
      <Toaster position="top-center" richColors />
      <AdminPageHeader
        title="System Governance & Settings"
        description="Manage database connections, security parameters, system maintenance, and cloud backups."
        icon={<Settings size={24} />}
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Live Database Status */}
        <div className="lg:col-span-3 bg-white border border-slate-200 rounded-2xl p-6 shadow-sm flex flex-col md:flex-row gap-6 items-start justify-between">
          <div className="flex items-start gap-4">
            <div className="w-12 h-12 bg-sky-50 text-sky-700 rounded-2xl flex items-center justify-center shrink-0 border border-sky-100">
              <Database size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-lg font-bold text-slate-900">Cloud PostgreSQL Database</h3>
                {dbStatus === "connected" ? (
                  <span className="inline-flex items-center gap-1 text-xs font-bold text-emerald-700 bg-emerald-50 px-2.5 py-0.5 rounded-full border border-emerald-200">
                    <CheckCircle2 size={12} /> Connected (Supabase)
                  </span>
                ) : dbStatus === "checking" ? (
                  <span className="inline-flex items-center gap-1 text-xs font-bold text-amber-700 bg-amber-50 px-2.5 py-0.5 rounded-full border border-amber-200">
                    <RefreshCw size={12} className="animate-spin" /> Checking
                  </span>
                ) : (
                  <span className="inline-flex items-center gap-1 text-xs font-bold text-slate-600 bg-slate-100 px-2.5 py-0.5 rounded-full border border-slate-200">
                    Local Storage Mode
                  </span>
                )}
              </div>
              <p className="text-slate-600 text-sm mt-1 leading-relaxed max-w-2xl">
                Active project: <code className="font-mono text-slate-800 font-bold">nisjigguleygbjcvfmbb.supabase.co</code>.
                Synchronizing user profiles, bookings, live queue tokens, and role-based permissions with automatic keep-alive heartbeat.
              </p>
              {profileCount !== null && (
                <div className="mt-3 text-xs font-semibold text-slate-500">
                  Total Synced Profiles: <span className="text-slate-900 font-bold">{profileCount}</span>
                </div>
              )}
            </div>
          </div>
          <div className="flex gap-2 shrink-0">
            <button
              onClick={checkDatabase}
              className="flex items-center gap-1.5 px-4 h-10 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 hover:bg-slate-50 transition-colors"
            >
              <RefreshCw size={14} className={dbStatus === "checking" ? "animate-spin" : ""} />
              Test Connection
            </button>
            <button
              onClick={handleExportBackup}
              className="flex items-center gap-1.5 px-4 h-10 bg-slate-900 hover:bg-slate-800 text-white rounded-xl text-xs font-bold transition-all shadow-sm"
            >
              <Download size={14} />
              Export Snapshot
            </button>
          </div>
        </div>

        {/* System Policies */}
        <div className="lg:col-span-2 bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
          <h3 className="text-base font-bold text-slate-900 mb-4 flex items-center gap-2">
            <Shield size={18} className="text-sky-700" />
            Security & Registration Controls
          </h3>
          <div className="space-y-4 divide-y divide-slate-100">
            <div className="pt-2 flex items-center justify-between">
              <div>
                <h4 className="font-bold text-sm text-slate-800">Public Patient Registration</h4>
                <p className="text-xs text-slate-500 mt-0.5">Allow public patients to create accounts via portal.</p>
              </div>
              <span className="text-xs font-bold text-emerald-700 bg-emerald-50 px-2.5 py-1 rounded-lg border border-emerald-200">
                Enabled
              </span>
            </div>

            <div className="pt-4 flex items-center justify-between">
              <div>
                <h4 className="font-bold text-sm text-slate-800">Doctor Verification Requirement</h4>
                <p className="text-xs text-slate-500 mt-0.5">Require BMDC verification before doctor profile listing.</p>
              </div>
              <span className="text-xs font-bold text-sky-700 bg-sky-50 px-2.5 py-1 rounded-lg border border-sky-200">
                Active
              </span>
            </div>

            <div className="pt-4 flex items-center justify-between">
              <div>
                <h4 className="font-bold text-sm text-slate-800">Emergency Red Flag Filter</h4>
                <p className="text-xs text-slate-500 mt-0.5">Rule-based clinical intercept for critical patient symptoms.</p>
              </div>
              <span className="text-xs font-bold text-emerald-700 bg-emerald-50 px-2.5 py-1 rounded-lg border border-emerald-200">
                Enforced
              </span>
            </div>

            <div className="pt-4 flex items-center justify-between">
              <div>
                <h4 className="font-bold text-sm text-slate-800">Automated Supabase Keep-Alive Cron</h4>
                <p className="text-xs text-slate-500 mt-0.5">Scheduled GitHub Actions ping every 3 days.</p>
              </div>
              <span className="text-xs font-bold text-emerald-700 bg-emerald-50 px-2.5 py-1 rounded-lg border border-emerald-200">
                Running
              </span>
            </div>
          </div>
        </div>

        {/* Danger Zone */}
        <div className="lg:col-span-1 bg-white border border-slate-200 rounded-2xl p-6 shadow-sm flex flex-col justify-between">
          <div>
            <h3 className="text-base font-bold text-slate-900 mb-2 flex items-center gap-2">
              <AlertTriangle className="text-rose-600" size={18} />
              Maintenance & Reset
            </h3>
            <p className="text-slate-500 text-xs leading-relaxed mb-6">
              Factory reset will flush the local storage caches and re-seed default admin, doctor, hospital, and assistant credentials.
            </p>
          </div>
          <button
            onClick={handleResetDatabase}
            disabled={isResetting}
            className="w-full h-11 bg-rose-50 hover:bg-rose-600 text-rose-700 hover:text-white rounded-xl text-xs font-bold transition-colors flex items-center justify-center gap-2 border border-rose-200 hover:border-transparent"
          >
            <RotateCcw size={15} className={isResetting ? "animate-spin" : ""} />
            {isResetting ? "Resetting State..." : "Reset Local Cache"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import {
  Users, UserPlus, Edit2, Ban, ShieldAlert, CheckCircle2, Trash2,
  X as XIcon, Eye, EyeOff, Save, RefreshCw, Search, ShieldCheck, AlertCircle
} from "lucide-react";
import { toast, Toaster } from "sonner";
import { motion, AnimatePresence } from "framer-motion";
import { supabase } from "@/lib/supabase";

const ROLE_COLORS: Record<string, string> = {
  admin: "bg-amber-50 text-amber-700 border-amber-200",
  doctor: "bg-sky-50 text-sky-700 border-sky-200",
  patient: "bg-emerald-50 text-emerald-700 border-emerald-200",
  hospital: "bg-purple-50 text-purple-700 border-purple-200",
  assistant: "bg-rose-50 text-rose-700 border-rose-200",
};

export default function AdminUsersPage() {
  const [users, setUsers] = useState<any[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState<"all" | "patient" | "doctor" | "hospital" | "assistant" | "admin">("all");
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingUser, setEditingUser] = useState<any | null>(null);
  const [showPasswords, setShowPasswords] = useState<Record<string, boolean>>({});
  const [formData, setFormData] = useState({ name: "", email: "", password: "", role: "patient", status: "active" });
  const [editForm, setEditForm] = useState({ name: "", email: "", password: "", role: "patient", status: "active" });
  const [isLoading, setIsLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = async () => {
    setIsLoading(true);
    setDbError(null);
    try {
      // 1. Fetch directly from Supabase database
      const { data, error } = await supabase
        .from("profiles")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) {
        throw error;
      }

      const formattedUsers = (data || []).map((p: any) => ({
        id: p.id,
        name: p.name || "User",
        email: p.email,
        role: p.role || "patient",
        status: p.status || "active",
        password: p.password || "••••••••",
        joinDate: p.join_date || (p.created_at ? p.created_at.split("T")[0] : new Date().toISOString().split("T")[0]),
        phone: p.phone,
        doctorId: p.doctor_id,
        assistantId: p.assistant_id
      }));

      setUsers(formattedUsers);
      // Cache locally for offline resilience
      localStorage.setItem("oxpecker_synced_users", JSON.stringify(formattedUsers));
    } catch (err: any) {
      console.error("Supabase load error:", err);
      setDbError(err.message || "Failed to load profiles from Supabase. Please ensure supabase_schema.sql has been executed in SQL editor.");
      // Fallback to locally cached sync if network offline
      const cached = localStorage.getItem("oxpecker_synced_users");
      if (cached) {
        try { setUsers(JSON.parse(cached)); } catch {}
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.password) {
      toast.error("All fields are required.");
      return;
    }

    try {
      const { data, error } = await supabase
        .from("profiles")
        .insert([{
          name: formData.name.trim(),
          email: formData.email.toLowerCase().trim(),
          password: formData.password.trim(),
          role: formData.role,
          status: formData.status,
          join_date: new Date().toISOString().split("T")[0]
        }])
        .select()
        .single();

      if (error) throw error;

      toast.success("User created successfully in database.");
      setShowAddModal(false);
      setFormData({ name: "", email: "", password: "", role: "patient", status: "active" });
      loadUsers();
    } catch (err: any) {
      toast.error(err.message || "Failed to create user in database.");
    }
  };

  const openEdit = (user: any) => {
    setEditingUser(user);
    setEditForm({
      name: user.name,
      email: user.email,
      password: user.password || "",
      role: user.role,
      status: user.status || "active"
    });
  };

  const handleSaveEdit = async () => {
    if (!editForm.name || !editForm.email) {
      toast.error("Name and email are required.");
      return;
    }

    try {
      const { error } = await supabase
        .from("profiles")
        .update({
          name: editForm.name.trim(),
          email: editForm.email.toLowerCase().trim(),
          password: editForm.password.trim(),
          role: editForm.role,
          status: editForm.status
        })
        .eq("id", editingUser.id);

      if (error) throw error;

      toast.success("User updated successfully.");
      setEditingUser(null);
      loadUsers();
    } catch (err: any) {
      toast.error(err.message || "Failed to update user.");
    }
  };

  const handleDeleteUser = async (user: any) => {
    if (user.role === "admin" && users.filter(u => u.role === "admin").length <= 1) {
      toast.error("Cannot delete the only admin account.");
      return;
    }

    if (confirm(`Permanently delete user ${user.name} (${user.email})? This cannot be undone.`)) {
      try {
        const { error } = await supabase
          .from("profiles")
          .delete()
          .eq("id", user.id);

        if (error) throw error;

        toast.success("User permanently deleted from database.");
        loadUsers();
      } catch (err: any) {
        toast.error(err.message || "Failed to delete user.");
      }
    }
  };

  const handleStatusChange = async (userId: string, newStatus: string) => {
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ status: newStatus })
        .eq("id", userId);

      if (error) throw error;

      toast.success(`Status updated to ${newStatus}.`);
      loadUsers();
    } catch (err: any) {
      toast.error(err.message || "Failed to update status.");
    }
  };

  const togglePassword = (id: string) => setShowPasswords(prev => ({ ...prev, [id]: !prev[id] }));

  const filteredUsers = users
    .filter(u => activeTab === "all" || u.role === activeTab)
    .filter(u => {
      if (!searchQuery) return true;
      const q = searchQuery.toLowerCase();
      return u.name?.toLowerCase().includes(q) || u.email?.toLowerCase().includes(q) || u.id?.toLowerCase().includes(q);
    });

  return (
    <div className="space-y-6 pb-24">
      <Toaster position="top-center" richColors />

      <AdminPageHeader
        title="Supreme User Governance"
        description="Live cloud database records: inspect credentials, edit profiles, alter roles, ban, or hard delete users in real time."
        icon={<Users size={24} />}
        action={
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 h-11 px-5 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-all shadow-sm text-sm"
          >
            <UserPlus size={16} /> Add User
          </button>
        }
      />

      {dbError && (
        <div className="p-4 bg-amber-50 border border-amber-200 rounded-2xl flex items-start gap-3 text-amber-800 text-xs">
          <AlertCircle size={18} className="shrink-0 text-amber-600 mt-0.5" />
          <div>
            <div className="font-bold mb-0.5">Database Notice</div>
            <div>{dbError}</div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row gap-3 items-stretch sm:items-center justify-between">
        <div className="flex gap-2 overflow-x-auto pb-1 [&::-webkit-scrollbar]:hidden flex-1">
          {(["all", "admin", "patient", "doctor", "hospital", "assistant"] as const).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap transition-colors shrink-0 ${
                activeTab === tab
                  ? "bg-slate-900 text-white shadow-sm"
                  : "bg-white text-slate-600 hover:bg-slate-50 border border-slate-200"
              }`}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)} ({tab === "all" ? users.length : users.filter(u => u.role === tab).length})
            </button>
          ))}
        </div>
        
        <div className="flex items-center gap-2">
          <div className="relative flex-1 sm:w-64">
            <Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Search name, email or ID..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-4 h-10 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
            />
          </div>
          <button
            onClick={loadUsers}
            disabled={isLoading}
            className="flex items-center gap-1.5 px-3 h-10 border border-slate-200 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-50 bg-white transition-colors shrink-0"
            title="Reload from Cloud Database"
          >
            <RefreshCw size={14} className={isLoading ? "animate-spin" : ""} />
            <span className="hidden sm:inline">Sync DB</span>
          </button>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                {["User", "Database ID", "Password", "Role", "Status", "Joined", "Actions"].map((h, i) => (
                  <th key={i} className="text-left px-5 py-3.5 text-xs font-bold text-slate-500 uppercase tracking-wider">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredUsers.length === 0 ? (
                <tr>
                  <td colSpan={7} className="py-16 text-center text-slate-400 text-sm">
                    {isLoading ? "Loading users directly from Supabase database..." : "No users found in database."}
                  </td>
                </tr>
              ) : filteredUsers.map(user => (
                <tr key={user.id} className="hover:bg-slate-50/70 transition-colors">
                  <td className="px-5 py-3.5">
                    <div className="flex items-center gap-3">
                      <div className="w-9 h-9 rounded-full bg-slate-100 border border-slate-200 flex items-center justify-center shrink-0">
                        <span className="text-slate-700 font-bold text-xs">{(user.name || "?").charAt(0).toUpperCase()}</span>
                      </div>
                      <div>
                        <p className="font-bold text-slate-800 text-[13px] leading-tight flex items-center gap-1.5">
                          {user.name}
                          {user.role === "admin" && <ShieldCheck size={13} className="text-amber-500" />}
                        </p>
                        <p className="text-[11px] text-slate-500 mt-0.5">{user.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-5 py-3.5">
                    <code className="text-[11px] text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-mono select-all">{user.id}</code>
                  </td>
                  <td className="px-5 py-3.5">
                    <div className="flex items-center gap-2">
                      <code className="text-[12px] text-slate-700 font-mono select-all">
                        {showPasswords[user.id] ? (user.password || "—") : "••••••••"}
                      </code>
                      <button onClick={() => togglePassword(user.id)} className="text-slate-400 hover:text-slate-700 transition-colors p-1">
                        {showPasswords[user.id] ? <EyeOff size={14} /> : <Eye size={14} />}
                      </button>
                    </div>
                  </td>
                  <td className="px-5 py-3.5">
                    <span className={`text-[11px] font-bold px-2.5 py-1 rounded-lg border capitalize ${ROLE_COLORS[user.role] || "bg-slate-50 text-slate-600 border-slate-200"}`}>
                      {user.role}
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    {user.status === "active" ? (
                      <span className="inline-flex items-center gap-1 text-xs font-bold text-emerald-600">
                        <CheckCircle2 size={13} /> Active
                      </span>
                    ) : user.status === "pending" ? (
                      <span className="inline-flex items-center gap-1 text-xs font-bold text-amber-600">
                        <ShieldAlert size={13} /> Pending
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-1 text-xs font-bold text-rose-600">
                        <Ban size={13} /> Banned
                      </span>
                    )}
                  </td>
                  <td className="px-5 py-3.5 text-[12px] text-slate-500">{user.joinDate || "—"}</td>
                  <td className="px-5 py-3.5">
                    <div className="flex items-center justify-end gap-1">
                      <button
                        onClick={() => openEdit(user)}
                        className="p-2 text-slate-400 hover:text-sky-600 hover:bg-sky-50 rounded-lg transition-colors"
                        title="Edit User"
                      >
                        <Edit2 size={15} />
                      </button>
                      {user.status === "banned" ? (
                        <button
                          onClick={() => handleStatusChange(user.id, "active")}
                          className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"
                          title="Unban"
                        >
                          <CheckCircle2 size={15} />
                        </button>
                      ) : (
                        <button
                          onClick={() => handleStatusChange(user.id, "banned")}
                          className="p-2 text-slate-400 hover:text-amber-600 hover:bg-amber-50 rounded-lg transition-colors"
                          title="Ban"
                        >
                          <Ban size={15} />
                        </button>
                      )}
                      <button
                        onClick={() => handleDeleteUser(user)}
                        className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                        title="Hard Delete"
                      >
                        <Trash2 size={15} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Edit Modal */}
      <AnimatePresence>
        {editingUser && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                <div>
                  <h2 className="text-lg font-bold text-slate-800">Edit User Account</h2>
                  <p className="text-xs text-slate-500 mt-0.5 font-mono">{editingUser.id}</p>
                </div>
                <button onClick={() => setEditingUser(null)} className="text-slate-400 hover:text-slate-700 p-1.5 rounded-lg hover:bg-slate-100 transition-colors">
                  <XIcon size={18} />
                </button>
              </div>
              <div className="p-6 space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Full Name</label>
                  <input
                    type="text"
                    value={editForm.name}
                    onChange={e => setEditForm({ ...editForm, name: e.target.value })}
                    className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Email Address</label>
                  <input
                    type="email"
                    value={editForm.email}
                    onChange={e => setEditForm({ ...editForm, email: e.target.value })}
                    className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Password</label>
                  <input
                    type="text"
                    value={editForm.password}
                    onChange={e => setEditForm({ ...editForm, password: e.target.value })}
                    className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white font-mono"
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1.5">Role</label>
                    <select
                      value={editForm.role}
                      onChange={e => setEditForm({ ...editForm, role: e.target.value })}
                      className="w-full h-11 px-3 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white capitalize"
                    >
                      {["patient", "doctor", "hospital", "assistant", "admin"].map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1.5">Status</label>
                    <select
                      value={editForm.status}
                      onChange={e => setEditForm({ ...editForm, status: e.target.value })}
                      className="w-full h-11 px-3 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white capitalize"
                    >
                      {["active", "pending", "banned"].map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                </div>
                <div className="pt-2 flex gap-3">
                  <button onClick={() => setEditingUser(null)} className="flex-1 h-11 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl transition-colors text-sm">
                    Cancel
                  </button>
                  <button onClick={handleSaveEdit} className="flex-1 h-11 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-colors shadow-md text-sm flex items-center justify-center gap-2">
                    <Save size={15} /> Save Changes
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Add Modal */}
      <AnimatePresence>
        {showAddModal && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                <h2 className="text-lg font-bold text-slate-800">Add New User to Database</h2>
                <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-slate-700 p-1.5 rounded-lg hover:bg-slate-100 transition-colors">
                  <XIcon size={18} />
                </button>
              </div>
              <form onSubmit={handleAddUser} className="p-6 space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Full Name</label>
                  <input
                    type="text"
                    required
                    value={formData.name}
                    onChange={e => setFormData({ ...formData, name: e.target.value })}
                    className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
                    placeholder="e.g. Dr. Kamal Hossain"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Email Address</label>
                  <input
                    type="email"
                    required
                    value={formData.email}
                    onChange={e => setFormData({ ...formData, email: e.target.value })}
                    className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white"
                    placeholder="e.g. kamal@example.com"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Password</label>
                  <input
                    type="text"
                    required
                    value={formData.password}
                    onChange={e => setFormData({ ...formData, password: e.target.value })}
                    className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white font-mono"
                    placeholder="Create user password"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1.5">Role</label>
                  <select
                    value={formData.role}
                    onChange={e => setFormData({ ...formData, role: e.target.value })}
                    className="w-full h-11 px-4 border border-slate-200 rounded-xl text-sm outline-none focus:border-slate-900 bg-white capitalize"
                  >
                    {["patient", "doctor", "hospital", "assistant", "admin"].map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="pt-2 flex gap-3">
                  <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 h-11 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl transition-colors text-sm">
                    Cancel
                  </button>
                  <button type="submit" className="flex-1 h-11 bg-slate-900 hover:bg-slate-800 text-white font-bold rounded-xl transition-colors shadow-md text-sm flex items-center justify-center gap-2">
                    <UserPlus size={15} /> Create User
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { AppointmentPass } from "@/components/appointments/AppointmentPass";
import { CalendarRange, Stethoscope, Calendar, Clock, MapPin, Video, Navigation, Activity, History, CheckCircle2, XCircle, ArrowRight, Users, AlertTriangle, FileText } from "lucide-react";
import { motion, AnimatePresence } from 'framer-motion';
import Image from 'next/image';
import ReportsPage from "../reports/page";

const mockDoctorAppointments = [
  {
    type: "doctor" as const,
    id: "AP-8942-01",
    doctorName: "Dr. Farzana Alam",
    doctorImage: "https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=300&h=300&fit=crop",
    specialty: "Gynecologist",
    hospitalName: "Labaid Specialized Hospital",
    hospitalLogo: "/images/Oxpecker_icon.png",
    address: "House 6, Road 4, Dhanmondi, Dhaka",
    date: "24 Nov, 2026",
    time: "10:30 AM",
    patientName: "Patient Profile",
    age: "28",
    guardianName: "Md. Hasan",
    phone: "017XXXXXXXX",
    fee: 1050,
    advancePaid: 0,
    status: "Confirmed" as const
  }
];

const mockHistoryAppointments = [
  { id: "AP-8120", doctor: "Dr. Ahmed Hossain", specialty: "Cardiologist", date: "15 Oct, 2026", time: "05:00 PM", status: "Completed", fee: 1200 },
  { id: "AP-7052", doctor: "Dr. Salma Begum", specialty: "Dermatologist", date: "02 Sep, 2026", time: "11:30 AM", status: "Cancelled", fee: 800 },
  { id: "AP-6401", doctor: "Dr. Farzana Alam", specialty: "Gynecologist", date: "10 Aug, 2026", time: "10:00 AM", status: "Completed", fee: 1000 },
];

export default function AppointmentsPage() {
  const [activeTab, setActiveTab] = useState<"tracker" | "passes" | "history" | "reports">("tracker");
  const [timer, setTimer] = useState(1543);
  
  // Dynamic Queue Simulation
  const [peopleAhead, setPeopleAhead] = useState(3);

  useEffect(() => {
    const interval = setInterval(() => {
      setTimer(prev => prev + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Simulate queue moving every 10 seconds for demo
  useEffect(() => {
    if (peopleAhead > 0) {
      const sim = setTimeout(() => setPeopleAhead(prev => prev - 1), 10000);
      return () => clearTimeout(sim);
    }
  }, [peopleAhead]);

  const formatDuration = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return h > 0 ? `${h}:${m}:${s}` : `${m}:${s}`;
  };

  const isNext = peopleAhead === 1;
  const isNow = peopleAhead === 0;

  // Dynamic Styles
  let tokenTheme = "bg-[#00C2A8]/5 border-[#00C2A8]/20";
  let tokenText = "text-[#00C2A8]";
  let mainText = "text-slate-900";
  let iconTheme = "text-slate-400";
  let message = `Doctor is seeing S-${String(14 - peopleAhead).padStart(2, '0')}`;
  let highlightBg = "bg-[#00C2A8]/10";
  let badgeTheme = "bg-[#00C2A8]/10 text-[#00C2A8]";

  if (isNext) {
     tokenTheme = "bg-amber-50 border-amber-300 shadow-[0_0_40px_rgba(245,158,11,0.15)] ring-4 ring-amber-500/10";
     tokenText = "text-amber-500";
     mainText = "text-amber-800";
     iconTheme = "text-amber-500 animate-pulse";
     message = "You are next! Please get ready.";
     highlightBg = "bg-amber-400/20";
     badgeTheme = "bg-amber-100 text-amber-700 border border-amber-200 shadow-sm";
  } else if (isNow) {
     tokenTheme = "bg-emerald-50 border-emerald-400 shadow-[0_0_50px_rgba(16,185,129,0.2)] ring-4 ring-emerald-500/20";
     tokenText = "text-emerald-500";
     mainText = "text-emerald-800";
     iconTheme = "text-emerald-500";
     message = "It's your turn! Please enter.";
     highlightBg = "bg-emerald-400/30";
     badgeTheme = "bg-emerald-500 text-white shadow-md animate-pulse";
  }

  return (
    <div className="h-full overflow-y-auto bg-[#F7FAFC] font-sans pb-32">
      
      {/* =========================================
          HEADER & PREMIUM NAVBAR
         ========================================= */}
      <div className="sticky top-0 z-40 bg-white/90 backdrop-blur-2xl border-b border-slate-200/60 px-4 md:px-8 py-4 print:hidden shadow-sm">
        <div className="w-full max-w-[1200px] mx-auto flex flex-col md:flex-row items-center justify-center relative gap-4">
          <h1 className="font-[900] text-[20px] md:text-[24px] text-slate-900 flex items-center gap-2 md:absolute left-0 tracking-tight">
            <CalendarRange size={24} className="text-[#00C2A8]" />
            Appointments
          </h1>
          
          {/* iOS Style Segmented Control */}
          <div className="w-full md:w-[640px] bg-slate-100/80 p-1.5 rounded-[16px] grid grid-cols-4 gap-1 relative shadow-inner border border-slate-200/50">
            {["tracker", "passes", "history", "reports"].map((tab) => {
              const Icon = tab === 'tracker' ? Activity : tab === 'passes' ? Stethoscope : tab === 'history' ? History : FileText;
              const label = tab === 'tracker' ? 'Tracker' : tab === 'passes' ? 'Passes' : tab === 'history' ? 'History' : 'Reports';
              
              return (
                 <button 
                   key={tab}
                   onClick={() => setActiveTab(tab as any)}
                   className={`relative z-10 flex flex-col md:flex-row items-center justify-center gap-1 md:gap-2 h-[52px] md:h-[44px] rounded-xl text-[12px] md:text-[14px] font-[800] transition-colors ${activeTab === tab ? 'text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}
                 >
                   {activeTab === tab && (
                     <motion.div layoutId="activeNavTab" className="absolute inset-0 bg-white rounded-[12px] shadow-[0_2px_10px_rgba(0,0,0,0.08)] -z-10" />
                   )}
                   <Icon size={18} className={activeTab === tab ? 'text-[#00C2A8]' : ''} />
                   <span>{label}</span>
                 </button>
              );
            })}
          </div>
        </div>
      </div>

      <div className={`max-w-[1200px] mx-auto ${activeTab !== "reports" ? "p-4 md:p-8" : ""}`}>
        
        {/* =========================================
            LIVE TRACKER TAB
           ========================================= */}
        {activeTab === "tracker" && (
           <div className="w-full flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
             
             <div className="w-full min-h-[400px] bg-white rounded-[32px] shadow-[0_20px_60px_rgba(0,0,0,0.04)] border border-slate-100 p-5 md:p-8 flex flex-col gap-8">
               
               {/* Top Section: Doctor & Location */}
               <div className="flex flex-col md:flex-row justify-between gap-4 border-b border-slate-100 pb-6">
                 <div className="flex items-center gap-5">
                   <div className="w-[72px] h-[72px] rounded-[20px] overflow-hidden shadow-md border border-slate-100 relative shrink-0">
                      <Image src={mockDoctorAppointments[0].doctorImage} alt="Doctor" fill className="object-cover" />
                   </div>
                   <div>
                     <h2 className="text-[24px] font-[900] text-slate-900 leading-tight tracking-tight">
                       {mockDoctorAppointments[0].doctorName}
                     </h2>
                     <p className="text-[15px] font-medium text-slate-500 mt-1 flex items-center gap-1.5">
                       <MapPin size={16} className="text-[#00C2A8]" /> {mockDoctorAppointments[0].hospitalName}
                     </p>
                   </div>
                 </div>
                 <div className="flex items-center gap-3 md:justify-end">
                    <button className="h-[48px] px-6 rounded-xl bg-[#00C2A8]/10 text-[#00C2A8] font-[800] text-[15px] hover:bg-[#00C2A8]/20 transition-colors flex items-center gap-2">
                      <Video size={18} /> Video Call
                    </button>
                 </div>
               </div>
               
               {/* Middle Section: Timing & Status Grid */}
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="h-[88px]  from-emerald-500/10 to-emerald-500/5 rounded-[24px] border border-emerald-500/20 flex flex-col justify-center px-6 relative overflow-hidden group">
                   <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 rounded-full blur-2xl group-hover:scale-150 transition-transform duration-700"></div>
                   <span className="text-[12px] font-[800] text-emerald-600 uppercase tracking-widest mb-1 flex items-center gap-2">
                     <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.6)]"></span>
                     LIVE STATUS
                   </span>
                   <span className="text-[18px] font-[900] text-emerald-700">Consultation Running</span>
                 </div>
                 
                 <div className="h-[88px] bg-slate-900 rounded-[24px] shadow-inner flex flex-col justify-center items-center relative overflow-hidden">
                   <div className="absolute inset-0 opacity-20 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))]    blur-xl"></div>
                   <span className="text-[11px] font-[800] text-slate-400 uppercase tracking-widest mb-0.5 relative z-10 flex items-center gap-1.5"><Clock size={12} /> ELAPSED TIME</span>
                   <span className="text-[32px] font-mono font-[900] text-emerald-400 leading-none relative z-10 tracking-tighter drop-shadow-[0_0_12px_rgba(52,211,153,0.4)]">
                     {formatDuration(timer)}
                   </span>
                 </div>
               </div>

               {/* Bottom Section: Dynamic Serial Ticket */}
               <motion.div 
                 layout
                 className={`mt-2 flex flex-col md:flex-row rounded-[32px] relative overflow-hidden transition-all duration-500 border ${tokenTheme}`}
               >
                 
                 {/* Left Side: Token */}
                 <div className="flex-[2] p-6 md:p-8 flex flex-col relative z-10">
                   <div className={`absolute -right-20 -bottom-20 w-64 h-64 rounded-full blur-3xl pointer-events-none transition-colors duration-500 ${highlightBg}`}></div>
                   
                   {/* Date & Time Header */}
                   <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 sm:gap-4 mb-6 pb-4 border-b border-slate-900/10 relative z-10">
                     <div className={`flex items-center gap-4 text-[14px] font-[800] ${mainText}`}>
                       <span className="flex items-center gap-1.5"><Calendar size={16} /> {mockDoctorAppointments[0].date}</span>
                       <span className="w-1.5 h-1.5 rounded-full bg-slate-900/20"></span>
                       <span className="flex items-center gap-1.5"><Clock size={16} /> {mockDoctorAppointments[0].time}</span>
                     </div>
                     <span className={`text-[12px] font-[800] uppercase tracking-widest ${isNow ? 'text-emerald-500' : isNext ? 'text-amber-500' : 'text-slate-400'}`}>Appointment Schedule</span>
                   </div>

                   {/* Token Details */}
                   <div className="flex flex-col md:flex-row items-center justify-between w-full relative z-10">
                     <div className="flex flex-col items-center md:items-start">
                       <span className={`text-[13px] font-[900] uppercase tracking-widest mb-2 px-3 py-1 rounded-full transition-colors duration-500 ${badgeTheme}`}>
                         Your Token
                       </span>
                       <div className={`text-[72px] font-[900] leading-none tracking-tighter transition-colors duration-500 drop-shadow-sm ${tokenText}`}>
                         S-14
                       </div>
                     </div>
                   
                   <div className="mt-6 md:mt-0 text-center md:text-right flex flex-col gap-2 relative z-10">
                     <div className={`flex items-center justify-center md:justify-end gap-2 font-[900] text-[24px] transition-colors duration-500 ${isNow ? 'text-emerald-600' : 'text-amber-500'}`}>
                       {isNow ? (
                         <><CheckCircle2 size={24} className="animate-bounce" /> Your Turn!</>
                       ) : isNext ? (
                         <><AlertTriangle size={24} className="animate-pulse" /> 1 Ahead</>
                       ) : (
                         <><Users size={24} /> {peopleAhead} Ahead</>
                       )}
                     </div>
                     <span className={`text-[16px] font-[700] transition-colors duration-500 ${mainText}`}>{message}</span>
                   </div>
                 </div>
               </div>

                 {/* Ticket Perforation / Divider (Desktop) */}
                 <div className="hidden md:flex flex-col justify-between items-center w-8 relative z-20">
                    <div className="w-8 h-8 rounded-full bg-white absolute -top-4 border-b border-slate-200/50 shadow-[inset_0_-2px_4px_rgba(0,0,0,0.02)]" />
                    <div className="h-full border-l-[4px] border-dashed border-black/10 my-8" />
                    <div className="w-8 h-8 rounded-full bg-white absolute -bottom-4 border-t border-slate-200/50 shadow-[inset_0_2px_4px_rgba(0,0,0,0.02)]" />
                 </div>

                 {/* Ticket Perforation / Divider (Mobile) */}
                 <div className="md:hidden flex w-full justify-between items-center h-8 relative z-20">
                    <div className="w-8 h-8 rounded-full bg-white absolute -left-4 border-r border-slate-200/50 shadow-[inset_-2px_0_4px_rgba(0,0,0,0.02)]" />
                    <div className="w-full border-t-[4px] border-dashed border-black/10 mx-8" />
                    <div className="w-8 h-8 rounded-full bg-white absolute -right-4 border-l border-slate-200/50 shadow-[inset_2px_0_4px_rgba(0,0,0,0.02)]" />
                 </div>

                 {/* Right Side: Wait Time */}
                 <div className="flex-1 bg-white/30 backdrop-blur-sm p-6 md:p-8 flex flex-col items-center justify-center text-center relative z-10">
                   <Clock size={28} className={`mb-3 transition-colors duration-500 ${iconTheme}`} />
                   <span className={`text-[32px] font-[900] leading-none mb-2 tracking-tight transition-colors duration-500 ${mainText}`}>
                     {isNow ? "0 Min" : isNext ? "~5 Min" : `~${peopleAhead * 15} Min`}
                   </span>
                   <span className={`text-[12px] font-[800] uppercase tracking-widest transition-colors duration-500 ${isNow ? 'text-emerald-500/80' : isNext ? 'text-amber-500/80' : 'text-slate-400'}`}>Est. Wait Time</span>
                 </div>
               </motion.div>

             </div>
           </div>
        )}

        {/* =========================================
            PASSES & MEMOS TAB
           ========================================= */}
        {activeTab === "passes" && (
          <div className="max-w-[700px] mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="mb-8 text-center bg-blue-50/80 p-5 rounded-[20px] border border-blue-100 flex items-center justify-center gap-3 print:hidden shadow-sm">
              <Activity className="text-blue-500" size={24} />
              <p className="text-blue-800 text-[16px] font-bold">
                Show this Digital Memo at the hospital reception to confirm your arrival.
              </p>
            </div>
            {mockDoctorAppointments.map((appointment) => (
              <AppointmentPass key={appointment.id} data={appointment} />
            ))}
          </div>
        )}

        {/* =========================================
            HISTORY TAB
           ========================================= */}
        {activeTab === "history" && (
          <div className="w-full max-w-[800px] mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h2 className="text-[24px] font-[900] text-slate-900 mb-8 flex items-center gap-2">
              <History className="text-[#00C2A8]" /> Past Appointments
            </h2>
            
            <div className="flex flex-col gap-4">
              {mockHistoryAppointments.map((apt, idx) => (
                <div key={idx} className="bg-white border border-slate-200/80 rounded-[24px] p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-5 hover:shadow-[0_10px_30px_rgba(0,0,0,0.04)] hover:border-slate-300 transition-all cursor-pointer group">
                  
                  <div className="flex items-center gap-5">
                    {/* Date Bubble */}
                    <div className="w-[72px] h-[72px] rounded-[20px] bg-slate-50 border border-slate-100 flex flex-col items-center justify-center shrink-0 group-hover:bg-sky-600/5 group-hover:border-primary/20 transition-colors">
                      <span className="text-[24px] font-[900] text-slate-800 leading-none group-hover:text-sky-600 transition-colors">{apt.date.split(' ')[0]}</span>
                      <span className="text-[12px] font-[800] text-slate-500 uppercase mt-1 tracking-wider">{apt.date.split(' ')[1].replace(',', '')}</span>
                    </div>
                    
                    {/* Info */}
                    <div>
                      <h3 className="text-[20px] font-[900] text-slate-900 group-hover:text-[#00C2A8] transition-colors tracking-tight">{apt.doctor}</h3>
                      <p className="text-[15px] font-medium text-slate-500">{apt.specialty}</p>
                      <p className="text-[14px] text-slate-400 mt-1.5 font-bold flex items-center gap-1.5"><Clock size={14}/> {apt.time} • ৳{apt.fee}</p>
                    </div>
                  </div>

                  {/* Status & Action */}
                  <div className="flex items-center justify-between w-full sm:w-auto sm:flex-col sm:items-end gap-3 mt-2 sm:mt-0 pt-4 sm:pt-0 border-t sm:border-0 border-slate-100">
                    {apt.status === "Completed" ? (
                      <span className="flex items-center gap-1.5 px-4 py-1.5 bg-emerald-50 text-emerald-600 text-[14px] font-[800] rounded-full border border-emerald-100">
                        <CheckCircle2 size={16} /> Completed
                      </span>
                    ) : (
                      <span className="flex items-center gap-1.5 px-4 py-1.5 bg-red-50 text-red-500 text-[14px] font-[800] rounded-full border border-red-100">
                        <XCircle size={16} /> Cancelled
                      </span>
                    )}
                    <button className="text-[15px] font-[800] text-[#00C2A8] flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all -translate-x-4 group-hover:translate-x-0">
                      View Details <ArrowRight size={18} />
                    </button>
                  </div>

                </div>
              ))}
            </div>
            
            <div className="mt-10 text-center">
              <button className="px-8 py-3.5 bg-white border-2 border-slate-200 text-slate-700 font-[800] text-[15px] rounded-2xl hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm">
                Load More History
              </button>
            </div>
          </div>
        )}
      </div>

      {/* =========================================
          REPORTS TAB (Edge to Edge)
         ========================================= */}
      {activeTab === "reports" && (
        <div className="w-full animate-in fade-in slide-in-from-bottom-4 duration-500">
           <ReportsPage isEmbedded={true} />
        </div>
      )}

    </div>
  );
}

