"use client";

import React, { useState } from "react";
import { Bell, CheckCircle2, Calendar, CreditCard, MessageSquare, UserPlus, Clock } from "lucide-react";
import { NotificationDetailModal } from "@/components/assistant/NotificationDetailModal";
import { useAuth } from "@/context/AuthContext";
import { toast } from "sonner";

export default function AssistantNotificationsPage() {
  const { user, updateUser } = useAuth();
  const [notifications, setNotifications] = useState<any[]>([]);
  const [selectedNotification, setSelectedNotification] = useState<any>(null);

  React.useEffect(() => {
    if (!user) return;
    
    const loadData = () => {
      const allNotifs: any[] = [];
      const currentAssistantId = (user as any).assistantId;
      
      // Load invites targeted at this assistant
      if (currentAssistantId) {
        const invitesStr = localStorage.getItem('oxpecker_invites');
        if (invitesStr) {
          try {
            const allInvites = JSON.parse(invitesStr);
            const targetedInvites = allInvites.filter((i: any) => i.assistantId === currentAssistantId && i.status === 'pending');
            
            targetedInvites.forEach((inv: any) => {
               allNotifs.push({
                 id: inv.id,
                 type: 'doctor_invite',
                 title: 'Connection Request',
                 message: `${inv.doctorName || 'A Doctor'} (${inv.email}) wants to connect with you. If you accept, you will gain access to their queue.`,
                 time: 'Just now',
                 unread: true,
                 doctorName: inv.doctorName || inv.email,
                 specialty: inv.role || "General"
               });
            });
          } catch (e) {}
        }
      }
      
      // Load system notifications
      const notifStr = localStorage.getItem('oxpecker_notifications');
      if (notifStr) {
        try {
          const sysNotifs = JSON.parse(notifStr);
          const targeted = sysNotifs.filter((n: any) => n.targetId === currentAssistantId || n.targetId === user.id);
          
          targeted.forEach((n: any) => {
            allNotifs.push({
               id: n.id,
               type: 'message',
               title: 'System Alert',
               message: n.message,
               time: 'Just now',
               unread: !n.read
            });
          });
        } catch (e) {}
      }
      
      setNotifications(allNotifs);
    };

    loadData();
    window.addEventListener('storage', loadData);
    const interval = setInterval(loadData, 1000);
    
    return () => {
      window.removeEventListener('storage', loadData);
      clearInterval(interval);
    };
  }, [user]);

  const unreadCount = notifications.filter(n => n.unread).length;

  const markAllAsRead = () => {
    setNotifications(notifications.map(n => ({ ...n, unread: false })));
  };

  const markAsRead = (id: number | string) => {
    setNotifications(notifications.map(n => n.id === id ? { ...n, unread: false } : n));
  };

  const handleOpenNotification = (notif: any) => {
    if (notif.unread) {
      markAsRead(notif.id);
    }
    setSelectedNotification(notif);
  };

  const handleInviteResponse = (id: number | string, status: 'accepted' | 'declined') => {
    // Find the invite in localStorage
    const invitesStr = localStorage.getItem('oxpecker_invites');
    let doctorName = "the doctor";
    let doctorId = "";
    
    if (invitesStr) {
      const allInvites = JSON.parse(invitesStr);
      const inviteIndex = allInvites.findIndex((i: any) => i.id === id);
      
      if (inviteIndex !== -1) {
        allInvites[inviteIndex].status = status;
        doctorName = allInvites[inviteIndex].doctorName || doctorName;
        doctorId = allInvites[inviteIndex].doctorId || "";
        localStorage.setItem('oxpecker_invites', JSON.stringify(allInvites));
      }
    }

    if (status === 'accepted' && doctorId && user) {
      // 1. Update global users list
      const usersStr = localStorage.getItem('oxpecker_users');
      if (usersStr) {
        const users = JSON.parse(usersStr);
        const uIdx = users.findIndex((u: any) => u.id === user.id);
        if (uIdx !== -1) {
          users[uIdx].doctorId = doctorId;
          localStorage.setItem('oxpecker_users', JSON.stringify(users));
        }
      }
      
      // 2. Update current auth user context
      updateUser({ ...user, doctorId });
      toast.success(`You are now officially connected to ${doctorName}!`);

      // 3. Update Doctor's connected assistants list so they see it in real-time
      const asstStr = localStorage.getItem('oxpecker_assistants');
      if (asstStr) {
        const docAssistants = JSON.parse(asstStr);
        const aIdx = docAssistants.findIndex((a: any) => a.id === user.assistantId);
        if (aIdx !== -1) {
          docAssistants[aIdx].status = "Connected";
          docAssistants[aIdx].name = user.name;
          docAssistants[aIdx].color = "text-[#22C55E]";
          docAssistants[aIdx].bg = "bg-[#22C55E]";
          docAssistants[aIdx].isPending = false;
          localStorage.setItem('oxpecker_assistants', JSON.stringify(docAssistants));
        }
      }
    }

    // Update local state to reflect UI change instantly
    setNotifications(notifications.map(n => 
      n.id === id ? { ...n, status: status, message: status === 'accepted' ? `You are now connected with ${doctorName}.` : "You declined the connection request." } : n
    ));
    
    if (selectedNotification && selectedNotification.id === id) {
       setSelectedNotification({
         ...selectedNotification,
         status: status,
         message: status === 'accepted' ? `You are now connected with ${doctorName}. You can now manage their patients and prescriptions.` : "You declined the connection request."
       });
    }
  };

  const getIcon = (type: string) => {
    switch (type) {
      case "doctor_invite": return <div className="w-12 h-12 lg:w-14 lg:h-14 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center shrink-0 border-2 border-white shadow-sm"><UserPlus size={22} /></div>;
      case "appointment": return <div className="w-12 h-12 lg:w-14 lg:h-14 rounded-full bg-blue-100 text-[#2F80ED] flex items-center justify-center shrink-0"><Calendar size={22} /></div>;
      case "payment": return <div className="w-12 h-12 lg:w-14 lg:h-14 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center shrink-0"><CreditCard size={22} /></div>;
      case "message": return <div className="w-12 h-12 lg:w-14 lg:h-14 rounded-full bg-amber-100 text-amber-500 flex items-center justify-center shrink-0"><MessageSquare size={22} /></div>;
      default: return <div className="w-12 h-12 lg:w-14 lg:h-14 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center shrink-0"><Bell size={22} /></div>;
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 min-h-screen pb-24 lg:pb-10 relative overflow-hidden">
      
      {/* Decorative background blobs for glassmorphism refraction */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-400/20 rounded-full blur-[120px] pointer-events-none" />
      <div className="absolute top-[40%] right-[-10%] w-[30%] h-[50%] bg-emerald-400/10 rounded-full blur-[100px] pointer-events-none" />

      {/* Page Header */}
      <div className="relative z-10 px-4 sm:px-6 lg:px-8 py-5 lg:py-8">
        <div className="max-w-[1200px] mx-auto w-full flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-[24px] lg:text-[28px] font-black text-slate-800 flex items-center gap-3 tracking-tight">
              <div className="w-12 h-12 rounded-[16px]   to-blue-100/50 flex items-center justify-center shrink-0 border border-blue-100 shadow-sm">
                <Bell className="text-[#2F80ED]" size={24} strokeWidth={2.5} />
              </div>
              Notifications
              {unreadCount > 0 && (
                <span className="   text-white text-[12px] font-bold px-3 py-1 rounded-full ml-2 shadow-[0_4px_12px_rgba(239,68,68,0.3)]">
                  {unreadCount} New
                </span>
              )}
            </h1>
            <p className="text-slate-500 mt-2 text-[14px] lg:text-[15px]">Stay updated with your latest alerts and requests.</p>
          </div>
          
          {unreadCount > 0 && (
            <button 
              onClick={markAllAsRead}
              className="flex items-center justify-center sm:justify-start gap-2 text-[14px] font-bold text-[#2F80ED] bg-white/60 backdrop-blur-md hover:bg-blue-50 border border-white/80 px-5 py-3 sm:py-2.5 rounded-[14px] active:scale-95 transition-all shadow-sm"
            >
              <CheckCircle2 size={18} strokeWidth={2.5} />
              Mark all as read
            </button>
          )}
        </div>
      </div>

      <div className="relative z-10 px-4 sm:px-6 lg:px-8 space-y-3 sm:space-y-4 max-w-[1200px] mx-auto w-full mt-2 lg:mt-4">
        
        {notifications.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="w-20 h-20 rounded-full bg-slate-100 flex items-center justify-center mb-4">
              <Bell size={32} className="text-slate-300" />
            </div>
            <h3 className="text-[18px] font-bold text-slate-600 mb-1">No Notifications</h3>
            <p className="text-[14px] text-slate-400 max-w-[300px]">When a doctor sends you an invite or you receive alerts, they will appear here.</p>
          </div>
        )}

        {notifications.map((notif) => (
          <div 
            key={notif.id} 
            onClick={() => handleOpenNotification(notif)}
            className={`p-4 lg:p-6 rounded-[20px] lg:rounded-[24px] border transition-all active:scale-[0.98] cursor-pointer relative overflow-hidden ${
              notif.unread 
                ? "bg-white/80 backdrop-blur-xl border-[#2F80ED]/20 shadow-[0_8px_30px_rgba(47,128,237,0.08)] hover:shadow-[0_8px_30px_rgba(47,128,237,0.12)]" 
                : "bg-white/40 backdrop-blur-lg border-white/60 shadow-[0_4px_20px_rgba(0,0,0,0.03)] hover:bg-white/60"
            }`}
          >
            {/* Unread Indicator Line */}
            {notif.unread && (
              <div className="absolute left-0 top-0 bottom-0 w-1.5   " />
            )}

            <div className="flex gap-4 lg:gap-6">
              {getIcon(notif.type)}
              <div className="flex-1">
                <div className="flex justify-between items-start mb-1.5">
                  <h3 className={`text-[16px] lg:text-[18px] font-bold ${notif.unread ? "text-slate-800" : "text-slate-600"} flex items-center gap-2 tracking-tight`}>
                    {notif.title}
                    {notif.status === 'accepted' && <span className="bg-emerald-100/80 text-emerald-700 text-[11px] px-2.5 py-0.5 rounded-full uppercase font-bold tracking-wider">Connected</span>}
                  </h3>
                  {notif.unread && <div className="w-2.5 h-2.5 rounded-full bg-[#2F80ED] mt-1.5 shrink-0 shadow-[0_0_10px_rgba(47,128,237,0.5)] hidden sm:block" />}
                </div>
                <p className={`text-[14px] lg:text-[15px] leading-relaxed mb-3 lg:w-5/6 line-clamp-2 ${notif.unread ? "text-slate-600 font-medium" : "text-slate-500"}`}>
                  {notif.message}
                </p>
                <div className="flex items-center gap-2">
                  <Clock size={14} className="text-slate-400" />
                  <p className="text-[12px] font-bold text-slate-400 uppercase tracking-wider">{notif.time}</p>
                </div>
              </div>
            </div>
          </div>
        ))}
        
      </div>

      <NotificationDetailModal 
        isOpen={!!selectedNotification} 
        onClose={() => setSelectedNotification(null)}
        notification={selectedNotification}
        onInviteResponse={handleInviteResponse}
      />

    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Users, UserCheck, Clock, XCircle, DollarSign, Video, 
  Play, Pause, SkipForward, AlertTriangle, 
  FileText, MoreVertical, Search, Plus, TrendingUp, TrendingDown, CheckCircle2, ChevronDown, X, BellRing, User, Receipt
} from 'lucide-react';
import Image from 'next/image';
import { useAuth } from '@/context/AuthContext';

const stats = [
  { title: "Today's Appts", count: "42", trend: "+12%", trendUp: true, icon: Users, color: "text-[#6DDA6E]", bg: "bg-[#6DDA6E]/10" },
  { title: "Waiting", count: "12", trend: "-2%", trendUp: false, icon: Clock, color: "text-[#F2994A]", bg: "bg-[#F2994A]/10" },
  { title: "Revenue", count: "৳28K", trend: "+18%", trendUp: true, icon: DollarSign, color: "text-[#8B5CF6]", bg: "bg-[#8B5CF6]/10" },
];

const INITIAL_QUEUE = [
  { id: "S-01", name: "Rahim Uddin", age: 45, gender: "M", phone: "01711...", time: "10:30 AM", type: "First Visit", symptoms: "Fever, Cough", status: "Waiting", payment: "Paid", paymentMethod: "Online (bKash)" },
  { id: "S-02", name: "Fatema Begum", age: 32, gender: "F", phone: "01822...", time: "10:45 AM", type: "Follow Up", symptoms: "Headache", status: "Waiting", payment: "Pending", paymentMethod: "Cash" },
  { id: "S-03", name: "Korim Hossain", age: 58, gender: "M", phone: "01933...", time: "11:00 AM", type: "First Visit", symptoms: "Chest Pain", status: "Waiting", payment: "Paid", paymentMethod: "Online (Card)", priority: true },
  { id: "S-04", name: "Nusrat Jahan", age: 24, gender: "F", phone: "01644...", time: "11:15 AM", type: "Report Show", symptoms: "Blood Test", status: "Waiting", payment: "Paid", paymentMethod: "Online (Nagad)" },
];

export default function AssistantDashboardPage() {
  const { user } = useAuth();
  const [selectedPatient, setSelectedPatient] = useState<any>(null);
  const [queue, setQueue] = useState(INITIAL_QUEUE);
  const [isBillingOpen, setIsBillingOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [assignedDoctorName, setAssignedDoctorName] = useState("Not Connected");

  useEffect(() => {
    if ((user as any)?.doctorId) {
      const usersStr = localStorage.getItem('oxpecker_users');
      if (usersStr) {
        const users = JSON.parse(usersStr);
        const doc = users.find((u: any) => u.id === (user as any).doctorId);
        if (doc) {
          setAssignedDoctorName(doc.name || "Assigned Doctor");
        }
      }
    }
  }, [user]);

  useEffect(() => {
    // Simulate fetching dashboard data
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1500);
    return () => clearTimeout(timer);
  }, []);
  
  // LIVE QUEUE STATE MACHINE
  // States: 'idle' (waiting to start), 'active' (timer running), 'signaled' (doctor blinking yellow)
  const [queueState, setQueueState] = useState<'idle' | 'active' | 'signaled'>('idle');
  const [timer, setTimer] = useState(0);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Derived state
  const currentIndex = queue.findIndex(p => p.status === 'In Consultation' || p.status === 'Waiting');
  const currentPatient = currentIndex !== -1 ? queue[currentIndex] : null;
  const nextPatient = currentIndex !== -1 && currentIndex + 1 < queue.length ? queue[currentIndex + 1] : null;

  useEffect(() => {
    if (queueState === 'active') {
      timerRef.current = setInterval(() => {
        setTimer((prev) => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [queueState]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  const handleStart = () => {
    if (!currentPatient) return;
    setQueueState('active');
    setTimer(0);
    const newQueue = [...queue];
    newQueue[currentIndex].status = 'In Consultation';
    setQueue(newQueue);
  };

  const handleComplete = () => {
    if (!currentPatient) return;
    setQueueState('idle');
    setTimer(0);
    const newQueue = [...queue];
    newQueue[currentIndex].status = 'Completed';
    setQueue(newQueue);
  };

  const handleSkip = () => {
    if (!currentPatient) return;
    setQueueState('idle');
    setTimer(0);
    const newQueue = [...queue];
    newQueue[currentIndex].status = 'Skipped';
    setQueue(newQueue);
  };

  // Mocking the doctor's signal
  const simulateDoctorSignal = () => {
    if (queueState === 'active') {
      setQueueState('signaled');
    }
  };

  const handleSignaledNext = () => {
    handleComplete();
  };

  if (isLoading) {
    return (
      <div className="w-full flex flex-col gap-4 md:gap-6 relative min-h-screen pb-24 lg:pb-10 bg-slate-50 animate-pulse">
        
        {/* Skeleton Hero Box */}
        <div className="w-full rounded-none sm:rounded-[24px] sm:mt-4 bg-slate-200 border-y sm:border border-slate-200 p-6 md:p-8 flex flex-col justify-between overflow-hidden relative min-h-[300px]">
          <div className="flex justify-between items-center mb-6 md:mb-8">
            <div className="h-6 w-40 bg-slate-300 rounded-md"></div>
            <div className="h-8 w-8 bg-slate-300 rounded-full"></div>
          </div>
          <div className="flex flex-col relative z-10">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-8">
              <div>
                <div className="h-4 w-32 bg-slate-300 rounded-md mb-4"></div>
                <div className="h-16 w-64 md:w-96 bg-slate-300 rounded-xl mb-4"></div>
                <div className="flex gap-2">
                  <div className="h-6 w-24 bg-slate-300 rounded-md"></div>
                  <div className="h-6 w-24 bg-slate-300 rounded-md"></div>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className="h-14 w-14 bg-slate-300 rounded-full"></div>
                <div className="h-14 w-14 bg-slate-300 rounded-full"></div>
              </div>
            </div>
          </div>
        </div>

        {/* Skeleton Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mx-4 sm:mx-0">
          {[1, 2, 3].map((i) => (
            <div key={i} className="bg-white rounded-[20px] p-6 border border-slate-100 flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl bg-slate-200 shrink-0"></div>
              <div className="flex-1 space-y-2">
                <div className="h-4 w-20 bg-slate-200 rounded-md"></div>
                <div className="h-8 w-24 bg-slate-200 rounded-md"></div>
              </div>
            </div>
          ))}
        </div>

        {/* Skeleton Queue List */}
        <div className="bg-white rounded-[24px] shadow-sm border border-slate-100 p-6 mx-4 sm:mx-0">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
            <div className="h-8 w-40 bg-slate-200 rounded-md"></div>
            <div className="w-full md:w-[300px] h-10 bg-slate-200 rounded-xl"></div>
          </div>

          <div className="space-y-3">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="bg-white border border-slate-100 rounded-xl p-4 flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div className="flex items-center gap-4 w-full lg:w-1/3">
                  <div className="w-12 h-12 bg-slate-200 rounded-full shrink-0"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-5 w-32 bg-slate-200 rounded-md"></div>
                    <div className="h-3 w-20 bg-slate-200 rounded-md"></div>
                  </div>
                </div>
                <div className="flex-1 space-y-2 hidden md:block">
                  <div className="h-4 w-24 bg-slate-200 rounded-md"></div>
                  <div className="h-3 w-32 bg-slate-200 rounded-md"></div>
                </div>
                <div className="h-10 w-28 bg-slate-200 rounded-xl"></div>
              </div>
            ))}
          </div>
        </div>

      </div>
    );
  }

  return (
    <div className="w-full flex flex-col gap-4 md:gap-6 relative min-h-screen pb-24 lg:pb-10 bg-slate-50">
      
      {/* 1. HERO: Live Queue Control */}
      <motion.div 
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className={`w-full rounded-none sm:rounded-[24px] sm:mt-4 shadow-sm border-y sm:border border-slate-200 p-6 md:p-8 flex flex-col justify-between transition-colors duration-500 overflow-hidden relative
          ${queueState === 'signaled' ? 'bg-amber-400 border-amber-500 shadow-[0_0_40px_rgba(251,191,36,0.3)]' : 
            queueState === 'active' ? 'bg-white' : 'bg-slate-900'}
        `}
      >
        {/* Background Decorative Rings */}
        <div className={`absolute top-0 right-0 w-64 h-64 rounded-full blur-3xl pointer-events-none -mr-20 -mt-20 transition-colors duration-500
          ${queueState === 'signaled' ? 'bg-white/20' : queueState === 'active' ? 'bg-emerald-100' : 'bg-[#2F80ED]/20'}
        `} />

        <div className="flex justify-between items-center mb-6 md:mb-8 relative z-10">
          <div className="flex items-center gap-3">
            {/* Back Button */}
            <button className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center text-current backdrop-blur-md transition-colors" title="Back to Queue List">
               <ChevronDown size={18} className={`rotate-90 ${queueState === 'signaled' ? 'text-amber-950' : queueState === 'active' ? 'text-slate-800' : 'text-white'}`} />
            </button>
            {queueState === 'signaled' ? (
              <div className="w-4 h-4 rounded-full bg-white animate-ping" />
            ) : queueState === 'active' ? (
              <div className="w-3 h-3 rounded-full bg-emerald-500 animate-pulse" />
            ) : (
              <div className="w-3 h-3 rounded-full bg-[#2F80ED]" />
            )}
            <h2 className={`text-[16px] md:text-[18px] font-bold uppercase tracking-wider ${queueState === 'signaled' ? 'text-amber-950' : queueState === 'active' ? 'text-slate-800' : 'text-slate-400'}`}>
              Live Queue Status
            </h2>
          </div>
          
          {/* Debug/Mock Button to trigger doctor signal */}
          {queueState === 'active' && (
            <button onClick={simulateDoctorSignal} className="px-3 py-1 bg-slate-100 hover:bg-amber-100 text-[11px] font-bold text-slate-400 rounded-full transition-colors">
              Mock Doctor Signal
            </button>
          )}
        </div>

        {currentPatient ? (
          <div className="flex flex-col relative z-10">
            {/* Main Info */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-8">
              <div>
                <p className={`text-[14px] font-bold uppercase tracking-widest mb-2 ${queueState === 'signaled' ? 'text-amber-900/70' : queueState === 'active' ? 'text-emerald-600' : 'text-[#2F80ED]'}`}>
                  {queueState === 'active' ? 'In Consultation' : queueState === 'signaled' ? 'Doctor Calling Next' : 'Waiting To Start'}
                </p>
                <div className="flex items-center gap-4">
                  <h1 className={`text-[56px] md:text-[72px] font-black leading-none tracking-tighter ${queueState === 'signaled' ? 'text-amber-950' : queueState === 'active' ? 'text-slate-800' : 'text-white'}`}>
                    {currentPatient.id}
                  </h1>
                  <div className={`h-[48px] w-1 rounded-full ${queueState === 'signaled' ? 'bg-amber-500' : queueState === 'active' ? 'bg-slate-200' : 'bg-slate-700'}`} />
                  <div className="flex flex-col">
                    <h2 className={`text-[24px] md:text-[32px] font-bold leading-tight ${queueState === 'signaled' ? 'text-amber-950' : queueState === 'active' ? 'text-slate-800' : 'text-white'}`}>
                      {currentPatient.name}
                    </h2>
                    {nextPatient && queueState !== 'signaled' && (
                      <p className={`text-[15px] font-medium mt-1 flex items-center gap-2 ${queueState === 'active' ? 'text-slate-500' : 'text-slate-400'}`}>
                        <span className="opacity-70">Next:</span> {nextPatient.id} {nextPatient.name}
                      </p>
                    )}
                  </div>
                </div>
              </div>

              {/* Timer */}
              {queueState === 'active' && (
                <div className="flex flex-col md:items-end">
                  <span className="text-[12px] font-bold text-slate-400 uppercase tracking-wider mb-1">Time Elapsed</span>
                  <span className="text-[48px] font-mono font-bold text-emerald-700 leading-none bg-emerald-50 px-4 py-2 rounded-2xl border border-emerald-100 shadow-inner">
                    {formatTime(timer)}
                  </span>
                </div>
              )}
            </div>

            {/* Massive Action Buttons */}
            <div className="flex flex-col sm:flex-row gap-3 md:gap-4 mt-2">
              
              {queueState === 'idle' && (
                <>
                  <button onClick={handleStart} className="flex-1 min-h-[64px] bg-[#2F80ED] hover:bg-[#256bbd] text-white rounded-[20px] font-bold text-[18px] md:text-[20px] transition-transform active:scale-[0.98] flex items-center justify-center gap-3 shadow-lg">
                    <Play fill="currentColor" size={24} /> Start Conversation
                  </button>
                  <button onClick={handleSkip} className="sm:w-[160px] min-h-[64px] bg-slate-800 hover:bg-slate-700 text-white rounded-[20px] font-bold text-[16px] transition-transform active:scale-[0.98] flex items-center justify-center gap-2">
                    <SkipForward size={20} /> Skip
                  </button>
                </>
              )}

              {queueState === 'active' && (
                <>
                  <button onClick={() => setIsBillingOpen(true)} className="w-[140px] md:w-[180px] min-h-[64px] bg-indigo-50 hover:bg-indigo-600 text-indigo-600 hover:text-white border-2 border-indigo-100 hover:border-indigo-600 rounded-[20px] font-bold text-[16px] md:text-[18px] transition-all active:scale-[0.98] flex items-center justify-center gap-2 shadow-sm">
                    <Receipt size={24} /> Bill
                  </button>
                  <button onClick={handleComplete} className="flex-1 min-h-[64px] bg-slate-800 hover:bg-slate-900 text-white rounded-[20px] font-bold text-[18px] md:text-[20px] transition-transform active:scale-[0.98] flex items-center justify-center gap-3 shadow-lg">
                    <CheckCircle2 size={24} /> Mark Completed
                  </button>
                </>
              )}

              {queueState === 'signaled' && (
                <>
                  <button onClick={handleSignaledNext} className="flex-1 min-h-[72px] bg-white text-amber-600 rounded-[24px] font-black text-[20px] md:text-[24px] transition-transform active:scale-[0.98] flex items-center justify-center gap-3 shadow-2xl animate-pulse">
                    <BellRing size={28} /> Call Next Now
                  </button>
                </>
              )}

            </div>
          </div>
        ) : (
           <div className="py-8 text-center relative z-10">
             <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-4">
               <CheckCircle2 size={32} className="text-[#6DDA6E]" />
             </div>
             <h2 className="text-[24px] font-bold text-white mb-2">Queue Empty</h2>
             <p className="text-slate-400">All patients have been seen.</p>
           </div>
        )}
      </motion.div>

      <div className="px-4 sm:px-0 grid grid-cols-1 md:grid-cols-12 gap-4 md:gap-6 mt-2">
        {/* Statistics Cards */}
        <div className="md:col-span-8 grid grid-cols-2 md:grid-cols-3 gap-4">
          {stats.map((stat, idx) => (
            <div key={idx} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between">
              <div className="flex justify-between items-start mb-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${stat.bg}`}>
                  <stat.icon size={20} className={stat.color} />
                </div>
              </div>
              <div>
                <h3 className="text-[24px] font-black text-slate-800 leading-none mb-1">{stat.count}</h3>
                <p className="text-[13px] font-semibold text-slate-500">{stat.title}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Doctor Status */}
        <div className="md:col-span-4 bg-white rounded-2xl p-5 shadow-sm border border-slate-100 flex flex-col justify-center">
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 rounded-full overflow-hidden border-2 border-slate-100 relative shrink-0">
               <Image src="https://api.dicebear.com/7.x/avataaars/svg?seed=Sarah&backgroundColor=e0f2fe" alt="Doctor" fill className="object-cover" />
            </div>
            <div>
              <h3 className="text-[18px] font-bold text-slate-800">{assignedDoctorName}</h3>
              <div className="flex items-center gap-2 mt-1">
                {queueState === 'idle' ? (
                  <><div className="w-2.5 h-2.5 bg-slate-400 rounded-full"></div><span className="text-[14px] font-bold text-slate-500">Waiting for Patient</span></>
                ) : queueState === 'active' ? (
                  <><div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse"></div><span className="text-[14px] font-bold text-emerald-600">In Consultation</span></>
                ) : (
                  <><div className="w-2.5 h-2.5 bg-amber-500 rounded-full animate-ping"></div><span className="text-[14px] font-bold text-amber-600">Calling Next</span></>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Today's Queue List (Simplified Desktop only or Scrollable) */}
      <div className="mt-4 px-4 sm:px-0">
        <h3 className="text-[16px] font-bold text-slate-800 mb-3 px-1">Upcoming Queue</h3>
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden divide-y divide-slate-100">
           {queue.filter(p => p.status === 'Waiting').map((row, i) => (
             <div key={i} className="p-4 flex items-center justify-between">
               <div className="flex items-center gap-4">
                 <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center font-bold text-slate-800 text-[16px] border border-slate-200">
                   {row.id.split('-')[1]}
                 </div>
                 <div>
                   <p className="font-bold text-slate-800">{row.name}</p>
                   <p className="text-[13px] text-slate-500 mt-0.5">{row.time} • {row.type}</p>
                 </div>
               </div>
               <div className="flex items-center gap-3">
                 <div className="flex flex-col items-end mr-1 sm:mr-2 shrink-0">
                    {row.payment === "Paid" ? (
                      <span className="text-[10px] sm:text-[11px] font-bold bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full whitespace-nowrap">{row.paymentMethod}</span>
                    ) : (
                      <span className="text-[10px] sm:text-[11px] font-bold bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full whitespace-nowrap">Pending ({row.paymentMethod})</span>
                    )}
                 </div>
                 <button onClick={() => setSelectedPatient(row)} className="w-10 h-10 rounded-xl bg-slate-50 text-slate-400 flex items-center justify-center hover:bg-slate-100 hover:text-[#2F80ED] transition-colors">
                   <User size={18} />
                 </button>
               </div>
             </div>
           ))}
           {queue.filter(p => p.status === 'Waiting').length === 0 && (
             <div className="p-6 text-center text-slate-500 font-medium">No more patients waiting.</div>
           )}
        </div>
      </div>

      {/* Floating Add Button (Mobile) */}
      <div className="fixed bottom-24 sm:bottom-8 right-6 sm:right-8 z-40">
        <button className="w-[56px] h-[56px] sm:w-[64px] sm:h-[64px] bg-[#2F80ED] hover:bg-[#256bbd] text-white rounded-full flex items-center justify-center shadow-lg transition-transform active:scale-95">
          <Plus size={24} />
        </button>
      </div>

      {/* Simple Details Modal */}
      <AnimatePresence>
        {selectedPatient && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center sm:p-4"
          >
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
              transition={{ type: "spring", bounce: 0, duration: 0.4 }}
              className="w-full sm:w-[400px] bg-white rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden"
            >
              <div className="px-6 py-4 flex items-center justify-between border-b border-slate-100">
                <h3 className="font-bold text-slate-800">Patient Info</h3>
                <button onClick={() => setSelectedPatient(null)} className="p-2 bg-slate-50 rounded-full"><X size={18} /></button>
              </div>
              <div className="p-6 space-y-4">
                <div className="flex items-center gap-4 mb-2">
                  <div className="w-16 h-16 rounded-full bg-blue-100 text-[#2F80ED] text-[24px] font-bold flex items-center justify-center">
                    {selectedPatient.name.charAt(0)}
                  </div>
                  <div>
                    <h2 className="text-[20px] font-bold text-slate-800">{selectedPatient.name}</h2>
                    <p className="text-slate-500">{selectedPatient.id}</p>
                  </div>
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 space-y-2">
                  <p className="text-[14px] text-slate-600"><strong className="text-slate-800">Phone:</strong> {selectedPatient.phone}</p>
                  <p className="text-[14px] text-slate-600"><strong className="text-slate-800">Age/Gender:</strong> {selectedPatient.age} / {selectedPatient.gender}</p>
                  <p className="text-[14px] text-slate-600"><strong className="text-slate-800">Symptoms:</strong> {selectedPatient.symptoms}</p>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Billing Drawer (Dashboard version) */}
      <AnimatePresence>
        {isBillingOpen && currentPatient && (
          <>
            <motion.div 
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} 
              className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100]"
              onClick={() => setIsBillingOpen(false)}
            />
            <motion.div 
              initial={{ x: '100%', y: '100%' }} animate={{ x: 0, y: 0 }} exit={{ x: '100%', y: '100%' }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="fixed bottom-0 lg:bottom-auto lg:top-0 right-0 w-full h-[80vh] lg:h-full lg:max-w-[450px] bg-white shadow-2xl z-[101] flex flex-col rounded-t-[24px] lg:rounded-none lg:border-l border-slate-200"
            >
              <div className="h-[72px] px-6 border-b border-slate-100 flex justify-between items-center bg-white shrink-0 pt-2 lg:pt-safe-top rounded-t-[24px] lg:rounded-none">
                <h2 className="text-[18px] font-bold text-slate-800 flex items-center gap-2">
                  <Receipt size={20} className="text-indigo-600" /> Patient Billing
                </h2>
                <button onClick={() => setIsBillingOpen(false)} className="w-8 h-8 flex items-center justify-center bg-slate-50 text-slate-500 hover:bg-slate-100 rounded-full transition-colors">
                  <X size={18}/>
                </button>
              </div>
              
              <div className="flex-1 overflow-y-auto p-5 sm:p-6 custom-scrollbar bg-slate-50/50">
                <div className="bg-white rounded-[16px] p-5 shadow-sm border border-slate-100 flex items-center gap-4 mb-6">
                  <div className="w-[48px] h-[48px] rounded-full bg-indigo-50 text-indigo-600 font-bold text-[20px] flex items-center justify-center shrink-0 border border-indigo-100">
                    {currentPatient.name.charAt(0)}
                  </div>
                  <div>
                    <h3 className="text-[18px] font-bold text-slate-800">{currentPatient.name}</h3>
                    <p className="text-[13px] font-medium text-slate-500 font-mono">{currentPatient.id} • {currentPatient.phone}</p>
                  </div>
                </div>

                <div className="bg-white rounded-[16px] shadow-sm border border-slate-100 overflow-hidden mb-6">
                  <div className="p-4 border-b border-slate-100 bg-slate-50/50">
                    <h4 className="text-[14px] font-bold text-slate-800">Invoice Details</h4>
                  </div>
                  <div className="p-4 space-y-4">
                    <div className="flex justify-between items-center text-[14px]">
                      <span className="text-slate-500 font-medium">Treatment / Service</span>
                      <span className="font-bold text-slate-800">{currentPatient.symptoms || "General"}</span>
                    </div>
                    <div className="flex justify-between items-center text-[14px]">
                      <span className="text-slate-500 font-medium">Date</span>
                      <span className="font-bold text-slate-800">{new Date().toLocaleDateString()}</span>
                    </div>
                    <div className="w-full h-px bg-slate-100" />
                    <div className="flex justify-between items-center text-[14px]">
                      <span className="text-slate-500 font-medium">Total Bill</span>
                      <span className="font-bold text-slate-800">৳1500</span>
                    </div>
                    <div className="flex justify-between items-center text-[14px]">
                      <span className="text-slate-500 font-medium">Amount Paid</span>
                      <span className="font-bold text-emerald-600">৳0</span>
                    </div>
                    <div className="w-full h-px bg-slate-200" />
                    <div className="flex justify-between items-center text-[16px]">
                      <span className="text-slate-800 font-black">Due Amount</span>
                      <span className="font-black text-rose-500">৳1500</span>
                    </div>

                    <div className="mt-4 pt-4 border-t border-slate-200">
                      <p className="text-[13px] font-bold text-slate-700 mb-2">Select Payment Method</p>
                      <div className="grid grid-cols-3 gap-2">
                        <button className="h-10 bg-indigo-50 border border-indigo-600 text-indigo-700 rounded-lg text-[13px] font-bold">Cash</button>
                        <button className="h-10 bg-slate-50 border border-slate-200 text-slate-600 rounded-lg text-[13px] font-medium hover:bg-slate-100">bKash</button>
                        <button className="h-10 bg-slate-50 border border-slate-200 text-slate-600 rounded-lg text-[13px] font-medium hover:bg-slate-100">Card</button>
                      </div>
                    </div>

                  </div>
                </div>
              </div>
              
              <div className="p-4 border-t border-slate-100 bg-white shrink-0 pb-safe">
                 <button 
                  onClick={() => setIsBillingOpen(false)}
                  className="w-full h-[52px] bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-[14px] transition-all flex items-center justify-center gap-2 text-[15px] shadow-md active:scale-[0.98]"
                 >
                   <CheckCircle2 size={20}/> Confirm Payment & Generate Bill
                 </button>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

    </div>
  );
}

"use client";

import React, { useState } from "react";
import { ArrowLeft, Clock, MapPin, ChevronRight, MessageSquareHeart, Users } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { toast } from "sonner";

export default function ChamberPatientListPage() {
  const params = useParams();
  const router = useRouter();
  const [isStarting, setIsStarting] = useState(false);

  // Mock chamber info
  const chamberInfo = {
    id: params.id,
    name: params.id === 'gulshan-morning' ? "Gulshan Branch" : "Banani Clinic",
    room: "Room 201",
    date: "25 Jul, 2026"
  };

  const PATIENTS = [
    { id: "1", name: "Rahim Uddin", serial: 1, time: "10:00 AM", status: "Waiting", type: "New", image: "https://api.dicebear.com/7.x/avataaars/svg?seed=Rahim&backgroundColor=c0aede" },
    { id: "2", name: "Karim Ali", serial: 2, time: "10:15 AM", status: "Waiting", type: "Follow-up", image: "https://api.dicebear.com/7.x/avataaars/svg?seed=Karim&backgroundColor=b6e3f4" },
    { id: "3", name: "Salma Begum", serial: 3, time: "10:30 AM", status: "Waiting", type: "Report", image: "https://api.dicebear.com/7.x/avataaars/svg?seed=Salma&backgroundColor=ffdfbf" },
    { id: "4", name: "Jabbar Mia", serial: 4, time: "10:45 AM", status: "Waiting", type: "New", image: "https://api.dicebear.com/7.x/avataaars/svg?seed=Jabbar&backgroundColor=d1d4f9" },
    { id: "5", name: "Fatema Khatun", serial: 5, time: "11:00 AM", status: "Waiting", type: "New", image: "https://api.dicebear.com/7.x/avataaars/svg?seed=Fatema&backgroundColor=e0f2fe" },
  ];

  const handleStartConversation = () => {
    setIsStarting(true);
    // Simulate pushing entire list to live dashboard queue
    setTimeout(() => {
      toast.success(`Queue for ${chamberInfo.name} pushed to Live Dashboard!`);
      router.push("/assistant"); // Navigate to live dashboard to call them
    }, 800);
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 min-h-screen pb-24 lg:pb-10 relative overflow-hidden">
      
      {/* Decorative Blobs */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-400/20 rounded-full blur-[120px] pointer-events-none" />
      <div className="absolute top-[40%] right-[-10%] w-[30%] h-[50%] bg-emerald-400/10 rounded-full blur-[100px] pointer-events-none" />

      {/* Top Navigation Bar */}
      <div className="relative z-10 px-4 sm:px-6 lg:px-8 py-4 border-b border-white/60 bg-white/50 backdrop-blur-md sticky top-[72px] lg:top-0">
        <div className="max-w-[1200px] mx-auto w-full flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <Link href="/assistant/patient-list" className="w-10 h-10 bg-white border border-slate-200 rounded-full flex items-center justify-center text-slate-600 hover:text-[#2F80ED] hover:border-[#2F80ED] transition-all shadow-sm shrink-0">
              <ArrowLeft size={20} />
            </Link>
            <div>
              <h1 className="text-[18px] lg:text-[22px] font-black text-slate-800 leading-tight">{chamberInfo.name}</h1>
              <p className="text-[13px] text-slate-500 font-medium">{chamberInfo.date} • {chamberInfo.room}</p>
            </div>
          </div>

          {/* Desktop Start Conversation Button */}
          <div className="hidden lg:block">
             <button 
                onClick={handleStartConversation}
                disabled={isStarting}
                className="w-[250px] h-[56px] bg-emerald-500 hover:bg-emerald-600 active:scale-95 text-white font-bold text-[16px] rounded-[16px] shadow-[0_8px_20px_rgba(16,185,129,0.3)] transition-all flex items-center justify-center gap-2"
              >
                {isStarting ? (
                  <span className="animate-pulse">Starting Queue...</span>
                ) : (
                  <>
                    <MessageSquareHeart size={20} /> Start Conversation
                  </>
                )}
              </button>
          </div>
        </div>
      </div>

      {/* Mobile Sticky Action Button (Right below header) */}
      <div className="lg:hidden sticky top-[146px] z-20 px-4 py-3 bg-slate-50/90 backdrop-blur-md border-b border-slate-200">
        <button 
          onClick={handleStartConversation}
          disabled={isStarting}
          className="w-full h-[52px] bg-emerald-500 active:bg-emerald-600 text-white font-bold text-[15px] rounded-[16px] shadow-[0_4px_14px_rgba(16,185,129,0.3)] transition-all flex items-center justify-center gap-2"
        >
          {isStarting ? (
            <span className="animate-pulse">Starting Queue...</span>
          ) : (
            <>
              <MessageSquareHeart size={20} /> Start Conversation
            </>
          )}
        </button>
      </div>

      <div className="relative z-10 px-4 sm:px-6 lg:px-8 max-w-[1200px] mx-auto w-full mt-4 lg:mt-8">
        
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-[16px] font-bold text-slate-800 flex items-center gap-2">
            <Users className="text-[#2F80ED]" size={18} /> Waiting List ({PATIENTS.length})
          </h2>
        </div>

        {/* Patient List Grid */}
        <div className="grid grid-cols-1 gap-3 lg:gap-4">
          {PATIENTS.map((patient, index) => (
            <motion.div
              key={patient.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
              className="bg-white/90 backdrop-blur-xl border border-white/60 rounded-[20px] p-3 lg:p-4 shadow-[0_4px_20px_rgba(0,0,0,0.02)] hover:shadow-[0_8px_30px_rgba(0,0,0,0.06)] hover:border-[#2F80ED]/20 transition-all flex items-center gap-4 min-h-auto lg:min-h-[88px] cursor-pointer group"
            >
              {/* Serial Number & Avatar */}
              <div className="relative shrink-0 flex items-center gap-2 lg:gap-4">
                <span className="text-[14px] lg:text-[18px] font-black text-slate-300 w-5 lg:w-8 text-center">{patient.serial}</span>
                <div className="w-[48px] h-[48px] lg:w-[56px] lg:h-[56px] rounded-[14px] lg:rounded-[16px] bg-slate-100 border-2 border-white shadow-sm relative overflow-hidden group-hover:scale-105 transition-transform">
                  <Image src={patient.image} alt={patient.name} fill className="object-cover" />
                </div>
              </div>

              {/* Patient Info */}
              <div className="flex-1 min-w-0">
                <h3 className="text-[16px] lg:text-[18px] font-bold text-slate-800 truncate mb-1 group-hover:text-[#2F80ED] transition-colors">{patient.name}</h3>
                <div className="flex flex-wrap items-center gap-2 lg:gap-3 text-[12px] lg:text-[14px] text-slate-500 font-medium">
                  <span className="flex items-center gap-1"><Clock size={14} className="text-amber-500"/> {patient.time}</span>
                  <span className="hidden sm:inline text-slate-300">•</span>
                  <span className={`font-bold px-2 py-0.5 rounded-md uppercase tracking-wider text-[10px] lg:text-[11px] ${
                    patient.type === 'New' ? 'bg-blue-100 text-blue-600' :
                    patient.type === 'Report' ? 'bg-purple-100 text-purple-600' : 'bg-emerald-100 text-emerald-600'
                  }`}>
                    {patient.type}
                  </span>
                </div>
              </div>

              {/* Actions */}
              <div className="shrink-0 flex items-center">
                 <div className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-slate-400 group-hover:bg-[#2F80ED] group-hover:text-white transition-colors">
                   <ChevronRight size={18} />
                 </div>
              </div>

            </motion.div>
          ))}
        </div>

      </div>

    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Search, MapPin, Calendar, Users, Building, ArrowRight } from "lucide-react";
import Link from "next/link";
import { motion } from "framer-motion";

const CHAMBERS = [
  { id: "gulshan-morning", name: "Gulshan Branch", room: "Room 201", date: "25 Jul, 2026", location: "Gulshan 2, Dhaka", patientsCount: 12 },
  { id: "banani-evening", name: "Banani Clinic", room: "Room 105", date: "25 Jul, 2026", location: "Banani, Dhaka", patientsCount: 8 },
  { id: "dhanmondi-morning", name: "Dhanmondi Care", room: "Room 304", date: "26 Jul, 2026", location: "Dhanmondi 27", patientsCount: 15 },
  { id: "mirpur-evening", name: "Mirpur Specialized", room: "Room 401", date: "26 Jul, 2026", location: "Mirpur 10", patientsCount: 5 },
];

export default function ChamberSelectionPage() {
  const [searchTerm, setSearchTerm] = useState("");

  const filteredChambers = CHAMBERS.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="flex-1 flex flex-col bg-slate-50 min-h-screen pb-24 lg:pb-10 relative overflow-hidden">
      
      {/* Decorative Blobs */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-400/20 rounded-full blur-[120px] pointer-events-none" />
      <div className="absolute top-[40%] right-[-10%] w-[30%] h-[50%] bg-emerald-400/10 rounded-full blur-[100px] pointer-events-none" />

      {/* Header */}
      <div className="relative z-10 px-4 sm:px-6 lg:px-8 py-5 lg:py-8 bg-white/50 backdrop-blur-md border-b border-white/60 sticky top-[72px] lg:top-0">
        <div className="max-w-[1200px] mx-auto w-full flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-[24px] lg:text-[28px] font-black text-slate-800 flex items-center gap-3 tracking-tight">
              <div className="w-12 h-12 rounded-[16px]    flex items-center justify-center shrink-0 border border-blue-200 shadow-sm">
                <Building className="text-[#2F80ED]" size={24} strokeWidth={2.5} />
              </div>
              Select Chamber
            </h1>
            <p className="text-slate-500 mt-2 text-[14px] lg:text-[15px] font-medium">Choose a chamber location to view its patient list.</p>
          </div>
          
          <div className="relative w-full lg:w-[320px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search chamber or location..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full h-[48px] pl-10 pr-4 bg-white border border-slate-200 rounded-xl text-[14px] font-medium outline-none focus:border-[#2F80ED] focus:ring-4 focus:ring-[#2F80ED]/10 transition-all shadow-sm"
            />
          </div>
        </div>
      </div>

      {/* Chamber List Content */}
      <div className="relative z-10 px-4 sm:px-6 lg:px-8 max-w-[1200px] mx-auto w-full mt-6">
        
        {filteredChambers.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20">
            <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
              <Building size={24} className="text-slate-400" />
            </div>
            <h3 className="text-[18px] font-bold text-slate-800">No Chambers Found</h3>
            <p className="text-[14px] text-slate-500 mt-1">Try adjusting your search criteria.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 lg:gap-6">
            {filteredChambers.map((chamber, index) => (
              <motion.div
                key={chamber.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.05 }}
              >
                <Link href={`/assistant/patient-list/${chamber.id}`}>
                  <div className="bg-white/90 backdrop-blur-xl border border-white/60 rounded-[20px] p-4 lg:p-6 min-h-[120px] lg:min-h-[140px] shadow-[0_4px_20px_rgba(0,0,0,0.03)] hover:shadow-[0_8px_30px_rgba(0,0,0,0.08)] hover:border-[#2F80ED]/30 transition-all group relative overflow-hidden flex flex-col justify-between">
                    
                    {/* Background Graphic */}
                    <div className="absolute right-[-10%] top-[-10%] w-[40%] h-[120%]  from-blue-50/50  pointer-events-none group-hover:from-blue-100/50 transition-colors" />

                    <div className="flex justify-between items-start relative z-10">
                      <div className="pr-12">
                        <h3 className="text-[18px] lg:text-[20px] font-bold text-slate-800 mb-2 group-hover:text-[#2F80ED] transition-colors line-clamp-1">{chamber.name}</h3>
                        
                        <div className="space-y-1.5">
                          <p className="flex items-center gap-2 text-[13px] lg:text-[14px] text-slate-600 font-medium">
                            <MapPin size={16} className="text-rose-500" /> {chamber.location}
                          </p>
                          <p className="flex items-center gap-2 text-[13px] lg:text-[14px] text-slate-600 font-medium">
                            <Building size={16} className="text-emerald-500" /> {chamber.room}
                          </p>
                          <p className="flex items-center gap-2 text-[13px] lg:text-[14px] text-slate-600 font-medium">
                            <Calendar size={16} className="text-amber-500" /> {chamber.date}
                          </p>
                        </div>
                      </div>

                      {/* Patient Count Badge */}
                      <div className="absolute top-0 right-0 w-[48px] h-[48px] bg-blue-50 border border-blue-100 rounded-full flex flex-col items-center justify-center shrink-0 shadow-sm group-hover:bg-[#2F80ED] group-hover:border-[#2F80ED] transition-colors">
