                >
                  <Receipt size={18} /> View Bill
                </button>
             </div>
           ))}
        </div>

      </div>

      {/* BILLING DRAWER (Slide In Panel) */}
      <AnimatePresence>
        {billingPatient && (
          <>
            {/* Overlay */}
            <motion.div 
              initial={{ opacity: 0 }} 
              animate={{ opacity: 1 }} 
              exit={{ opacity: 0 }} 
              className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100]"
              onClick={() => setBillingPatient(null)}
            />

            {/* Desktop Slide from Right | Mobile Bottom Sheet */}
            <motion.div 
