"use client";

import React, { useState, useEffect, useRef } from "react";
import { Settings, User, Bell, Shield, LogOut, ChevronRight, Moon, Edit3, Fingerprint, FileCheck2, GraduationCap, CheckCircle2, UploadCloud, X, Save, FileText, Globe, Camera, AlertCircle, Info, Stethoscope, Upload, Image as ImageIcon, Clock } from "lucide-react";
import Image from "next/image";
import { useAuth } from "@/context/AuthContext";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { motion, AnimatePresence } from "framer-motion";

export default function AssistantSettingsPage() {
  const { user, logout, updateUser } = useAuth();
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [activeTab, setActiveTab] = useState<'profile' | 'security' | 'preferences'>('profile');
  
  // Settings State
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [darkMode, setDarkMode] = useState(false);
  const [language, setLanguage] = useState("English");

  // Profile Edit State
  const [isIdentityEditMode, setIsIdentityEditMode] = useState(false);
  const [editForm, setEditForm] = useState({
    name: "",
    email: "",
    phone: "+880 1711-000000",
    address: "Dhaka, Bangladesh"
  });

  // Verification State Workflow
  const [verificationStep, setVerificationStep] = useState<'idle' | 'select' | 'upload' | 'pending'>('idle');
  const [selectedDocType, setSelectedDocType] = useState<'NID' | 'Passport' | null>(null);
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);
  
  // Verification Countdown State
  const [countdown, setCountdown] = useState(72 * 60 * 60); // 72 hours in seconds

  useEffect(() => {
    if (verificationStep === 'pending') {
      const timer = setInterval(() => {
        setCountdown((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [verificationStep]);

  const formatCountdown = (totalSeconds: number) => {
    const h = Math.floor(totalSeconds / 3600);
    const m = Math.floor((totalSeconds % 3600) / 60);
    const s = totalSeconds % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  // Load user data into form when available
  useEffect(() => {
    if (user) {
      setEditForm(prev => ({
        ...prev,
        name: user.name || "",
        email: user.email || ""
      }));
    }
  }, [user]);

  // Handle Profile Picture Upload
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && user) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        updateUser({
          ...user,
          image: base64String
        });
        toast.success("Profile picture updated successfully!");
      };
      reader.readAsDataURL(file);
    }
  };

  // Mock Verification State
  const profileCompletion = 80;
  const isReady = profileCompletion >= 80;

  const handleLogout = () => {
    logout();
    toast.success("Logged out successfully");
    router.push("/auth/login");
  };

  const handleSaveProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (user) {
      updateUser({
        ...user,
        name: editForm.name,
        email: editForm.email
      });
      toast.success("Profile saved successfully to the database!");
      setIsIdentityEditMode(false);
    }
  };

  const getProgressColor = (percent: number) => {
    if (percent < 50) return "bg-red-500";
    if (percent < 80) return "bg-amber-500";
    return "bg-emerald-500";
  };

  const getProgressBg = (percent: number) => {
    if (percent < 50) return "bg-red-100";
    if (percent < 80) return "bg-amber-100";
    return "bg-emerald-100";
  };

  const getProgressText = (percent: number) => {
    if (percent < 50) return "text-red-600";
    if (percent < 80) return "text-amber-600";
    return "text-emerald-600";
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 min-h-screen pb-24 lg:pb-10 relative overflow-hidden">
      
      {/* Decorative background blobs for glassmorphism refraction */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-400/20 rounded-full blur-[120px] pointer-events-none" />
      <div className="absolute top-[40%] right-[-10%] w-[30%] h-[50%] bg-emerald-400/10 rounded-full blur-[100px] pointer-events-none" />

      {/* Page Header */}
      <div className="relative z-10 px-4 sm:px-6 lg:px-8 py-5 lg:py-8">
        <div className="max-w-[1200px] mx-auto w-full flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-[24px] lg:text-[28px] font-black text-slate-800 flex items-center gap-3 tracking-tight">
              <div className="w-12 h-12 rounded-[16px]   to-slate-200/50 flex items-center justify-center shrink-0 border border-slate-200 shadow-sm">
                <Settings className="text-slate-700" size={24} strokeWidth={2.5} />
              </div>
              Settings
            </h1>
            <p className="text-slate-500 mt-2 text-[14px] lg:text-[15px]">Manage your account, preferences, and security.</p>
          </div>
        </div>
      </div>

      <div className="relative z-10 px-4 sm:px-6 lg:px-8 max-w-[1200px] mx-auto w-full mt-2 lg:mt-4">
        
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8">
          
          {/* Left Column: Profile Card & Tabs */}
          <div className="lg:col-span-4 space-y-6">
            
            {/* Profile Card */}
            <div className="bg-white/80 backdrop-blur-xl rounded-[20px] lg:rounded-[24px] p-6 shadow-[0_8px_30px_rgba(0,0,0,0.04)] border border-white/60 flex flex-col gap-6 relative overflow-hidden group">
              <div className="flex flex-col sm:flex-row lg:flex-col items-center lg:items-start gap-4">
                <div className="relative w-16 h-16 lg:w-20 lg:h-20 rounded-full bg-slate-100 flex items-center justify-center shrink-0 border-[3px] border-white shadow-md overflow-hidden group/avatar">
                  <Image 
                    src={user?.image || "https://api.dicebear.com/7.x/avataaars/svg?seed=Felix&backgroundColor=e0f2fe"} 
                    alt="Assistant Avatar"
                    fill
                    className="object-cover"
                  />
                  {/* Upload Overlay */}
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="absolute inset-0 bg-slate-900/40 flex items-center justify-center opacity-0 group-hover/avatar:opacity-100 transition-opacity cursor-pointer backdrop-blur-sm"
                  >
                    <Camera size={20} className="text-white" />
                  </div>
                  <input 
                    type="file" 
                    accept="image/*" 
                    className="hidden" 
                    ref={fileInputRef} 
                    onChange={handleImageUpload} 
                  />
                </div>
                <div className="flex-1 text-center sm:text-left lg:text-left">
                  <h2 className="text-[18px] lg:text-[20px] font-bold text-slate-800">{user?.name || "Assistant"}</h2>
                  <p className="text-[14px] text-[#2F80ED] font-bold capitalize">{user?.role || "Head Assistant"}</p>
                </div>
              </div>

              {/* Profile Completion Bar */}
              <div className={`p-4 rounded-xl border ${isReady ? 'bg-emerald-50/50 border-emerald-100' : 'bg-amber-50/50 border-amber-100'}`}>
                <div className="flex justify-between items-center mb-2">
                  <p className={`text-[12px] font-bold uppercase tracking-wider ${getProgressText(profileCompletion)}`}>
                    Profile Status
                  </p>
                  <p className={`text-[14px] font-extrabold ${getProgressText(profileCompletion)}`}>
                    {profileCompletion}%
                  </p>
                </div>
                <div className={`h-2.5 w-full rounded-full overflow-hidden ${getProgressBg(profileCompletion)}`}>
                  <div 
                    className={`h-full rounded-full transition-all duration-1000 ${getProgressColor(profileCompletion)}`} 
                    style={{ width: `${profileCompletion}%` }}
                  />
                </div>
                <p className="text-[12px] text-slate-500 mt-2 font-medium leading-relaxed">
                  {isReady 
                    ? "Verified. Doctors can send you connection invites." 
                    : "Complete 80% to accept doctor invites."}
                </p>
              </div>
            </div>

            {/* Desktop Navigation Tabs */}
            <div className="hidden lg:flex flex-col gap-2 bg-white/40 backdrop-blur-md border border-white/60 p-2 rounded-[20px]">
              <button 
                onClick={() => setActiveTab('profile')}
                className={`flex items-center gap-3 p-4 rounded-[14px] transition-all font-semibold ${activeTab === 'profile' ? 'bg-white shadow-sm text-[#2F80ED]' : 'text-slate-500 hover:bg-white/50'}`}
              >
                <User size={20} /> My Profile
              </button>
              <button 
                onClick={() => setActiveTab('security')}
                className={`flex items-center gap-3 p-4 rounded-[14px] transition-all font-semibold ${activeTab === 'security' ? 'bg-white shadow-sm text-[#2F80ED]' : 'text-slate-500 hover:bg-white/50'}`}
              >
                <Shield size={20} /> Security
              </button>
              <button 
                onClick={() => setActiveTab('preferences')}
                className={`flex items-center gap-3 p-4 rounded-[14px] transition-all font-semibold ${activeTab === 'preferences' ? 'bg-white shadow-sm text-[#2F80ED]' : 'text-slate-500 hover:bg-white/50'}`}
              >
                <Bell size={20} /> Preferences
              </button>
            </div>

          </div>

          {/* Right Column: Settings Content */}
          <div className="lg:col-span-8 pb-12 lg:pb-0">
            
            {/* Mobile Tabs */}
            <div className="lg:hidden flex overflow-x-auto gap-2 pb-4 hide-scrollbar">
              <button 
                onClick={() => setActiveTab('profile')}
                className={`whitespace-nowrap px-5 py-2.5 rounded-full font-bold text-[14px] transition-all ${activeTab === 'profile' ? 'bg-[#2F80ED] text-white shadow-md' : 'bg-white/60 text-slate-500 border border-white'}`}
              >
                My Profile
              </button>
              <button 
                onClick={() => setActiveTab('security')}
                className={`whitespace-nowrap px-5 py-2.5 rounded-full font-bold text-[14px] transition-all ${activeTab === 'security' ? 'bg-[#2F80ED] text-white shadow-md' : 'bg-white/60 text-slate-500 border border-white'}`}
              >
                Security
              </button>
              <button 
                onClick={() => setActiveTab('preferences')}
                className={`whitespace-nowrap px-5 py-2.5 rounded-full font-bold text-[14px] transition-all ${activeTab === 'preferences' ? 'bg-[#2F80ED] text-white shadow-md' : 'bg-white/60 text-slate-500 border border-white'}`}
              >
                Preferences
              </button>
            </div>

            {/* Content Area */}
            <AnimatePresence mode="wait">
              <motion.div
                key={activeTab}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
                className="space-y-6"
              >

                {/* PROFILE TAB */}
                {activeTab === 'profile' && (
                  <>
                    <div className="bg-white/80 backdrop-blur-xl rounded-[20px] lg:rounded-[24px] p-6 lg:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] border border-white/60 transition-all">
                      <div className="flex items-center justify-between mb-6">
                        <h3 className="text-[18px] font-bold text-slate-800 flex items-center gap-2">
                          <Fingerprint className="text-[#2F80ED]" /> Assistant Identity
                        </h3>
                        {isIdentityEditMode ? (
                          <button 
                            onClick={handleSaveProfile as any}
                            className="bg-[#2F80ED] hover:bg-blue-600 text-white px-3 py-1.5 rounded-lg text-[13px] font-bold flex items-center gap-1.5 transition-all shadow-sm active:scale-95"
                          >
                            <Save size={16} /> Save
                          </button>
                        ) : (
                          <button 
                            onClick={() => setIsIdentityEditMode(true)}
                            className="bg-slate-100 hover:bg-slate-200 text-slate-700 px-3 py-1.5 rounded-lg text-[13px] font-bold flex items-center gap-1.5 transition-all shadow-sm active:scale-95"
                          >
                            <Edit3 size={16} /> Edit
                          </button>
                        )}
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <div>
                          <label className="text-[12px] font-bold text-slate-400 uppercase tracking-wider block mb-1">Full Name</label>
                          {isIdentityEditMode ? (
                            <input 
                              type="text" 
                              value={editForm.name}
                              onChange={(e) => setEditForm({...editForm, name: e.target.value})}
                              className="w-full bg-white px-4 py-3 rounded-xl border border-blue-200 outline-none focus:ring-4 focus:ring-blue-100 transition-all text-[15px] font-semibold text-slate-800 shadow-sm"
                            />
                          ) : (
                            <p className="text-[15px] font-semibold text-slate-800 bg-slate-50 px-4 py-3 rounded-xl border border-slate-100 transition-all">{user?.name || "Not set"}</p>
                          )}
                        </div>
                        <div>
                          <label className="text-[12px] font-bold text-slate-400 uppercase tracking-wider block mb-1">Email Address</label>
                          {isIdentityEditMode ? (
                            <input 
                              type="email" 
                              value={editForm.email}
                              onChange={(e) => setEditForm({...editForm, email: e.target.value})}
                              className="w-full bg-white px-4 py-3 rounded-xl border border-blue-200 outline-none focus:ring-4 focus:ring-blue-100 transition-all text-[15px] font-semibold text-slate-800 shadow-sm"
                            />
                          ) : (
                            <p className="text-[15px] font-semibold text-slate-800 bg-slate-50 px-4 py-3 rounded-xl border border-slate-100 transition-all">{user?.email || "Not set"}</p>
                          )}
                        </div>
                        <div>
                          <label className="text-[12px] font-bold text-slate-400 uppercase tracking-wider block mb-1">Phone Number</label>
                          {isIdentityEditMode ? (
                            <input 
                              type="text" 
                              value={editForm.phone}
                              onChange={(e) => setEditForm({...editForm, phone: e.target.value})}
                              className="w-full bg-white px-4 py-3 rounded-xl border border-blue-200 outline-none focus:ring-4 focus:ring-blue-100 transition-all text-[15px] font-semibold text-slate-800 shadow-sm"
                            />
                          ) : (
                            <p className="text-[15px] font-semibold text-slate-800 bg-slate-50 px-4 py-3 rounded-xl border border-slate-100 transition-all">{editForm.phone}</p>
                          )}
                        </div>
                        <div>
                          <label className="text-[12px] font-bold text-slate-400 uppercase tracking-wider block mb-1">Assistant ID (Read-only)</label>
                          <div className="flex items-center gap-2 opacity-80 cursor-not-allowed">
                            <p className="text-[15px] font-mono font-bold text-[#2F80ED] bg-blue-50 px-4 py-3 rounded-xl border border-blue-100 flex-1">
                              492 183 029 155
                            </p>
                            <button 
                              onClick={() => {
                                navigator.clipboard.writeText("492183029155");
                                toast.success("ID Copied!");
                              }}
                              className="h-[46px] px-4 bg-white text-slate-600 font-bold rounded-xl border border-slate-200 hover:bg-slate-50 transition-colors shadow-sm"
                            >
                              Copy
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Verification Center (3-Step Workflow) */}
                    <div className="bg-white/80 backdrop-blur-xl rounded-[20px] lg:rounded-[24px] p-6 lg:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] border border-white/60">
                      <div className="flex items-center justify-between mb-6">
                        <h3 className="text-[18px] font-bold text-slate-800 flex items-center gap-2">
                          <FileCheck2 className="text-[#2F80ED]" /> Identity Verification
                        </h3>
                      </div>
                      
                      {verificationStep === 'idle' && (
                        <div className="text-center py-6 px-4">
                          <div className="w-16 h-16 bg-blue-50 text-[#2F80ED] rounded-full flex items-center justify-center mx-auto mb-4">
                            <Shield size={32} />
                          </div>
                          <h4 className="text-[16px] font-bold text-slate-800 mb-2">Verify your Identity</h4>
                          <p className="text-[14px] text-slate-500 mb-6 w-full whitespace-nowrap overflow-hidden text-ellipsis">
                            To ensure platform security, please verify your identity using a government-issued document.
                          </p>
                          <button 
                            onClick={() => setVerificationStep('select')}
                            className="bg-[#2F80ED] text-white px-6 py-3 rounded-xl font-bold text-[14px] hover:bg-blue-600 active:scale-95 transition-all shadow-md"
                          >
                            Start Verification
                          </button>
                        </div>
                      )}

                      {verificationStep === 'select' && (
                        <div>
                          <h4 className="text-[15px] font-bold text-slate-800 mb-4">Select Document Type</h4>
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <button 
                              onClick={() => {
                                setSelectedDocType('NID');
                                setVerificationStep('upload');
                              }}
                              className="p-5 border-2 border-slate-100 rounded-[16px] text-left hover:border-[#2F80ED] hover:bg-blue-50/30 transition-all group"
                            >
                              <FileText className="text-slate-400 group-hover:text-[#2F80ED] mb-3" size={28} />
                              <h5 className="text-[15px] font-bold text-slate-800 mb-1">National ID Card</h5>
                              <p className="text-[13px] text-slate-500">Government issued NID</p>
                            </button>
                            <button 
                              onClick={() => {
                                setSelectedDocType('Passport');
                                setVerificationStep('upload');
                              }}
                              className="p-5 border-2 border-slate-100 rounded-[16px] text-left hover:border-[#2F80ED] hover:bg-blue-50/30 transition-all group"
                            >
                              <Globe className="text-slate-400 group-hover:text-[#2F80ED] mb-3" size={28} />
                              <h5 className="text-[15px] font-bold text-slate-800 mb-1">Passport</h5>
                              <p className="text-[13px] text-slate-500">International Passport</p>
                            </button>
                          </div>
                          <button 
                            onClick={() => setVerificationStep('idle')}
                            className="mt-6 text-[14px] font-bold text-slate-500 hover:text-slate-700 transition-colors"
                          >
                            Cancel
                          </button>
                        </div>
                      )}

                      {verificationStep === 'upload' && (
                        <div>
                          <div className="flex items-center gap-3 mb-6">
                            <button onClick={() => setVerificationStep('select')} className="text-slate-400 hover:text-slate-700">
                              <ChevronRight className="rotate-180" size={20} />
                            </button>
                            <div>
                              <h4 className="text-[15px] font-bold text-slate-800">Upload {selectedDocType}</h4>
                              <p className="text-[13px] text-slate-500">Please provide a clear image of your document.</p>
                            </div>
                          </div>

                          <div className="border-2 border-dashed border-slate-200 rounded-[20px] p-8 text-center bg-slate-50/50 hover:bg-slate-50 transition-colors cursor-pointer relative group">
                            <input 
                              type="file" 
                              accept="image/*"
                              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                              onChange={(e) => {
                                if (e.target.files?.[0]) {
                                  setUploadedFileName(e.target.files[0].name);
                                }
                              }}
                            />
                            {uploadedFileName ? (
                              <div className="flex flex-col items-center">
                                <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-3">
                                  <ImageIcon size={28} />
                                </div>
                                <p className="text-[15px] font-bold text-emerald-600">{uploadedFileName}</p>
                                <p className="text-[13px] text-slate-500 mt-1">Click to change file</p>
                              </div>
                            ) : (
                              <div className="flex flex-col items-center">
                                <div className="w-16 h-16 bg-blue-50 text-[#2F80ED] rounded-full flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                                  <UploadCloud size={28} />
                                </div>
                                <p className="text-[15px] font-bold text-slate-700">Click to upload or drag and drop</p>
                                <p className="text-[13px] text-slate-500 mt-1">PNG, JPG up to 10MB</p>
                              </div>
                            )}
                          </div>

                          <div className="mt-6 flex gap-3">
                            <button 
                              onClick={() => setVerificationStep('select')}
                              className="flex-1 px-4 py-3 bg-slate-100 text-slate-700 font-bold rounded-xl hover:bg-slate-200 transition-colors"
                            >
                              Back
                            </button>
                            <button 
                              onClick={() => {
                                if (uploadedFileName) {
                                  setVerificationStep('pending');
                                  toast.success("Document submitted for review!");
                                } else {
                                  toast.error("Please select a file first");
                                }
                              }}
                              className={`flex-1 px-4 py-3 font-bold rounded-xl flex items-center justify-center gap-2 transition-all shadow-md ${uploadedFileName ? 'bg-[#2F80ED] text-white hover:bg-blue-600 active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                            >
                              Submit Document
                            </button>
                          </div>
                        </div>
                      )}

                      {verificationStep === 'pending' && (
                        <div className="bg-amber-50 border border-amber-200/60 rounded-[16px] p-6 text-center">
                          <div className="w-16 h-16 bg-amber-100 text-amber-500 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertCircle size={32} />
                          </div>
                          <h4 className="text-[16px] font-bold text-amber-700 mb-2">Pending Manual Review</h4>
                          <p className="text-[14px] text-amber-600/80 mb-6 max-w-4xl mx-auto leading-relaxed whitespace-nowrap overflow-hidden text-ellipsis">
                            Your {selectedDocType} has been submitted successfully. A Super Admin will manually review your document. Please allow up to <strong>72 hours</strong> for verification.
                          </p>
                          <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
                            <div className="inline-flex items-center gap-2 bg-amber-100/50 px-5 py-2.5 rounded-full text-amber-700 text-[14px] font-bold">
                              <Clock size={18} className="animate-pulse" />
                              Review in progress...
                            </div>
                            <div className="inline-flex items-center gap-2 bg-slate-800 px-5 py-2.5 rounded-full text-white text-[14px] font-bold shadow-md tracking-wider font-mono">
                              {formatCountdown(countdown)}
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  </>
                )}

                {/* SECURITY TAB */}
                {activeTab === 'security' && (
                  <div className="bg-white/80 backdrop-blur-xl rounded-[20px] lg:rounded-[24px] p-6 lg:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] border border-white/60">
                    <h3 className="text-[18px] font-bold text-slate-800 mb-6 flex items-center gap-2">
                      <Shield className="text-amber-500" /> Security Settings
                    </h3>
                    
                    <div className="space-y-6">
                      <div>
                        <label className="text-[13px] font-bold text-slate-700 block mb-2">Current Password</label>
                        <input type="password" placeholder="••••••••" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-[15px] outline-none focus:border-[#2F80ED] transition-colors" />
                      </div>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div>
                          <label className="text-[13px] font-bold text-slate-700 block mb-2">New Password</label>
                          <input type="password" placeholder="••••••••" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-[15px] outline-none focus:border-[#2F80ED] transition-colors" />
                        </div>
                        <div>
                          <label className="text-[13px] font-bold text-slate-700 block mb-2">Confirm New Password</label>
                          <input type="password" placeholder="••••••••" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-[15px] outline-none focus:border-[#2F80ED] transition-colors" />
                        </div>
                      </div>
                      <button 
                        onClick={() => toast.success("Password successfully updated!")}
                        className="bg-[#2F80ED] text-white px-6 py-3 rounded-xl font-bold text-[14px] hover:bg-[#256bc7] active:scale-95 transition-all shadow-md w-full sm:w-auto"
                      >
                        Update Password
                      </button>
                    </div>

                    <div className="mt-10 pt-6 border-t border-slate-100">
                      <h4 className="text-[16px] font-bold text-slate-800 mb-2">Two-Factor Authentication</h4>
                      <p className="text-[14px] text-slate-500 mb-4">Add an extra layer of security to your account.</p>
                      <button 
                        onClick={() => toast.success("2FA Setup initiated")}
                        className="bg-white border border-slate-200 text-slate-700 px-6 py-3 rounded-xl font-bold text-[14px] hover:bg-slate-50 active:scale-95 transition-all shadow-sm w-full sm:w-auto"
                      >
                        Enable 2FA
                      </button>
                    </div>
                  </div>
                )}

                {/* PREFERENCES TAB */}
                {activeTab === 'preferences' && (
                  <div className="space-y-6">
                    <div className="bg-white/80 backdrop-blur-xl rounded-[20px] lg:rounded-[24px] p-6 lg:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] border border-white/60">
                      <h3 className="text-[18px] font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <Settings className="text-slate-500" /> App Preferences
                      </h3>
                      
                      <div className="space-y-2">
                        <div className="w-full flex items-center justify-between p-4 rounded-xl hover:bg-slate-50/50 transition-colors">
                          <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-xl bg-amber-50 text-amber-500 flex items-center justify-center shrink-0">
                              <Bell size={22} />
                            </div>
                            <div>
                              <span className="text-[16px] font-semibold text-slate-800 block">Push Notifications</span>
                              <span className="text-[13px] text-slate-500">Receive alerts for queues and appointments</span>
                            </div>
                          </div>
                          <button 
                            onClick={() => {
                              setNotificationsEnabled(!notificationsEnabled);
                              toast(notificationsEnabled ? "Notifications Disabled" : "Notifications Enabled");
                            }}
                            className={`w-14 h-8 rounded-full transition-colors relative shadow-inner ${notificationsEnabled ? 'bg-[#22C55E]' : 'bg-slate-200'}`}
                          >
                            <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-transform shadow-md ${notificationsEnabled ? 'left-7' : 'left-1'}`} />
                          </button>
                        </div>
                        
                        <div className="w-full flex items-center justify-between p-4 rounded-xl hover:bg-slate-50/50 transition-colors">
                          <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-xl bg-indigo-50 text-indigo-500 flex items-center justify-center shrink-0">
                              <Moon size={22} />
                            </div>
                            <div>
                              <span className="text-[16px] font-semibold text-slate-800 block">Dark Mode</span>
                              <span className="text-[13px] text-slate-500">Toggle dark theme across the app</span>
                            </div>
                          </div>
                          <button 
                            onClick={() => {
                              setDarkMode(!darkMode);
                              toast.info("Dark mode coming soon!");
                            }}
                            className={`w-14 h-8 rounded-full transition-colors relative shadow-inner ${darkMode ? 'bg-[#2F80ED]' : 'bg-slate-200'}`}
                          >
                            <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-transform shadow-md ${darkMode ? 'left-7' : 'left-1'}`} />
                          </button>
                        </div>
                      </div>
                    </div>

                    <div className="bg-red-50/50 backdrop-blur-xl rounded-[20px] lg:rounded-[24px] p-6 shadow-sm border border-red-100">
                      <div className="flex items-center justify-between">
                        <div>
                          <h4 className="text-[16px] font-bold text-red-600 mb-1">Sign Out</h4>
                          <p className="text-[13px] text-red-400">Log out of your assistant account</p>
                        </div>
                        <button 
                          onClick={handleLogout}
                          className="bg-red-500 text-white px-5 py-2.5 rounded-xl font-bold text-[14px] flex items-center gap-2 hover:bg-red-600 active:scale-95 transition-all shadow-md"
                        >
                          <LogOut size={18} /> Logout
                        </button>
                      </div>
                    </div>
                  </div>
                )}

              </motion.div>
            </AnimatePresence>
            
            <p className="text-center text-[13px] text-slate-400 font-medium py-8 pb-12">
              Oxpecker AI App v1.2.0 • Production Level
            </p>

          </div>
        </div>
      </div>



    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  UserPlus, Phone, CalendarDays, Clock, 
  MapPin, Printer, Check, User, Banknote, CreditCard, Smartphone, ShieldAlert, BadgeCheck, CheckCircle2, Barcode
} from 'lucide-react';
import { toast } from 'sonner';
import { QRCodeSVG } from 'qrcode.react';

export default function WalkInPage() {
  const [isLoading, setIsLoading] = useState(true);
  
  // Form State
  const [formData, setFormData] = useState({
    name: '', age: '', gender: 'Male', phone: '',
    symptoms: '', doctor: '', priority: 'Normal',
    paymentMethod: 'Cash', discount: ''
  });
  const [phoneDigits, setPhoneDigits] = useState<string[]>(Array(11).fill(''));
  const [tokenId, setTokenId] = useState('S-' + Math.floor(Math.random() * 900 + 100));

  // Validation & Success State
  const [errors, setErrors] = useState<string[]>([]);
  const [isGenerated, setIsGenerated] = useState(false);
  
  // Derived Billing
  const fee = formData.doctor ? 1000 : 0; // Example dynamic fee
  const discountAmount = formData.discount ? (fee * (Number(formData.discount) / 100)) : 0;
  const total = fee - discountAmount;

  useEffect(() => {
    // Simulate fetching page layout/data
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error for this field if it exists
    if (errors.includes(field)) {
      setErrors(errors.filter(e => e !== field));
    }
  };

  const handleGenerate = () => {
    const newErrors = [];
    if (!formData.name.trim()) newErrors.push('name');
    if (!formData.age.trim()) newErrors.push('age');
    
    const fullPhone = phoneDigits.join('');
    if (fullPhone.length < 11) newErrors.push('phone');
    
    if (!formData.doctor) newErrors.push('doctor');

    if (newErrors.length > 0) {
      setErrors(newErrors);
      toast.error('Please fill in all required fields.');
      return;
    }

    // Success logic
    setIsGenerated(true);
    toast.success(`Token ${tokenId} generated successfully!`);
  };

  const handleReset = () => {
    setFormData({
      name: '', age: '', gender: 'Male', phone: '',
      symptoms: '', doctor: '', priority: 'Normal',
      paymentMethod: 'Cash', discount: ''
    });
    setPhoneDigits(Array(11).fill(''));
    setErrors([]);
    setIsGenerated(false);
    setTokenId('S-' + Math.floor(Math.random() * 900 + 100));
  };

  const handlePhoneDigitChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;
    const newDigits = [...phoneDigits];
    newDigits[index] = value;
    setPhoneDigits(newDigits);
    
    // Update formData for derived logic if needed
    setFormData(prev => ({ ...prev, phone: newDigits.join('') }));

    // Auto-focus next
    if (value && index < 10) {
      document.getElementById(`phone-digit-${index + 1}`)?.focus();
    }
  };

  const handlePhoneDigitKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Backspace' && !phoneDigits[index] && index > 0) {
      document.getElementById(`phone-digit-${index - 1}`)?.focus();
    }
  };

  if (isLoading) {
    return (
      <div className="w-full flex flex-col font-sans pb-24 -mt-6 lg:-mt-10 animate-pulse">
        {/* Skeleton Header */}
        <div className="bg-white/80 border-b border-white/50 px-4 lg:px-8 py-5 lg:py-6 shadow-[0_4px_30px_rgba(0,0,0,0.03)] -mx-4 sm:-mx-6 lg:-mx-10 mb-6 sm:mb-8 pt-6 lg:pt-10">
          <div className="max-w-[1200px] mx-auto w-full flex flex-col gap-2">
            <div className="h-8 bg-slate-200 rounded-lg w-64"></div>
            <div className="h-4 bg-slate-200 rounded-md w-80"></div>
          </div>
        </div>

        <div className="max-w-[1200px] mx-auto w-full px-4 sm:px-0">
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
            <div className="xl:col-span-2 space-y-6">
              <div className="bg-white rounded-[20px] shadow-sm border border-slate-100 p-8 h-[400px]"></div>
              <div className="bg-white rounded-[20px] shadow-sm border border-slate-100 p-8 h-[200px]"></div>
            </div>
            <div className="xl:col-span-1">
              <div className="bg-white rounded-[20px] shadow-sm border border-slate-100 p-6 h-[500px]"></div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full flex flex-col font-sans pb-24 -mt-6 lg:-mt-10">
      
      {/* Header (Edge to Edge, Scrollable, Glassmorphism) */}
      <div className="bg-white/80 backdrop-blur-xl border-b border-white/50 px-4 lg:px-8 py-5 lg:py-6 shadow-[0_4px_30px_rgba(0,0,0,0.03)] -mx-4 sm:-mx-6 lg:-mx-10 mb-6 sm:mb-8 pt-6 lg:pt-10">
        <div className="max-w-[1200px] mx-auto w-full flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <h1 className="text-[20px] lg:text-[24px] font-bold text-slate-800 flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-emerald-100 flex items-center justify-center shrink-0 shadow-inner">
                <UserPlus className="text-emerald-600" size={24} />
              </div>
              Walk-in Registration
            </h1>
            <p className="text-[13px] text-slate-500 font-medium mt-1">Register new walk-in patients and assign tokens instantly.</p>
          </div>
        </div>
      </div>

      <div className="max-w-[1200px] mx-auto w-full px-4 sm:px-0">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 lg:gap-8">
          
          {/* Left: Registration Form */}
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            className="xl:col-span-2 flex flex-col gap-6"
          >
            {/* --- 1. Patient Details Card --- */}
            <div className="bg-white rounded-[20px] shadow-sm border border-slate-200 overflow-hidden relative">
              <div className="p-5 lg:p-6 border-b border-slate-100 bg-slate-50/50">
                <h2 className="text-[18px] font-bold text-slate-800 flex items-center gap-2">
                  <span className="w-8 h-8 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[14px]">1</span> 
                  Patient Details
                </h2>
              </div>
              <div className="p-6 lg:p-8 grid grid-cols-1 md:grid-cols-2 gap-6">
                
                {/* Name */}
                <div className="md:col-span-2">
                  <label className="block text-[13px] font-bold text-slate-700 mb-2">Patient Full Name <span className="text-rose-500">*</span></label>
                  <div className="relative">
                    <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="e.g. Rahim Uddin"
                      value={formData.name}
                      onChange={(e) => handleInputChange('name', e.target.value)}
                      className={`w-full h-[48px] bg-slate-50 border ${errors.includes('name') ? 'border-rose-300 ring-4 ring-rose-50' : 'border-slate-200 focus:border-indigo-600 focus:ring-4 focus:ring-indigo-50'} rounded-xl pl-11 pr-4 text-[14px] font-medium text-slate-800 outline-none transition-all`}
                    />
                  </div>
                </div>

                {/* Age */}
                <div>
                  <label className="block text-[13px] font-bold text-slate-700 mb-2">Age <span className="text-rose-500">*</span></label>
                  <input 
                    type="number" 
                    placeholder="Years"
                    value={formData.age}
                    onChange={(e) => handleInputChange('age', e.target.value)}
                    className={`w-full h-[48px] bg-slate-50 border ${errors.includes('age') ? 'border-rose-300 ring-4 ring-rose-50' : 'border-slate-200 focus:border-indigo-600 focus:ring-4 focus:ring-indigo-50'} rounded-xl px-4 text-[14px] font-medium text-slate-800 outline-none transition-all`}
                  />
                </div>

                {/* Gender */}
                <div className="md:col-span-2">
                  <label className="block text-[13px] font-bold text-slate-700 mb-2">Gender <span className="text-rose-500">*</span></label>
                  <div className="flex gap-3">
                    {['Male', 'Female', 'Other'].map(g => (
                      <button
                        key={g}
                        onClick={() => handleInputChange('gender', g)}
                        className={`flex-1 h-[48px] rounded-xl text-[14px] font-bold border-2 transition-all flex items-center justify-center gap-2 ${
                          formData.gender === g 
                            ? 'border-indigo-500 bg-indigo-50 text-indigo-700 shadow-sm' 
                            : 'border-slate-100 bg-slate-50 text-slate-500 hover:border-slate-200'
                        }`}
                      >
                        {g}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Phone - 11 Digit Boxes */}
                <div className="md:col-span-2">
                  <div className="flex items-center justify-between mb-2">
                    <label className="block text-[13px] font-bold text-slate-700">Phone Number (11 Digits) <span className="text-rose-500">*</span></label>
                    {phoneDigits.join('').length > 0 && phoneDigits.join('').length < 11 && (
                      <span className="text-[12px] font-medium text-amber-500 bg-amber-50 px-2 py-0.5 rounded-full">Incomplete</span>
                    )}
                    {phoneDigits.join('').length === 11 && (
                      <span className="text-[12px] font-bold text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full flex items-center gap-1"><CheckCircle2 size={12}/> Verified</span>
                    )}
                  </div>
                  <div className={`flex gap-1 sm:gap-1.5 p-1 rounded-xl transition-all ${errors.includes('phone') ? 'bg-rose-50 p-2 border border-rose-200' : ''}`}>
                    {phoneDigits.map((digit, index) => (
                      <input 
                        key={index}
                        id={`phone-digit-${index}`}
                        type="text"
                        maxLength={1}
                        value={digit}
                        onChange={(e) => handlePhoneDigitChange(index, e.target.value)}
                        onKeyDown={(e) => handlePhoneDigitKeyDown(index, e)}
                        placeholder="-"
                        className={`w-full min-w-0 max-w-[44px] h-10 sm:h-12 shrink-1 rounded-lg text-center text-[16px] sm:text-[18px] font-bold outline-none transition-all shadow-sm ${
                          digit 
                            ? 'bg-white border-2 border-indigo-400 text-indigo-700 placeholder-transparent' 
                            : 'bg-slate-50 text-slate-800 border border-slate-200 focus:border-indigo-400 focus:bg-white focus:ring-2 focus:ring-indigo-100 placeholder-slate-300'
                        }`}
                      />
                    ))}
                  </div>
                </div>

                {/* Symptoms */}
                <div className="md:col-span-2">
                  <label className="block text-[13px] font-bold text-slate-700 mb-2">Symptoms / Reason for Visit</label>
                  <textarea 
                    rows={3}
                    placeholder="Briefly describe the symptoms..."
                    value={formData.symptoms}
                    onChange={(e) => handleInputChange('symptoms', e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-[14px] font-medium text-slate-800 outline-none focus:border-indigo-600 focus:ring-4 focus:ring-indigo-50 transition-all resize-none min-h-[100px]"
                  ></textarea>
                </div>
              </div>
            </div>

            {/* --- 2. Assignment Card --- */}
            <div className="bg-white rounded-[20px] shadow-sm border border-slate-200 overflow-hidden relative">
              <div className="p-5 lg:p-6 border-b border-slate-100 bg-slate-50/50">
                <h2 className="text-[18px] font-bold text-slate-800 flex items-center gap-2">
                  <span className="w-8 h-8 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[14px]">2</span> 
                  Assignment & Priority
                </h2>
              </div>
              <div className="p-6 lg:p-8 grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                  <label className="block text-[13px] font-bold text-slate-700 mb-2">Assign Doctor <span className="text-rose-500">*</span></label>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {[
                      { id: 'Dr. Farzana Alam', name: 'Dr. Farzana Alam', dept: 'Gynecology', color: 'pink' },
                      { id: 'Dr. Hasan', name: 'Dr. Hasan', dept: 'Cardiology', color: 'blue' }
                    ].map(doc => {
                      const isSelected = formData.doctor === doc.id;
                      const colors = {
                        pink: isSelected ? 'bg-pink-50 border-pink-400 ring-4 ring-pink-50' : 'bg-white border-slate-200 hover:border-pink-200',
                        blue: isSelected ? 'bg-blue-50 border-blue-400 ring-4 ring-blue-50' : 'bg-white border-slate-200 hover:border-blue-200'
                      }[doc.color];
                      
                      return (
                        <button 
                          key={doc.id}
                          onClick={() => handleInputChange('doctor', doc.id)}
                          className={`p-4 rounded-xl border-2 text-left transition-all ${colors} ${errors.includes('doctor') && !formData.doctor ? 'border-rose-300 ring-4 ring-rose-50' : ''}`}
                        >
                          <h3 className="font-bold text-slate-800 text-[15px]">{doc.name}</h3>
                          <p className="text-[13px] font-medium text-slate-500">{doc.dept}</p>
                        </button>
                      );
                    })}
                  </div>
                </div>
                <div>
                  <label className="block text-[13px] font-bold text-slate-700 mb-2">Priority Level</label>
                  <div className="flex bg-slate-100 p-1 rounded-xl h-[48px]">
                    <button 
                      onClick={() => handleInputChange('priority', 'Normal')}
                      className={`flex-1 rounded-[8px] text-[13px] font-bold transition-all ${formData.priority === 'Normal' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      Normal
                    </button>
                    <button 
                      onClick={() => handleInputChange('priority', 'Urgent')}
                      className={`flex-1 rounded-[8px] text-[13px] font-bold transition-all ${formData.priority === 'Urgent' ? 'bg-rose-500 text-white shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      Urgent
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* --- 3. Billing & Payment Card --- */}
            <div className="bg-white rounded-[20px] shadow-sm border border-slate-200 overflow-hidden relative">
              <div className="p-5 lg:p-6 border-b border-slate-100 bg-slate-50/50">
                <h2 className="text-[18px] font-bold text-slate-800 flex items-center gap-2">
                  <span className="w-8 h-8 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[14px]">3</span> 
                  Billing & Payment
                </h2>
              </div>
              <div className="p-6 lg:p-8">
                <div className="flex flex-col md:flex-row gap-8">
                  {/* Payment Methods */}
                  <div className="flex-1 space-y-3">
                    <label className="block text-[13px] font-bold text-slate-700 mb-2">Select Payment Method</label>
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                      <button 
                        onClick={() => handleInputChange('paymentMethod', 'Cash')}
                        className={`h-[56px] rounded-xl flex items-center justify-center gap-2 text-[14px] font-bold border-2 transition-all ${formData.paymentMethod === 'Cash' ? 'border-emerald-500 bg-emerald-50 text-emerald-700' : 'border-slate-100 bg-white text-slate-500 hover:border-slate-200'}`}
                      >
                        <Banknote size={20} /> Cash
                      </button>
                      <button 
                        onClick={() => handleInputChange('paymentMethod', 'bKash')}
                        className={`h-[56px] rounded-xl flex items-center justify-center gap-2 text-[14px] font-bold border-2 transition-all ${formData.paymentMethod === 'bKash' ? 'border-pink-500 bg-pink-50 text-pink-700' : 'border-slate-100 bg-white text-slate-500 hover:border-slate-200'}`}
                      >
                        <Smartphone size={20} /> bKash
                      </button>
                      <button 
                        onClick={() => handleInputChange('paymentMethod', 'Card')}
                        className={`h-[56px] rounded-xl flex items-center justify-center gap-2 text-[14px] font-bold border-2 transition-all ${formData.paymentMethod === 'Card' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-slate-100 bg-white text-slate-500 hover:border-slate-200'}`}
                      >
                        <CreditCard size={20} /> Card
                      </button>
                    </div>
                  </div>

                  {/* Summary */}
                  <div className="w-full md:w-[280px] bg-slate-50 rounded-xl p-5 border border-slate-200 flex flex-col justify-center">
                    <div className="flex justify-between items-center text-[14px] mb-2">
                      <span className="text-slate-500 font-medium">Consultation Fee</span>
                      <span className="font-bold text-slate-800">৳{fee}</span>
                    </div>
                    <div className="flex justify-between items-center text-[14px] pb-3 border-b border-slate-200 mb-3 gap-4">
                      <span className="text-slate-500 font-medium whitespace-nowrap">Discount (%)</span>
                      <input 
                        type="number" 
                        placeholder="0"
                        value={formData.discount}
                        onChange={(e) => handleInputChange('discount', e.target.value)}
                        className="w-20 h-8 bg-white border border-slate-200 rounded-lg px-2 text-right text-[14px] font-bold text-slate-800 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 transition-all"
                      />
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-[15px] font-bold text-slate-800">Total Payable</span>
                      <span className="text-[24px] font-black text-indigo-600">৳{total}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Actions */}
            <div className="flex flex-col sm:flex-row gap-4 justify-end mt-2">
              <button 
                onClick={handleReset}
                className="h-[56px] px-8 bg-white border border-slate-200 text-slate-700 font-bold text-[15px] rounded-xl hover:bg-slate-50 transition-colors"
              >
                Clear Form
              </button>
              <button 
                onClick={handleGenerate}
                disabled={isGenerated}
                className={`h-[56px] px-10 text-white font-bold text-[16px] rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 w-full sm:w-auto ${isGenerated ? 'bg-emerald-500 shadow-emerald-500/25' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-600/25 active:scale-95'}`}
              >
                {isGenerated ? <><CheckCircle2 size={20} /> Token Generated</> : 'Generate Token & Bill'}
              </button>
            </div>
          </motion.div>

          {/* Right: Live Preview & Print */}
          <motion.div 
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2, duration: 0.4 }}
            className="xl:col-span-1"
          >
            <div className="sticky top-[100px] flex flex-col gap-6">
              
              <div className={`bg-white rounded-[24px] shadow-sm border p-6 lg:p-8 flex flex-col items-center text-center transition-colors duration-500 ${isGenerated ? 'border-emerald-200 shadow-emerald-100/50' : 'border-slate-200'}`}>
                <div className="flex items-center justify-between w-full mb-6">
                  <span className="text-[12px] text-slate-400 font-bold uppercase tracking-widest">Live Preview</span>
                  {isGenerated && <span className="bg-emerald-100 text-emerald-600 text-[11px] font-bold px-2 py-0.5 rounded-full flex items-center gap-1"><BadgeCheck size={12}/> Ready</span>}
                </div>
                
                {/* The Ticket */}
                <div className="w-full relative bg-white border-2 border-dashed border-slate-200 rounded-[20px] p-6 lg:p-8 mb-6 shadow-sm">
                  {/* Decorative Ticket Cutouts */}
                  <div className="absolute top-1/2 -left-3 w-6 h-6 bg-white border-r-2 border-dashed border-slate-200 rounded-full -translate-y-1/2"></div>
                  <div className="absolute top-1/2 -right-3 w-6 h-6 bg-white border-l-2 border-dashed border-slate-200 rounded-full -translate-y-1/2"></div>

                  <h3 className="text-[18px] font-black text-slate-800 mb-6 text-center">Oxpecker AI Hospital</h3>
                  
                  <div className="flex flex-col items-center justify-center mb-6">
                    <div className={`mb-4 transition-opacity duration-500 ${isGenerated ? 'opacity-100' : 'opacity-30'}`}>
                      <img 
                        src={`https://bwipjs-api.metafloor.com/?bcid=code128&text=${tokenId}&scale=3&height=10&includetext=false`} 
                        alt="Token Barcode" 
                        className="h-[60px] w-auto object-contain mix-blend-multiply"
                      />
                    </div>

                    <div className="text-[11px] text-slate-400 font-bold uppercase tracking-widest mb-1">Token Number</div>
                    <div className={`text-[56px] font-black leading-none transition-colors ${isGenerated ? 'text-emerald-500' : 'text-slate-800'}`}>
                      {tokenId}
                    </div>
                  </div>
                  
                  <div className="flex flex-col gap-4 text-left border-t-2 border-dashed border-slate-100 pt-6">
                    <div className="flex justify-between items-end gap-2">
                      <div>
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Patient Name</p>
                        <p className="font-bold text-slate-800 text-[15px]">{formData.name || 'Not specified'}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Age</p>
                        <p className="font-bold text-slate-800 text-[15px]">{formData.age ? `${formData.age} Y` : '--'}</p>
                      </div>
                    </div>
                    <div>
                      <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Phone Number</p>
                      <p className="font-bold text-slate-800 text-[15px]">{phoneDigits.join('') || 'Not specified'}</p>
                    </div>
                    <div>
                      <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Assigned Doctor</p>
                      <p className="font-bold text-slate-800 text-[15px]">{formData.doctor || 'Not assigned'}</p>
                    </div>
                    <div className="grid grid-cols-2 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100 mt-2">
                      <div>
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Payment</p>
                        <p className="font-bold text-slate-700 text-[14px]">{formData.paymentMethod}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Discount</p>
                        <p className="font-bold text-slate-700 text-[14px]">{formData.discount ? `${formData.discount}%` : '0%'}</p>
                      </div>
                      <div>
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Total Paid</p>
                        <p className="font-black text-indigo-600 text-[16px]">৳{total}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Priority</p>
                        <p className={`font-bold text-[14px] ${formData.priority === 'Urgent' ? 'text-rose-500' : 'text-slate-700'}`}>{formData.priority}</p>
                      </div>
                    </div>
                  </div>
                </div>

                <button 
                  disabled={!isGenerated}
                  className={`w-full h-[56px] font-bold text-[15px] rounded-xl flex items-center justify-center gap-2 transition-all ${isGenerated ? 'bg-slate-800 text-white hover:bg-slate-900 shadow-md active:scale-95' : 'bg-slate-50 text-slate-400 border border-slate-200 cursor-not-allowed'}`}
                >
                  <Printer size={20} /> Print Token
                </button>
              </div>
            </div>
          </motion.div>

        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useRef, useEffect, useCallback, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { WelcomeScreen } from "@/components/chat/WelcomeScreen";
import { ChatInput, ChatMode } from "@/components/chat/ChatInput";
import { MessageBubble } from "@/components/chat/MessageBubble";
import { ArrowRight, AlertTriangle, Phone } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import Image from "next/image";
import { detectEmergency } from "@/lib/ai/emergency-detector";
import PerspectiveGrid3D from "@/components/shared/PerspectiveGrid3D";
import { useChatHistory, Message } from "@/context/ChatHistoryContext";

type EmergencyAlert = {
  type: string;
  condition: string;
  severity: string;
  message: string;
  callNumber: string;
};

function ChatContent() {
  const searchParams = useSearchParams();
  const initialQuery = searchParams?.get("q");
  const autoSentRef = useRef(false);

  const { activeThreadId, getActiveThread, addMessageToThread, createNewThread, updateMessageInThread, updateThreadTitle, isLoaded } = useChatHistory();

  // Create a thread if none exists on mount, but ONLY after localStorage is loaded
  useEffect(() => {
    if (isLoaded && !activeThreadId) {
      createNewThread("New Chat");
    }
  }, [isLoaded, activeThreadId, createNewThread]);

  const activeThread = getActiveThread();
  const messages = activeThread?.messages || [];

  const [isTyping, setIsTyping] = useState(false);
  const [selectedMode, setSelectedMode] = useState<ChatMode | null>(null);
  const [emergencyAlert, setEmergencyAlert] = useState<EmergencyAlert | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  // Parse emergency alerts from AI response
  const parseStructuredBlocks = useCallback((content: string) => {
    const emergencyMatch = content.match(/```json:emergency_alert\s*\n?([\s\S]*?)```/);
    if (emergencyMatch) {
      try {
        const alert = JSON.parse(emergencyMatch[1]);
        setEmergencyAlert(alert);
      } catch { /* ignore parse errors */ }
    }
  }, []);

  const handleSend = async (text?: string, customMode?: ChatMode | null) => {
    const activeMode = customMode || selectedMode;
    const userMsgContent = (text || "").trim();
    if (!userMsgContent && !activeMode) return;

    let apiContent = userMsgContent;
    let displayContent = userMsgContent;

    if (activeMode) {
      const additionalText = userMsgContent ? `\n\n${userMsgContent}` : "";
      const basePrompt = activeMode.promptText ? `\n\n${activeMode.promptText}` : "";
      apiContent = `[Action: ${activeMode.title}]${basePrompt}${additionalText}`;

      displayContent = `|MODE:${activeMode.title}|${userMsgContent}`;
      setSelectedMode(null);
    }

    // Determine thread ID and title for Sidebar
    const threadTitleToUse = activeMode?.title || (userMsgContent.length > 25 ? userMsgContent.substring(0, 25) + "..." : userMsgContent);
    const threadIdToUse = activeThreadId || createNewThread(threadTitleToUse);
    if (activeMode?.title) {
      updateThreadTitle(threadIdToUse, activeMode.title);
    }

    // Filter existing messages for non-empty text content
    const existingMessages = (activeThread?.messages || [])
      .filter(m => m.content && m.content.trim().length > 0);

    // Add user message to UI
    const userMsg: Message = { id: Date.now().toString(), role: "user", content: displayContent };
    addMessageToThread(threadIdToUse, userMsg);
    setIsTyping(true);
    setEmergencyAlert(null);

    // Client-side instant emergency detection
    const emergencyResult = detectEmergency(apiContent);
    if (emergencyResult) {
      setEmergencyAlert({
        type: 'emergency',
        condition: emergencyResult.condition,
        severity: emergencyResult.severity,
        message: emergencyResult.message,
        callNumber: emergencyResult.callNumber,
      });
    }

    // Update thread title if this is the first message
    if (existingMessages.length === 0) {
      updateThreadTitle(threadIdToUse, threadTitleToUse);
    }

    // Create placeholder bot message for streaming
    const botMsgId = (Date.now() + 1).toString();
    const botMsg: Message = { id: botMsgId, role: "bot", content: "" };
    addMessageToThread(threadIdToUse, botMsg);

    try {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      abortControllerRef.current = new AbortController();

      let pContext: any = null;
      if (typeof window !== "undefined") {
        const stored = localStorage.getItem("oxpecker_user");
        if (stored) {
          try { pContext = JSON.parse(stored); } catch {}
        }
      }

      const apiMessages = [
        ...existingMessages.map(m => ({
          role: m.role === "bot" ? ("assistant" as const) : ("user" as const),
          content: m.content,
        })),
        { role: "user" as const, content: apiContent }
      ];

      const response = await fetch("/api/ai/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          messages: apiMessages,
          patientContext: pContext
        }),
        signal: abortControllerRef.current.signal 
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Server error: ${response.status}`);
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error("No response stream");

      const decoder = new TextDecoder();
      let fullContent = "";
      let buffer = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() || "";

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || trimmed === "data: [DONE]") continue;
          if (trimmed.startsWith("data: ")) {
            try {
              const data = JSON.parse(trimmed.slice(6));
              if (data.content) {
                fullContent += data.content;
                updateMessageInThread(threadIdToUse, botMsgId, fullContent);
              }
            } catch {}
          }
        }
      }

      parseStructuredBlocks(fullContent);

    } catch (error: any) {
      if (error.name === "AbortError") return;
      console.error("[Oxpecker AI] Stream error:", error);
      updateMessageInThread(
        threadIdToUse, 
        botMsgId, 
        `⚠️ **Error:** ${error.message || "Something went wrong. Please try again."}`
      );
    } finally {
      setIsTyping(false);
    }
  };

  // Auto-send query passed via URL parameter e.g. /chat?q=হ্যালো
  useEffect(() => {
    if (initialQuery && initialQuery.trim() && !autoSentRef.current) {
      autoSentRef.current = true;
      handleSend(initialQuery.trim());
    }
  }, [initialQuery]);

  const handleWelcomeSelect = (modeItem: any) => {
    const modeObj: ChatMode = { 
      icon: modeItem.icon, 
      title: modeItem.title, 
      color: modeItem.color, 
      bg: modeItem.bg,
      promptText: modeItem.promptText 
    };
    setSelectedMode(modeObj);
  };

  const followUpChips = [
    "Explain More", "Find Doctors", "Compare Medicines", "Book Appointment"
  ];

  const handleFileUpload = async (file: File, analysisType: string) => {
    const analysisEndpoints: Record<string, string> = {
      prescription: '/api/ai/analyze-prescription',
      report: '/api/ai/analyze-report',
      food: '/api/ai/analyze-food',
      image: '/api/ai/analyze-image',
    };

    const analysisLabels: Record<string, string> = {
      prescription: '📋 Analyzing Prescription',
      report: '📊 Analyzing Medical Report',
      food: '🍽️ Analyzing Food & Nutrition',
      image: '🔬 Analyzing Medical Image',
    };

    const endpoint = analysisEndpoints[analysisType] || analysisEndpoints.image;
    const label = analysisLabels[analysisType] || '🔍 Analyzing Image';

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: `📎 Uploaded: **${file.name}** (${label})`,
    };
    if (activeThreadId) addMessageToThread(activeThreadId, userMsg);
    setIsTyping(true);

    const botMsgId = (Date.now() + 1).toString();
    if (activeThreadId) {
      addMessageToThread(activeThreadId, { id: botMsgId, role: 'bot', content: '' });
    }

    try {
      const formData = new FormData();
      formData.append('image', file);

      const response = await fetch(endpoint, {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Analysis failed: ${response.status}`);
      }

      const data = await response.json();
      const analysisContent = data.analysis || 'Analysis could not be completed.';
      parseStructuredBlocks(analysisContent);

      if (activeThreadId) {
        updateMessageInThread(activeThreadId, botMsgId, analysisContent);
      }
    } catch (error: any) {
      if (activeThreadId) {
        updateMessageInThread(activeThreadId, botMsgId, `⚠️ **Analysis Error:** ${error.message}`);
      }
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="relative flex flex-col h-full bg-white overflow-hidden">

      {/* Emergency Alert Banner */}
      <AnimatePresence>
        {emergencyAlert && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="bg-red-600 text-white overflow-hidden z-50 relative"
          >
            <div className="max-w-[900px] mx-auto px-4 py-4 flex flex-col sm:flex-row items-start sm:items-center gap-3">
              <div className="flex items-center gap-3 flex-1">
                <motion.div
                  animate={{ scale: [1, 1.2, 1] }}
                  transition={{ duration: 1, repeat: Infinity }}
                >
                  <AlertTriangle size={28} />
                </motion.div>
                <div>
                  <p className="font-black text-[16px]">⚠️ EMERGENCY DETECTED: {emergencyAlert.condition}</p>
                  <p className="text-[14px] text-red-100 mt-0.5">{emergencyAlert.message}</p>
                </div>
              </div>
              <a
                href={`tel:${emergencyAlert.callNumber}`}
                className="flex items-center gap-2 bg-white text-red-600 font-bold px-5 py-2.5 rounded-xl text-[14px] hover:bg-red-50 transition-colors shrink-0 shadow-lg"
              >
                <Phone size={18} /> Call {emergencyAlert.callNumber}
              </a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 3D Perspective Grid Background */}
      <div className="absolute inset-0 pointer-events-none z-0 opacity-60">
        <PerspectiveGrid3D variant="chat" fadeRadius={85} />
      </div>

      {/* Background Watermark */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] select-none">
        <div className="relative w-[300px] h-[300px] md:w-[400px] md:h-[400px] grayscale">
          <Image 
            src="/images/Oxpecker_icon.png" 
            alt="Watermark" 
            fill 
            className="object-contain"
            priority
          />
        </div>
      </div>

      {/* Main Scrollable Area */}
      <div className="flex-1 overflow-y-auto scrollbar-thin pt-8 pb-4 relative z-10">
        <div className="max-w-[900px] mx-auto w-full px-4 md:px-8">

          {messages.length === 0 ? (
            <WelcomeScreen onSelect={handleWelcomeSelect} />
          ) : (
            <div className="flex flex-col space-y-2 mt-4 md:mt-8 pb-10">
              {messages.map((msg) => {
                if (isTyping && msg.role === "bot" && msg.content === "") return null;
                return <MessageBubble key={msg.id} role={msg.role} content={msg.content} />;
              })}

              {isTyping && messages[messages.length - 1]?.content === "" && (
                <div className="flex justify-start mb-6">
                  <div className="flex gap-4 w-[760px] max-w-full">
                    <div className="relative shrink-0 w-10 h-10 rounded-full flex items-center justify-center mt-1 bg-sky-600/5 ring-1 ring-primary/20 shadow-sm overflow-hidden">
                      <motion.div
                        animate={{ opacity: [0.3, 0.8, 0.3], scale: [0.95, 1.05, 0.95] }}
                        transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}
                        className="absolute inset-0 bg-sky-600/10 rounded-full"
                      />
                      <Image src="/images/Oxpecker_icon.png" alt="AI Processing" fill sizes="40px" className="object-contain p-2 relative z-10" />
                    </div>

                    <div className="flex items-center">
                      <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        className="text-[14px] text-sky-600/70 font-medium flex items-center gap-1.5"
                      >
                        Oxpecker AI is analyzing
                        <span className="flex gap-0.5">
                          <motion.span animate={{ opacity: [0, 1, 0] }} transition={{ duration: 1.5, repeat: Infinity, delay: 0 }}>.</motion.span>
                          <motion.span animate={{ opacity: [0, 1, 0] }} transition={{ duration: 1.5, repeat: Infinity, delay: 0.2 }}>.</motion.span>
                          <motion.span animate={{ opacity: [0, 1, 0] }} transition={{ duration: 1.5, repeat: Infinity, delay: 0.4 }}>.</motion.span>
                        </span>
                      </motion.div>
                    </div>
                  </div>
                </div>
              )}

              {!isTyping && messages.length > 0 && messages[messages.length - 1].role === "bot" && messages[messages.length - 1].content !== "" && (
                <motion.div 
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="flex flex-wrap gap-2 mt-2 ml-12"
                >
                  {followUpChips.map((chip, idx) => (
                    <button 
                      key={idx}
                      onClick={() => handleSend(chip)}
                      className="flex items-center gap-1.5 h-[38px] px-4 rounded-full bg-white border border-slate-200 text-slate-600 text-[14px] font-medium hover:border-primary/50 hover:text-sky-600 transition-colors shadow-sm"
                    >
                      {chip} <ArrowRight size={14} className="opacity-50" />
                    </button>
                  ))}
                </motion.div>
              )}

              <div ref={messagesEndRef} className="h-4" />
            </div>
          )}
        </div>
      </div>

      {/* Input Area */}
      <ChatInput 
        onSend={(t) => handleSend(t)} 
        onFileUpload={handleFileUpload}
        selectedMode={selectedMode} 
        onSelectMode={setSelectedMode}
      />
    </div>
  );
}

export default function ChatPage() {
  return (
    <Suspense fallback={<div className="h-full w-full bg-white flex items-center justify-center text-slate-400">Loading Chat...</div>}>
      <ChatContent />
    </Suspense>
  );
}

"use client";

import { useState } from "react";
import { 
  Calendar, Clock, Search, Filter, MoreVertical, CheckCircle2, 
  XCircle, Clock3, CalendarClock, User, Phone, Edit
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast, Toaster } from "sonner";

import { useDoctor } from "@/context/DoctorContext";

export default function DoctorAppointmentsPage() {
  const [activeTab, setActiveTab] = useState<"Today" | "Upcoming" | "Past">("Today");
  const [searchQuery, setSearchQuery] = useState("");
