    // Search match
    const matchSearch = apt.name.toLowerCase().includes(searchQuery.toLowerCase()) || apt.token.toLowerCase().includes(searchQuery.toLowerCase());
    
    // Tab match
    let matchTab = false;
    if (activeTab === "Today") matchTab = apt.date === "Today";
    else if (activeTab === "Upcoming") matchTab = apt.date === "Tomorrow" || apt.date.includes("202");
    else if (activeTab === "Past") matchTab = apt.date === "Yesterday" || apt.status === "Cancelled";
    
    return matchSearch && matchTab;
  });

  const handleCancelAppointmentLocal = (id: string) => {
    cancelAppointment(id);
    setActionMenuOpen(null);
    const notifsStr = localStorage.getItem('oxpecker_notifications');
    const notifs = notifsStr ? JSON.parse(notifsStr) : [];
    notifs.push({ 
      id: Date.now().toString(), 
      targetId: 'assistant', 
      message: `Doctor cancelled appointment ${id}.`, 
      read: false 
    });
    localStorage.setItem('oxpecker_notifications', JSON.stringify(notifs));
  };

  const handleReschedule = (id: string) => {
    toast.success("Reschedule request sent to Assistant.", { style: { background: '#2F80ED', color: 'white' }});
    setActionMenuOpen(null);
  };

  return (
    <div className="p-4 lg:p-6 space-y-6 bg-slate-950 min-h-[calc(100vh-80px)] w-full max-w-[1600px] mx-auto overflow-y-auto pb-20">
      
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-[24px] font-extrabold text-slate-200 flex items-center gap-2">
            Appointments Management
          </h1>
          <p className="text-slate-500 mt-1">Manage your schedule and coordinate with your assistants.</p>
        </div>
      </div>

      {/* Controls: Tabs & Search */}
      <div className="bg-slate-900 rounded-[20px] shadow-none border border-slate-800 p-4 flex flex-col lg:flex-row justify-between items-center gap-4">
        
        {/* Tabs */}
        <div className="flex bg-slate-950 p-1.5 rounded-xl border border-slate-800 w-full lg:w-auto">
