              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl pl-11 pr-4 text-[14px] focus:outline-none focus:border-[#2F80ED] transition-colors"
            />
          </div>
