                      </td>

                      {/* Type */}
                      <td className="px-6 py-4 font-medium text-slate-500">
                        {apt.type}
                      </td>

                      {/* Booked By (Assistant Sync) */}
                      <td className="px-6 py-4">
                        {apt.bookedBy === "Online" ? (
                          <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-slate-800 text-slate-500 rounded-full text-[12px] font-bold">
                            <User size={12} /> Online Patient
                          </span>
                        ) : (
                          <div className="flex flex-col">
                            <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-[#8B5CF6]/10 text-[#8B5CF6] rounded-full text-[12px] font-bold w-fit">
                              <User size={12} /> Assistant
                            </span>
                            <span className="text-[12px] text-slate-500 mt-1 font-medium pl-1">
                              {apt.assistant}
                            </span>
                          </div>
                        )}
                      </td>

                      {/* Status */}
                      <td className="px-6 py-4">
                        {apt.status === "Completed" && <span className="text-[12px] font-bold text-[#22C55E] bg-[#22C55E]/10 px-3 py-1.5 rounded-lg flex items-center gap-1 w-fit"><CheckCircle2 size={14}/> Completed</span>}
                        {apt.status === "Waiting" && <span className="text-[12px] font-bold text-[#F59E0B] bg-[#F59E0B]/10 px-3 py-1.5 rounded-lg flex items-center gap-1 w-fit"><Clock3 size={14}/> Waiting</span>}
                        {apt.status === "Upcoming" && <span className="text-[12px] font-bold text-[#2F80ED] bg-sky-500/10 px-3 py-1.5 rounded-lg flex items-center gap-1 w-fit"><CalendarClock size={14}/> Upcoming</span>}
                        {apt.status === "Cancelled" && <span className="text-[12px] font-bold text-red-500 bg-red-50 px-3 py-1.5 rounded-lg flex items-center gap-1 w-fit"><XCircle size={14}/> Cancelled</span>}
                      </td>

                      {/* Actions */}
                      <td className="px-6 py-4 text-right relative">
                        <button 
                          onClick={() => setActionMenuOpen(actionMenuOpen === apt.id ? null : apt.id)}
                          className="w-10 h-10 rounded-full hover:bg-slate-800 flex items-center justify-center text-slate-500 transition-colors ml-auto"
                        >
                          <MoreVertical size={18} />
                        </button>

                        {/* Dropdown Menu */}
                        <AnimatePresence>
                          {actionMenuOpen === apt.id && (
                            <motion.div 
                              initial={{ opacity: 0, scale: 0.95, y: -10 }}
                              animate={{ opacity: 1, scale: 1, y: 0 }}
                              exit={{ opacity: 0, scale: 0.95, y: -10 }}
                              className="absolute right-10 top-10 bg-slate-900 border border-slate-800 shadow-none rounded-xl w-[180px] py-2 z-20 text-left overflow-hidden"
                            >
                              <button onClick={() => handleReschedule(apt.id)} className="w-full px-4 py-2.5 text-[13px] font-bold text-slate-300 hover:bg-slate-950 flex items-center gap-2">
                                <Edit size={14} /> Reschedule
                              </button>
                              {apt.status !== "Cancelled" && apt.status !== "Completed" && (
                                <button onClick={() => handleCancelAppointmentLocal(apt.id)} className="w-full px-4 py-2.5 text-[13px] font-bold text-red-600 hover:bg-red-50 flex items-center gap-2">
                                  <XCircle size={14} /> Cancel Appointment
                                </button>
                              )}
                            </motion.div>
                          )}
                        </AnimatePresence>

                      </td>
                    </motion.tr>
                  ))}
                </AnimatePresence>
              </tbody>
            </table>
          </div>
        )}

      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { usePathname } from "next/navigation";
import { useAuth } from "@/context/AuthContext";
import { DoctorSidebar } from "@/components/doctor/DoctorSidebar";
import DoctorTopNav from "@/components/dashboard/doctor/DoctorTopNav";
import { MobileBottomNav } from "@/components/shared/MobileBottomNav";
import { AccessDeniedModal } from "@/components/doctor/AccessDeniedModal";
import { DoctorDashboardSkeleton } from "@/components/doctor/DoctorDashboardSkeleton";
import { DoctorProvider } from "@/context/DoctorContext";
import { Toaster } from "sonner";

export default function DoctorDashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const { user, role, isAuthenticated, isLoading } = useAuth();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const pathname = usePathname();

  // Loading state
  if (isLoading) {
    return (
      <div className="flex h-screen bg-slate-950">
        <div className="w-[240px] bg-slate-900 border-r border-slate-800 hidden lg:block" />
        <div className="flex-1">
          <div className="h-16 bg-slate-900 border-b border-slate-800" />
          <DoctorDashboardSkeleton />
        </div>
      </div>
    );
  }

  // Access control
  if (!isAuthenticated || role !== "doctor") {
    return <AccessDeniedModal />;
  }

  return (
    <DoctorProvider>
      <div className="flex h-screen bg-[#050B14] overflow-hidden">
        <Toaster position="top-right" richColors closeButton />

        {/* Sidebar (Desktop lg:block) */}
        <DoctorSidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col h-full overflow-hidden relative">
          
          {/* Top Mega Menu Navbar (Desktop lg:flex) */}
          <DoctorTopNav onMenuClick={() => setSidebarOpen(true)} />

          {/* Page Content */}
          <main className={`flex-1 overflow-y-auto rounded-t-[32px] border-t border-x border-slate-800 bg-slate-950 shadow-2xl shadow-black relative ${pathname.includes('/prescription/new') ? 'p-0 pb-[90px] lg:pb-0' : 'pb-[90px] lg:pb-6 p-4 sm:p-6 lg:p-8'}`}>
            {children}
          </main>
          
          {/* Rx Floating Bottom Navigation Pill System (Mobile & Tablet) */}
          <MobileBottomNav />
        </div>
      </div>
    </DoctorProvider>
  );
}

"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Users, Clock, MonitorPlay, UserCheck, Activity, Smartphone, Plus, X, ToggleLeft, ToggleRight, QrCode, Mail, Link as LinkIcon, CheckCircle2, Undo2 } from 'lucide-react';
import Image from 'next/image';
import Link from 'next/link';
import { toast, Toaster } from 'sonner';
import { useAuth } from '@/context/AuthContext';
import { useDoctor } from '@/context/DoctorContext';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const stats = [
  { title: "Today's Appointments", count: "42", icon: Users, color: "text-sky-400", bg: "bg-sky-500/10" },
  { title: "Patients Waiting", count: "12", icon: Clock, color: "text-[#F59E0B]", bg: "bg-[#F59E0B]/10" },
  { title: "Completed", count: "18", icon: UserCheck, color: "text-[#22C55E]", bg: "bg-[#22C55E]/10" },
  { title: "Walk-in Patients", count: "14", icon: Activity, color: "text-[#8B5CF6]", bg: "bg-[#8B5CF6]/10" },
  { title: "Online Consultations", count: "8", icon: Smartphone, color: "text-[#00C2A8]", bg: "bg-[#00C2A8]/10" },
  { title: "Revenue", count: "৳28K", icon: MonitorPlay, color: "text-slate-300", bg: "bg-slate-800" },
];

const chartData = [
  { name: 'Mon', patients: 35 },
  { name: 'Tue', patients: 42 },
  { name: 'Wed', patients: 28 },
  { name: 'Thu', patients: 50 },
  { name: 'Fri', patients: 45 },
  { name: 'Sat', patients: 65 },
  { name: 'Sun', patients: 58 },
];

export default function DoctorDashboardPage() {
  const { user } = useAuth();
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [inviteId, setInviteId] = useState("");
  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState("Front Desk / Receptionist");
  const [isInviting, setIsInviting] = useState(false);
  
  const { 
    queue, previousQueue, connectedAssistants, activityLog, 
    handleNextPatient, handleUndoPatient, addAssistant, removeAssistant 
  } = useDoctor();

  const [permissions, setPermissions] = useState({
    apt: true, queue: true, walkin: true, pay: true, notif: true, cal: true, 
    sched: true, checkin: true, report: true, analytics: true,
    presc: false, diag: false, medrec: false, docprof: false
  });

  const togglePermission = (key: keyof typeof permissions) => {
    setPermissions(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSendInvite = async () => {
    let finalInviteId = inviteId;
    if (inviteId && (inviteId.length !== 12 || !/^\d+$/.test(inviteId))) {
      toast.error("Assistant ID must be exactly 12 digits if provided.");
      return;
    }
    if (!inviteId) {
      finalInviteId = `ast-${Math.floor(Math.random() * 1000000)}`;
    }
    if (!inviteEmail) {
      toast.error("Please enter email address.");
      return;
    }

    setIsInviting(true);
    await new Promise(r => setTimeout(r, 1000));
    setIsInviting(false);

    // Add to pending
    const newAst = {
      id: finalInviteId,
      name: "Pending Assistant",
      status: "Pending Invite",
      color: "text-[#F59E0B]",
      bg: "bg-[#F59E0B]",
      isPending: true
    };
    
    addAssistant(newAst);
    
    const invitesStr = localStorage.getItem('oxpecker_invites');
    const invites = invitesStr ? JSON.parse(invitesStr) : [];
    invites.push({ 
      id: Date.now().toString(), 
      assistantId: finalInviteId, 
      email: inviteEmail, 
      role: inviteRole, 
      status: 'pending',
      doctorId: user?.id || 'doctor-test-101',
      doctorName: user?.name || 'Dr. Sarah Rahman',
      doctorEmail: user?.email || 'doctor@oxpecker.equisaas-bd.com'
    });
    localStorage.setItem('oxpecker_invites', JSON.stringify(invites));

    setShowInviteModal(false);
    setInviteId("");
    setInviteEmail("");
    toast.success("Invite sent successfully!");
  };

  const handleRemoveAssistant = (id: string) => {
    removeAssistant(id);
    toast.success("Assistant removed.");
    
    const notifsStr = localStorage.getItem('oxpecker_notifications');
    const notifs = notifsStr ? JSON.parse(notifsStr) : [];
    notifs.push({ id: Date.now().toString(), targetId: id, message: "You have been removed by Dr. Sarah.", read: false });
    localStorage.setItem('oxpecker_notifications', JSON.stringify(notifs));
  };

  return (
    <div className="p-4 lg:p-6 space-y-4 lg:space-y-6 bg-slate-950 min-h-full w-full max-w-[1600px] mx-auto">
      {/* HEADER */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 sm:gap-0 mb-2">
        <h1 className="text-[20px] lg:text-[24px] font-bold text-slate-200">Live Monitor & Team Dashboard</h1>
        <div className="flex gap-4">
          <div className="px-4 py-2 bg-slate-900 rounded-full shadow-none flex items-center gap-2 border border-slate-800">
            <span className="w-2.5 h-2.5 bg-[#22C55E] rounded-full animate-pulse"></span>
            <span className="text-[14px] font-bold text-slate-300 hidden sm:inline">Live Sync Active</span>
          </div>
        </div>
      </div>

      {/* STATS */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-3 sm:gap-4 lg:gap-5">
        {stats.map((stat, idx) => (
          <motion.div 
            key={idx}
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.05 }}
            className="bg-slate-900 rounded-[20px] p-4 sm:p-5 shadow-none border border-slate-800 flex flex-col justify-between hover:shadow-none transition-shadow h-full min-h-[140px]"
          >
            <div className="flex justify-between items-start mb-4">
              <div className={`w-[40px] h-[40px] rounded-[12px] flex items-center justify-center ${stat.bg}`}>
                <stat.icon size={20} className={stat.color} />
              </div>
            </div>
            <div>
              <h3 className="text-[28px] sm:text-[32px] font-extrabold text-slate-200 leading-none mb-1.5">{stat.count}</h3>
              <p className="text-[12px] sm:text-[13px] font-semibold text-slate-500 leading-snug">{stat.title}</p>
            </div>
          </motion.div>
        ))}
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {/* Main Queue Progress */}
        <motion.div 
          initial={{ opacity: 0, scale: 0.98 }}
          animate={{ opacity: 1, scale: 1 }}
          className="xl:col-span-2 bg-slate-900 rounded-[20px] shadow-none border border-slate-800 p-5 lg:p-8 flex flex-col gap-6 lg:gap-8"
        >
          <div className="flex justify-between items-end">
            <div className="w-full">
              <h2 className="text-[20px] font-bold text-slate-200 mb-3">Current Queue Progress</h2>
              <div className="w-full max-w-[400px] h-[12px] bg-slate-800 rounded-full overflow-hidden">
                <div className="h-full bg-sky-600 rounded-full w-[45%]"></div>
              </div>
              <p className="text-[13px] text-slate-500 mt-2">18 of 42 patients completed</p>
            </div>
            <div className="text-right whitespace-nowrap">
              <p className="text-[14px] text-slate-500 font-medium">Est. Waiting Time</p>
              <p className="text-[24px] font-bold text-[#F59E0B]">~45 mins</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Current Patient */}
            <div 
              onClick={() => {
                if (queue[0]) {
                  window.location.href = `/doctor/dashboard/prescription/new?patientName=${encodeURIComponent(queue[0].name || "")}&patientId=${queue[0].token || ""}&appointmentTime=10:00+AM`;
                }
              }}
              className="bg-gradient-to-br from-sky-900/30 via-slate-900 to-slate-900 p-6 rounded-[16px] border border-sky-500/20 relative overflow-hidden group flex flex-col justify-between h-full cursor-pointer hover:border-sky-500/40 hover:shadow-[0_0_20px_rgba(14,165,233,0.1)] transition-all"
            >
              <div>
                <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button className="text-[12px] bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 shadow-none px-4 py-1.5 rounded-full font-bold hover:bg-emerald-500 hover:text-white transition-colors">Start Consultation</button>
                </div>
                <span className="text-[14px] text-sky-400 font-semibold uppercase tracking-wider flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-sky-400 animate-pulse shadow-[0_0_8px_rgba(56,189,248,0.8)]"></span>
                  Current Patient
                </span>
                <div className="mt-4 flex items-center justify-between">
                  <div>
                    <span className="text-[54px] font-extrabold text-white drop-shadow-[0_2px_10px_rgba(56,189,248,0.2)] leading-none block mb-2">{queue[0]?.token || "-"}</span>
                    <span className="text-[18px] font-bold text-slate-200">{queue[0]?.name || "No Patient"}</span>
                    <p className="text-[14px] text-slate-400">{queue[0]?.info || ""}</p>
                  </div>
                  <div className="w-[70px] h-[70px] rounded-full bg-sky-500/10 border border-sky-500/20 hidden sm:flex items-center justify-center text-[24px] font-bold text-sky-400 shadow-[inset_0_2px_10px_rgba(56,189,248,0.1)]">
                    {queue[0]?.name?.charAt(0) || "-"}
                  </div>
                </div>
              </div>
              
              <div className="mt-6 pt-5 border-t border-slate-700/50 flex gap-3">
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    handleUndoPatient();
                  }}
                  disabled={previousQueue.length === 0}
                  title="Undo Call Next"
                  className="w-[60px] h-[52px] shrink-0 bg-amber-500/10 hover:bg-amber-500 text-amber-500 hover:text-white border border-amber-500/30 font-bold rounded-xl flex items-center justify-center transition-all disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  <Undo2 size={20} />
                </button>
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    handleNextPatient();
                  }}
                  disabled={queue.length === 0}
                  className="flex-1 bg-sky-600 hover:bg-sky-500 text-white font-bold h-[52px] rounded-xl shadow-none transition-all active:scale-[0.98] flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <CheckCircle2 size={20} /> Call Next
                </button>
              </div>
            </div>

            {/* Next Patient */}
            <div className="bg-slate-900 p-6 rounded-[16px] border border-slate-700 flex flex-col">
              <span className="text-[14px] text-slate-500 font-semibold uppercase tracking-wider">Next Patient</span>
              <div className="mt-4 flex items-center justify-between opacity-80">
                <div>
                  <span className="text-[40px] font-bold text-slate-500 leading-none block mb-2">{queue[1]?.token || "-"}</span>
                  <span className="text-[16px] font-bold text-slate-300">{queue[1]?.name || "End of Queue"}</span>
                  <p className="text-[14px] text-slate-500">{queue[1]?.info || ""}</p>
                </div>
                {queue[1] && (
                  <div className="w-[60px] h-[60px] rounded-full bg-slate-800 hidden sm:flex items-center justify-center text-[20px] font-bold text-slate-500">
                    {queue[1].name.charAt(0)}
                  </div>
                )}
              </div>
              
              {queue.length > 2 && (
                <div className="mt-auto pt-5">
                  <p className="text-[13px] text-slate-500 font-medium bg-slate-950 p-3 rounded-lg border border-slate-800">
                    <span className="font-bold text-slate-300">Upcoming:</span> {queue[2].token} - {queue[2].name}
                  </p>
                </div>
              )}
            </div>
          </div>
        </motion.div>

        {/* Connect Team */}
        <div className="flex flex-col gap-6">
          <motion.div 
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            className="bg-slate-900 rounded-[20px] shadow-none border border-slate-800 p-6 flex flex-col h-full"
          >
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-[18px] font-bold text-slate-200">Connected Assistant</h3>
              <button onClick={() => setShowInviteModal(true)} className="px-4 py-2 bg-sky-500/10 text-sky-400 text-sm font-bold rounded-lg hover:bg-sky-600 hover:text-white transition-colors flex items-center gap-1.5">
                <Plus size={16} /> Invite
              </button>
            </div>
            
            <div className="flex flex-col gap-3">
              {connectedAssistants.map((ast) => (
                <div key={ast.id} className="flex items-center justify-between bg-slate-950 p-4 rounded-[12px] border border-slate-800 group transition-colors hover:border-slate-700">
                  <div className="flex items-center gap-3">
                    <div className={`w-[40px] h-[40px] rounded-full ${ast.bg}/20 ${ast.color} font-bold flex items-center justify-center text-sm shrink-0`}>
                      {ast.name.charAt(0)}
                    </div>
                    <div>
                      <h4 className="text-[15px] font-bold text-slate-200 leading-tight">{ast.name}</h4>
                      <span className={`text-[13px] ${ast.color} font-medium flex items-center gap-1.5 mt-0.5`}>
                        {!ast.isPending && ast.status.includes('Online') && <span className={`w-1.5 h-1.5 rounded-full ${ast.bg} animate-pulse`}></span>}
                        {ast.status}
                      </span>
                    </div>
                  </div>
                  <button onClick={() => handleRemoveAssistant(ast.id)} className="text-[12px] font-bold text-[#EF4444] opacity-0 group-hover:opacity-100 transition-opacity bg-red-50 px-3 py-1.5 rounded-lg hover:bg-red-100">
                    {ast.isPending ? 'Cancel' : 'Remove'}
                  </button>
                </div>
              ))}
            </div>
          </motion.div>
        </div>
      </div>

      {/* Analytics Chart */}
      <div className="grid grid-cols-1 mt-6">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-slate-900 rounded-[20px] shadow-none border border-slate-800 p-6"
        >
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-[18px] font-bold text-slate-200">Weekly Patient Flow</h3>
            <select className="bg-slate-950 border border-slate-700 rounded-lg px-3 py-1.5 text-sm font-medium text-slate-300 outline-none">
              <option>This Week</option>
              <option>Last Week</option>
            </select>
          </div>
          <div className="w-full h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                <Line type="monotone" dataKey="patients" stroke="#2F80ED" strokeWidth={3} dot={{ r: 4, strokeWidth: 2, fill: "#fff", stroke: "#2F80ED" }} activeDot={{ r: 6, fill: "#2F80ED" }} />
                <CartesianGrid stroke="#f1f5f9" strokeDasharray="5 5" vertical={false} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 13 }} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 13 }} dx={-10} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }}
                  itemStyle={{ color: '#2F80ED', fontWeight: 'bold' }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </motion.div>
      </div>

      {/* Assistant Activity Log */}
      <h2 className="text-[20px] font-bold text-slate-200 pt-4">Live Assistant Activity Log</h2>
      <div className="w-full bg-slate-950/40 backdrop-blur-xl rounded-[20px] shadow-[0_8px_30px_rgba(0,0,0,0.2)] border border-slate-800/60 overflow-hidden relative">
        <div className="h-[400px] overflow-auto custom-scrollbar">
          <table className="w-full text-left border-collapse min-w-[700px]">
            <thead className="sticky top-0 bg-slate-950/90 backdrop-blur-md z-10 border-b border-slate-700">
              <tr className="text-[13px] text-slate-500 font-semibold h-[50px] uppercase tracking-wider">
                <th className="px-6 py-3 font-semibold">Time</th>
                <th className="px-6 py-3 font-semibold">Assistant Name</th>
                <th className="px-6 py-3 font-semibold">Action</th>
                <th className="px-6 py-3 font-semibold">Patient Token</th>
                <th className="px-6 py-3 font-semibold text-right">Status</th>
              </tr>
            </thead>
            <tbody className="text-[14px]">
              {activityLog.map((log, i) => (
                <tr key={i} className="border-b border-slate-800/50 hover:bg-slate-800/30 transition-colors h-[56px]">
                  <td className="px-6 py-3 font-medium text-slate-500 whitespace-nowrap">{log.time}</td>
                  <td className="px-6 py-3 font-semibold text-slate-300 flex items-center gap-3 whitespace-nowrap">
                    <div className="w-7 h-7 rounded-full bg-slate-800 flex items-center justify-center text-[11px] font-bold shrink-0">{log.name.charAt(0)}</div>
                    {log.name}
                  </td>
                  <td className="px-6 py-3 font-medium text-slate-200 whitespace-nowrap">{log.action}</td>
                  <td className="px-6 py-3 font-bold text-slate-300 whitespace-nowrap">{log.token}</td>
                  <td className={`px-6 py-3 font-bold text-right whitespace-nowrap ${log.color}`}>{log.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Invite Modal */}
      <AnimatePresence>
        {showInviteModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <motion.div 
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="w-full max-w-[720px] bg-slate-900 rounded-[24px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
            >
              <div className="px-6 md:px-8 py-5 border-b border-slate-800 flex items-center justify-between sticky top-0 bg-slate-900 z-10 shrink-0">
                <h2 className="text-[20px] font-bold text-slate-200">Invite Assistant</h2>
                <button onClick={() => setShowInviteModal(false)} className="p-2 text-slate-500 hover:text-slate-300 bg-slate-950 hover:bg-slate-800 rounded-full transition-colors">
                  <X size={20} />
                </button>
              </div>

              <div className="p-6 md:p-8 overflow-y-auto custom-scrollbar">
                <div className="grid grid-cols-2 gap-4 mb-6">
                  <div className="col-span-2 md:col-span-1">
                    <label className="text-[13px] font-semibold text-slate-300 block mb-1.5">Assistant id (Optional)</label>
                    <input 
                      type="text" 
                      value={inviteId}
                      onChange={(e) => setInviteId(e.target.value.replace(/\D/g, ''))}
                      maxLength={12} 
                      placeholder="12-digit number"
                      className="w-full h-[50px] bg-slate-950 text-slate-200 border border-slate-700 rounded-[12px] px-4 text-[14px] focus:outline-none focus:border-sky-500 placeholder-slate-600" 
                    />
                  </div>
                  <div className="col-span-2 md:col-span-1">
                    <label className="text-[13px] font-semibold text-slate-300 block mb-1.5">Email Address *</label>
                    <input 
                      type="email" 
                      value={inviteEmail}
                      onChange={(e) => setInviteEmail(e.target.value)}
                      placeholder="assistant@email.com"
                      className="w-full h-[50px] bg-slate-950 text-slate-200 border border-slate-700 rounded-[12px] px-4 text-[14px] focus:outline-none focus:border-sky-500 placeholder-slate-600" 
                    />
                  </div>
                  <div className="col-span-2 md:col-span-2">
                    <label className="text-[13px] font-semibold text-slate-300 block mb-1.5">Role *</label>
                    <select 
                      value={inviteRole}
                      onChange={(e) => setInviteRole(e.target.value)}
                      className="w-full h-[50px] bg-slate-950 text-slate-200 border border-slate-700 rounded-[12px] px-4 text-[14px] focus:outline-none focus:border-sky-500 appearance-none"
                    >
                      <option className="bg-slate-900 text-slate-200">Front Desk / Receptionist</option>
                      <option className="bg-slate-900 text-slate-200">Clinic Manager</option>
                    </select>
                  </div>
                </div>

                <div className="mb-6">
                  <h3 className="text-[16px] font-bold text-slate-200 mb-3">Permissions</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-3 bg-slate-950 p-5 rounded-[16px] border border-slate-800">
                    <div className="col-span-1 md:col-span-2"><h4 className="text-[12px] font-bold text-slate-500 uppercase tracking-wider">Management</h4></div>
                    <PermissionToggle label="Appointment Mgmt" active={permissions.apt} onClick={() => togglePermission('apt')} />
                    <PermissionToggle label="Queue Management" active={permissions.queue} onClick={() => togglePermission('queue')} />
                    <PermissionToggle label="Walk-in Patients" active={permissions.walkin} onClick={() => togglePermission('walkin')} />
                    <PermissionToggle label="Payments" active={permissions.pay} onClick={() => togglePermission('pay')} />
                    
                    <div className="col-span-1 md:col-span-2 mt-2"><h4 className="text-[12px] font-bold text-slate-500 uppercase tracking-wider">Clinical (Disabled by default)</h4></div>
                    <PermissionToggle label="Prescriptions" active={permissions.presc} onClick={() => togglePermission('presc')} />
                    <PermissionToggle label="Medical Records" active={permissions.medrec} onClick={() => togglePermission('medrec')} />
                  </div>
                </div>
              </div>

              <div className="px-6 md:px-8 py-5 border-t border-slate-800 bg-slate-950 flex items-center justify-end gap-3 sticky bottom-0 z-10 shrink-0">
                <button onClick={() => setShowInviteModal(false)} className="px-6 py-2.5 text-slate-500 font-semibold rounded-[12px] hover:bg-slate-800 transition-colors">
                  Cancel
                </button>
                <button 
                  onClick={handleSendInvite}
                  disabled={isInviting}
                  className="px-6 py-2.5 bg-sky-600 hover:bg-sky-500 text-white font-bold rounded-[12px] transition-colors shadow-none flex items-center gap-2"
                >
                  {isInviting ? <span className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></span> : 'Send Invite'}
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

const PermissionToggle = ({ label, active, onClick }: { label: string, active: boolean, onClick: () => void }) => {
  return (
    <div className="flex items-center justify-between py-1 cursor-pointer group" onClick={onClick}>
      <span className="text-[14px] font-medium text-slate-300 group-hover:text-slate-100 transition-colors">{label}</span>
      <button className="text-slate-500 focus:outline-none">
        {active ? <ToggleRight size={32} className="text-sky-400" strokeWidth={1.5} /> : <ToggleLeft size={32} strokeWidth={1.5} />}
      </button>
    </div>
  );
};

"use client";

import React, { useState, useMemo, useEffect, Suspense } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Filter, Calendar, MapPin, User, Activity, FileText, ChevronRight, CheckCircle2, AlertCircle, Download, Clock, ChevronLeft, ChevronDown } from 'lucide-react';
import { useDoctor } from '@/context/DoctorContext';
import { toast } from 'sonner';
import { PatientDetailsDrawer } from '@/components/patients/PatientDetailsDrawer';
import { useSearchParams } from 'next/navigation';

function DoctorPatientsContent() {
  const { patients: contextPatients } = useDoctor();
  const [patients, setPatients] = useState<any[]>(contextPatients);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedPatient, setSelectedPatient] = useState<any>(null);
  const [activeFilter, setActiveFilter] = useState("All");
  const [currentPage, setCurrentPage] = useState(1);
  const [dateRange, setDateRange] = useState("All Time");
  
  const itemsPerPage = 10;
  const filters = ["All", "Appointment", "Walk-in", "Online"];

  // Fetch real patients from DB
  useEffect(() => {
    fetch('/api/patients')
      .then(res => res.json())
      .then(json => {
        if (json.success && json.data) {
          setPatients(prev => {
            const dbIds = new Set(json.data.map((p: any) => p.id));
            const filteredMock = contextPatients.filter(p => !dbIds.has(p.id));
            return [...json.data, ...filteredMock];
          });
        }
      })
      .catch(e => console.error("Failed to load DB patients:", e));
  }, [contextPatients]);

  // Open profile automatically if redirected from prescription finalize
  const searchParams = useSearchParams();
  useEffect(() => {
    const idFromUrl = searchParams?.get('id');
    if (idFromUrl && patients.length > 0 && !selectedPatient) {
      const patient = patients.find(p => p.id === idFromUrl);
      if (patient) {
        setSelectedPatient(patient);
        // Remove id from URL so it doesn't re-open on refresh
        window.history.replaceState(null, '', '/doctor/dashboard/patients');
      }
    }
  }, [searchParams, patients, selectedPatient]);

  // Filter & Sort Logic
  const filteredPatients = useMemo(() => {
    let result = patients;

    // Type Filter
    if (activeFilter !== "All") {
      result = result.filter(p => p.type === activeFilter);
    }

    // Search Filter
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter(p => 
        p.name.toLowerCase().includes(q) || 
        p.id.toLowerCase().includes(q) ||
        p.diagnosis.toLowerCase().includes(q)
      );
    }

    // Sort by Date (Descending)
    return result.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [patients, activeFilter, searchQuery]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredPatients.length / itemsPerPage);
  const currentData = filteredPatients.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const handleExport = () => {
    toast.success("Patient list exported to CSV successfully!");
  };

  return (
    <div className="p-4 lg:p-8 space-y-6 bg-slate-950 min-h-[calc(100vh-80px)] w-full max-w-[1600px] mx-auto overflow-y-auto pb-24">
      
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
        <div>
          <h1 className="text-[28px] font-extrabold text-slate-200 tracking-tight">Patients Database</h1>
          <p className="text-[15px] text-slate-500 font-medium mt-1">Manage all patient records, filter, search and export data.</p>
        </div>
        
        <div className="flex items-center gap-3">
          <button 
            onClick={handleExport}
            className="flex items-center gap-2 px-5 py-2.5 bg-slate-900 border border-slate-700 hover:bg-slate-950 text-slate-300 rounded-xl font-bold shadow-none transition-colors"
          >
            <Download size={18} /> Export CSV
          </button>
        </div>
      </div>

      {/* Advanced Filters Bar */}
      <div className="bg-slate-900 rounded-[20px] shadow-none border border-slate-800 p-4 flex flex-col xl:flex-row justify-between items-center gap-4">
        
        {/* Type Tabs */}
        <div className="flex bg-slate-950 p-1.5 rounded-xl border border-slate-800 w-full xl:w-auto">
          {filters.map(filter => (
            <button
              key={filter}
              onClick={() => { setActiveFilter(filter); setCurrentPage(1); }}
              className={`flex-1 xl:flex-none px-6 py-2 rounded-lg text-[14px] font-bold transition-all ${
                activeFilter === filter 
                  ? "bg-slate-900 text-[#2F80ED] shadow-none border border-slate-700" 
                  : "text-slate-500 hover:text-slate-300"
              }`}
            >
              {filter}
            </button>
          ))}
        </div>

        {/* Search & Date */}
        <div className="flex flex-col sm:flex-row gap-3 w-full xl:w-auto">
          <div className="relative">
            <select 
              value={dateRange}
              onChange={(e) => setDateRange(e.target.value)}
              className="w-full sm:w-[160px] h-11 pl-4 pr-10 bg-slate-950 border border-slate-700 rounded-xl text-[14px] text-slate-300 font-bold focus:outline-none focus:border-[#2F80ED] appearance-none cursor-pointer"
            >
              <option>All Time</option>
              <option>Today</option>
              <option>This Week</option>
              <option>This Month</option>
            </select>
            <ChevronDown size={16} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
          </div>

          <div className="relative flex-1 sm:w-[320px]">
            <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
            <input 
              type="text"
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setCurrentPage(1); }}
              placeholder="Search Name, ID or Diagnosis..."
              className="w-full h-11 pl-11 pr-4 bg-slate-950 border border-slate-700 rounded-xl text-[14px] text-slate-300 placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-[#2F80ED]/20 focus:border-[#2F80ED]/40 transition-all"
            />
          </div>
        </div>
      </div>

      {/* Data Table */}
      <div className="bg-slate-900 rounded-[20px] shadow-none border border-slate-800 overflow-hidden">
        {filteredPatients.length === 0 ? (
          <div className="py-24 flex flex-col items-center justify-center text-center border-dashed border-2 border-slate-800 m-4 rounded-2xl bg-slate-950/50">
            <div className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center mb-6 shadow-none border border-slate-800">
              <Search size={32} className="text-slate-300" />
            </div>
            <h3 className="text-[20px] font-bold text-slate-300 mb-2">No patients found</h3>
            <p className="text-[14px] text-slate-500 max-w-md">Try adjusting your search criteria, or select a different date range.</p>
          </div>
        ) : (
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse min-w-[1000px]">
              <thead className="bg-slate-950 border-b border-slate-800">
                <tr className="text-[13px] text-slate-500 font-bold tracking-wide uppercase">
                  <th className="px-6 py-4 rounded-tl-[20px]">Patient Info</th>
                  <th className="px-6 py-4">Diagnosis</th>
                  <th className="px-6 py-4">Visit Type</th>
                  <th className="px-6 py-4">Date & Time</th>
                  <th className="px-6 py-4">Status</th>
                  <th className="px-6 py-4 text-right rounded-tr-[20px]">Action</th>
                </tr>
              </thead>
              <tbody className="text-[14px]">
                {currentData.map((patient) => (
                  <tr key={patient.id} className="border-b border-slate-50 hover:bg-slate-950/80 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-slate-800 text-slate-500 flex items-center justify-center font-bold">
                          {patient.avatar}
                        </div>
                        <div>
                          <p className="font-bold text-slate-200">{patient.name}</p>
                          <p className="text-[12.5px] text-slate-500 font-medium">{patient.id} • {patient.gender}, {patient.age}y</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="font-medium text-slate-300 line-clamp-1 max-w-[200px]">{patient.diagnosis}</span>
                    </td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center gap-1.5 bg-slate-800 text-slate-500 px-3 py-1 rounded-lg text-[12.5px] font-bold">
                        {patient.type === 'Appointment' ? <Calendar size={13}/> : patient.type === 'Walk-in' ? <MapPin size={13}/> : <Activity size={13}/>} 
                        {patient.type}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <p className="font-bold text-slate-300">{new Date(patient.date).toLocaleDateString()}</p>
                      <p className="text-[12.5px] text-slate-500">{new Date(patient.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                    </td>
                    <td className="px-6 py-4">
                      {patient.status === "Completed" && <span className="inline-flex items-center gap-1 text-[#22C55E] bg-[#22C55E]/10 px-2.5 py-1 rounded-md text-[12px] font-bold"><CheckCircle2 size={12}/> Completed</span>}
                      {patient.status === "Waiting" && <span className="inline-flex items-center gap-1 text-[#F59E0B] bg-[#F59E0B]/10 px-2.5 py-1 rounded-md text-[12px] font-bold"><Clock size={12}/> Waiting</span>}
                      {patient.status === "In Progress" && <span className="inline-flex items-center gap-1 text-[#2F80ED] bg-sky-500/10 px-2.5 py-1 rounded-md text-[12px] font-bold"><Activity size={12} className="animate-pulse"/> In Progress</span>}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => setSelectedPatient(patient)}
                        className="px-4 py-2 bg-slate-900 border border-slate-700 text-slate-300 rounded-lg text-[13px] font-bold shadow-none hover:bg-sky-600 hover:text-white hover:border-primary transition-all"
                      >
                        View Details
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        
        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-6 py-4 border-t border-slate-800 flex items-center justify-between bg-slate-950/50">
            <span className="text-[13px] font-bold text-slate-500">
              Showing {(currentPage - 1) * itemsPerPage + 1} to {Math.min(currentPage * itemsPerPage, filteredPatients.length)} of {filteredPatients.length} entries
            </span>
            <div className="flex gap-2">
              <button 
                disabled={currentPage === 1}
                onClick={() => setCurrentPage(p => p - 1)}
                className="w-9 h-9 rounded-lg border border-slate-700 bg-slate-900 flex items-center justify-center text-slate-500 hover:bg-slate-950 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft size={18} />
              </button>
              <button 
                disabled={currentPage === totalPages}
                onClick={() => setCurrentPage(p => p + 1)}
                className="w-9 h-9 rounded-lg border border-slate-700 bg-slate-900 flex items-center justify-center text-slate-500 hover:bg-slate-950 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronRight size={18} />
              </button>
            </div>
          </div>
        )}
      </div>

      <PatientDetailsDrawer 
        isOpen={!!selectedPatient}
        onClose={() => setSelectedPatient(null)}
        patient={selectedPatient}
      />
    </div>
  );
}

export default function DoctorPatientsPage() {
  return (
    <Suspense fallback={<div className="p-8 text-center text-slate-500">Loading patients...</div>}>
      <DoctorPatientsContent />
    </Suspense>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { PrescriptionEditorLayout } from "@/components/prescription/PrescriptionEditorLayout";
import { PatientContextSidebar } from "@/components/prescription/PatientContextSidebar";
import { SmartEditorArea } from "@/components/prescription/SmartEditorArea";
import { PrescriptionTopbar } from "@/components/prescription/PrescriptionTopbar";
import { AIAssistancePanel } from "@/components/prescription/AIAssistancePanel";
import { PrescriptionProvider } from "@/context/PrescriptionContext";
import { PrescriptionFinalizeModal } from "@/components/prescription/PrescriptionFinalizeModal";
import { PrescriptionPreviewModal } from "@/components/prescription/PrescriptionPreviewModal";
import { TestReportViewer } from "@/components/prescription/TestReportViewer";

export default function NewPrescriptionPage() {
  const [isFinalizeModalOpen, setIsFinalizeModalOpen] = useState(false);
  const [isPreviewModalOpen, setIsPreviewModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<"prescription" | "report">("prescription");

  const searchParams = useSearchParams();
  
  useEffect(() => {
    if (searchParams?.get('preview') === 'true') {
      setIsPreviewModalOpen(true);
    }
  }, [searchParams]);

  return (
    <PrescriptionProvider>
      <PrescriptionEditorLayout
        topbar={
          <PrescriptionTopbar 
            onFinalize={() => setIsFinalizeModalOpen(true)} 
            onPreview={() => setIsPreviewModalOpen(true)}
            activeTab={activeTab}
            onTabChange={setActiveTab}
          />
        }
        editor={
          <div key={activeTab} className="h-full flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-500 ease-out">
            {activeTab === "prescription" ? (
              <SmartEditorArea onFinalize={() => setIsFinalizeModalOpen(true)} />
            ) : (
              <TestReportViewer />
            )}
          </div>
        }
        aiPanel={<AIAssistancePanel />}
      />

      <PrescriptionFinalizeModal 
        isOpen={isFinalizeModalOpen} 
        onClose={() => setIsFinalizeModalOpen(false)} 
      />

      <PrescriptionPreviewModal
        isOpen={isPreviewModalOpen}
        onClose={() => setIsPreviewModalOpen(false)}
      />
    </PrescriptionProvider>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { FileText, Plus, Search, Filter, Pencil, CheckCircle2, Eye, Calendar, X } from "lucide-react";
import { toast } from "sonner";

// Mock Data for Prescription History
const MOCK_HISTORY = [
  { id: "RX-1004", patientName: "Patient", date: "24 July, 2026", diagnosis: "Viral Fever & Fatigue", age: 24, gender: "Male" },
  { id: "RX-1003", patientName: "Nafisa Akter", date: "23 July, 2026", diagnosis: "Migraine & Sleep Deprivation", age: 28, gender: "Female" },
  { id: "RX-1002", patientName: "Karim Uddin", date: "22 July, 2026", diagnosis: "Gastric Ulcer", age: 45, gender: "Male" },
  { id: "RX-1001", patientName: "Sumaiya Rahman", date: "20 July, 2026", diagnosis: "Seasonal Asthma", age: 32, gender: "Female" },
];

export default function PrescriptionsPage() {
  const [history, setHistory] = useState(MOCK_HISTORY);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedRx, setSelectedRx] = useState<typeof MOCK_HISTORY[0] | null>(null);

  const handleEdit = (rx: typeof MOCK_HISTORY[0]) => {
    // In a real app, this would open the editor or redirect to /prescription/new?id=...
    // For now, we simulate the edit and trigger the required notification.
    toast.success(`Editing Prescription ${rx.id}`);
    
    // Simulate saving the edit after a short delay to trigger patient notification
    setTimeout(() => {
      toast("Patient Notified", {
        description: `Notification sent to ${rx.patientName}: "Your prescription has been updated by your doctor."`,
        icon: <CheckCircle2 className="text-emerald-500" />,
      });
      
      // Save notification to local storage for patient side simulation
      const notifsStr = localStorage.getItem('oxpecker_notifications');
      const notifs = notifsStr ? JSON.parse(notifsStr) : [];
      notifs.push({ 
        id: Date.now().toString(), 
        title: "Prescription Updated",
        message: `Your prescription (${rx.id}) for ${rx.diagnosis} has been updated by your doctor.`, 
        read: false,
        time: new Date().toISOString()
      });
      localStorage.setItem('oxpecker_notifications', JSON.stringify(notifs));
    }, 1500);
  };

  const filteredHistory = history.filter(h => 
    h.patientName.toLowerCase().includes(searchQuery.toLowerCase()) || 
    h.id.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="p-4 lg:p-6 max-w-7xl mx-auto flex flex-col gap-4 lg:gap-6 pb-[80px] lg:pb-6">
      
      {/* Header Area */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-slate-900 p-4 lg:p-6 rounded-2xl shadow-none border border-slate-800">
        <div>
          <h1 className="text-[20px] lg:text-[24px] font-bold text-slate-200 flex items-center gap-2">
            <FileText className="text-[#2F80ED]" />
            Prescriptions
          </h1>
          <p className="text-slate-500 mt-1 text-[13px] lg:text-[14px]">Manage and view all your patient prescriptions.</p>
        </div>
        
        <Link href="/doctor/dashboard/prescription/new" className="w-full sm:w-auto bg-[#6DDA6E] hover:bg-[#5bc95c] text-white px-6 h-[48px] rounded-xl font-bold flex items-center justify-center gap-2 shadow-none shadow-[#6DDA6E]/20 transition-all hover:-translate-y-0.5 active:scale-95">
          <Plus size={20} />
          Create New
        </Link>
      </div>

      {/* Filter and Search */}
      <div className="flex flex-col sm:flex-row gap-3 lg:gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
          <input 
            type="text" 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search by Patient Name or ID..."
            className="w-full h-[48px] pl-12 pr-4 bg-slate-900 border border-slate-700 rounded-xl focus:outline-none focus:border-[#2F80ED] focus:ring-4 focus:ring-[#2F80ED]/10 transition-all shadow-none text-[14px]"
          />
        </div>
        <button className="h-[48px] px-6 bg-slate-900 border border-slate-700 rounded-xl flex items-center justify-center gap-2 text-slate-500 font-bold hover:bg-slate-950 transition-colors shadow-none shrink-0 w-full sm:w-auto">
          <Filter size={18} />
          Filters
        </button>
      </div>

      {/* Prescription History List */}
      <div className="flex flex-col gap-3 lg:gap-4">
        <h2 className="text-[16px] lg:text-[18px] font-bold text-slate-200 px-1 mt-2">Prescription History</h2>
        
        {filteredHistory.length > 0 ? (
          <div className="flex flex-col gap-3">
            {filteredHistory.map((rx) => (
              <div key={rx.id} className="bg-slate-900 p-4 lg:p-5 rounded-2xl shadow-none border border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-4 hover:shadow-none transition-shadow">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-1.5">
                    <span className="text-[12px] font-bold text-[#2F80ED] bg-sky-500/10 px-2.5 py-1 rounded-md">{rx.id}</span>
                    <span className="text-[12px] text-slate-500 font-medium flex items-center gap-1.5">
                      <Calendar size={12} /> {rx.date}
                    </span>
                  </div>
                  <h3 className="text-[15px] lg:text-[16px] font-bold text-slate-200">{rx.patientName}</h3>
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1">
                    <p className="text-[12px] lg:text-[13px] text-slate-500">{rx.age} yrs • {rx.gender}</p>
                    <span className="text-slate-300 hidden sm:inline">•</span>
                    <p className="text-[13px] font-medium text-slate-500 line-clamp-1">{rx.diagnosis}</p>
                  </div>
                </div>
                
                <div className="flex items-center gap-2 pt-3 sm:pt-0 border-t sm:border-t-0 border-slate-800 w-full sm:w-auto">
                  <button 
                    onClick={() => setSelectedRx(rx)}
                    className="flex-1 sm:flex-none flex items-center justify-center gap-1.5 text-[13px] font-bold text-[#2F80ED] hover:text-[#2563EB] bg-sky-500/10 hover:bg-[#2F80ED]/20 px-4 py-2.5 rounded-xl transition-colors"
                  >
                    <Eye size={16} />
                    View
                  </button>
                  <Link 
                    href={`/doctor/dashboard/prescription/new?patientName=${encodeURIComponent(rx.patientName)}&edit=true`}
                    className="flex-1 sm:flex-none flex items-center justify-center gap-1.5 text-[13px] font-bold text-[#F59E0B] hover:text-[#D97706] bg-[#F59E0B]/10 hover:bg-[#F59E0B]/20 px-4 py-2.5 rounded-xl transition-colors"
                  >
                    <Pencil size={16} />
                    Edit
                  </Link>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="bg-slate-900 rounded-2xl shadow-none border border-slate-800 flex flex-col items-center justify-center p-12 text-center mt-2">
            <FileText size={32} className="text-slate-300 mb-4" />
            <p className="text-slate-500 text-[14px]">No prescriptions found.</p>
          </div>
        )}
      </div>

      {/* View Details Modal */}
      {selectedRx && (
        <div className="fixed inset-0 z-[200] flex sm:items-center justify-center sm:p-4 bg-slate-900/40 sm:backdrop-blur-sm" onClick={() => setSelectedRx(null)}>
          <div className="bg-slate-900 w-full h-full sm:h-auto sm:rounded-2xl sm:max-w-md shadow-none flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200" onClick={e => e.stopPropagation()}>
            
            {/* Header */}
            <div className="flex justify-between items-center p-4 border-b border-slate-800 bg-slate-950/50 shrink-0">
              <h3 className="font-bold text-slate-200 text-[16px]">Prescription Details</h3>
              <button onClick={() => setSelectedRx(null)} className="p-2 bg-slate-900 rounded-full text-slate-500 hover:text-slate-300 shadow-none border border-slate-800 transition-colors">
                <X size={16} />
              </button>
            </div>
            
            {/* Body */}
            <div className="p-5 space-y-5 overflow-y-auto flex-1">
              <div className="flex justify-between items-center">
                <span className="text-[13px] font-bold text-[#2F80ED] bg-sky-500/10 px-3 py-1.5 rounded-lg">{selectedRx.id}</span>
                <span className="text-[13px] text-slate-500 font-medium flex items-center gap-1.5"><Calendar size={14} /> {selectedRx.date}</span>
              </div>
              <div>
                <p className="text-[13px] text-slate-500 mb-0.5">Patient Name</p>
                <h4 className="text-[20px] font-bold text-slate-200">{selectedRx.patientName}</h4>
                <p className="text-[14px] text-slate-500 mt-1">{selectedRx.age} yrs • {selectedRx.gender}</p>
              </div>
              <div className="bg-slate-950 p-4 rounded-xl border border-slate-800">
                <p className="text-[13px] text-slate-500 mb-1.5">Primary Diagnosis</p>
                <p className="text-[15px] font-semibold text-slate-200 leading-relaxed">{selectedRx.diagnosis}</p>
              </div>
            </div>
            
            {/* Footer */}
            <div className="p-4 border-t border-slate-800 flex justify-end shrink-0 bg-slate-900">
              <Link 
                href={`/doctor/dashboard/prescription/new?patientName=${encodeURIComponent(selectedRx.patientName)}&edit=true`}
                className="flex items-center justify-center gap-2 text-[15px] font-bold text-white bg-[#F59E0B] hover:bg-[#D97706] px-6 h-[52px] sm:h-[48px] rounded-xl transition-all shadow-none shadow-[#F59E0B]/20 w-full sm:w-auto"
              >
                <Pencil size={18} />
                Edit Prescription
              </Link>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { mockChambers } from "@/lib/doctorMockData";
import { 
  Building2, Plus, Trash2, Calendar, Clock, MapPin, 
  ToggleLeft, ToggleRight, Check, X
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast, Toaster } from "sonner";

export default function ChambersSettingsPage() {
  const [chambers, setChambers] = useState(
    mockChambers.map(c => ({ ...c, active: true }))
  );
  
  const [showAddForm, setShowAddForm] = useState(false);
  const [newChamber, setNewChamber] = useState({ 
    name: "", 
    address: "", 
    time: "", 
    days: [] as string[]
  });

  const weekDays = ["Sat", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri"];

  const handleToggleDay = (day: string) => {
    if (newChamber.days.includes(day)) {
      setNewChamber({ ...newChamber, days: newChamber.days.filter(d => d !== day) });
    } else {
      setNewChamber({ ...newChamber, days: [...newChamber.days, day] });
    }
  };

  const handleAddChamber = () => {
    if (!newChamber.name || !newChamber.address || !newChamber.time || newChamber.days.length === 0) {
      toast.error("Please fill all details and select at least one visiting day.");
      return;
    }
    setChambers([
      ...chambers,
      { id: `c${Date.now()}`, ...newChamber, active: true }
    ]);
    setShowAddForm(false);
    setNewChamber({ name: "", address: "", time: "", days: [] });
    toast.success("New chamber added successfully!");
  };

  const handleRemoveChamber = (id: string) => {
    setChambers(chambers.filter(c => c.id !== id));
    toast.success("Chamber removed.");
  };

  const toggleChamberStatus = (id: string) => {
    setChambers(chambers.map(c => c.id === id ? { ...c, active: !c.active } : c));
    toast.success("Chamber status updated.");
  };

  return (
    <div className="space-y-8 animate-fade-in-up pb-20">
      <Toaster position="top-center" />
      
      {/* Header */}
      <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 p-6 lg:p-8">
        <div className="flex justify-between items-start md:items-center">
          <div>
            <h1 className="text-2xl font-extrabold text-slate-200 tracking-tight flex items-center gap-3">
              Chambers & Schedule
            </h1>
            <p className="text-slate-500 mt-1">Manage your practice locations, visiting days, and time slots.</p>
          </div>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className="px-5 py-2.5 bg-[#2F80ED] hover:bg-[#2563EB] text-white font-bold rounded-xl shadow-none shadow-[#2F80ED]/20 transition-all flex items-center gap-2"
          >
            <Plus size={18} /> Add Chamber
          </button>
        </div>
      </div>

      <AnimatePresence>
        {showAddForm && (
          <motion.div 
            initial={{ opacity: 0, y: -20, height: 0 }}
            animate={{ opacity: 1, y: 0, height: 'auto' }}
            exit={{ opacity: 0, y: -20, height: 0 }}
            className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full p-6 lg:p-8"
          >
            <h3 className="text-[16px] font-bold text-slate-200 mb-6 flex items-center gap-2">
              <Building2 size={20} className="text-[#2F80ED]" /> Add New Chamber
            </h3>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Chamber Name / Hospital</label>
                <input 
                  type="text" 
                  placeholder="e.g. Labaid Cardiac Hospital"
                  value={newChamber.name}
                  onChange={(e) => setNewChamber({...newChamber, name: e.target.value})}
                  className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED]"
                />
              </div>
              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Time Slot</label>
                <input 
                  type="text" 
                  placeholder="e.g. 05:00 PM - 09:00 PM"
                  value={newChamber.time}
                  onChange={(e) => setNewChamber({...newChamber, time: e.target.value})}
                  className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED]"
                />
              </div>
              <div className="md:col-span-2">
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Full Address</label>
                <input 
                  type="text" 
                  placeholder="e.g. House 1, Road 4, Dhanmondi, Dhaka"
                  value={newChamber.address}
                  onChange={(e) => setNewChamber({...newChamber, address: e.target.value})}
                  className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED]"
                />
              </div>
            </div>

            <div className="mb-8">
              <label className="block text-[13px] font-semibold text-slate-500 mb-3 ml-1">Visiting Days</label>
              <div className="flex flex-wrap gap-3">
                {weekDays.map(day => (
                  <button
                    key={day}
                    onClick={() => handleToggleDay(day)}
                    className={`px-4 py-2 rounded-xl text-[13px] font-bold transition-all border ${
                      newChamber.days.includes(day)
                        ? "bg-[#2F80ED] text-white border-[#2F80ED] shadow-none shadow-[#2F80ED]/20"
                        : "bg-slate-900 text-slate-500 border-slate-700 hover:border-[#2F80ED] hover:text-[#2F80ED]"
                    }`}
                  >
                    {day}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t border-slate-800">
              <button 
                onClick={() => setShowAddForm(false)}
                className="px-6 py-2.5 text-slate-500 hover:bg-slate-800 font-bold rounded-xl text-[14px] transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={handleAddChamber}
                className="px-8 py-2.5 bg-slate-800 text-white hover:bg-slate-700 font-bold rounded-xl text-[14px] shadow-none transition-all"
              >
                Save Chamber
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="space-y-4">
        {chambers.map((chamber) => (
          <div key={chamber.id} className={`bg-slate-900 rounded-[24px] shadow-none border p-6 transition-all ${chamber.active ? 'border-slate-700' : 'border-slate-800 opacity-60'}`}>
            <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6">
              
              {/* Info */}
              <div className="flex gap-5 items-start flex-1">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${chamber.active ? 'bg-sky-500/10 text-[#2F80ED]' : 'bg-slate-800 text-slate-500'}`}>
                  <Building2 size={24} />
                </div>
                <div>
                  <h3 className="text-[18px] font-bold text-slate-200 mb-1">{chamber.name}</h3>
                  <div className="space-y-1.5">
                    <p className="text-[14px] text-slate-500 flex items-center gap-2">
                      <MapPin size={14} /> {chamber.address}
                    </p>
                    <p className="text-[14px] text-slate-500 flex items-center gap-2">
                      <Clock size={14} /> {chamber.time}
                    </p>
                  </div>
                </div>
              </div>

              {/* Days & Actions */}
              <div className="flex flex-col sm:flex-row items-start sm:items-center gap-6 xl:border-l xl:border-slate-800 xl:pl-8">
                <div className="flex flex-wrap gap-1.5 max-w-[200px]">
                  {weekDays.map(day => (
                    <span 
                      key={day}
                      className={`text-[11px] font-bold px-2 py-1 rounded-md ${
                        chamber.days.includes(day)
                          ? chamber.active ? "bg-slate-800 text-white" : "bg-slate-700 text-white"
                          : "bg-slate-950 text-slate-500 border border-slate-800"
                      }`}
                    >
                      {day}
                    </span>
                  ))}
                </div>

                <div className="flex items-center gap-4 border-t sm:border-t-0 sm:border-l border-slate-800 pt-4 sm:pt-0 sm:pl-6 w-full sm:w-auto">
                  <button 
                    onClick={() => toggleChamberStatus(chamber.id)}
                    className="flex flex-col items-center gap-1 group"
                  >
                    {chamber.active ? (
                      <ToggleRight size={32} className="text-[#22C55E]" />
                    ) : (
                      <ToggleLeft size={32} className="text-slate-300 group-hover:text-slate-300" />
                    )}
                    <span className="text-[11px] font-bold text-slate-500">{chamber.active ? "Active" : "Inactive"}</span>
                  </button>
                  <button 
                    onClick={() => handleRemoveChamber(chamber.id)}
                    className="w-10 h-10 flex items-center justify-center text-slate-500 hover:text-red-500 hover:bg-red-50 rounded-xl transition-colors ml-auto sm:ml-0"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            </div>
          </div>
        ))}

        {chambers.length === 0 && (
          <div className="text-center py-12 bg-slate-900 rounded-[24px] border border-slate-700 border-dashed">
            <Building2 size={48} className="text-slate-200 mx-auto mb-3" />
            <p className="text-slate-500 text-[14px]">No chambers active. Add your primary chamber schedule to receive appointments.</p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { mockEducation } from "@/lib/doctorMockData";
import { 
  ShieldCheck, UploadCloud, FileText,
  Clock, Lock, CheckCircle2, GraduationCap, 
  Plus, Trash2, Award
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast, Toaster } from "sonner";

export default function EducationSettingsPage() {
  // --- BMDC Verification State ---
  const [bmdcReg, setBmdcReg] = useState("");
  const [bmdcStatus, setBmdcStatus] = useState<"none" | "pending" | "verified">("none");
  const [certificateFile, setCertificateFile] = useState<File | null>(null);
  const certInputRef = useRef<HTMLInputElement>(null);

  // --- Education State ---
  const [educationList, setEducationList] = useState(mockEducation);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newEducation, setNewEducation] = useState({ degree: "", institution: "", year: "" });

  // Load BMDC State
  useEffect(() => {
    const savedBmdcStatus = localStorage.getItem('oxpecker_doc_bmdc_status');
    if (savedBmdcStatus) setBmdcStatus(savedBmdcStatus as any);
    const savedReg = localStorage.getItem('oxpecker_doc_bmdc');
    if (savedReg) setBmdcReg(savedReg);
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (!file.type.includes('pdf') && !file.type.includes('image/')) {
        toast.error("Please upload a PDF or Image (JPG/PNG).");
        return;
      }
      setCertificateFile(file);
    }
  };

  const handleSubmitBMDC = () => {
    if (!bmdcReg.trim()) return toast.error("Please enter BMDC Registration Number.");
    if (!certificateFile) return toast.error("Please upload your medical certificate.");

    toast.loading("Submitting credentials securely...", { id: 'bmdc' });
    setTimeout(() => {
      toast.success("Medical credentials submitted for verification!", { id: 'bmdc' });
      setBmdcStatus("pending");
      localStorage.setItem('oxpecker_doc_bmdc_status', 'pending');
      localStorage.setItem('oxpecker_doc_bmdc', bmdcReg);
    }, 2000);
  };

  const handleAddEducation = () => {
    if (!newEducation.degree || !newEducation.institution || !newEducation.year) {
      toast.error("Please fill in all fields.");
      return;
    }
    
    setEducationList([
      { 
        id: `e${Date.now()}`, 
        ...newEducation, 
        status: "Pending" 
      },
      ...educationList
    ]);
    
    setNewEducation({ degree: "", institution: "", year: "" });
    setShowAddForm(false);
    toast.success("Education record added successfully.");
  };

  const handleRemoveEducation = (id: string) => {
    setEducationList(educationList.filter(e => e.id !== id));
    toast.success("Education record removed.");
  };

  return (
    <div className="space-y-8 animate-fade-in-up pb-20">
      <Toaster position="top-center" />
      
      {/* Header */}
      <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 p-6 lg:p-8">
        <div>
          <h1 className="text-2xl font-extrabold text-slate-200 tracking-tight flex items-center gap-3">
            Education & Certifications
          </h1>
          <p className="text-slate-500 mt-1">Manage your educational background and official medical credentials.</p>
        </div>
      </div>

      <div className="flex flex-col gap-8">
        
        {/* Medical Credentials Verification (BMDC) */}
        <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full">
          <div className="p-6 border-b border-slate-800 bg-[#2F80ED]/5">
            <h3 className="text-[16px] font-bold text-slate-200 flex items-center gap-2">
              <ShieldCheck size={20} className="text-[#2F80ED]" /> Primary Medical Credentials (BMDC)
            </h3>
            <p className="text-[13px] text-slate-500 mt-1 leading-snug">To practice on the platform, your primary medical credentials must be verified by the Super Admin.</p>
          </div>
          
          <div className="p-6 lg:p-8 space-y-6">
            
            <AnimatePresence>
              {bmdcStatus === "pending" && (
                <motion.div 
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  className="bg-[#F59E0B]/10 border border-[#F59E0B]/30 rounded-[16px] p-4 flex gap-3"
                >
                  <Clock size={20} className="text-[#F59E0B] shrink-0 mt-0.5" />
                  <div>
                    <h4 className="text-[14px] font-bold text-[#D97706]">Pending Verification</h4>
                    <p className="text-[13px] text-[#D97706]/80 mt-1 leading-snug">
                      Your credentials are under review by the Super Admin. Please allow up to <strong>72 hours</strong> for manual verification.
                    </p>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 flex justify-between items-center">
                  <span>BMDC Registration Number</span>
                  {bmdcStatus === "pending" && <Lock size={12} className="text-slate-500" />}
                </label>
                <input 
                  type="text" 
                  value={bmdcReg}
                  onChange={(e) => setBmdcReg(e.target.value)}
                  disabled={bmdcStatus === "pending"}
                  placeholder="e.g. A-12345"
                  className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] disabled:opacity-60 disabled:cursor-not-allowed transition-all"
                />
              </div>

              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 flex justify-between items-center">
                  <span>Upload Certificate (PDF/JPG)</span>
                  {bmdcStatus === "pending" && <Lock size={12} className="text-slate-500" />}
                </label>
                
                <input 
                  type="file"
                  ref={certInputRef}
                  onChange={handleFileUpload}
                  accept=".pdf,image/jpeg,image/png"
                  className="hidden"
                  disabled={bmdcStatus === "pending"}
                />

                <div 
                  onClick={() => bmdcStatus !== "pending" && certInputRef.current?.click()}
                  className={`w-full border-2 border-dashed rounded-[16px] p-6 flex flex-col items-center justify-center transition-all ${
                    bmdcStatus === "pending" 
                      ? "border-slate-700 bg-slate-950 opacity-60 cursor-not-allowed" 
                      : "border-slate-600 bg-slate-950 hover:bg-[#2F80ED]/5 hover:border-[#2F80ED] cursor-pointer"
                  }`}
                >
                  {certificateFile ? (
                    <div className="flex flex-col items-center">
                      <FileText size={32} className="text-[#22C55E] mb-2" />
                      <span className="text-[13px] font-bold text-slate-300 text-center">{certificateFile.name}</span>
                    </div>
                  ) : (
                    <div className="flex flex-col items-center">
                      <UploadCloud size={24} className="text-slate-500 mb-2" />
                      <span className="text-[14px] font-bold text-slate-300">Click to upload document</span>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {bmdcStatus !== "pending" && (
              <button 
                onClick={handleSubmitBMDC}
                className="w-full md:w-auto px-8 py-3.5 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-xl shadow-none transition-all active:scale-[0.98] flex items-center justify-center gap-2"
              >
                <ShieldCheck size={18} />
                Submit Medical Credentials
              </button>
            )}

          </div>
        </div>

        {/* Education Background */}
        <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full">
          <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-950">
            <div>
              <h3 className="text-[16px] font-bold text-slate-200 flex items-center gap-2">
                <GraduationCap size={20} className="text-[#2F80ED]" /> Educational Background
              </h3>
              <p className="text-[13px] text-slate-500 mt-1">List your degrees and qualifications.</p>
            </div>
            <button 
              onClick={() => setShowAddForm(!showAddForm)}
              className="px-4 py-2 bg-sky-500/10 text-[#2F80ED] hover:bg-[#2F80ED]/20 font-bold rounded-lg transition-colors flex items-center gap-2 text-[13px]"
            >
              <Plus size={16} /> Add New
            </button>
          </div>

          <div className="p-6 lg:p-8 space-y-4">
            
            <AnimatePresence>
              {showAddForm && (
                <motion.div 
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  exit={{ opacity: 0, height: 0 }}
                  className="bg-slate-950 border border-slate-700 p-6 rounded-[16px] mb-6"
                >
                  <h4 className="text-[14px] font-bold text-slate-200 mb-4">Add New Degree</h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                      <label className="block text-[12px] font-semibold text-slate-500 mb-1">Degree Name</label>
                      <input 
                        type="text" 
                        placeholder="e.g. MBBS, FCPS"
                        value={newEducation.degree}
                        onChange={(e) => setNewEducation({...newEducation, degree: e.target.value})}
                        className="w-full h-[40px] bg-slate-900 border border-slate-700 rounded-lg px-3 text-[13px] focus:outline-none focus:border-[#2F80ED]"
                      />
                    </div>
                    <div>
                      <label className="block text-[12px] font-semibold text-slate-500 mb-1">Institution</label>
                      <input 
                        type="text" 
                        placeholder="e.g. Dhaka Medical College"
                        value={newEducation.institution}
                        onChange={(e) => setNewEducation({...newEducation, institution: e.target.value})}
                        className="w-full h-[40px] bg-slate-900 border border-slate-700 rounded-lg px-3 text-[13px] focus:outline-none focus:border-[#2F80ED]"
                      />
                    </div>
                    <div>
                      <label className="block text-[12px] font-semibold text-slate-500 mb-1">Passing Year</label>
                      <input 
                        type="text" 
                        placeholder="e.g. 2015"
                        value={newEducation.year}
                        onChange={(e) => setNewEducation({...newEducation, year: e.target.value})}
                        className="w-full h-[40px] bg-slate-900 border border-slate-700 rounded-lg px-3 text-[13px] focus:outline-none focus:border-[#2F80ED]"
                      />
                    </div>
                  </div>
                  <div className="mt-4 flex justify-end gap-3">
                    <button 
                      onClick={() => setShowAddForm(false)}
                      className="px-5 py-2 text-slate-500 hover:bg-slate-800 font-bold rounded-lg text-[13px]"
                    >
                      Cancel
                    </button>
                    <button 
                      onClick={handleAddEducation}
                      className="px-5 py-2 bg-slate-800 text-white hover:bg-slate-700 font-bold rounded-lg text-[13px]"
                    >
                      Save Degree
                    </button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            {educationList.length === 0 ? (
              <div className="text-center py-10">
                <Award size={48} className="text-slate-200 mx-auto mb-3" />
                <p className="text-slate-500 text-[14px]">No education records found. Add your degrees to build trust with patients.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {educationList.map((edu) => (
                  <div key={edu.id} className="group p-5 border border-slate-800 bg-slate-900 hover:border-slate-600 hover:shadow-none rounded-[16px] transition-all flex justify-between items-center">
                    <div className="flex gap-4 items-start">
                      <div className="w-10 h-10 bg-sky-500/10 rounded-full flex items-center justify-center shrink-0">
                        <GraduationCap size={18} className="text-[#2F80ED]" />
                      </div>
                      <div>
                        <h4 className="text-[15px] font-bold text-slate-200 flex items-center gap-2">
                          {edu.degree}
                          {edu.status === 'Verified' ? (
                            <span className="text-[10px] uppercase font-bold bg-[#22C55E]/10 text-[#22C55E] px-2 py-0.5 rounded-full flex items-center gap-1">
                              <CheckCircle2 size={10} /> Verified
                            </span>
                          ) : (
                            <span className="text-[10px] uppercase font-bold bg-[#F59E0B]/10 text-[#D97706] px-2 py-0.5 rounded-full">
                              Pending
                            </span>
                          )}
                        </h4>
                        <p className="text-[13px] text-slate-500 mt-0.5">{edu.institution} • {edu.year}</p>
                      </div>
                    </div>
                    <button 
                      onClick={() => handleRemoveEducation(edu.id)}
                      className="w-8 h-8 flex items-center justify-center text-slate-500 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                ))}
              </div>
            )}

          </div>
        </div>

      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { GoogleMap } from "@/components/shared/GoogleMap";
import { mockPracticeLocations } from "@/lib/doctorMockData";
import { 
  MapPin, Plus, Trash2, Navigation, Copy
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast, Toaster } from "sonner";

export default function PracticeLocationsPage() {
  const [locations, setLocations] = useState<{ id: string, name: string, address: string, googleMapsLink?: string }[]>([
    { id: "L-1", name: "Green View Hospital", address: "Dhanmondi, Dhaka", googleMapsLink: "" }
  ]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newLocation, setNewLocation] = useState({ name: "", address: "", googleMapsLink: "" });

  const handleAddLocation = () => {
    if (!newLocation.name || !newLocation.address) {
      toast.error("Name and Address are required.");
      return;
    }
    setLocations([
      ...locations,
      { id: `l${Date.now()}`, ...newLocation }
    ]);
    setShowAddForm(false);
    setNewLocation({ name: "", address: "", googleMapsLink: "" });
    toast.success("Location added successfully!");
  };

  const handleRemoveLocation = (id: string) => {
    setLocations(locations.filter(l => l.id !== id));
    toast.success("Location removed.");
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast.success("Address copied to clipboard!");
  };

  return (
    <div className="space-y-8 animate-fade-in-up pb-20">
      <Toaster position="top-center" />
      
      {/* Header */}
      <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 p-6 lg:p-8">
        <div className="flex justify-between items-start md:items-center">
          <div>
            <h1 className="text-2xl font-extrabold text-slate-200 tracking-tight flex items-center gap-3">
              Practice Locations
            </h1>
            <p className="text-slate-500 mt-1">Manage physical addresses where patients can visit you.</p>
          </div>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className="px-5 py-2.5 bg-[#2F80ED] hover:bg-[#2563EB] text-white font-bold rounded-xl shadow-none shadow-[#2F80ED]/20 transition-all flex items-center gap-2"
          >
            <Plus size={18} /> Add Location
          </button>
        </div>
      </div>

      <AnimatePresence>
        {showAddForm && (
          <motion.div 
            initial={{ opacity: 0, y: -20, height: 0 }}
            animate={{ opacity: 1, y: 0, height: 'auto' }}
            exit={{ opacity: 0, y: -20, height: 0 }}
            className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full p-6 lg:p-8"
          >
            <h3 className="text-[16px] font-bold text-slate-200 mb-6 flex items-center gap-2">
              <MapPin size={20} className="text-[#2F80ED]" /> Add New Practice Location
            </h3>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Location Name</label>
                <input 
                  type="text" 
                  placeholder="e.g. HealthCare Clinic"
                  value={newLocation.name}
                  onChange={(e) => setNewLocation({...newLocation, name: e.target.value})}
                  className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED]"
                />
              </div>
              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Google Maps Link (Optional)</label>
                <input 
                  type="text" 
                  placeholder="https://maps.google.com/..."
                  value={newLocation.googleMapsLink}
                  onChange={(e) => setNewLocation({...newLocation, googleMapsLink: e.target.value})}
                  className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED]"
                />
              </div>
              <div className="md:col-span-2">
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Complete Address</label>
                <textarea 
                  placeholder="Street address, building number, floor, city, etc."
                  value={newLocation.address}
                  onChange={(e) => setNewLocation({...newLocation, address: e.target.value})}
                  className="w-full min-h-[100px] bg-slate-950 border border-slate-700 rounded-xl p-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] resize-none"
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t border-slate-800">
              <button 
                onClick={() => setShowAddForm(false)}
                className="px-6 py-2.5 text-slate-500 hover:bg-slate-800 font-bold rounded-xl text-[14px] transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={handleAddLocation}
                className="px-8 py-2.5 bg-slate-800 text-white hover:bg-slate-700 font-bold rounded-xl text-[14px] shadow-none transition-all"
              >
                Save Location
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {locations.map((loc) => (
          <div key={loc.id} className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 p-6 flex flex-col justify-between group hover:border-[#2F80ED]/30 hover:shadow-none transition-all">
            
            <div>
              <div className="flex justify-between items-start mb-4">
                <div className="w-12 h-12 bg-sky-500/10 rounded-full flex items-center justify-center shrink-0">
                  <MapPin size={24} className="text-[#2F80ED]" />
                </div>
                <button 
                  onClick={() => handleRemoveLocation(loc.id)}
                  className="w-8 h-8 flex items-center justify-center text-slate-500 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                >
                  <Trash2 size={16} />
                </button>
              </div>
              <h3 className="text-[18px] font-bold text-slate-200 mb-2">{loc.name}</h3>
              <p className="text-[14px] text-slate-500 leading-relaxed mb-4">{loc.address}</p>
              
              <div className="w-full h-[180px] rounded-xl overflow-hidden border border-slate-700 shadow-inner mb-6">
                <GoogleMap 
                  lat={23.7461} 
                  lng={90.3742} 
                  title={loc.name}
                  className="h-full w-full"
                />
              </div>
            </div>

            <div className="flex items-center gap-3 pt-6 border-t border-slate-800">
              <button 
                onClick={() => copyToClipboard(loc.address)}
                className="flex-1 py-2.5 bg-slate-950 hover:bg-slate-800 text-slate-500 font-bold rounded-xl text-[13px] border border-slate-700 transition-colors flex justify-center items-center gap-2"
              >
                <Copy size={16} /> Copy Address
              </button>
              <button 
                onClick={() => {
                  if(loc.googleMapsLink) window.open(loc.googleMapsLink, '_blank');
                  else toast.info("No maps link provided for this location.");
                }}
                className={`w-11 h-11 flex items-center justify-center rounded-xl text-white transition-colors ${
                  loc.googleMapsLink ? 'bg-[#2F80ED] hover:bg-[#2563EB] shadow-none shadow-[#2F80ED]/20' : 'bg-slate-700 cursor-not-allowed'
                }`}
                title="Open in Maps"
              >
                <Navigation size={18} />
              </button>
            </div>
            
          </div>
        ))}
      </div>
      
      {locations.length === 0 && (
        <div className="text-center py-12 bg-slate-900 rounded-[24px] border border-slate-700 border-dashed">
          <MapPin size={48} className="text-slate-200 mx-auto mb-3" />
          <p className="text-slate-500 text-[14px]">No practice locations added.</p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useRef, useEffect, useMemo } from "react";
import { mockDoctorProfile } from "@/lib/doctorMockData";
import { 
  Camera, Save,
  Phone, Globe, Link,
  UploadCloud, FileText,
  Clock, CheckCircle2, Lock,
  User, IdCard, BadgeCheck
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast, Toaster } from "sonner";

export default function ProfileSettingsPage() {
  // --- Form State ---
  const [formData, setFormData] = useState({
    ...mockDoctorProfile,
    gender: "Male",
    phone: "+880 1711-000000",
    whatsapp: "+880 1711-000000",
    facebook: "facebook.com/dr.fazlul",
    linkedin: "linkedin.com/in/drfazlul",
    avatar: mockDoctorProfile.avatar,
  });

  const [isSaving, setIsSaving] = useState(false);
  const avatarInputRef = useRef<HTMLInputElement>(null);
  
  // --- Identity ID State ---
  const [idType, setIdType] = useState("Government ID");
  const [idStatus, setIdStatus] = useState<"none" | "pending" | "verified">("none");
  const [idFile, setIdFile] = useState<File | null>(null);
  const idInputRef = useRef<HTMLInputElement>(null);

  // --- Load Initial State ---
  useEffect(() => {
    const savedIdStatus = localStorage.getItem('oxpecker_doc_id_status');
    if (savedIdStatus) setIdStatus(savedIdStatus as any);
    
    const savedIdType = localStorage.getItem('oxpecker_doc_id_type');
    if (savedIdType) setIdType(savedIdType);
  }, []);

  // --- Calculate Verification Score (Adjusted for Profile Only) ---
  const verificationScore = useMemo(() => {
    let score = 0;
    
    // Basic Info: 30%
    if (formData.name && formData.specialization && formData.bio && formData.gender) score += 30;
    
    // Contact Info: 30%
    if (formData.consultationFee && formData.phone && (formData.facebook || formData.linkedin)) score += 30;
    
    // ID Verification: 40%
    if (idStatus === "pending" || idStatus === "verified") score += 40;

    return score;
  }, [formData, idStatus]);

  // --- Handlers ---
  const handleSaveProfile = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      toast.success("Profile updated successfully!");
    }, 1500);
  };

  const handleAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (!file.type.includes('image/')) {
        toast.error("Please upload a valid image file (JPG/PNG).");
        return;
      }
      
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setFormData(prev => ({ ...prev, avatar: event.target!.result as string }));
          toast.success("Profile photo updated!");
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (!file.type.includes('pdf') && !file.type.includes('image/')) {
        toast.error("Please upload a PDF or Image (JPG/PNG).");
        return;
      }
      setIdFile(file);
    }
  };

  const handleSubmitID = () => {
    if (!idFile) return toast.error("Please upload your Identity Document.");

    toast.loading("Submitting identity document securely...", { id: 'idDoc' });
    setTimeout(() => {
      toast.success("Identity document submitted for verification!", { id: 'idDoc' });
      setIdStatus("pending");
      localStorage.setItem('oxpecker_doc_id_status', 'pending');
      localStorage.setItem('oxpecker_doc_id_type', idType);
    }, 2000);
  };

  // UI Helpers
  const isGreen = verificationScore >= 90;
  const isYellow = verificationScore >= 40 && verificationScore < 90;

  const specializations = [
    "Cardiology", "Dermatology", "Neurology", "Orthopedics", 
    "Pediatrics", "Psychiatry", "General Practice", "Gynecology",
    "Oncology", "Urology", "Endocrinology", "Ophthalmology"
  ];

  return (
    <div className="space-y-8 animate-fade-in-up pb-20">
      <Toaster position="top-center" />
      
      {/* Header & Verification Bar */}
      <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 p-6 lg:p-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h1 className="text-2xl font-extrabold text-slate-200 tracking-tight flex items-center gap-3">
              Public Profile 
              {isGreen && <BadgeCheck size={28} className="text-[#22C55E]" />}
            </h1>
            <p className="text-slate-500 mt-1">Manage your public information and identity verification.</p>
          </div>

          <div className="w-full md:w-[350px]">
            <div className="flex justify-between items-end mb-2">
              <span className="text-[13px] font-bold text-slate-500 uppercase tracking-wider">Profile Verification</span>
              <span className={`text-[20px] font-extrabold ${isGreen ? 'text-[#22C55E]' : isYellow ? 'text-[#F59E0B]' : 'text-slate-500'}`}>
                {verificationScore}%
              </span>
            </div>
            <div className="h-3 w-full bg-slate-800 rounded-full overflow-hidden">
              <motion.div 
                initial={{ width: 0 }}
                animate={{ width: `${verificationScore}%` }}
                transition={{ duration: 1, ease: "easeOut" }}
                className={`h-full rounded-full ${
                  isGreen 
                    ? 'bg-emerald-500' 
                    : isYellow 
                      ? 'bg-amber-400' 
                      : 'bg-slate-700'
                }`}
              />
            </div>
            {isGreen && <p className="text-[12px] font-bold text-emerald-500 mt-2 flex items-center gap-1 justify-end"><CheckCircle2 size={14}/> Identity Verified</p>}
          </div>
        </div>
      </div>

      {/* Main Stack */}
      <div className="flex flex-col gap-8">
        
        {/* Full Page Width: Public Profile Form */}
        <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full">
          
          <div className="p-6 border-b border-slate-800 flex flex-col sm:flex-row items-center gap-6 bg-slate-950">
            <div className="relative group shrink-0">
              <div className="w-[100px] h-[100px] rounded-full overflow-hidden border-4 border-white shadow-none bg-slate-800 relative">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={formData.avatar} alt="Profile" className="w-full h-full object-cover" />
                {isGreen && (
                  <div className="absolute inset-0 border-4 border-[#22C55E] rounded-full pointer-events-none"></div>
                )}
              </div>
            </div>
            <div className="text-center sm:text-left flex-1">
              <h3 className="text-[18px] font-bold text-slate-200 flex items-center justify-center sm:justify-start gap-2">
                Public Photo 
              </h3>
              <p className="text-[13px] text-slate-500 mt-1 mb-4">Recommended size: 400x400px (JPG or PNG).</p>
              <div className="flex items-center justify-center sm:justify-start gap-3">
                <input 
                  type="file" 
                  ref={avatarInputRef} 
                  onChange={handleAvatarUpload} 
                  accept="image/jpeg,image/png,image/jpg" 
                  className="hidden" 
                />
                <button 
                  onClick={() => avatarInputRef.current?.click()}
                  className="px-5 py-2 bg-slate-900 border border-slate-700 hover:bg-slate-950 text-slate-300 text-[13px] font-bold rounded-xl transition-colors shadow-none flex items-center gap-2"
                >
                  <Camera size={14}/> Change Photo
                </button>
                <button 
                  onClick={() => setFormData(prev => ({ ...prev, avatar: "https://i.pravatar.cc/150?u=placeholder" }))}
                  className="px-5 py-2 text-red-500 hover:bg-red-50 text-[13px] font-bold rounded-xl transition-colors"
                >
                  Remove
                </button>
              </div>
            </div>
          </div>

          <div className="p-6 lg:p-8 space-y-6">
            {/* Basic Info */}
            <div>
              <h4 className="text-[15px] font-bold text-slate-200 mb-4 flex items-center gap-2">
                <User size={18} className="text-[#2F80ED]" /> Basic Information
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
                <div className="md:col-span-1">
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Full Name</label>
                  <input 
                    type="text" 
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all"
                  />
                </div>
                
                <div className="md:col-span-1">
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Gender</label>
                  <select 
                    value={formData.gender}
                    onChange={(e) => setFormData({...formData, gender: e.target.value})}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all"
                  >
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Other">Other</option>
                  </select>
                </div>

                <div className="md:col-span-1">
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Specialization</label>
                  <select 
                    value={formData.specialization}
                    onChange={(e) => setFormData({...formData, specialization: e.target.value})}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all"
                  >
                    {specializations.map(spec => (
                      <option key={spec} value={spec}>{spec}</option>
                    ))}
                  </select>
                </div>

                <div className="md:col-span-3">
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Professional Bio</label>
                  <textarea 
                    value={formData.bio}
                    onChange={(e) => setFormData({...formData, bio: e.target.value})}
                    className="w-full min-h-[100px] bg-slate-950 border border-slate-700 rounded-xl p-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all resize-none"
                  />
                </div>
              </div>
            </div>

            <div className="h-[1px] w-full bg-slate-800"></div>

            {/* Consultation & Contact */}
            <div>
              <h4 className="text-[15px] font-bold text-slate-200 mb-4 flex items-center gap-2">
                <Phone size={18} className="text-[#2F80ED]" /> Contact & Fees
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Consultation Fee (BDT)</label>
                  <input 
                    type="text" 
                    value={formData.consultationFee}
                    onChange={(e) => setFormData({...formData, consultationFee: e.target.value})}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1 flex items-center gap-1.5">
                      Public Phone Number
                  </label>
                  <input 
                    type="text" 
                    value={formData.phone}
                    onChange={(e) => setFormData({...formData, phone: e.target.value})}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1 flex items-center gap-1.5">
                    <Globe size={14} className="text-[#1877F2]" /> Facebook Profile
                  </label>
                  <input 
                    type="text" 
                    value={formData.facebook}
                    onChange={(e) => setFormData({...formData, facebook: e.target.value})}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1 flex items-center gap-1.5">
                    <Link size={14} className="text-[#0A66C2]" /> LinkedIn Profile
                  </label>
                  <input 
                    type="text" 
                    value={formData.linkedin}
                    onChange={(e) => setFormData({...formData, linkedin: e.target.value})}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] focus:bg-slate-900 transition-all"
                  />
                </div>
              </div>
            </div>
            
            <div className="pt-4 flex justify-end">
              <button 
                onClick={handleSaveProfile}
                disabled={isSaving}
                className="w-full sm:w-auto px-8 py-3 bg-slate-800 hover:bg-slate-700 text-white text-[14px] font-bold rounded-xl shadow-none shadow-slate-800/20 transition-all flex items-center justify-center gap-2"
              >
                {isSaving ? (
                  <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                ) : (
                  <Save size={18} />
                )}
                Save Profile
              </button>
            </div>

          </div>
        </div>

        {/* Identity Document Verification (Full Width Panel) */}
        <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full xl:w-1/2">
          <div className="p-6 border-b border-slate-800 bg-[#8B5CF6]/5">
            <h3 className="text-[16px] font-bold text-slate-200 flex items-center gap-2">
              <IdCard size={20} className="text-[#8B5CF6]" /> Identity Verification
            </h3>
            <p className="text-[13px] text-slate-500 mt-1 leading-snug">Verify your identity to increase trust and receive the verified profile badge.</p>
          </div>
          
          <div className="p-6 space-y-6">
            
            <AnimatePresence>
              {idStatus === "pending" && (
                <motion.div 
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  className="bg-[#F59E0B]/10 border border-[#F59E0B]/30 rounded-[16px] p-4 flex gap-3"
                >
                  <Clock size={20} className="text-[#F59E0B] shrink-0 mt-0.5" />
                  <div>
                    <h4 className="text-[14px] font-bold text-[#D97706]">Pending Verification</h4>
                    <p className="text-[13px] text-[#D97706]/80 mt-1 leading-snug">
                      Your ID document is under review by the Super Admin. Please allow up to <strong>72 hours</strong> for manual verification.
                    </p>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="space-y-4">
              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 flex justify-between items-center">
                  <span>Document Type</span>
                  {idStatus === "pending" && <Lock size={12} className="text-slate-500" />}
                </label>
                <select 
                  value={idType}
                  onChange={(e) => setIdType(e.target.value)}
                  disabled={idStatus === "pending"}
                  className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl px-4 text-[14px] text-slate-200 focus:outline-none focus:border-[#8B5CF6] disabled:opacity-60 disabled:cursor-not-allowed transition-all"
                >
                  <option value="Government ID">Government ID (NID)</option>
                  <option value="Passport">Passport</option>
                  <option value="Driving License">Driving License</option>
                </select>
              </div>

              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 flex justify-between items-center">
                  <span>Upload {idType} (PDF/JPG)</span>
                  {idStatus === "pending" && <Lock size={12} className="text-slate-500" />}
                </label>
                
                <input 
                  type="file"
                  ref={idInputRef}
                  onChange={handleFileUpload}
                  accept=".pdf,image/jpeg,image/png"
                  className="hidden"
                  disabled={idStatus === "pending"}
                />

                <div 
                  onClick={() => idStatus !== "pending" && idInputRef.current?.click()}
                  className={`w-full border-2 border-dashed rounded-[16px] p-6 flex flex-col items-center justify-center transition-all ${
                    idStatus === "pending" 
                      ? "border-slate-700 bg-slate-950 opacity-60 cursor-not-allowed" 
                      : "border-slate-600 bg-slate-950 hover:bg-[#8B5CF6]/5 hover:border-[#8B5CF6] cursor-pointer"
                  }`}
                >
                  {idFile ? (
                    <div className="flex flex-col items-center">
                      <FileText size={32} className="text-[#22C55E] mb-2" />
                      <span className="text-[13px] font-bold text-slate-300 text-center">{idFile.name}</span>
                      <span className="text-[11px] text-slate-500 mt-1">Ready to upload</span>
                    </div>
                  ) : (
                    <div className="flex flex-col items-center">
                      <UploadCloud size={32} className="text-slate-500 mb-3" />
                      <span className="text-[14px] font-bold text-slate-300">Click to upload document</span>
                      <span className="text-[12px] text-slate-500 mt-1">Clear copy required (Max 5MB)</span>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {idStatus !== "pending" && (
              <button 
                onClick={handleSubmitID}
                className="w-full bg-slate-800 hover:bg-slate-700 text-white font-bold py-3.5 rounded-xl shadow-none transition-all active:scale-[0.98] flex items-center justify-center gap-2"
              >
                <IdCard size={18} />
                Submit Identity Document
              </button>
            )}

            {idStatus === "pending" && (
              <button 
                disabled
                className="w-full bg-slate-800 text-slate-500 font-bold py-3.5 rounded-xl border border-slate-700 cursor-not-allowed flex items-center justify-center gap-2"
              >
                <Lock size={16} /> Locked During Review
              </button>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { 
  ShieldAlert, KeyRound, Smartphone, Monitor, Lock, AlertTriangle, Eye, EyeOff
} from "lucide-react";
import { motion } from "framer-motion";
import { toast, Toaster } from "sonner";

export default function SecuritySettingsPage() {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState({ current: false, new: false, confirm: false });
  
  const [twoFactorEnabled, setTwoFactorEnabled] = useState(true);
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  const activeSessions = [
    { id: 1, device: "Windows 11 - Chrome", location: "Dhaka, Bangladesh", time: "Active now", current: true, icon: Monitor },
    { id: 2, device: "iPhone 15 Pro - Safari", location: "Dhaka, Bangladesh", time: "Last active: 2 hours ago", current: false, icon: Smartphone },
  ];

  const handleUpdatePassword = () => {
    if (!currentPassword || !newPassword || !confirmPassword) {
      toast.error("Please fill all password fields.");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("New passwords do not match.");
      return;
    }
    setIsChangingPassword(true);
    setTimeout(() => {
      setIsChangingPassword(false);
      setCurrentPassword("");
      setNewPassword("");
      setConfirmPassword("");
      toast.success("Password updated successfully!");
    }, 1500);
  };

  const handleToggle2FA = () => {
    setTwoFactorEnabled(!twoFactorEnabled);
    toast.success(`Two-Factor Authentication ${!twoFactorEnabled ? 'Enabled' : 'Disabled'}.`);
  };

  const handleLogoutSession = (id: number) => {
    toast.success("Session terminated securely.");
  };

  return (
    <div className="space-y-8 animate-fade-in-up pb-20">
      <Toaster position="top-center" />
      
      {/* Header */}
      <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 p-6 lg:p-8">
        <div>
          <h1 className="text-2xl font-extrabold text-slate-200 tracking-tight flex items-center gap-3">
            Account & Security
          </h1>
          <p className="text-slate-500 mt-1">Manage your password, 2FA, and active sessions.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        
        {/* Left Column: Password & 2FA */}
        <div className="space-y-8">
          
          {/* Change Password */}
          <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full">
            <div className="p-6 border-b border-slate-800 bg-slate-950">
              <h3 className="text-[16px] font-bold text-slate-200 flex items-center gap-2">
                <KeyRound size={20} className="text-[#2F80ED]" /> Change Password
              </h3>
            </div>
            
            <div className="p-6 space-y-5">
              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Current Password</label>
                <div className="relative">
                  <input 
                    type={showPassword.current ? "text" : "password"} 
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl pl-4 pr-12 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] transition-all"
                  />
                  <button 
                    onClick={() => setShowPassword({ ...showPassword, current: !showPassword.current })}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300"
                  >
                    {showPassword.current ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">New Password</label>
                <div className="relative">
                  <input 
                    type={showPassword.new ? "text" : "password"} 
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl pl-4 pr-12 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] transition-all"
                  />
                  <button 
                    onClick={() => setShowPassword({ ...showPassword, new: !showPassword.new })}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300"
                  >
                    {showPassword.new ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-[13px] font-semibold text-slate-500 mb-1.5 ml-1">Confirm New Password</label>
                <div className="relative">
                  <input 
                    type={showPassword.confirm ? "text" : "password"} 
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full h-[48px] bg-slate-950 border border-slate-700 rounded-xl pl-4 pr-12 text-[14px] text-slate-200 focus:outline-none focus:border-[#2F80ED] transition-all"
                  />
                  <button 
                    onClick={() => setShowPassword({ ...showPassword, confirm: !showPassword.confirm })}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300"
                  >
                    {showPassword.confirm ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <button 
                onClick={handleUpdatePassword}
                disabled={isChangingPassword}
                className="w-full h-[48px] bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-xl shadow-none transition-all mt-2"
              >
                {isChangingPassword ? "Updating..." : "Update Password"}
              </button>
            </div>
          </div>

          {/* 2FA */}
          <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full">
            <div className="p-6 flex items-center justify-between">
              <div className="flex gap-4 items-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${twoFactorEnabled ? 'bg-[#22C55E]/10' : 'bg-slate-800'}`}>
                  <ShieldAlert size={24} className={twoFactorEnabled ? 'text-[#22C55E]' : 'text-slate-500'} />
                </div>
                <div>
                  <h3 className="text-[16px] font-bold text-slate-200">Two-Factor Authentication</h3>
                  <p className="text-[13px] text-slate-500 mt-1">Add an extra layer of security to your account.</p>
                </div>
              </div>
              <button 
                onClick={handleToggle2FA}
                className={`relative inline-flex h-7 w-12 items-center rounded-full transition-colors focus:outline-none ${twoFactorEnabled ? 'bg-[#22C55E]' : 'bg-slate-700'}`}
              >
                <span className={`inline-block h-5 w-5 transform rounded-full bg-slate-900 transition-transform shadow-none ${twoFactorEnabled ? 'translate-x-6' : 'translate-x-1'}`} />
              </button>
            </div>
            
            {twoFactorEnabled && (
              <div className="px-6 pb-6 pt-2">
                <div className="bg-slate-950 border border-slate-700 rounded-xl p-4 flex gap-3">
                  <Lock size={16} className="text-slate-500 shrink-0 mt-0.5" />
                  <p className="text-[13px] text-slate-500">
                    2FA is currently <strong className="text-[#22C55E]">Enabled</strong>. You will receive an OTP via SMS to your registered phone number upon every new login.
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Right Column: Active Sessions */}
        <div className="bg-slate-900 rounded-[24px] shadow-none border border-slate-700 overflow-hidden w-full h-fit">
          <div className="p-6 border-b border-slate-800 bg-slate-950 flex justify-between items-center">
            <h3 className="text-[16px] font-bold text-slate-200 flex items-center gap-2">
              <Monitor size={20} className="text-[#2F80ED]" /> Active Sessions
            </h3>
            <button className="text-[13px] font-bold text-red-500 hover:text-red-600">
              Logout All
            </button>
          </div>
          
          <div className="p-2">
            {activeSessions.map((session, i) => {
              const Icon = session.icon;
              return (
                <div key={session.id} className={`p-4 flex items-center justify-between ${i !== activeSessions.length -1 ? 'border-b border-slate-800' : ''}`}>
                  <div className="flex gap-4 items-center">
                    <div className="w-10 h-10 bg-slate-950 border border-slate-700 rounded-full flex items-center justify-center shrink-0">
                      <Icon size={18} className="text-slate-500" />
                    </div>
                    <div>
                      <h4 className="text-[14px] font-bold text-slate-200 flex items-center gap-2">
                        {session.device}
                        {session.current && (
                          <span className="text-[10px] uppercase font-bold bg-[#22C55E]/10 text-[#22C55E] px-2 py-0.5 rounded-full">
                            Current
                          </span>
                        )}
                      </h4>
                      <p className="text-[13px] text-slate-500 mt-0.5">{session.location} • {session.time}</p>
                    </div>
                  </div>
                  {!session.current && (
                    <button 
                      onClick={() => handleLogoutSession(session.id)}
                      className="text-[13px] font-bold text-slate-500 hover:text-red-500 px-3 py-1.5 rounded-lg hover:bg-red-50 transition-colors"
                    >
                      Logout
                    </button>
                  )}
                </div>
              )
            })}
          </div>

          <div className="p-6 bg-[#F59E0B]/5 border-t border-[#F59E0B]/20">
            <div className="flex gap-3">
              <AlertTriangle size={18} className="text-[#F59E0B] shrink-0 mt-0.5" />
              <p className="text-[13px] text-slate-500 leading-relaxed">
                If you notice any unfamiliar devices in this list, immediately change your password and click "Logout All".
              </p>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

"use client";

import { use, useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { ArrowLeft, MapPin, Calendar, Clock, CheckCircle2, Building2 } from "lucide-react";
import { mockDoctors, DoctorProfile } from "@/lib/mockData";

const consultationTypes = ["Hospital Visit", "Video Call"];

export default function BookingPage({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter();
  const resolvedParams = use(params);
  const [doctor, setDoctor] = useState<DoctorProfile | null>(null);
  const [step, setStep] = useState(1);
  
  // Form State
  const [consultType, setConsultType] = useState("Hospital Visit");
  const [selectedChamber, setSelectedChamber] = useState("");
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedTime, setSelectedTime] = useState("");

  useEffect(() => {
    const doc = mockDoctors.find(d => d.id === resolvedParams.id);
    if (doc) setDoctor(doc);
  }, [resolvedParams.id]);

  if (!doctor) {
    return <div className="h-full flex items-center justify-center bg-white">Loading booking engine...</div>;
  }

  // Generate next 7 days for the date picker
  const dates = Array.from({ length: 7 }).map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() + i);
    return {
      dayStr: d.toLocaleDateString('en-US', { weekday: 'short' }),
      dateNum: d.getDate(),
      fullDate: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    };
  });

  const nextStep = () => setStep(s => Math.min(s + 1, 5));
  const prevStep = () => setStep(s => Math.max(s - 1, 1));
  const submitBooking = () => setStep(5);

  return (
    <div className="h-full overflow-y-auto bg-white font-sans pb-32 selection:bg-sky-600/20">
      
      {/* Minimalist Header */}
      <div className="sticky top-0 z-40 bg-white/80 backdrop-blur-xl border-b border-slate-100">
        <div className="max-w-[1000px] mx-auto px-6 h-[72px] flex items-center justify-between">
          <button 
            onClick={() => router.back()}
            className="flex items-center gap-2 text-slate-500 hover:text-slate-900 font-medium transition-colors text-[15px]"
          >
            <ArrowLeft size={18} /> Back
          </button>
          
          {/* Subtle Progress Indicator */}
          <div className="hidden md:flex items-center gap-1.5">
            {[1, 2, 3, 4].map(i => (
              <div 
                key={i} 
                className={`h-1.5 rounded-full transition-all duration-500 ${
                  i === step ? 'w-8 bg-sky-600' : i < step ? 'w-4 bg-sky-600/40' : 'w-4 bg-slate-100'
                }`} 
              />
            ))}
          </div>
        </div>
      </div>

      <div className="max-w-[1000px] mx-auto mt-8 md:mt-12 px-6 flex flex-col lg:flex-row gap-12 md:gap-20">
        
        {/* Left Column - Clean Booking Flow */}
        <div className="flex-1 min-h-[500px]">
            
          {/* Step 1: Consultation & Chamber */}
          {step === 1 && (
            <div className="animate-fade-in-up">
              <h1 className="text-[32px] md:text-[36px] font-[800] text-slate-900 tracking-tight mb-2">Consultation Type</h1>
              <p className="text-[16px] text-slate-500 mb-10">How would you like to consult the doctor?</p>
              
              <div className="grid grid-cols-2 gap-4 mb-10">
                {consultationTypes.map(type => (
                  <button
                    key={type}
                    onClick={() => setConsultType(type)}
                    className={`relative p-5 md:p-6 rounded-[20px] text-center transition-all duration-300 ${
                      consultType === type 
                        ? 'bg-slate-900 text-white shadow-xl shadow-slate-900/10 scale-[1.02]' 
                        : 'bg-slate-50 text-slate-600 hover:bg-slate-100'
                    }`}
                  >
                    <span className="font-semibold text-[15px]">{type}</span>
                    {consultType === type && (
                      <CheckCircle2 size={18} className="absolute top-4 right-4 text-white/50" />
                    )}
                  </button>
                ))}
              </div>

              {consultType === "Hospital Visit" && doctor.chambers && doctor.chambers.length > 0 && (
                <div className="animate-fade-in-up">
                  <h3 className="text-[18px] font-bold text-slate-900 mb-5">Available Chambers</h3>
                  <div className="space-y-4">
                    {doctor.chambers.map((chamber, i) => (
                      <button
                        key={i}
                        onClick={() => setSelectedChamber(chamber.name)}
                        className={`w-full p-5 rounded-[20px] text-left transition-all duration-300 flex items-start gap-5 ${
                          selectedChamber === chamber.name 
                            ? 'bg-slate-900 text-white shadow-md' 
                            : 'bg-white ring-1 ring-slate-100 hover:ring-slate-200 hover:bg-slate-50'
                        }`}
                      >
                        <div className={`mt-0.5 p-3 rounded-[14px] ${selectedChamber === chamber.name ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-400'}`}>
                          <Building2 size={20} />
                        </div>
                        <div>
                          <h4 className={`font-bold text-[17px] mb-1 ${selectedChamber === chamber.name ? 'text-white' : 'text-slate-900'}`}>{chamber.name}</h4>
                          <p className={`text-[14px] leading-relaxed mb-2 ${selectedChamber === chamber.name ? 'text-slate-300' : 'text-slate-500'}`}>{chamber.address}</p>
                          <div className={`inline-flex items-center gap-2 px-2.5 py-1 rounded-md text-[13px] font-medium ${selectedChamber === chamber.name ? 'bg-white/10 text-white' : 'bg-slate-100 text-slate-600'}`}>
                            <Clock size={14} /> {chamber.days}, {chamber.time}
                          </div>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Step 2: Date & Time */}
          {step === 2 && (
            <div className="animate-fade-in-up">
              <h1 className="text-[32px] md:text-[36px] font-[800] text-slate-900 tracking-tight mb-2">Date & Time</h1>
              <p className="text-[16px] text-slate-500 mb-10">Select your preferred slot for the appointment.</p>
              
              <h3 className="text-[18px] font-bold text-slate-900 mb-5">October 2026</h3>
              <div className="flex gap-3 overflow-x-auto pb-6 scrollbar-hide -mx-6 px-6 md:mx-0 md:px-0">
                {dates.map((d, i) => (
                  <button
                    key={i}
                    onClick={() => setSelectedDate(d.fullDate)}
                    className={`min-w-[72px] h-[90px] rounded-[20px] flex flex-col items-center justify-center transition-all duration-300 shrink-0 ${
                      selectedDate === d.fullDate 
                        ? 'bg-slate-900 text-white shadow-xl shadow-slate-900/10 scale-[1.05]' 
                        : 'bg-white ring-1 ring-slate-100 text-slate-500 hover:bg-slate-50'
                    }`}
                  >
                    <span className="text-[13px] font-medium mb-1 uppercase tracking-wider">{d.dayStr}</span>
                    <span className="text-[22px] font-bold">{d.dateNum}</span>
                  </button>
                ))}
              </div>

              <div className="flex flex-wrap items-center justify-between mt-6 mb-5 gap-2">
                <h3 className="text-[18px] font-bold text-slate-900">Available Slots</h3>
                <span className="text-xs font-semibold text-rose-600 bg-rose-50 px-2.5 py-1 rounded-lg animate-pulse border border-rose-100 flex items-center gap-1">
                  Slots filling fast: Only 2 left
                </span>
              </div>
              <div className="grid grid-cols-3 gap-3">
                {doctor.timeSlots.map((time, i) => (
                  <button
                    key={i}
                    onClick={() => setSelectedTime(time)}
                    className={`py-3.5 rounded-[14px] text-center transition-all duration-300 text-[14px] font-medium ${
                      selectedTime === time 
                        ? 'bg-sky-600 text-white shadow-md shadow-primary/20 scale-[1.02]' 
                        : 'bg-slate-50 text-slate-600 hover:bg-slate-100'
                    }`}
                  >
                    {time}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Step 3: Patient Info */}
          {step === 3 && (
            <div className="animate-fade-in-up">
              <h1 className="text-[32px] md:text-[36px] font-[800] text-slate-900 tracking-tight mb-2">Patient Details</h1>
              <p className="text-[16px] text-slate-500 mb-10">Please provide the patient's basic information.</p>
              
              <div className="space-y-8">
                <div>
                  <label className="block text-[13px] font-bold text-slate-500 uppercase tracking-wider mb-3">Patient Name</label>
                  <input type="text" placeholder="e.g. John Doe" className="w-full pb-3 bg-transparent text-[18px] text-slate-900 placeholder:text-slate-300 border-b border-slate-200 focus:border-primary outline-none transition-colors" />
                </div>
                
                <div className="grid grid-cols-2 gap-8">
                  <div>
                    <label className="block text-[13px] font-bold text-slate-500 uppercase tracking-wider mb-3">Age</label>
                    <input type="number" placeholder="28" className="w-full pb-3 bg-transparent text-[18px] text-slate-900 placeholder:text-slate-300 border-b border-slate-200 focus:border-primary outline-none transition-colors" />
                  </div>
                  <div>
                    <label className="block text-[13px] font-bold text-slate-500 uppercase tracking-wider mb-3">Gender</label>
                    <select className="w-full pb-3 bg-transparent text-[18px] text-slate-900 border-b border-slate-200 focus:border-primary outline-none transition-colors cursor-pointer appearance-none">
                      <option value="" disabled selected className="text-slate-300">Select Gender</option>
                      <option>Male</option>
                      <option>Female</option>
                      <option>Other</option>
                    </select>
                  </div>
                </div>
                
                <div>
                  <label className="block text-[13px] font-bold text-slate-500 uppercase tracking-wider mb-3">Reason for visit (Optional)</label>
                  <textarea rows={1} placeholder="Briefly describe your symptoms..." className="w-full pb-3 bg-transparent text-[18px] text-slate-900 placeholder:text-slate-300 border-b border-slate-200 focus:border-primary outline-none transition-colors resize-none" />
                </div>
              </div>
            </div>
          )}

          {/* Step 4: Summary & Payment */}
          {step === 4 && (
            <div className="animate-fade-in-up">
              <h1 className="text-[32px] md:text-[36px] font-[800] text-slate-900 tracking-tight mb-2">Review Booking</h1>
              <p className="text-[16px] text-slate-500 mb-10">Verify your details before confirming the appointment.</p>
              
              <div className="bg-slate-50 p-6 md:p-8 rounded-[24px] mb-8 relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-1 h-full bg-sky-600" />
                
                <div className="flex flex-col md:flex-row md:items-center gap-6 mb-8 pb-8 border-b border-slate-200">
                  <div className="w-[72px] h-[72px] rounded-full overflow-hidden shrink-0 relative ring-4 ring-white shadow-sm">
                    <Image src={doctor.image} alt={doctor.name} fill className="object-cover" />
                  </div>
                  <div>
                    <h4 className="font-bold text-[22px] text-slate-900 mb-1">{doctor.name}</h4>
                    <p className="text-sky-600 font-medium text-[15px]">{doctor.specialty}</p>
                  </div>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                  <div>
                    <p className="text-[12px] font-bold text-slate-400 uppercase tracking-wider mb-1">Date & Time</p>
                    <p className="text-[16px] font-semibold text-slate-900 flex items-center gap-2">
                      <Calendar size={16} className="text-slate-400" />
                      {selectedDate || "Not selected"}, {selectedTime}
                    </p>
                  </div>
                  <div>
                    <p className="text-[12px] font-bold text-slate-400 uppercase tracking-wider mb-1">Consultation Type</p>
                    <p className="text-[16px] font-semibold text-slate-900 flex items-center gap-2">
                      <Building2 size={16} className="text-slate-400" />
                      {consultType}
                    </p>
                  </div>
                  {consultType === "Hospital Visit" && (
                    <div className="md:col-span-2">
                      <p className="text-[12px] font-bold text-slate-400 uppercase tracking-wider mb-1">Chamber Address</p>
                      <p className="text-[16px] font-semibold text-slate-900 flex items-start gap-2">
                        <MapPin size={16} className="text-slate-400 shrink-0 mt-0.5" />
                        <span>{selectedChamber}</span>
                      </p>
                    </div>
                  )}
                </div>
              </div>

              <div className=" from-primary/5 via-primary/[0.08] to-primary/5 p-6 rounded-[24px] border border-primary/20 relative overflow-hidden group">
                <div className="absolute -right-10 -top-10 w-40 h-40 bg-sky-600/10 rounded-full blur-3xl pointer-events-none" />
                
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 relative z-10">
                  <div>
                    <span className="block font-[800] text-[18px] text-slate-900 mb-1">Total Payable Amount</span>
                    <span className="text-[13px] text-slate-500 font-medium bg-white/50 px-2 py-0.5 rounded-md border border-slate-200/50">Includes all taxes and fees</span>
                  </div>
                  <div className="flex items-start gap-1 text-sky-600">
                    <span className="text-[20px] font-bold mt-1.5">৳</span>
                    <span className="font-[900] text-[48px] tracking-tight leading-none drop-shadow-sm">{doctor.fee}</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Step 5: Success */}
          {step === 5 && (
            <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-center animate-fade-in-up">
              <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mb-6">
                <CheckCircle2 size={40} className="text-green-500" />
              </div>
              <h2 className="text-[36px] font-[800] text-slate-900 tracking-tight mb-3">Booking Confirmed</h2>
              <p className="text-slate-500 text-[16px] max-w-[400px] leading-relaxed mb-10">
                Your appointment with <span className="font-semibold text-slate-900">{doctor.name}</span> is confirmed for <span className="font-semibold text-slate-900">{selectedDate}</span> at <span className="font-semibold text-slate-900">{selectedTime}</span>.
              </p>
              <button 
                onClick={() => router.push(`/doctors/${doctor.id}`)}
                className="px-8 h-[52px] bg-slate-900 hover:bg-slate-800 text-white rounded-full font-semibold text-[15px] transition-colors"
              >
                Done
              </button>
            </div>
          )}
          
          {/* Action Buttons */}
          {step < 5 && (
            <div className="mt-12 pt-8 flex items-center justify-between border-t border-slate-100">
              {step > 1 ? (
                <button 
                  onClick={prevStep}
                  className="px-6 h-[48px] text-slate-500 hover:text-slate-900 font-semibold text-[15px] transition-colors"
                >
                  Back
                </button>
              ) : <div></div>}
              
              <button 
                onClick={step === 4 ? submitBooking : nextStep}
                disabled={(step === 1 && consultType === 'Hospital Visit' && !selectedChamber) || (step === 2 && (!selectedDate || !selectedTime))}
                className={`px-8 h-[48px] rounded-full font-semibold text-[15px] transition-all duration-300 ${
                  ((step === 1 && consultType === 'Hospital Visit' && !selectedChamber) || (step === 2 && (!selectedDate || !selectedTime)))
                    ? 'bg-slate-100 text-slate-400 cursor-not-allowed'
                    : 'bg-sky-600 text-white shadow-lg shadow-primary/20 hover:bg-[#0052cc] hover:-translate-y-0.5'
                }`}
              >
                {step === 4 ? "Confirm & Pay" : "Continue"}
              </button>
            </div>
          )}

        </div>

        {/* Right Column - Minimalist Profile Snippet (Hidden on Success) */}
        {step < 5 && (
          <div className="hidden lg:block w-[320px] shrink-0">
            <div className="sticky top-[104px]">
              
              <div className="mb-8">
                <h3 className="font-[800] text-[20px] text-slate-900 mb-6">Booking Summary</h3>
                
                <div className="flex items-center gap-4 mb-6">
                  <div className="w-14 h-14 rounded-full overflow-hidden relative border border-slate-200">
                    <Image src={doctor.image} alt={doctor.name} fill className="object-cover" />
                  </div>
                  <div>
                    <h4 className="font-bold text-[16px] text-slate-900 leading-snug">{doctor.name}</h4>
                    <p className="text-[13px] font-medium text-slate-500">{doctor.specialty}</p>
                  </div>
                </div>
                
                <div className="space-y-4">
                  <div className="flex justify-between items-center text-[14px]">
                    <span className="text-slate-500">Consultation Fee</span>
                    <span className="text-slate-900 font-bold">৳{doctor.fee}</span>
                  </div>
                  <div className="flex justify-between items-center text-[14px]">
                    <span className="text-slate-500">Service Charge</span>
                    <span className="text-slate-900 font-bold">৳50</span>
                  </div>
                  
                  <div className="pt-4 mt-2 border-t border-dashed border-slate-200">
                    <span className="text-slate-500 text-[12px] font-bold uppercase tracking-wider mb-2 block">Total to Pay</span>
                    <div className=" from-primary/5  p-4 rounded-xl border border-sky-200 flex items-center justify-between">
                      <span className="text-slate-800 font-bold text-[14px]">Payable Now</span>
                      <div className="flex items-start gap-1 text-sky-600">
                        <span className="text-[16px] font-bold mt-0.5">৳</span>
                        <span className="text-[32px] font-[900] leading-none tracking-tight">{Number(doctor.fee) + 50}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex items-start gap-3">
                <CheckCircle2 className="text-sky-600/60 shrink-0 mt-0.5" size={16} />
                <p className="text-[12px] text-slate-500 font-medium leading-relaxed">
                  By confirming this booking, you agree to the Terms of Service and Cancellation Policy.
                </p>
              </div>

            </div>
          </div>
        )}

      </div>
    </div>
  );
}

"use client";

import { use, useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { ArrowLeft, Star, MapPin, Award, CheckCircle2, Languages, Clock, Hospital, GraduationCap, FileText, CalendarDays, AlertCircle, BadgeCheck } from "lucide-react";
import { mockDoctors, DoctorProfile } from "@/lib/mockData";
import { useAuth } from "@/context/AuthContext";
import { BookingModal } from "@/components/doctors/BookingModal";
import { GoogleMap } from "@/components/shared/GoogleMap";

export default function DoctorProfilePage({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter();
  const resolvedParams = use(params);
  const [doctor, setDoctor] = useState<DoctorProfile | null>(null);
  const [activeMapIndex, setActiveMapIndex] = useState<number | null>(0);
  const { user } = useAuth();
  const isGuest = !user;

  const handleBookingClick = () => {
    if (isGuest) {
      router.push("/login");
    } else {
      router.push(`/doctors/${doctor?.id}/book`);
    }
  };

  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const doc = mockDoctors.find(d => d.id === resolvedParams.id);
    if (doc) setDoctor(doc);
    // Simulate loading for skeleton
    const timer = setTimeout(() => setIsLoading(false), 1200);
    return () => clearTimeout(timer);
  }, [resolvedParams.id]);

  if (!doctor || isLoading) {
    return (
      <div className="h-full overflow-y-auto bg-[#F8FAFC] pb-32 font-sans">
        {/* Skeleton: Sticky Nav */}
        <div className="bg-white/80 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-40">
          <div className="max-w-[1280px] mx-auto px-6 h-16 flex items-center">
            <div className="w-32 h-5 bg-slate-200 animate-pulse rounded-lg"></div>
          </div>
        </div>

        {/* Skeleton: Profile Header */}
        <div className="bg-white border-b border-slate-200">
          <div className="max-w-[1280px] mx-auto px-6 flex flex-col md:flex-row gap-8 items-center py-12">
            {/* Avatar */}
            <div className="w-[120px] h-[120px] md:w-[140px] md:h-[140px] rounded-full bg-slate-200 animate-pulse shrink-0"></div>
            
            {/* Header Details */}
            <div className="flex-1 flex flex-col items-center md:items-start gap-4 w-full">
              {/* Badges */}
              <div className="flex gap-3">
                <div className="w-28 h-8 bg-slate-100 animate-pulse rounded-full"></div>
                <div className="w-32 h-8 bg-slate-100 animate-pulse rounded-full"></div>
                <div className="w-36 h-8 bg-slate-100 animate-pulse rounded-full hidden sm:block"></div>
              </div>
              {/* Name */}
              <div className="w-72 h-10 bg-slate-200 animate-pulse rounded-xl"></div>
              {/* Title */}
              <div className="w-48 h-6 bg-slate-100 animate-pulse rounded-lg"></div>
              {/* Hospital */}
              <div className="w-56 h-5 bg-slate-100 animate-pulse rounded-lg"></div>
            </div>
          </div>
        </div>

        {/* Skeleton: Content */}
        <div className="max-w-[1280px] mx-auto mt-12 px-6 flex flex-col lg:flex-row gap-12">
          {/* Left Column */}
          <div className="w-full lg:w-[65%] space-y-10">
            {/* About */}
            <div>
              <div className="w-36 h-6 bg-slate-200 animate-pulse rounded-lg mb-4"></div>
              <div className="bg-white p-6 rounded-xl border border-slate-200 space-y-3">
                <div className="w-full h-4 bg-slate-100 animate-pulse rounded"></div>
                <div className="w-full h-4 bg-slate-100 animate-pulse rounded"></div>
                <div className="w-3/4 h-4 bg-slate-100 animate-pulse rounded"></div>
              </div>
            </div>

            {/* Chambers */}
            <div>
              <div className="w-48 h-6 bg-slate-200 animate-pulse rounded-lg mb-4"></div>
              <div className="bg-white p-6 rounded-xl border border-slate-200 space-y-5">
                {[1, 2].map(i => (
                  <div key={i} className="flex flex-col gap-3 pb-5 border-b border-slate-100 last:border-0 last:pb-0">
                    <div className="w-48 h-5 bg-slate-200 animate-pulse rounded-lg"></div>
                    <div className="w-64 h-4 bg-slate-100 animate-pulse rounded"></div>
                    <div className="flex gap-3">
                      <div className="w-28 h-8 bg-slate-50 animate-pulse rounded-md border border-slate-200"></div>
                      <div className="w-36 h-8 bg-slate-50 animate-pulse rounded-md border border-slate-200"></div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Education */}
            <div>
              <div className="w-32 h-6 bg-slate-200 animate-pulse rounded-lg mb-4"></div>
              <div className="bg-white p-6 rounded-xl border border-slate-200 space-y-4">
                {[1, 2].map(i => (
                  <div key={i} className="flex justify-between items-center p-4 bg-slate-50 border border-slate-200 rounded-lg">
                    <div className="space-y-2">
                      <div className="w-40 h-5 bg-slate-200 animate-pulse rounded"></div>
                      <div className="w-56 h-4 bg-slate-100 animate-pulse rounded"></div>
                    </div>
                    <div className="w-20 h-5 bg-green-100 animate-pulse rounded-full"></div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Right Column */}
          <div className="w-full lg:w-[35%] space-y-10">
            {/* Stats */}
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white border border-slate-200 rounded-xl p-4 flex flex-col items-center gap-2">
                <div className="w-12 h-8 bg-slate-200 animate-pulse rounded-lg"></div>
                <div className="w-16 h-4 bg-slate-100 animate-pulse rounded"></div>
              </div>
              <div className="bg-white border border-slate-200 rounded-xl p-4 flex flex-col items-center gap-2">
                <div className="w-12 h-8 bg-slate-200 animate-pulse rounded-lg"></div>
                <div className="w-16 h-4 bg-slate-100 animate-pulse rounded"></div>
              </div>
            </div>

            {/* Map */}
            <div className="bg-white p-6 rounded-xl border border-slate-200">
              <div className="w-36 h-5 bg-slate-200 animate-pulse rounded-lg mb-3"></div>
              <div className="w-48 h-4 bg-slate-100 animate-pulse rounded mb-1"></div>
              <div className="w-32 h-4 bg-slate-100 animate-pulse rounded mb-4"></div>
              <div className="w-full h-[240px] bg-slate-100 animate-pulse rounded-lg"></div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full overflow-y-auto bg-[#F8FAFC] pb-32 font-sans relative">
      
      {/* Sticky Navigation */}
      <div className="bg-white/90 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-40 shadow-sm shadow-slate-100/50">
        <div className="max-w-[1280px] mx-auto px-6 h-16 md:h-20 flex items-center justify-between">
          <button 
            onClick={() => router.back()}
            className="flex items-center gap-2 text-[#64748B] hover:text-[#0F172A] font-bold text-[16px] transition-colors"
          >
            <ArrowLeft size={20} /> <span className="hidden sm:inline">Back to Search</span><span className="sm:hidden">Back</span>
          </button>
          
          {/* Desktop Nav Booking Button */}
          <div className="hidden md:block">
            <button 
              onClick={handleBookingClick}
              className="h-[48px] bg-sky-600 hover:bg-[#0052cc] text-white rounded-xl flex items-center justify-between gap-4 pl-5 pr-1.5 transition-all shadow-md shadow-primary/20 hover:shadow-lg hover:shadow-primary/30 group overflow-hidden border border-primary/20 hover:-translate-y-0.5"
            >
              <span className="font-bold text-[15px] tracking-wide">Book Appointment</span>
              <div className="bg-white/20 backdrop-blur-md border border-white/20 text-white h-[38px] px-4 rounded-lg flex items-center justify-center gap-1 font-[900] text-[16px]">
                <span>৳</span>{doctor.fee}
              </div>
            </button>
          </div>
        </div>
      </div>

      {/* PROFILE HEADER */}
      <div className="bg-white border-b border-slate-200">
        <div className="max-w-[1280px] mx-auto px-6 flex flex-col md:flex-row gap-8 items-center py-12 relative">
          
          {/* Avatar */}
          <div className="relative shrink-0">
            <div className="w-[120px] h-[120px] md:w-[140px] md:h-[140px] rounded-full overflow-hidden border border-slate-200 bg-slate-50 z-10 relative">
              <Image src={doctor.image} alt={doctor.name} fill sizes="140px" className="object-cover" />
            </div>
            <div className="absolute -bottom-1 -right-1 z-20 bg-white rounded-full p-0.5">
              <CheckCircle2 size={24} className="text-[#22C55E] fill-white" />
            </div>
          </div>
          
          {/* Header Details */}
          <div className="flex-1 text-center md:text-left flex flex-col justify-center h-full items-center md:items-start w-full">
            
            <h1 className="text-[32px] md:text-[48px] leading-[1.2] font-[800] text-[#0F172A] mb-3 tracking-tight text-center md:text-left">
              {doctor.name}
              {doctor.verified && <BadgeCheck size={32} className="inline-block ml-1.5 text-blue-500 fill-blue-50 align-middle -mt-1.5" />}
            </h1>

            <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 mb-4">
              <span className="bg-sky-600/10 text-sky-600 font-bold text-[14px] px-4 py-1.5 rounded-full uppercase tracking-wider">
                {doctor.specialty}
              </span>
            </div>
            
            <p className="text-[20px] md:text-[22px] text-[#64748B] font-medium mb-2">
              {doctor.title}
            </p>
            <p className="text-[18px] text-[#0F172A] font-medium flex items-center justify-center md:justify-start gap-2 mb-4">
              <Hospital size={20} className="text-[#64748B]" /> {doctor.hospital}
            </p>
            
            {/* Rating moved down here */}
            <div className="flex items-center justify-center md:justify-start gap-2 mb-6">
              <span className="flex items-center gap-1.5 text-[#F59E0B] text-[15px] font-bold bg-[#F59E0B]/10 px-4 py-2 rounded-full">
                <Star size={18} className="fill-[#F59E0B]" /> {doctor.rating} ({doctor.reviews} Reviews)
              </span>
            </div>
            
            {/* Mobile Book Now Button (Hidden on Desktop) */}
            <div className="md:hidden mt-6 w-full">
              <button 
                onClick={handleBookingClick}
                className="w-full h-[56px] bg-sky-600 hover:bg-[#0052cc] text-white rounded-xl flex items-center justify-between gap-6 pl-6 pr-1.5 transition-all shadow-xl shadow-primary/30 hover:shadow-primary/40 group overflow-hidden border border-primary/20"
              >
                <span className="font-bold text-[16px] tracking-wide">Book Appointment</span>
                <div className="bg-white/20 backdrop-blur-md border border-white/20 text-white h-[44px] px-5 rounded-lg flex items-center justify-center gap-1 font-[900] text-[18px]">
                  <span>৳</span>{doctor.fee}
                </div>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* PROFILE CONTENT (2 Columns) */}
      <div className="max-w-[1280px] mx-auto mt-12 px-6 flex flex-col lg:flex-row gap-12">
        
        {/* Left Column: 65% */}
        <div className="w-full lg:w-[65%] space-y-[48px]">
          
          {/* About Doctor */}
          <section>
            <h2 className="text-[20px] font-bold text-slate-900 mb-4 flex items-center gap-2">
              <FileText className="text-sky-600" size={20} /> About Doctor
            </h2>
            <div className="bg-white p-6 rounded-xl border border-slate-200">
              <p className="text-slate-600 text-[15px] leading-relaxed">
                {doctor.about}
              </p>
            </div>
          </section>

          {/* Chambers & Schedule */}
          {doctor.chambers && doctor.chambers.length > 0 && (
            <section>
              <h2 className="text-[20px] font-bold text-slate-900 mb-4 flex items-center gap-2">
                <CalendarDays className="text-sky-600" size={20} /> Chambers & Schedule
              </h2>
              <div className="bg-white p-6 rounded-xl border border-slate-200 flex flex-col gap-6">
                {doctor.chambers.map((chamber, idx) => (
                  <div key={idx} className="flex flex-col gap-2 pb-6 border-b border-slate-100 last:border-0 last:pb-0">
                    
                    <div 
                      className="cursor-pointer group flex flex-col gap-2 p-2 -mx-2 rounded-lg hover:bg-slate-50 transition-colors"
                      onClick={() => setActiveMapIndex(activeMapIndex === idx ? null : idx)}
                    >
                      <div className="flex items-center justify-between">
                        <h3 className="text-[16px] font-bold text-slate-900 group-hover:text-sky-600 transition-colors">{chamber.name}</h3>
                        <span className="text-[12px] font-bold text-sky-600 bg-sky-600/10 px-3 py-1 rounded-full whitespace-nowrap">
                          {activeMapIndex === idx ? "Hide Map" : "View Map"}
                        </span>
                      </div>
                      
                      <p className="text-[14px] text-slate-500 flex items-center gap-1.5">
                        <MapPin size={16} /> {chamber.address}
                      </p>
                      
                      <div className="flex flex-wrap items-center gap-3 mt-1.5">
                        <div className="flex items-center gap-1.5 bg-white border border-slate-200 px-3 py-1.5 rounded-md group-hover:border-primary/30 transition-colors">
                          <Clock size={14} className="text-slate-500" />
                          <span className="text-[13px] font-medium text-slate-700">{chamber.time}</span>
                        </div>
                        <div className="flex items-center gap-1.5 bg-white border border-slate-200 px-3 py-1.5 rounded-md group-hover:border-primary/30 transition-colors">
                          <CalendarDays size={14} className="text-slate-500" />
                          <span className="text-[13px] font-medium text-slate-700">{chamber.days}</span>
                        </div>
                      </div>
                    </div>

                    {/* Conditional Map Render for this specific chamber */}
                    {activeMapIndex === idx && (
                      <div className="mt-4 pt-4 border-t border-slate-100 animate-in fade-in zoom-in-95 duration-200">
                        <div className="h-[300px] w-full rounded-xl overflow-hidden shadow-inner border border-slate-200">
                          <GoogleMap 
                            lat={doctor.mapLocation?.lat || 23.8052} 
                            lng={doctor.mapLocation?.lng || 90.3639} 
                            title={`${chamber.name} Location`}
                          />
                        </div>
                      </div>
                    )}

                  </div>
                ))}
              </div>
            </section>
          )}

          {/* Education & Qualifications */}
          <section>
            <h2 className="text-[20px] font-bold text-slate-900 mb-4 flex items-center gap-2">
              <GraduationCap className="text-sky-600" size={20} /> Education
            </h2>
            <div className="bg-white p-6 rounded-xl border border-slate-200">
              <div className="flex flex-col gap-4">
                {doctor.qualifications.map((qual, idx) => (
                  <div key={idx} className="flex flex-col md:flex-row items-start md:items-center justify-between p-4 bg-slate-50 border border-slate-200 rounded-lg">
                    <div>
                      <h3 className="text-[15px] font-bold text-slate-900 mb-0.5">{qual.degree}</h3>
                      <p className="text-[13px] text-slate-500">{qual.institute}, {qual.year}</p>
                    </div>
                    {qual.verified && (
                      <div className="flex items-center gap-1 mt-2 md:mt-0 text-[#22C55E]">
                        <CheckCircle2 size={16} className="fill-[#22C55E] text-white" />
                        <span className="text-[12px] font-bold uppercase tracking-wider">Verified</span>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </section>

        </div>

        {/* Right Column: 35% */}
        <div className="w-full lg:w-[35%] space-y-[48px]">
          
          {/* Quick Stats Grid */}
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white border border-slate-200 rounded-xl p-4 flex flex-col items-center justify-center text-center">
              <span className="text-[28px] font-bold text-sky-600 mb-0.5">{doctor.experienceYears}+</span>
              <span className="text-[12px] font-medium text-slate-500 uppercase tracking-wider">Years Exp</span>
            </div>
            <div className="bg-white border border-slate-200 rounded-xl p-4 flex flex-col items-center justify-center text-center">
              <span className="text-[28px] font-bold text-slate-900 mb-0.5">{doctor.reviews}</span>
              <span className="text-[12px] font-medium text-slate-500 uppercase tracking-wider">Patients</span>
            </div>
          </div>

          {/* Location Map */}
          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
            <h2 className="text-[16px] font-bold text-slate-900 mb-3 flex items-center gap-2">
              <MapPin className="text-sky-600" size={18} /> Practice Location
            </h2>
            <p className="text-slate-900 font-medium text-[14px] mb-0.5">{doctor.hospital}</p>
            <p className="text-slate-500 text-[13px] mb-4">{doctor.location}</p>
            
            <div className="w-full h-[260px] rounded-xl overflow-hidden border border-slate-200 shadow-inner">
              <GoogleMap 
                lat={doctor.mapLocation?.lat || 23.8052} 
                lng={doctor.mapLocation?.lng || 90.3639} 
                title={`${doctor.hospital} - Practice Location`}
                className="h-full w-full"
              />
            </div>
          </div>
          
        </div>
      </div>

      {/* Removed Bottom Booking Bar in favor of Top Right CTA */}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Search, SlidersHorizontal, Stethoscope, Heart, Activity, Pill, Syringe, ShieldCheck } from "lucide-react";
import { mockDoctors } from "@/lib/mockData";
import { DoctorCard } from "@/components/doctors/DoctorCard";
import { DoctorFilterModal } from "@/components/doctors/DoctorFilterModal";

function DoctorCardSkeleton() {
