      </div>
      {/* Details */}
      <div className="space-y-2.5 mt-4 mb-6">
        <div className="flex items-center gap-2.5">
          <div className="w-4 h-4 bg-slate-100 animate-pulse rounded"></div>
          <div className="w-2/5 h-4 bg-slate-100 animate-pulse rounded"></div>
        </div>
        <div className="flex items-center gap-2.5">
          <div className="w-4 h-4 bg-slate-100 animate-pulse rounded"></div>
