export default function DoctorsPage() {
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [showFilters, setShowFilters] = useState(false);

  // Simulate loading
  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 1500);
    return () => clearTimeout(timer);
  }, []);

  const filteredDoctors = mockDoctors.filter(doc => 
    doc.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    doc.specialty.toLowerCase().includes(searchQuery.toLowerCase()) ||
    doc.hospital.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const medicalIcons = [
    { Icon: Stethoscope, label: "Diagnostics" },
    { Icon: Heart, label: "Cardiology" },
    { Icon: Activity, label: "Health Monitor" },
    { Icon: Pill, label: "Pharmacy" },
    { Icon: Syringe, label: "Vaccination" },
    { Icon: ShieldCheck, label: "Verified" },
  ];

   return (
    <div className="h-full overflow-y-auto bg-[#F8FAFC]">
      {/* HERO SECTION */}
      <div className="w-full py-16 flex flex-col items-center justify-center bg-white border-b border-slate-200 relative overflow-hidden">
        
        {/* Floating Background Medical Icons */}
        <div className="absolute inset-0 pointer-events-none overflow-hidden">
          {[
            { Icon: Stethoscope, top: '8%', left: '5%', size: 30, delay: 0, dur: 8, color: '#3B82F6' },
            { Icon: Heart, top: '15%', right: '8%', size: 26, delay: 1, dur: 7, color: '#EF4444' },
            { Icon: Activity, top: '65%', left: '10%', size: 24, delay: 2, dur: 9, color: '#10B981' },
            { Icon: Pill, top: '70%', right: '12%', size: 28, delay: 0.5, dur: 6, color: '#F59E0B' },
            { Icon: Syringe, top: '30%', left: '15%', size: 22, delay: 3, dur: 10, color: '#8B5CF6' },
            { Icon: ShieldCheck, top: '45%', right: '6%', size: 26, delay: 1.5, dur: 8, color: '#22C55E' },
            { Icon: Stethoscope, top: '80%', left: '25%', size: 20, delay: 4, dur: 7, color: '#0EA5E9' },
            { Icon: Heart, top: '20%', right: '22%', size: 22, delay: 2.5, dur: 9, color: '#F43F5E' },
            { Icon: Pill, top: '50%', left: '3%', size: 24, delay: 1, dur: 11, color: '#F97316' },
            { Icon: Activity, top: '10%', right: '30%', size: 20, delay: 3.5, dur: 8, color: '#14B8A6' },
          ].map((item, i) => (
            <div
              key={i}
              className="absolute"
              style={{
                top: item.top,
                left: (item as any).left,
                right: (item as any).right,
                color: item.color,
                opacity: 0.12,
                animation: `floatIcon ${item.dur}s ease-in-out ${item.delay}s infinite`,
              }}
            >
              <item.Icon size={item.size} strokeWidth={1.5} />
            </div>
          ))}
        </div>

        <style jsx>{`
          @keyframes floatIcon {
            0%, 100% { transform: translateY(0px) rotate(0deg); opacity: 0.12; }
            25% { transform: translateY(-14px) rotate(6deg); opacity: 0.2; }
            50% { transform: translateY(-5px) rotate(-4deg); opacity: 0.15; }
            75% { transform: translateY(-18px) rotate(5deg); opacity: 0.22; }
          }
        `}</style>

        <div className="w-full max-w-[1280px] px-[20px] md:px-[32px] lg:px-[48px] flex flex-col items-center text-center relative z-10">

          <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-emerald-700 font-semibold text-xs uppercase tracking-widest mb-6">
            <ShieldCheck size={14} className="text-emerald-600" />
            BMDC Verified & Connected
          </div>

          <h1 className="text-[36px] md:text-[48px] font-[800] text-slate-900 mb-4 leading-tight tracking-[-0.04em]">
            National <span className="text-sky-600">Specialist Network</span>
          </h1>
          <p className="text-[16px] text-slate-500 max-w-[700px] mb-8 font-medium leading-relaxed">
            Every doctor listed is BMDC verified and connected to the Centralized National Healthcare Network. Book appointments, manage your Universal Health ID (UHID), and ensure your medical records are seamlessly updated across all hospitals.
          </p>

          <div className="w-full max-w-[720px] flex items-center bg-white/60 backdrop-blur-md border-[1.5px] border-primary/20 shadow-[0_8px_30px_rgb(0,61,155,0.08)] rounded-[16px] focus-within:border-primary focus-within:shadow-[0_8px_30px_rgb(0,61,155,0.15)] transition-all duration-300 p-1.5">
            <div className="pl-4 pr-2 flex items-center justify-center">
              <Search className="text-sky-600/70" size={22} />
            </div>
            <input 
              type="text" 
              placeholder="Search by name, specialty, or hospital..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="flex-1 h-12 px-1 sm:px-2 bg-transparent text-[14px] sm:text-[15px] text-slate-900 placeholder:text-slate-400 focus:outline-none min-w-0"
            />
            <button 
              onClick={() => setShowFilters(true)}
              className="h-[44px] sm:h-[48px] px-3 sm:px-6 bg-sky-600 hover:bg-[#0052cc] text-white rounded-[12px] flex items-center justify-center gap-2 font-bold text-[14px] sm:text-[15px] transition-all duration-300 shadow-md ml-1 sm:ml-2 shrink-0"
            >
              <SlidersHorizontal size={18} className="text-white/90 shrink-0" />
              <span className="hidden sm:inline">Filters</span>
            </button>
          </div>
        </div>
      </div>

      {/* MAIN GRID LAYOUT */}
      <div className="w-full max-w-[1280px] mx-auto px-[20px] md:px-[32px] lg:px-[48px] py-12">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-[20px] font-bold text-slate-900">Doctors ({isLoading ? "..." : filteredDoctors.length})</h2>
          <select className="bg-transparent text-[14px] font-medium text-slate-500 border-none focus:outline-none cursor-pointer">
            <option>Recommended</option>
            <option>Highest Rated</option>
            <option>Lowest Fee</option>
          </select>
        </div>

        {(() => {
          if (isLoading) {
            return (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-[24px]">
                {[1, 2, 3, 4, 5, 6].map((skeleton) => (
                  <DoctorCardSkeleton key={skeleton} />
                ))}
              </div>
            );
          }

          if (filteredDoctors.length === 0) {
            return (
              <div className="w-full py-20 flex flex-col items-center justify-center bg-white border border-slate-200 rounded-lg text-center">
                <div className="w-16 h-16 bg-slate-50 border border-slate-200 rounded-lg flex items-center justify-center mb-4">
                  <Search size={24} className="text-slate-400" />
                </div>
                <h3 className="text-[18px] font-bold text-slate-900 mb-1">No results</h3>
                <p className="text-[14px] text-slate-500">Try adjusting your filters.</p>
                <button 
                  onClick={() => {
                    setSearchQuery("");
                    setShowFilters(true);
                  }}
                  className="mt-4 px-4 py-2 bg-white border border-slate-200 hover:border-primary hover:text-sky-600 rounded-md font-medium text-[14px] transition-colors"
                >
                  Adjust Filters
                </button>
              </div>
            );
          }

          return (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-[24px]">
              {filteredDoctors.map(doctor => (
                <DoctorCard 
                  key={doctor.id} 
                  doctor={doctor} 
                />
              ))}
            </div>
          );
        })()}
      </div>

      {/* FILTER MODAL */}
      <DoctorFilterModal 
        isOpen={showFilters} 
        onClose={() => setShowFilters(false)} 
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { BedDouble, Plus, X, Search, Filter, Activity, Users, CheckCircle2, AlertTriangle } from "lucide-react";

// Sample Bed Data
const initialBeds = [
  { id: "B-101", ward: "General Ward A", type: "General", status: "Vacant", price: "৳ 1,500/day" },
  { id: "B-102", ward: "General Ward A", type: "General", status: "Occupied", patient: "Rahim Uddin", price: "৳ 1,500/day" },
  { id: "C-201", ward: "Cabin Block B", type: "Cabin", status: "Occupied", patient: "Karim Hassan", price: "৳ 4,000/day" },
  { id: "C-202", ward: "Cabin Block B", type: "Cabin", status: "Maintenance", price: "৳ 4,000/day" },
  { id: "ICU-01", ward: "Intensive Care Unit", type: "ICU", status: "Vacant", price: "৳ 12,000/day" },
  { id: "ICU-02", ward: "Intensive Care Unit", type: "ICU", status: "Occupied", patient: "Abdur Rahman", price: "৳ 12,000/day" },
];

export default function BedManagementPage() {
  const [beds, setBeds] = useState(initialBeds);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newBed, setNewBed] = useState({ id: "", ward: "", type: "General", status: "Vacant", price: "" });

  const stats = [
    { label: "Total Beds", value: beds.length, icon: BedDouble, color: "text-blue-600", bg: "bg-blue-50" },
    { label: "Occupied", value: beds.filter(b => b.status === "Occupied").length, icon: Users, color: "text-orange-600", bg: "bg-orange-50" },
    { label: "Vacant", value: beds.filter(b => b.status === "Vacant").length, icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-50" },
    { label: "Maintenance", value: beds.filter(b => b.status === "Maintenance").length, icon: AlertTriangle, color: "text-rose-600", bg: "bg-rose-50" },
  ];

  const handleAddBed = (e: React.FormEvent) => {
    e.preventDefault();
    setBeds([...beds, newBed]);
    setIsModalOpen(false);
    setNewBed({ id: "", ward: "", type: "General", status: "Vacant", price: "" });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "Vacant": return "bg-emerald-50 border-emerald-200 text-emerald-700";
      case "Occupied": return "bg-orange-50 border-orange-200 text-orange-700";
      case "Maintenance": return "bg-rose-50 border-rose-200 text-rose-700";
      default: return "bg-slate-50 border-slate-200 text-slate-700";
    }
  };

  return (
    <div className="w-full space-y-6 pb-10">
      {/* Header & Actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-[24px] font-bold text-slate-800">Bed Management</h1>
          <p className="text-[14px] text-slate-500 mt-1">Monitor and manage hospital bed availability in real-time.</p>
        </div>
        <button
          onClick={() => setIsModalOpen(true)}
          className="h-[48px] px-6 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[12px] font-bold text-[15px] flex items-center gap-2 shadow-sm transition-colors"
        >
          <Plus size={18} />
          Add New Bed
        </button>
      </div>

      {/* Metrics Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {stats.map((stat, idx) => {
          const Icon = stat.icon;
          return (
            <motion.div
              key={idx}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.1 }}
              className="h-[110px] bg-white rounded-[16px] border border-slate-200 p-6 flex items-center gap-4 shadow-sm"
            >
              <div className={`w-14 h-14 rounded-full ${stat.bg} flex items-center justify-center shrink-0`}>
                <Icon size={24} className={stat.color} />
              </div>
              <div>
                <p className="text-[14px] text-slate-500 font-medium mb-1">{stat.label}</p>
                <h3 className="text-[24px] font-bold text-slate-800 leading-none">{stat.value}</h3>
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-[16px] border border-slate-200 shadow-sm flex flex-col sm:flex-row gap-4 items-center justify-between">
        <div className="relative w-full sm:max-w-xs">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Search beds or wards..."
            className="w-full h-[46px] pl-9 pr-4 rounded-[12px] border border-slate-200 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 text-[14px]"
          />
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          <button className="h-[46px] px-4 rounded-[12px] border border-slate-200 text-slate-600 flex items-center gap-2 text-[14px] font-medium hover:bg-slate-50 flex-1 sm:flex-none justify-center">
            <Filter size={16} />
            Filter by Ward
          </button>
        </div>
      </div>

      {/* Bed Grid Display */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {beds.map((bed, idx) => (
          <motion.div
            key={idx}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className={`h-[160px] rounded-[12px] border p-4 flex flex-col justify-between transition-colors shadow-sm ${getStatusColor(bed.status)}`}
          >
            <div className="flex justify-between items-start">
              <div>
                <h3 className="text-[18px] font-bold">{bed.id}</h3>
                <p className="text-[13px] opacity-80">{bed.ward}</p>
              </div>
              <span className={`text-[11px] font-bold uppercase tracking-wider px-2.5 py-1 rounded-full bg-white/60`}>
                {bed.status}
              </span>
            </div>
            
            <div className="space-y-1">
              <div className="flex items-center justify-between text-[13px]">
                <span className="opacity-80">Type:</span>
                <span className="font-semibold">{bed.type}</span>
              </div>
              {bed.patient ? (
                <div className="flex items-center justify-between text-[13px]">
                  <span className="opacity-80">Patient:</span>
                  <span className="font-semibold truncate max-w-[120px]">{bed.patient}</span>
                </div>
              ) : (
                <div className="flex items-center justify-between text-[13px]">
                  <span className="opacity-80">Price:</span>
                  <span className="font-semibold">{bed.price}</span>
                </div>
              )}
            </div>
          </motion.div>
        ))}
      </div>

      {/* Bed Editor Modal */}
      <AnimatePresence>
        {isModalOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsModalOpen(false)}
              className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50"
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-full max-w-[500px] bg-white rounded-[20px] shadow-2xl z-50 p-6"
            >
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-[20px] font-bold text-slate-800">Add New Bed</h3>
                <button
                  onClick={() => setIsModalOpen(false)}
                  className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full"
                >
                  <X size={20} />
                </button>
              </div>

              <form onSubmit={handleAddBed} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[14px] font-medium text-slate-700 mb-1">Bed Number / ID</label>
                    <input
                      required
                      type="text"
                      value={newBed.id}
                      onChange={(e) => setNewBed({ ...newBed, id: e.target.value })}
                      placeholder="e.g. B-103"
                      className="w-full h-[46px] px-4 rounded-[12px] border border-slate-200 focus:outline-none focus:border-emerald-500 text-[14px]"
                    />
                  </div>
                  <div>
                    <label className="block text-[14px] font-medium text-slate-700 mb-1">Bed Category</label>
                    <select
                      value={newBed.type}
                      onChange={(e) => setNewBed({ ...newBed, type: e.target.value })}
                      className="w-full h-[46px] px-4 rounded-[12px] border border-slate-200 focus:outline-none focus:border-emerald-500 text-[14px] bg-white"
                    >
