          ) : (
            <div className="text-center">
              <h2 className="text-[60px] md:text-[80px] font-black text-slate-300 leading-none tracking-tight mb-4">
                No active patient
              </h2>
            </div>
          )}

        </div>

        {/* Footer info */}
        <div className="p-8 md:p-12 relative z-10 flex justify-between items-end">
