          </div>
        </div>
      </div>

      {/* RIGHT SIDE: Queue List */}
      <div className="w-full md:w-[40%] h-[50vh] md:h-full bg-slate-50 p-6 md:p-8 flex flex-col relative z-20">

        <div className="flex items-center justify-between mb-8">
