function getProviders(): ProviderConfig[] {
  const providers: ProviderConfig[] = [];

  // Priority 1: Google Gemini API
  if (process.env.GOOGLE_API_KEY) {
    providers.push({
      name: 'google',
      apiKey: process.env.GOOGLE_API_KEY,
      model: process.env.GOOGLE_MODEL || 'gemini-3.6-flash',
      baseUrl: 'https://generativelanguage.googleapis.com/v1beta',
      priority: 1,
      isEnabled: true,
    });
  }

  // Priority 2: Groq AI API
  if (process.env.GROQ_API_KEY) {
    providers.push({
      name: 'groq',
      apiKey: process.env.GROQ_API_KEY,
      model: process.env.GROQ_MODEL || 'qwen/qwen3.6-27b',
      baseUrl: 'https://api.groq.com/openai/v1',
      priority: 2,
      isEnabled: true,
    });
  }

  // Priority 3: OpenAI API
  if (process.env.OPENAI_API_KEY) {
    providers.push({
      name: 'openai',
      apiKey: process.env.OPENAI_API_KEY,
      model: process.env.OPENAI_MODEL || 'gpt-4o-mini',
      baseUrl: 'https://api.openai.com/v1',
      priority: 3,
      isEnabled: true,
    });
  }

  // Priority 4: DeepSeek API
  if (process.env.DEEPSEEK_API_KEY) {
    providers.push({
      name: 'deepseek',
      apiKey: process.env.DEEPSEEK_API_KEY,
      model: process.env.DEEPSEEK_MODEL || 'deepseek-chat',
      baseUrl: 'https://api.deepseek.com/v1',
      priority: 4,
      isEnabled: true,
    });
  }

  // Priority 5: Zhipu GLM API
  if (process.env.ZHIPU_API_KEY) {
    providers.push({
      name: 'zhipu',
      apiKey: process.env.ZHIPU_API_KEY,
      model: process.env.ZHIPU_MODEL || 'glm-4',
      baseUrl: 'https://open.bigmodel.cn/api/paas/v4',
      priority: 5,
      isEnabled: true,
    });
  }

  // Priority 6: Anthropic API
  if (process.env.ANTHROPIC_API_KEY) {
    providers.push({
      name: 'anthropic',
      apiKey: process.env.ANTHROPIC_API_KEY,
      model: process.env.ANTHROPIC_MODEL || 'claude-3-5-sonnet-20241022',
      baseUrl: 'https://api.anthropic.com/v1',
      priority: 6,
      isEnabled: true,
    });
  }

  // If no providers configured, use Mock Mode so the UI doesn't crash for users without API keys
  if (providers.length === 0) {
    providers.push({
      name: 'mock_ai',
      apiKey: 'demo',
      model: 'mock-model',
      baseUrl: 'demo',
      priority: 99,
      isEnabled: true,
    });
  }

  return providers.sort((a, b) => a.priority - b.priority);
}

