"use client";

import React, { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { X, User, DollarSign, Wallet, Smartphone, CreditCard, CheckCircle2 } from "lucide-react";

interface ManualPaymentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (payment: any) => void;
}

export function ManualPaymentModal({ isOpen, onClose, onSave }: ManualPaymentModalProps) {
  const [mounted, setMounted] = useState(false);
  const [patientId, setPatientId] = useState("");
  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState("Cash");

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!isOpen || !mounted) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!patientId || !amount) return;

    // Create a mock payment object
    const newPayment = {
      id: `PAY-${Math.floor(10000 + Math.random() * 90000)}`,
      patientName: "New Patient (Walk-in)",
      patientId: patientId,
      amount: parseInt(amount),
      method: method,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      date: new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }),
      status: "Paid",
      items: [
        { name: "Manual Payment Entry", amount: parseInt(amount) }
      ]
    };

    onSave(newPayment);
    // Reset form
    setPatientId("");
    setAmount("");
    setMethod("Cash");
  };

  return createPortal(
    <div className="fixed inset-0 z-[99999] flex flex-col justify-end sm:items-center sm:justify-center bg-slate-900/50 backdrop-blur-sm sm:p-4 animate-in fade-in duration-200">
      
      <div className="w-full sm:w-[450px] bg-white rounded-t-[32px] sm:rounded-3xl shadow-2xl flex flex-col overflow-hidden animate-in slide-in-from-bottom-full sm:slide-in-from-bottom-4 duration-300">
        
        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
          <h2 className="text-[18px] font-bold text-slate-800">Record Payment</h2>
          <button 
            onClick={onClose}
            className="w-8 h-8 flex items-center justify-center bg-slate-50 text-slate-500 hover:bg-slate-100 rounded-full transition-colors active:scale-95"
          >
            <X size={18} />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          
          <div>
            <label className="block text-[13px] font-bold text-slate-600 mb-1.5 uppercase tracking-wide">Patient ID / Phone</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
                <User size={18} className="text-slate-400" />
              </div>
              <input
                type="text"
                required
                value={patientId}
                onChange={(e) => setPatientId(e.target.value)}
                placeholder="e.g. 017XXXXX or K 99 11"
                className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-[14px] font-medium focus:outline-none focus:border-[#2F80ED] focus:bg-white transition-colors"
              />
            </div>
          </div>

          <div>
            <label className="block text-[13px] font-bold text-slate-600 mb-1.5 uppercase tracking-wide">Amount (৳)</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
                <DollarSign size={18} className="text-slate-400" />
              </div>
              <input
                type="number"
                required
                min="10"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-[18px] font-bold text-[#2F80ED] focus:outline-none focus:border-[#2F80ED] focus:bg-white transition-colors"
              />
            </div>
          </div>

          <div>
            <label className="block text-[13px] font-bold text-slate-600 mb-2 uppercase tracking-wide">Payment Method</label>
            <div className="grid grid-cols-3 gap-3">
              <button 
                type="button"
                onClick={() => setMethod("Cash")}
                className={`py-3 px-2 rounded-xl border flex flex-col items-center gap-1.5 transition-all ${method === "Cash" ? "bg-emerald-50 border-emerald-500 text-emerald-700 shadow-sm" : "bg-white border-slate-200 text-slate-500 hover:bg-slate-50"}`}
              >
                <Wallet size={20} className={method === "Cash" ? "text-emerald-600" : ""} />
                <span className="text-[12px] font-bold">Cash</span>
              </button>
              
              <button 
                type="button"
                onClick={() => setMethod("bKash")}
                className={`py-3 px-2 rounded-xl border flex flex-col items-center gap-1.5 transition-all ${method === "bKash" ? "bg-pink-50 border-pink-500 text-pink-700 shadow-sm" : "bg-white border-slate-200 text-slate-500 hover:bg-slate-50"}`}
              >
                <Smartphone size={20} className={method === "bKash" ? "text-pink-600" : ""} />
                <span className="text-[12px] font-bold">bKash</span>
              </button>
              
              <button 
                type="button"
                onClick={() => setMethod("Card")}
                className={`py-3 px-2 rounded-xl border flex flex-col items-center gap-1.5 transition-all ${method === "Card" ? "bg-purple-50 border-purple-500 text-purple-700 shadow-sm" : "bg-white border-slate-200 text-slate-500 hover:bg-slate-50"}`}
              >
                <CreditCard size={20} className={method === "Card" ? "text-purple-600" : ""} />
                <span className="text-[12px] font-bold">Card</span>
              </button>
            </div>
          </div>

          <div className="pt-4 pb-safe-bottom">
            <button 
              type="submit"
              className="w-full py-3.5 bg-[#2F80ED] hover:bg-[#256bbd] text-white rounded-xl font-bold text-[15px] shadow-md active:scale-95 transition-transform flex items-center justify-center gap-2"
            >
              <CheckCircle2 size={18} />
              Save Payment
            </button>
          </div>

        </form>

      </div>
    </div>,
    document.body
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { X, Calendar, CreditCard, MessageSquare, Bell, ArrowLeft, Trash2, Reply, UserPlus, CheckCircle2 } from "lucide-react";

interface NotificationDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  notification: any;
  onInviteResponse?: (id: number | string, status: 'accepted' | 'declined') => void;
}

export function NotificationDetailModal({ isOpen, onClose, notification, onInviteResponse }: NotificationDetailModalProps) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!isOpen || !mounted || !notification) return null;

  const getIcon = (type: string) => {
    switch (type) {
      case "doctor_invite": return <UserPlus size={24} className="text-indigo-600" />;
      case "appointment": return <Calendar size={24} className="text-[#2F80ED]" />;
      case "payment": return <CreditCard size={24} className="text-emerald-600" />;
      case "message": return <MessageSquare size={24} className="text-amber-500" />;
      default: return <Bell size={24} className="text-slate-500" />;
    }
  };

  const getIconBg = (type: string) => {
    switch (type) {
      case "doctor_invite": return "bg-indigo-100";
      case "appointment": return "bg-blue-100";
      case "payment": return "bg-emerald-100";
      case "message": return "bg-amber-100";
      default: return "bg-slate-100";
    }
  };

  return createPortal(
    <div className="fixed inset-0 z-[99999] flex flex-col sm:items-center sm:justify-center bg-white sm:bg-slate-900/40 sm:backdrop-blur-sm sm:p-4 animate-in fade-in duration-200">
      
      {/* Container: Full Screen on Mobile, Card on Desktop */}
      <div className="flex-1 sm:flex-none flex flex-col w-full sm:w-[500px] h-full sm:h-auto bg-white sm:rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-right sm:slide-in-from-bottom-4 duration-300">
        
        {/* Header (App Bar) */}
        <div className="bg-white px-4 py-4 flex items-center justify-between border-b border-slate-100 shrink-0 pt-safe-top">
          <button 
            onClick={onClose}
            className="flex items-center gap-1 text-[#2F80ED] font-semibold text-[15px] active:scale-95 transition-transform"
          >
            <ArrowLeft size={20} />
            Back
          </button>
          <h2 className="text-[16px] font-bold text-slate-800 absolute left-1/2 -translate-x-1/2">Notification</h2>
          <button className="w-9 h-9 flex items-center justify-center bg-red-50 text-red-500 hover:bg-red-100 rounded-full transition-colors active:scale-95">
            <Trash2 size={18} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-5 sm:p-6 custom-scrollbar relative">
          
          <div className="flex items-center gap-4 mb-6 pb-6 border-b border-slate-100">
            <div className={`w-14 h-14 rounded-full ${getIconBg(notification.type)} flex items-center justify-center shrink-0`}>
              {getIcon(notification.type)}
            </div>
            <div>
              <h3 className="text-[18px] font-bold text-slate-800 leading-tight">{notification.title}</h3>
              <p className="text-[13px] font-medium text-slate-400 mt-1">{notification.time} • Oxpecker AI System</p>
            </div>
          </div>

          <div className="prose prose-slate max-w-none">
            <p className="text-[15px] leading-relaxed text-slate-700 whitespace-pre-wrap">
              {notification.message}
            </p>

            {/* Extra context based on type */}
            
            {/* DOCTOR INVITE TYPE */}
            {notification.type === "doctor_invite" && !notification.status && (
              <div className="mt-8 bg-indigo-50 border border-indigo-100 rounded-2xl p-5">
                <div className="flex flex-col items-center text-center">
                  <div className="w-16 h-16 rounded-full bg-white border-4 border-indigo-50 flex items-center justify-center shadow-sm mb-3">
                    <UserPlus size={24} className="text-indigo-500" />
                  </div>
                  <h4 className="text-[16px] font-bold text-slate-800">{notification.doctorName}</h4>
                  <p className="text-[13px] text-slate-500 font-medium">{notification.specialty}</p>
                </div>
                <div className="mt-6 flex gap-3">
                  <button 
                    onClick={() => onInviteResponse?.(notification.id, 'accepted')}
                    className="flex-1 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold text-[14px] shadow-md active:scale-95 transition-transform"
                  >
                    Accept Invite
                  </button>
                  <button 
                    onClick={() => onInviteResponse?.(notification.id, 'declined')}
                    className="flex-1 py-3 bg-white hover:bg-slate-50 border border-slate-200 text-slate-700 rounded-xl font-bold text-[14px] active:scale-95 transition-transform"
                  >
                    Decline
                  </button>
                </div>
              </div>
            )}
            
            {notification.type === "doctor_invite" && notification.status === 'accepted' && (
              <div className="mt-8 bg-emerald-50 border border-emerald-100 rounded-2xl p-5 flex flex-col items-center text-center">
                <div className="w-14 h-14 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center mb-3">
                  <CheckCircle2 size={30} />
                </div>
                <h4 className="text-[16px] font-bold text-slate-800">Connection Successful</h4>
                <p className="text-[13px] text-slate-600 mt-1">You are now the official assistant for {notification.doctorName}. You can manage their patient queue and view reports.</p>
              </div>
            )}

            {notification.type === "payment" && (
              <div className="mt-6 bg-slate-50 border border-slate-200 rounded-xl p-4 flex items-center justify-between">
                <div>
                  <p className="text-[12px] font-semibold text-slate-500 uppercase">Transaction ID</p>
                  <p className="font-mono font-bold text-slate-800 text-[14px] mt-0.5">TXN-984323</p>
                </div>
                <button className="px-4 py-2 bg-white border border-slate-200 rounded-lg text-[13px] font-bold text-[#2F80ED] shadow-sm active:scale-95 transition-transform">
                  View Receipt
                </button>
              </div>
            )}
            
            {notification.type === "appointment" && (
              <div className="mt-6 flex gap-2">
                <button className="flex-1 py-3 bg-[#2F80ED] hover:bg-[#256bbd] text-white rounded-xl font-bold text-[14px] shadow-sm active:scale-95 transition-transform">
                  Confirm Booking
                </button>
                <button className="flex-1 py-3 bg-red-50 hover:bg-red-100 text-red-600 rounded-xl font-bold text-[14px] active:scale-95 transition-transform">
                  Decline
                </button>
              </div>
            )}

          </div>
        </div>
        
        {/* Footer (If Message Type) */}
        {notification.type === "message" && (
          <div className="p-4 border-t border-slate-100 shrink-0 pb-safe">
            <div className="relative">
              <input 
                type="text" 
                placeholder="Reply to Dr. Anisur..."
                className="w-full pl-4 pr-12 py-3.5 bg-slate-50 border border-slate-200 rounded-xl text-[14px] focus:outline-none focus:border-[#2F80ED] focus:bg-white transition-colors"
              />
              <button className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center bg-[#2F80ED] text-white rounded-lg hover:bg-[#256bbd] active:scale-95 transition-transform">
                <Reply size={16} />
              </button>
            </div>
          </div>
        )}
        
      </div>
    </div>,
    document.body
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter, usePathname } from "next/navigation";
import { useAuth } from "@/context/AuthContext";

export function AuthGuard({ children }: { children: React.ReactNode }) {
  const { isAuthenticated, isLoading, role } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  const [isAuthorized, setIsAuthorized] = useState(false);

  useEffect(() => {
    if (isLoading) return;

    // Public informational and discovery routes (no authentication required)
    const publicPages = [
      "/doctors",
      "/hospitals",
      "/medicines",
      "/about",
      "/contact",
      "/terms",
      "/privacy",
      "/refund",
      "/disclaimer",
      "/careers",
      "/press",
      "/docs"
    ];

    const isPublicPage = publicPages.some(p => pathname === p || pathname.startsWith(p + "/"));

    // 1. Unauthenticated users:
    if (!isAuthenticated) {
      if (isPublicPage) {
        setIsAuthorized(true);
        return;
      }

      // Store intended destination so user returns here after login
      if (
        pathname !== "/login" &&
        pathname !== "/" &&
        !pathname.startsWith("/register") &&
        pathname !== "/reset-password"
      ) {
        const fullUrl = typeof window !== "undefined" ? window.location.pathname + window.location.search : pathname;
        sessionStorage.setItem("redirect_after_login", fullUrl);
      }

      router.replace("/login");
      return;
    }

    // 2. Role-Based Access Control (RBAC) for Authenticated Users:
    let hasAccess = true;

    if (pathname.startsWith("/admin")) {
      hasAccess = role === "admin";
    } else if (pathname.startsWith("/hospital/")) {
      hasAccess = role === "hospital" || role === "admin";
    } else if (pathname.startsWith("/assistant")) {
      hasAccess = role === "assistant" || role === "admin";
    } else if (pathname.startsWith("/doctor/")) {
      hasAccess = role === "doctor" || role === "admin";
    }

    if (!hasAccess) {
      // If user tries to access a restricted panel they don't own, redirect to their role home
      if (role === "patient") router.replace("/chat");
      else if (role === "doctor") router.replace("/doctor/dashboard");
      else if (role === "hospital") router.replace("/hospital/dashboard");
      else if (role === "admin") router.replace("/admin/dashboard");
      else if (role === "assistant") router.replace("/assistant");
      else router.replace("/login");
      return;
    }

    setIsAuthorized(true);
  }, [isLoading, isAuthenticated, role, pathname, router]);

  if (isLoading || !isAuthorized) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-[#050B14] overflow-hidden">
        <div className="flex flex-col items-center justify-center gap-10">
          
          {/* Logo with Glowing Ping Effects */}
          <div className="relative flex items-center justify-center">
            <div className="absolute w-28 h-28 rounded-full border border-sky-500/20 animate-[ping_3s_cubic-bezier(0,0,0.2,1)_infinite]"></div>
            <div className="absolute w-36 h-36 rounded-full border border-emerald-500/10 animate-[ping_3s_cubic-bezier(0,0,0.2,1)_infinite]" style={{ animationDelay: '1.5s' }}></div>
            
            <div className="relative w-24 h-24 flex items-center justify-center z-10">
              <img src="/images/Oxpecker_icon.png" alt="Loading..." className="w-20 h-20 object-contain animate-breathing drop-shadow-lg" />
            </div>
          </div>
          
          {/* High-tech Progress Scanner */}
          <div className="flex flex-col items-center gap-3">
            <div className="w-40 h-1 bg-slate-800/80 rounded-full overflow-hidden relative shadow-inner">
              <div className="absolute top-0 bottom-0 left-0 w-1/2 bg-gradient-to-r from-transparent via-sky-400 to-transparent animate-[shimmer_1.5s_infinite_ease-in-out]"></div>
            </div>
            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.25em] animate-pulse">Initializing Workspace</p>
          </div>

        </div>
      </div>
    );
  }

  return <>{children}</>;
}

import { useState, useRef, useEffect } from "react";
import { Plus, Mic, Camera, ArrowRight, FileText, Activity, Image as ImageIcon, Pill, Apple, FileOutput, X, Paperclip, Stethoscope, Building2, User, HeartPulse } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useSpeechToText, VoiceMicButton, VoiceWaveform } from "./VoiceInput";

export const chatModeSuggestions = [
  { icon: Stethoscope, title: "Analyze my symptoms", promptText: "I would like to analyze my current symptoms. Please help me assess them.", color: "text-blue-500", bg: "bg-blue-50" },
  { icon: Pill, title: "Compare medicines", promptText: "I want to compare medicines and understand their uses and dosages.", color: "text-purple-500", bg: "bg-purple-50" },
  { icon: FileText, title: "Scan prescription", promptText: "Can you help me understand a doctor prescription?", color: "text-green-500", bg: "bg-green-50" },
  { icon: Activity, title: "Analyze blood report", promptText: "I want to analyze a blood test or medical lab report.", color: "text-rose-500", bg: "bg-rose-50" },
  { icon: Apple, title: "Calculate food calories", promptText: "I want to calculate food calories and get dietary recommendations.", color: "text-orange-500", bg: "bg-orange-50" },
  { icon: Building2, title: "Find nearby hospitals", promptText: "Can you help me locate nearby hospitals with specialized facilities?", color: "text-indigo-500", bg: "bg-indigo-50" },
  { icon: User, title: "Find a specialist doctor", promptText: "I need to find a specialist doctor for my health concern.", color: "text-teal-500", bg: "bg-teal-50" },
  { icon: HeartPulse, title: "Check health risks", promptText: "I want to check potential health risk factors.", color: "text-pink-500", bg: "bg-pink-50" },
];

export type ChatMode = {
  title: string;
  icon?: any;
  color?: string;
  bg?: string;
  promptText?: string;
};

export function ChatInput({ 
  onSend, 
  onFileUpload,
  selectedMode, 
  onSelectMode 
}: { 
  onSend: (text: string) => void;
  onFileUpload?: (file: File, analysisType: string) => void;
  selectedMode?: ChatMode | null;
  onSelectMode?: (mode: ChatMode | null) => void;
}) {
  const [text, setText] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);
  const [showMentionMenu, setShowMentionMenu] = useState(false);
  const [mentionQuery, setMentionQuery] = useState("");
  const [mentionIndex, setMentionIndex] = useState(0);
  const [pendingAnalysisType, setPendingAnalysisType] = useState<string | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Voice input
  const { isListening, transcript, isSupported: voiceSupported, toggleListening, setTranscript } = useSpeechToText();

  // Sync voice transcript to textarea
  useEffect(() => {
    if (transcript) {
      setText(prev => prev + transcript);
      setTranscript("");
    }
  }, [transcript, setTranscript]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 220)}px`;
    }
  }, [text, selectedMode]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setMenuOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setText(value);
    
    // Check for @mention
    const cursorPosition = e.target.selectionStart;
    const textBeforeCursor = value.slice(0, cursorPosition);
    const match = textBeforeCursor.match(/(?:^|\s)@([a-zA-Z0-9_ -]*)$/);
    
    if (match) {
      setShowMentionMenu(true);
      setMentionQuery(match[1] || "");
      setMentionIndex(0);
    } else {
      setShowMentionMenu(false);
    }
  };

  const filteredSuggestions = chatModeSuggestions.filter(s => 
    s.title.toLowerCase().includes(mentionQuery.toLowerCase())
  );

  const handleMentionSelect = (mode: ChatMode) => {
    if (onSelectMode) {
      onSelectMode(mode);
    }
    // Remove the @query from text
    const cursorPosition = textareaRef.current?.selectionStart || 0;
    const textBeforeCursor = text.slice(0, cursorPosition);
    const textAfterCursor = text.slice(cursorPosition);
    
    const match = textBeforeCursor.match(/(?:^|\s)@([a-zA-Z0-9_ -]*)$/);
    if (match) {
      const matchLength = match[0].length;
      const hasLeadingSpace = match[0].startsWith(' ') || match[0].startsWith('\n');
      const newTextBefore = textBeforeCursor.slice(0, cursorPosition - matchLength) + (hasLeadingSpace ? ' ' : '');
      setText(newTextBefore + textAfterCursor);
    }
    
    setShowMentionMenu(false);
  };

  const handleSend = () => {
    if (text.trim() || selectedMode) {
      onSend(text); // we can pass text and mode, or let page.tsx handle mode
      setText("");
      if (textareaRef.current) {
        textareaRef.current.style.height = "auto";
      }
      setShowMentionMenu(false);
    }
  };

  const menuItems = [
    { icon: FileText, title: "Scan Prescription", desc: "Extract medicine & instructions", color: "text-blue-600", bg: "bg-blue-100", analysisType: "prescription" },
    { icon: FileOutput, title: "Upload Medical Report", desc: "Analyze blood test, MRI, etc.", color: "text-purple-600", bg: "bg-purple-100", analysisType: "report" },
    { icon: Activity, title: "Upload Lab Result", desc: "Check parameters against normal", color: "text-rose-600", bg: "bg-rose-100", analysisType: "report" },
    { icon: ImageIcon, title: "Upload X-Ray / Image", desc: "Visual AI analysis", color: "text-amber-600", bg: "bg-amber-100", analysisType: "image" },
    { icon: Pill, title: "Compare Medicines", desc: "Check alternatives & side-effects", color: "text-teal-600", bg: "bg-teal-100" },
    { icon: Apple, title: "Food Calorie Scanner", desc: "Upload food image for nutrition", color: "text-green-600", bg: "bg-green-100", analysisType: "food" },
    { icon: Paperclip, title: "Upload from Device", desc: "Select photo, report or document", color: "text-slate-700", bg: "bg-slate-100", isAction: true },
  ];

  return (
    <div className="sticky bottom-0 w-full pb-4 sm:pb-6 pt-2 px-3 sm:px-4 md:px-8     z-40">
      <div className="max-w-[900px] mx-auto relative flex flex-col items-center">
        
        {/* Floating Plus Menu */}
        <AnimatePresence>
          {menuOpen && (
            <motion.div
              ref={menuRef}
              initial={{ opacity: 0, y: 15, scale: 0.95, filter: "blur(8px)" }}
              animate={{ opacity: 1, y: 0, scale: 1, filter: "blur(0px)" }}
              exit={{ opacity: 0, y: 10, scale: 0.95, filter: "blur(4px)" }}
              transition={{ type: "spring", stiffness: 400, damping: 25 }}
              className="absolute bottom-full mb-3 left-0 w-[240px] glass-panel rounded-[20px] p-1.5 z-50 overflow-hidden"
            >
              <div className="relative z-10 flex flex-col">
                {menuItems.map((item, idx) => (
                  <div key={idx} className="w-full">
                    {item.isAction && (
                      <div className="my-1 mx-2 border-t border-slate-200"></div>
                    )}
                    <button
                      className="group flex items-center gap-3 w-full p-2 rounded-2xl hover:bg-slate-100/50 transition-all text-left"
                      onClick={() => {
                        if (item.title === "Upload from Device") {
                          setPendingAnalysisType('image');
                          fileInputRef.current?.click();
                        } else if (item.analysisType) {
                          setPendingAnalysisType(item.analysisType);
                          fileInputRef.current?.click();
                        } else {
                          if (onSelectMode) onSelectMode(item);
                        }
                        setMenuOpen(false);
                      }}
                    >
                      <div className={`w-8 h-8 rounded-xl ${item.bg} flex items-center justify-center ${item.color} shrink-0 shadow-sm border border-black/5 group-hover:scale-105 transition-transform`}>
                        <item.icon size={16} strokeWidth={2.5} />
                      </div>
                      <div className="font-[800] text-[13px] text-slate-700 group-hover:text-slate-900 transition-colors">
                        {item.title}
                      </div>
                    </button>
                  </div>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Floating Mention Menu */}
        <AnimatePresence>
          {showMentionMenu && filteredSuggestions.length > 0 && (
            <motion.div
              initial={{ opacity: 0, y: 10, scale: 0.98 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 5, scale: 0.98 }}
              className="absolute bottom-full mb-3 left-4 sm:left-12 w-[280px] glass-panel rounded-2xl p-1.5 z-50 overflow-hidden"
            >
              <div className="px-2 pt-2 pb-1 text-[11px] font-bold text-slate-400 uppercase tracking-wider">Select a Mode</div>
              <div className="flex flex-col max-h-[220px] overflow-y-auto custom-scrollbar">
                {filteredSuggestions.map((item, idx) => (
                  <button
                    key={idx}
                    onClick={() => handleMentionSelect(item)}
                    className={`flex items-center gap-3 w-full p-2 rounded-xl transition-all text-left ${idx === mentionIndex ? 'bg-slate-100' : 'hover:bg-slate-50'}`}
                    onMouseEnter={() => setMentionIndex(idx)}
                  >
                    <div className={`w-8 h-8 rounded-xl ${item.bg} flex items-center justify-center ${item.color} shrink-0 shadow-sm border border-black/5`}>
                      <item.icon size={16} strokeWidth={2.5} />
                    </div>
                    <span className="font-bold text-[13px] text-slate-700">
                      {item.title}
                    </span>
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
        
        {/* Hidden File Input */}
        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file && onFileUpload) {
              onFileUpload(file, pendingAnalysisType || 'image');
              setPendingAnalysisType(null);
            } else if (file) {
              onSend(`[Uploaded File: ${file.name}]`);
            }
            // Reset input
            e.target.value = '';
          }} 
          accept="image/*,.pdf,.doc,.docx"
        />

        {/* Input Container */}
        <div className="w-full flex items-end gap-1.5 sm:gap-2 bg-white/60 backdrop-blur-xl rounded-xl p-1 sm:p-1.5 min-h-[48px] sm:min-h-[52px] border border-slate-200/80 shadow-sm focus-within:spatial-shadow-hover focus-within:border-primary/20 focus-within:bg-white transition-all duration-300">
          
          {/* Left Action (Plus Button) */}
          <button 
            type="button"
            onClick={() => setMenuOpen(!menuOpen)}
            className="w-[38px] h-[38px] sm:w-[42px] sm:h-[42px] shrink-0 rounded-full bg-slate-100/80 flex items-center justify-center text-slate-600 hover:bg-slate-200 hover:text-slate-900 border border-transparent transition-all duration-300 active:scale-95 mb-0.5 ml-0.5"
          >
            <Plus size={22} className={`transition-transform duration-300 ease-out ${menuOpen ? 'rotate-[135deg] text-primary' : ''}`} />
          </button>

          {/* Textarea Wrapper */}
          <div className="flex-1 flex flex-col justify-center mb-[2px] mt-[2px]">
            {/* Selected Mode Chip */}
            <AnimatePresence>
              {selectedMode && (
                <motion.div 
                  initial={{ opacity: 0, y: 5, height: 0, marginBottom: 0 }}
                  animate={{ opacity: 1, y: 0, height: 'auto', marginBottom: 6 }}
                  exit={{ opacity: 0, y: 5, height: 0, marginBottom: 0 }}
                  className="overflow-hidden"
                >
                  <div className="flex items-center justify-between gap-2 px-2.5 py-1.5 bg-slate-100/80 rounded-[10px] w-fit border border-slate-200/60 shadow-sm">
                    <div className="flex items-center gap-2">
                      {selectedMode.icon && (
                        <div className={`w-5 h-5 rounded-[6px] flex items-center justify-center ${selectedMode.bg} ${selectedMode.color} shadow-sm border border-white/50`}>
                          <selectedMode.icon size={12} strokeWidth={3} />
                        </div>
                      )}
                      <span className="text-[12px] font-bold text-slate-700">{selectedMode.title}</span>
                    </div>
                    <button 
                      onClick={() => onSelectMode?.(null)} 
                      className="text-slate-400 hover:text-slate-600 hover:bg-slate-200 p-0.5 rounded-full transition-colors ml-2"
                    >
                      <X size={14} />
                    </button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Textarea */}
            <textarea
              ref={textareaRef}
              value={text}
              onChange={handleTextChange}
              onKeyDown={(e) => {
                if (showMentionMenu && filteredSuggestions.length > 0) {
                  if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    setMentionIndex((prev) => (prev + 1) % filteredSuggestions.length);
                    return;
                  }
                  if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    setMentionIndex((prev) => (prev - 1 + filteredSuggestions.length) % filteredSuggestions.length);
                    return;
                  }
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    handleMentionSelect(filteredSuggestions[mentionIndex]);
                    return;
                  }
                  if (e.key === 'Escape') {
                    setShowMentionMenu(false);
                    return;
                  }
                }
                
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              placeholder={selectedMode ? `Add a message about ${selectedMode.title.toLowerCase()}...` : "Ask Oxpecker AI a health question..."}
              className="w-full max-h-[220px] bg-transparent resize-none outline-none text-[15px] sm:text-[16px] text-slate-800 placeholder:text-slate-400 py-2 px-2 sm:px-3 scrollbar-thin self-center leading-tight"
              rows={1}
            />
          </div>

          {/* Right Actions */}
          <div className="flex items-center gap-1 shrink-0 mb-0.5 pr-0.5">
            {/* Voice Waveform (visible when listening) */}
            <VoiceWaveform isActive={isListening} />
            
            {/* Mic Button */}
            <div className="hidden sm:flex">
              <VoiceMicButton isListening={isListening} onToggle={toggleListening} isSupported={voiceSupported} />
            </div>
            <button 
              type="button"
              onClick={() => {
                setPendingAnalysisType('image');
                fileInputRef.current?.click();
              }}
              className="hidden sm:flex w-[38px] h-[38px] sm:w-[42px] sm:h-[42px] rounded-full items-center justify-center text-slate-400 hover:bg-slate-100 hover:text-slate-700 transition-colors"
            >
              <Camera size={20} />
            </button>
            <button 
              onClick={handleSend}
              disabled={!text.trim() && !selectedMode}
              className={`w-[38px] h-[38px] sm:w-[42px] sm:h-[42px] rounded-full flex items-center justify-center transition-all duration-300 ${
                (text.trim() || selectedMode) ? "bg-primary text-white shadow-[0_4px_12px_rgba(0,61,155,0.25)] hover:bg-primary/90 hover:shadow-[0_6px_16px_rgba(0,61,155,0.3)] hover:scale-105 active:scale-95" : "bg-slate-100/80 text-slate-400"
              }`}
            >
              <ArrowRight size={20} className={(text.trim() || selectedMode) ? "ml-0.5" : ""} strokeWidth={2.5} />
            </button>
          </div>
        </div>

        {/* Disclaimer */}
        <div className="text-center mt-2.5 pb-1 w-full">
          <p className="text-[11px] sm:text-[12px] text-slate-400 font-medium">
            AI can make mistakes. Verify important medical information.
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Bot, Stethoscope, Pill, FileText, Activity, Apple, Building2, User, HeartPulse } from "lucide-react";
import Image from "next/image";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { DoctorRecommendationLoader, HospitalRecommendationLoader, MedicineRecommendationLoader } from "./cards/RecommendationLoaders";
import { EmergencyAlert } from "./cards/EmergencyAlert";
import { NutritionCard } from "./cards/NutritionCard";
import { PrescriptionCard } from "./cards/PrescriptionCard";
import { ReportCard } from "./cards/ReportCard";

const MODE_ICONS: Record<string, any> = {
  "Analyze my symptoms": Stethoscope,
  "Compare medicines": Pill,
  "Scan prescription": FileText,
  "Analyze blood report": Activity,
  "Calculate food calories": Apple,
  "Find nearby hospitals": Building2,
  "Find a specialist doctor": User,
  "Check health risks": HeartPulse,
};

interface MessageBubbleProps {
  role: "user" | "bot";
  content: string;
}

/**
 * Parses structured JSON blocks from AI response.
 * Format: ```json:block_type { ... } ```
 */
function parseStructuredBlocks(content: string) {
  const blocks: { type: string; data: any; start: number; end: number }[] = [];
  const regex = /```json:([\w_]+)\s*\n?([\s\S]*?)```/g;
  let match;

  while ((match = regex.exec(content)) !== null) {
    try {
      const data = JSON.parse(match[2].trim());
      blocks.push({
        type: match[1],
        data,
        start: match.index,
        end: match.index + match[0].length,
      });
    } catch {
      // Skip invalid JSON
    }
  }

  return blocks;
}

/**
 * Removes structured JSON blocks from content for clean markdown rendering
 */
function cleanContent(content: string): string {
  return content.replace(/```json:[\w_]+\s*\n?[\s\S]*?```/g, '').trim();
}

export function MessageBubble({ role, content }: MessageBubbleProps) {
  const isUser = role === "user";

  // Parse structured blocks from bot messages
  const structuredBlocks = !isUser ? parseStructuredBlocks(content) : [];
  const cleanedContent = !isUser && structuredBlocks.length > 0 
    ? cleanContent(content) 
    : content;

  return (
    <div className={`w-full flex ${isUser ? "justify-end" : "justify-start"} mb-6`}>
      <div className={`flex gap-4 max-w-full ${isUser ? "flex-row-reverse w-[720px]" : "w-[760px]"}`}>
        
        {/* Avatar */}
        <div className={`shrink-0 w-10 h-10 rounded-full flex items-center justify-center mt-1 ${isUser ? "bg-slate-200 text-slate-600 hidden md:flex" : "bg-primary/5 ring-1 ring-primary/20 shadow-sm relative overflow-hidden"}`}>
          {isUser ? <span className="text-sm font-bold">R</span> : <Image src="/images/Oxpecker_icon.png" alt="AI" fill sizes="40px" className="object-contain p-2" />}
        </div>

        {/* Message Content */}
        <div className={`flex-1 min-w-0 ${isUser ? "" : "pt-1"}`}>
          {isUser ? (
            <div className="text-[16px] text-slate-800 leading-relaxed whitespace-pre-wrap flex flex-col items-end gap-1.5">
              {content.startsWith('|MODE:') ? (
                <>
                  <div className="bg-primary/10 text-primary px-3 py-1.5 rounded-full text-[12px] font-bold border border-primary/20 flex items-center gap-1.5 shadow-sm">
                    {(() => {
                      const modeTitle = content.split('|')[1].replace('MODE:', '');
                      const Icon = MODE_ICONS[modeTitle] || Activity;
                      return (
                        <>
                          <Icon size={14} />
                          {modeTitle}
                        </>
                      );
                    })()}
                  </div>
                  {content.split('|').slice(2).join('|') && (
                    <div className="bg-slate-50 px-5 py-3.5 rounded-3xl rounded-tr-sm">
                      {content.split('|').slice(2).join('|')}
                    </div>
                  )}
                </>
              ) : (
                <div className="bg-slate-50 px-5 py-3.5 rounded-3xl rounded-tr-sm">
                  {content}
                </div>
              )}
            </div>
          ) : (
            <div className="space-y-4">
              {/* Markdown content */}
              {cleanedContent && (
                <div className="prose prose-slate max-w-none text-[16px] leading-relaxed prose-p:mb-4 prose-headings:font-semibold prose-a:text-primary hover:prose-a:underline prose-code:bg-slate-100 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded-md prose-pre:bg-slate-50 prose-pre:border prose-pre:border-slate-200 prose-pre:text-slate-800">
                  <ReactMarkdown
                    remarkPlugins={[remarkGfm]}
                    components={{
                      table: ({ node, ...props }) => (
                        <div className="my-4 w-full overflow-x-auto rounded-2xl border border-slate-200 shadow-xs bg-white">
                          <table className="w-full text-left text-sm border-collapse" {...props} />
                        </div>
                      ),
                      thead: ({ node, ...props }) => (
                        <thead className="bg-slate-100/80 border-b border-slate-200 text-slate-900 font-bold" {...props} />
                      ),
                      th: ({ node, ...props }) => (
                        <th className="px-4 py-3 font-bold border-r last:border-r-0 border-slate-200 text-slate-800" {...props} />
                      ),
                      td: ({ node, ...props }) => (
                        <td className="px-4 py-2.5 border-t border-r last:border-r-0 border-slate-100 text-slate-700 font-medium" {...props} />
                      ),
                    }}
                  >
                    {cleanedContent}
                  </ReactMarkdown>
                </div>
              )}

              {/* Structured cards */}
              {structuredBlocks.map((block, idx) => (
                <div key={idx} className="mt-3 w-full">
                  {block.type === 'doctor_recommendation' && (
                    <DoctorRecommendationLoader data={block.data} />
                  )}
                  {block.type === 'hospital_recommendation' && (
                    <HospitalRecommendationLoader data={block.data} />
                  )}
                  {block.type === 'medicine_info' && (
                    <MedicineRecommendationLoader data={block.data} />
                  )}
                  {block.type === 'emergency_alert' && (
                    <EmergencyAlert alert={block.data} />
                  )}
                  {block.type === 'nutrition_analysis' && (
                    <NutritionCard data={block.data} />
                  )}
                  {block.type === 'prescription_analysis' && (
                    <PrescriptionCard data={block.data} />
                  )}
                  {block.type === 'report_analysis' && (
                    <ReportCard data={block.data} />
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

