              {data.parameters.slice(0, 8).map((p, i) => (
                <div key={i} className={`grid grid-cols-4 gap-1 px-3 py-2.5 text-[13px] border-t border-slate-50 ${p.status !== 'normal' ? 'bg-rose-50/30' : ''}`}>
