                  <span className="text-center">
                    <span className={`text-[11px] font-bold px-2 py-0.5 rounded-md capitalize ${statusColors[p.status] || 'text-slate-600 bg-slate-50'}`}>
                      {p.status}
                    </span>
                  </span>
                </div>
              ))}
