}

interface PrescriptionDraft {
  chiefComplaint?: string;
  diagnosis?: string;
  vitals?: string;
  medicines?: {
    name: string;
    generic: string;
    strength: string;
    dosage: string;
    frequency: string;
    duration: string;
    instructions: string;
  }[];
  investigations?: string[];
  advice?: string;
  followUp?: string;
}

interface PatientContext {
  name: string;
  age: number;
  gender: string;
  symptoms: string;
  id: string;
}

