    color: "text-red-600 bg-red-50 border-red-100",
  },
];

// System prompt for Doctor AI Assistant
const DOCTOR_SYSTEM_PROMPT = `You are Oxpecker AI - Doctor's Clinical Assistant. You work alongside doctors to help them:

1. **Write Prescriptions**: When a doctor describes symptoms/diagnosis, generate a complete prescription in structured format.
2. **Analyze Reports**: When given lab report data, identify abnormals, explain findings, suggest follow-up.
3. **Suggest Medicines**: Recommend appropriate medicines with exact brand names (Bangladeshi market), dosage, frequency, duration, and warnings.
4. **Differential Diagnosis**: Given symptoms, list probable diagnoses ranked by likelihood.
5. **Drug Interactions**: Check for dangerous drug interactions.
6. **Treatment Plans**: Create comprehensive treatment plans.

RULES:
- You are assisting a LICENSED DOCTOR, not a patient. Speak professionally.
- Use Bangladeshi medicine brand names (Napa, Seclo, Ace, Sergel, etc.)
- Prices in BDT (৳)
- Always include generic names alongside brand names
- Flag any contraindications or drug interactions
- When writing prescriptions, use this JSON format:

\`\`\`json:prescription_draft
{
  "chiefComplaint": "...",
  "diagnosis": "...",
  "vitals": "...",
  "medicines": [
    {
      "name": "Brand Name",
      "generic": "Generic Name",
      "strength": "500mg",
      "dosage": "1+0+1",
      "frequency": "Twice daily",
      "duration": "7 days",
      "instructions": "After meal"
    }
  ],
  "investigations": ["CBC", "Urine R/E"],
  "advice": "...",
  "followUp": "7 days"
}
\`\`\`

- Respond in the same language the doctor uses (Bangla or English)
- Be concise but thorough
- Always verify critical decisions with the doctor`;

export function DoctorAIAssistant({
  isOpen,
  onClose,
  patient,
  onPrescriptionReady,
}: {
  isOpen: boolean;
  onClose: () => void;
  patient?: PatientContext | null;
  onPrescriptionReady?: (data: PrescriptionDraft) => void;
}) {
  const [messages, setMessages] = useState<DoctorMessage[]>([]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showActions, setShowActions] = useState(true);
  const [prescriptionDraft, setPrescriptionDraft] = useState<PrescriptionDraft | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Voice
  const { isListening, transcript, isSupported: voiceSupported, toggleListening, setTranscript } = useSpeechToText();

  useEffect(() => {
    if (transcript) {
      setInput(prev => prev + transcript);
      setTranscript("");
    }
  }, [transcript, setTranscript]);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + "px";
    }
  }, [input]);

  // Welcome message with patient context
  useEffect(() => {
    if (isOpen && messages.length === 0) {
      const welcomeMsg = patient
        ? `🩺 **ডাক্তার সাহেব, আমি আপনার AI সহকারী।**\n\nবর্তমান রোগী: **${patient.name}** (${patient.age}/${patient.gender})\nলক্ষণ: ${patient.symptoms}\n\nকিভাবে সাহায্য করতে পারি? নিচের অপশনগুলো থেকে বেছে নিন অথবা সরাসরি কমান্ড দিন।`
        : `🩺 **ডাক্তার সাহেব, আমি আপনার AI সহকারী।**\n\nআমি আপনাকে প্রেসক্রিপশন লেখা, রিপোর্ট বিশ্লেষণ, ওষুধ সাজেশন, এবং ডকুমেন্টেশনে সাহায্য করতে পারি। নিচের অপশনগুলো থেকে শুরু করুন।`;

      setMessages([{ id: "welcome", role: "ai", content: welcomeMsg }]);
    }
  }, [isOpen, patient]);

  const handleSend = async (text?: string) => {
    const msgText = text || input.trim();
    if (!msgText || isLoading) return;

    setInput("");
    setShowActions(false);

    // Check if it's a report scan action
    if (msgText === "[SCAN_REPORT]") {
      fileInputRef.current?.click();
      return;
    }

    const doctorMsg: DoctorMessage = {
      id: Date.now().toString(),
      role: "doctor",
      content: msgText,
    };
    setMessages(prev => [...prev, doctorMsg]);
    setIsLoading(true);

    // Bot placeholder
    const botId = (Date.now() + 1).toString();
    setMessages(prev => [...prev, { id: botId, role: "ai", content: "" }]);

    try {
      // Build context with patient info
      const systemContext = patient
        ? `${DOCTOR_SYSTEM_PROMPT}\n\nCURRENT PATIENT:\nName: ${patient.name}\nAge: ${patient.age}\nGender: ${patient.gender}\nSymptoms: ${patient.symptoms}\nID: ${patient.id}`
        : DOCTOR_SYSTEM_PROMPT;

      const allMessages = [
        { role: "system", content: systemContext },
        ...messages.filter(m => m.id !== "welcome").map(m => ({
          role: m.role === "doctor" ? "user" : "assistant",
          content: m.content,
        })),
        { role: "user", content: msgText },
      ];

      const response = await fetch("/api/ai/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: allMessages }),
      });

      if (!response.ok) throw new Error("AI request failed");

      // Stream response
      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      let fullContent = "";

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = decoder.decode(value, { stream: true });
          const lines = chunk.split("\n").filter(l => l.startsWith("data: "));

          for (const line of lines) {
            const data = line.slice(6);
            if (data === "[DONE]") continue;

            try {
              const parsed = JSON.parse(data);
              const content = parsed.content || parsed.choices?.[0]?.delta?.content || "";
              if (content) {
                fullContent += content;
                setMessages(prev =>
                  prev.map(m => m.id === botId ? { ...m, content: fullContent } : m)
                );
              }
            } catch {}
          }
        }
      }

      // Parse prescription draft from response
      const prescMatch = fullContent.match(/```json:prescription_draft\s*\n?([\s\S]*?)```/);
      if (prescMatch) {
        try {
          const draft = JSON.parse(prescMatch[1].trim());
          setPrescriptionDraft(draft);
        } catch {}
      }
    } catch (error: any) {
      setMessages(prev =>
        prev.map(m =>
          m.id === botId
            ? { ...m, content: `⚠️ Error: ${error.message}\n\nAPI Key কনফিগার করা আছে কিনা নিশ্চিত করুন।` }
            : m
        )
      );
    } finally {
      setIsLoading(false);
    }
  };

  // Handle report upload
  const handleReportUpload = async (file: File) => {
    const doctorMsg: DoctorMessage = {
      id: Date.now().toString(),
      role: "doctor",
      content: `📎 রিপোর্ট আপলোড: **${file.name}**\nবিশ্লেষণ করুন এবং বলুন রোগী কোন কোন সমস্যায় আছে, কি কি করতে হবে, এবং ওষুধ সাজেস্ট করুন।`,
    };
    setMessages(prev => [...prev, doctorMsg]);
    setShowActions(false);
    setIsLoading(true);

    const botId = (Date.now() + 1).toString();
    setMessages(prev => [...prev, { id: botId, role: "ai", content: "🔍 রিপোর্ট বিশ্লেষণ করছি..." }]);

    try {
      const formData = new FormData();
      formData.append("image", file);

      const response = await fetch("/api/ai/analyze-report", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) throw new Error("Report analysis failed");

      const data = await response.json();
      const analysis = data.analysis || "বিশ্লেষণ সম্ভব হয়নি।";

      setMessages(prev =>
        prev.map(m => m.id === botId ? { ...m, content: analysis } : m)
      );

      // Check for prescription draft
      const prescMatch = analysis.match(/```json:prescription_draft\s*\n?([\s\S]*?)```/);
      if (prescMatch) {
        try {
          const draft = JSON.parse(prescMatch[1].trim());
          setPrescriptionDraft(draft);
        } catch {}
      }
    } catch (error: any) {
      setMessages(prev =>
        prev.map(m =>
          m.id === botId ? { ...m, content: `⚠️ রিপোর্ট বিশ্লেষণে সমস্যা: ${error.message}` } : m
        )
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleAcceptPrescription = () => {
    if (prescriptionDraft && onPrescriptionReady) {
      onPrescriptionReady(prescriptionDraft);
      setPrescriptionDraft(null);
    }
  };

  if (!isOpen) return null;

  return (
    <>
      {/* Backdrop */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100]"
        onClick={onClose}
      />

      {/* Drawer */}
      <motion.div
        initial={{ x: "100%" }}
        animate={{ x: 0 }}
        exit={{ x: "100%" }}
        transition={{ type: "spring", damping: 25, stiffness: 200 }}
        className="fixed top-0 right-0 w-full lg:max-w-[520px] h-full bg-slate-900 shadow-2xl z-[101] flex flex-col border-l border-slate-700"
      >
        {/* Header */}
        <div className="h-[72px] px-5 border-b border-slate-800 flex items-center justify-between    shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl    flex items-center justify-center text-white shadow-none">
              <Bot size={22} />
            </div>
            <div>
              <h2 className="text-[16px] font-black text-slate-200">Oxpecker AI</h2>
              <p className="text-[12px] text-slate-500 font-medium">Doctor&apos;s Clinical Assistant</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => {
                setMessages([]);
                setShowActions(true);
                setPrescriptionDraft(null);
              }}
              className="w-9 h-9 rounded-lg bg-slate-900 border border-slate-700 flex items-center justify-center text-slate-500 hover:text-slate-300 transition-colors"
            >
              <RefreshCw size={16} />
            </button>
            <button
              onClick={onClose}
              className="w-9 h-9 rounded-lg bg-slate-900 border border-slate-700 flex items-center justify-center text-slate-500 hover:text-slate-300 transition-colors"
            >
              <X size={16} />
            </button>
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-950/30">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === "doctor" ? "justify-end" : "justify-start"}`}>
              <div className={`max-w-[85%] ${
                msg.role === "doctor"
                  ? "bg-blue-600 text-white rounded-2xl rounded-br-md px-4 py-3"
                  : "bg-slate-900 border border-slate-700 rounded-2xl rounded-bl-md px-4 py-3 shadow-none"
              }`}>
                {msg.role === "ai" && !msg.content && (
                  <div className="flex items-center gap-2 text-slate-500">
                    <div className="flex gap-1">
                      {[0, 1, 2].map(i => (
                        <motion.div
                          key={i}
                          animate={{ opacity: [0.3, 1, 0.3] }}
                          transition={{ duration: 1, repeat: Infinity, delay: i * 0.2 }}
                          className="w-2 h-2 bg-blue-400 rounded-full"
                        />
                      ))}
                    </div>
                    <span className="text-[13px]">চিন্তা করছি...</span>
                  </div>
                )}
                <div className={`text-[14px] leading-relaxed whitespace-pre-wrap ${
                  msg.role === "doctor" ? "text-white" : "text-slate-300"
                }`}>
                  {msg.content.split(/(\*\*.*?\*\*)/g).map((part, i) =>
                    part.startsWith("**") && part.endsWith("**") ? (
                      <strong key={i}>{part.slice(2, -2)}</strong>
                    ) : (
                      <span key={i}>{part}</span>
                    )
                  )}
                </div>
              </div>
            </div>
          ))}

          {/* Quick Actions */}
          {showActions && (
            <div className="grid grid-cols-2 gap-2 mt-2">
              {QUICK_ACTIONS.map((action, idx) => (
                <motion.button
                  key={idx}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  onClick={() => {
                    if (action.prompt === "[SCAN_REPORT]") {
                      fileInputRef.current?.click();
                    } else {
                      setInput(action.prompt);
                      textareaRef.current?.focus();
                    }
                  }}
                  className={`flex flex-col items-start gap-2 p-3 rounded-xl border text-left hover:shadow-none transition-all ${action.color}`}
                >
                  <action.icon size={20} />
                  <div>
                    <p className="text-[13px] font-bold leading-tight">{action.title}</p>
                    <p className="text-[11px] opacity-70 mt-0.5 leading-tight">{action.desc}</p>
                  </div>
                </motion.button>
              ))}
            </div>
          )}

          {/* Prescription Draft Card */}
          <AnimatePresence>
            {prescriptionDraft && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="bg-slate-900 border-2 border-blue-200 rounded-2xl overflow-hidden shadow-none"
              >
                <div className="   px-4 py-3 flex items-center justify-between">
                  <div className="flex items-center gap-2 text-white">
                    <Clipboard size={18} />
                    <span className="font-bold text-[14px]">প্রেসক্রিপশন ড্রাফট</span>
                  </div>
                  <div className="flex gap-1.5">
                    <button
                      onClick={() => setIsEditing(!isEditing)}
                      className="px-3 py-1 bg-slate-900/20 text-white text-[12px] font-bold rounded-lg hover:bg-slate-900/30 transition-colors flex items-center gap-1"
                    >
                      <Edit3 size={12} /> Edit
                    </button>
                  </div>
                </div>

                <div className="p-4 space-y-3 text-[13px]">
                  {prescriptionDraft.chiefComplaint && (
                    <div>
                      <p className="font-bold text-slate-500 text-[11px] uppercase tracking-wider">Chief Complaint</p>
                      <p className="text-slate-300 mt-0.5">{prescriptionDraft.chiefComplaint}</p>
                    </div>
                  )}
                  {prescriptionDraft.diagnosis && (
                    <div>
                      <p className="font-bold text-slate-500 text-[11px] uppercase tracking-wider">Diagnosis</p>
                      <p className="text-slate-300 font-semibold mt-0.5">{prescriptionDraft.diagnosis}</p>
                    </div>
                  )}
                  {prescriptionDraft.medicines && prescriptionDraft.medicines.length > 0 && (
                    <div>
                      <p className="font-bold text-slate-500 text-[11px] uppercase tracking-wider mb-1.5">Medicines ({prescriptionDraft.medicines.length})</p>
                      {prescriptionDraft.medicines.map((med, i) => (
                        <div key={i} className="bg-slate-950 rounded-lg p-2.5 mb-1.5 border border-slate-800">
                          <p className="font-bold text-slate-200">{med.name} <span className="font-normal text-slate-500">{med.strength}</span></p>
                          <p className="text-[11px] text-slate-500 italic">{med.generic}</p>
                          <p className="text-[12px] text-blue-600 mt-1">
                            {med.dosage} • {med.frequency} • {med.duration} • {med.instructions}
                          </p>
                        </div>
                      ))}
                    </div>
                  )}
                  {prescriptionDraft.advice && (
                    <div>
                      <p className="font-bold text-slate-500 text-[11px] uppercase tracking-wider">Advice</p>
                      <p className="text-slate-300 mt-0.5">{prescriptionDraft.advice}</p>
                    </div>
                  )}
                  {prescriptionDraft.followUp && (
                    <div>
                      <p className="font-bold text-slate-500 text-[11px] uppercase tracking-wider">Follow Up</p>
                      <p className="text-slate-300 mt-0.5">{prescriptionDraft.followUp}</p>
                    </div>
                  )}
                </div>

                <div className="px-4 pb-4 flex gap-2">
                  <button
                    onClick={handleAcceptPrescription}
                    className="flex-1 h-[40px] bg-emerald-600 text-white text-[13px] font-bold rounded-xl flex items-center justify-center gap-1.5 hover:bg-emerald-700 transition-colors"
                  >
                    <Check size={16} /> Accept & Use
                  </button>
                  <button
                    onClick={() => handleSend("এই প্রেসক্রিপশনটি আবার রিভাইজ করুন এবং আরো ভালো ওষুধ সাজেস্ট করুন।")}
                    className="h-[40px] px-4 border border-slate-700 text-slate-500 text-[13px] font-bold rounded-xl hover:bg-slate-950 transition-colors flex items-center gap-1.5"
                  >
                    <RefreshCw size={14} /> Revise
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <div ref={messagesEndRef} className="h-2" />
        </div>

        {/* Hidden File Input for Report Scan */}
        <input
          type="file"
          ref={fileInputRef}
          className="hidden"
          accept="image/*,.pdf"
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) handleReportUpload(file);
            e.target.value = "";
          }}
        />

        {/* Input Area */}
        <div className="p-3 border-t border-slate-800 bg-slate-900 shrink-0">
          {/* Patient context bar */}
          {patient && (
            <div className="flex items-center gap-2 mb-2 px-2">
              <div className="w-6 h-6 rounded-full bg-blue-100 text-blue-600 text-[11px] font-bold flex items-center justify-center">
                {patient.name.charAt(0)}
              </div>
              <span className="text-[12px] text-slate-500 font-medium">
                {patient.name} • {patient.age}/{patient.gender} • {patient.symptoms}
              </span>
            </div>
          )}

          <div className="flex items-end gap-2">
            {/* Quick actions toggle */}
            <button
              onClick={() => setShowActions(!showActions)}
              className="w-[40px] h-[40px] rounded-xl bg-slate-800 text-slate-500 flex items-center justify-center hover:bg-slate-800 transition-colors shrink-0"
            >
              <Bot size={18} />
            </button>

            {/* Report upload */}
            <button
              onClick={() => fileInputRef.current?.click()}
              className="w-[40px] h-[40px] rounded-xl bg-slate-800 text-slate-500 flex items-center justify-center hover:bg-slate-800 transition-colors shrink-0"
            >
              <Camera size={18} />
            </button>

            {/* Text input */}
            <div className="flex-1 bg-slate-800 rounded-xl px-3 py-1">
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    handleSend();
                  }
                }}
                placeholder="কমান্ড দিন বা প্রশ্ন করুন..."
                className="w-full bg-transparent resize-none outline-none text-[14px] text-slate-200 placeholder:text-slate-500 py-2 max-h-[80px] leading-tight"
                rows={1}
              />
            </div>

            {/* Voice */}
            <VoiceWaveform isActive={isListening} />
            <VoiceMicButton isListening={isListening} onToggle={toggleListening} isSupported={voiceSupported} />

            {/* Send */}
            <button
              onClick={() => handleSend()}
              disabled={!input.trim() || isLoading}
              className={`w-[40px] h-[40px] rounded-xl flex items-center justify-center transition-all shrink-0 ${
                input.trim() && !isLoading
                  ? "bg-blue-600 text-white shadow-none hover:bg-blue-700"
                  : "bg-slate-800 text-slate-500"
              }`}
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      </motion.div>
    </>
  );
}

"use client";

import { useState } from "react";
import { useAuth } from "@/context/AuthContext";
import {
  Search,
  Bell,
  UserPlus,
  CalendarPlus,
  Menu,
  ShieldCheck,
  ChevronDown,
  Maximize,
  Minimize,
  X,
} from "lucide-react";
import { toast } from "sonner";
import Image from "next/image";
import Link from "next/link";

interface DoctorHeaderProps {
  onMenuClick: () => void;
}

export function DoctorHeader({ onMenuClick }: DoctorHeaderProps) {
  const { user } = useAuth();
  const [searchQuery, setSearchQuery] = useState("");
  const [showNotifications, setShowNotifications] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch((err) => {
        toast.error(`Error attempting to enable fullscreen mode: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullscreen(false);
      }
    }
  };

  const notifications = [
    { id: 1, text: "New appointment request from Fatema Akter", time: "2 min ago", unread: true },
    { id: 2, text: "Lab report ready for Kamal Hossain", time: "15 min ago", unread: true },
    { id: 3, text: "Prescription approved for Abdul Matin", time: "1 hour ago", unread: false },
  ];

  const unreadCount = notifications.filter((n) => n.unread).length;

  return (
    <header className="h-16 bg-slate-900/60 backdrop-blur-xl border-b border-slate-700/80 flex items-center justify-between px-4 lg:px-6 shrink-0 w-full shadow-none">
      {/* Left: Mobile menu + Search */}
      <div className="flex items-center gap-3 flex-1">
        <button
          onClick={onMenuClick}
          className="lg:hidden p-2 -ml-1 text-slate-500 hover:bg-slate-800 rounded-lg transition-colors"
          aria-label="Toggle menu"
        >
          <Menu size={22} />
        </button>

        {/* Mobile Logo */}
        <Link href="/doctor/dashboard" className="flex items-center gap-2 lg:hidden">
          <Image
            src="/images/Oxpecker_icon.png"
            alt="Oxpecker"
            width={28}
            height={28}
            className="rounded-lg"
          />
          <div className="flex items-baseline gap-1.5">
            <span className="text-[16px] font-bold text-slate-200 tracking-tight">Oxpecker</span>
            <span className="text-[9px] font-bold text-[#2F80ED] bg-sky-500/10 px-1.5 py-0.5 rounded-full uppercase tracking-wider">Doctor</span>
          </div>
        </Link>

        {/* Search */}
        <div className="relative max-w-[600px] flex-1 hidden sm:block">
          <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
          <input
            type="text"
            placeholder="Search patients, appointments..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full h-11 lg:h-12 pl-11 pr-4 bg-slate-950 border border-slate-700 rounded-xl text-[14px] text-slate-300 placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-[#2F80ED]/20 focus:border-[#2F80ED]/40 transition-all shadow-none"
          />
        </div>
      </div>

      {/* Right: Actions + Notifications + Profile */}
      <div className="flex items-center gap-2">
        {/* Quick Actions */}
        <button
          onClick={() => toast.success("Add Patient dialog coming soon!")}
          className="hidden md:flex items-center gap-1.5 h-9 px-3.5 bg-primary/8 text-primary text-[13px] font-medium rounded-lg hover:bg-primary/12 transition-colors"
        >
          <UserPlus size={15} />
          <span>Add Patient</span>
        </button>
        <button
          onClick={() => toast.success("New Appointment dialog coming soon!")}
          className="hidden md:flex items-center gap-1.5 h-9 px-3.5 bg-emerald-50 text-emerald-600 text-[13px] font-medium rounded-lg hover:bg-emerald-100 transition-colors"
        >
          <CalendarPlus size={15} />
          <span>New Appointment</span>
        </button>

        {/* Fullscreen Toggle */}
        <button
          onClick={toggleFullscreen}
          className="hidden sm:flex p-2 text-slate-500 hover:bg-slate-800 rounded-lg transition-colors"
          aria-label="Toggle Fullscreen"
        >
          {isFullscreen ? <Minimize size={20} /> : <Maximize size={20} />}
        </button>

        {/* Notifications */}
        <div className="relative">
          <button
            onClick={() => setShowNotifications(!showNotifications)}
            className="relative p-2 text-slate-500 hover:bg-slate-800 rounded-lg transition-colors"
            aria-label="Notifications"
          >
            <Bell size={20} />
            {unreadCount > 0 && (
              <span className="absolute top-1 right-1 w-4.5 h-4.5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
                {unreadCount}
              </span>
            )}
          </button>

          {/* Notification Dropdown */}
          {showNotifications && (
            <>
              <div className="fixed inset-0 z-40 sm:z-40" onClick={() => setShowNotifications(false)} />
              <div className="fixed inset-0 z-[99999] bg-slate-950 flex flex-col h-[100dvh] sm:h-auto sm:absolute sm:inset-auto sm:right-0 sm:top-full sm:mt-2 sm:w-80 sm:bg-slate-900/60 sm:backdrop-blur-xl sm:rounded-xl sm:shadow-[0_8px_32px_rgba(0,0,0,0.12)] border-0 sm:border sm:border-white/60 overflow-hidden sm:z-50 animate-in slide-in-from-bottom-2 sm:slide-in-from-top-2 duration-200">
                <div className="px-4 py-4 sm:py-3 border-b border-slate-700 sm:border-white/50 bg-slate-900 sm:bg-slate-900/30 flex items-center justify-between shrink-0">
                  <h4 className="text-lg sm:text-sm font-bold text-slate-200">Notifications</h4>
                  <button 
                    onClick={() => setShowNotifications(false)}
                    className="sm:hidden p-2 -mr-2 text-slate-500 hover:bg-slate-800 rounded-full transition-colors"
                  >
                    <X size={20} />
                  </button>
                </div>
                <div className="flex-1 sm:max-h-64 overflow-y-auto custom-scrollbar">
                  {notifications.map((n) => (
                    <div
                      key={n.id}
                      className={`px-4 py-4 sm:py-3 border-b border-slate-800 sm:border-white/20 last:border-0 hover:bg-slate-800 sm:hover:bg-slate-900/40 transition-colors cursor-pointer ${n.unread ? "bg-blue-50/50 sm:bg-slate-900/30 shadow-none" : "bg-slate-900 sm:bg-transparent"}`}
                    >
                      <p className="text-[14px] sm:text-[13px] font-medium text-slate-200">{n.text}</p>
                      <p className="text-[12px] sm:text-[11px] font-bold text-[#2F80ED] sm:text-slate-500 mt-1">{n.time}</p>
                    </div>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>

              {/* Profile Link */}
        <Link href="/doctor/settings/profile" className="flex items-center gap-2 pl-2">
          <div className="hidden sm:block text-right">
            <p className="text-xs font-bold text-slate-200 line-clamp-1 max-w-[120px]">
              {user?.name || "Dr. User"}
            </p>
            <p className="text-[10px] text-sky-600 font-extrabold uppercase tracking-wider">
              Specialist
            </p>
          </div>
          <div className="w-9 h-9 rounded-full bg-sky-600 text-white flex items-center justify-center text-xs font-black overflow-hidden border border-slate-700 shadow-xs relative shrink-0">
            {user?.image ? (
              <Image src={user.image} alt={user?.name || "Doctor"} fill sizes="36px" className="object-cover" />
            ) : (
              user?.name ? user.name.charAt(0).toUpperCase() : "D"
            )}
          </div>
        </Link>
      </div>
    </header>
  );
}

"use client";

import { useState, useEffect } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import { useAuth } from "@/context/AuthContext";
import { motion } from "framer-motion";
import {
  LayoutDashboard,
  Users,
  CalendarDays,
  ClipboardList,
  FileBarChart,
  Pill,
  MessageSquare,
  Settings,
  LogOut,
  ShieldCheck,
  Lock,
  ChevronRight,
  ChevronLeft,
  X,
} from "lucide-react";

interface DoctorSidebarProps {
  isOpen: boolean;
  onClose: () => void;
}

const navCategories = [
  {
    title: "Overview",
    items: [
      { label: "Dashboard", href: "/doctor/dashboard", icon: LayoutDashboard },
    ]
  },
  {
    title: "Clinical",
    items: [
      { label: "Appointments", href: "/doctor/dashboard/appointments", icon: CalendarDays },
      { label: "Prescriptions", href: "/doctor/dashboard/prescription", icon: ClipboardList },
      { label: "Patient List", href: "/doctor/dashboard/patients", icon: Users },
      { label: "Reports & Diagnostics", href: "/doctor/dashboard/reports", icon: FileBarChart },
    ]
  },
  {
    title: "Management",
    items: [
      { label: "Medicine Inventory", href: "/doctor/dashboard/medicines", icon: Pill },
      { label: "Messages", href: "/doctor/dashboard/messages", icon: MessageSquare },
    ]
  }
];

export function DoctorSidebar({ isOpen, onClose }: DoctorSidebarProps) {
  const pathname = usePathname();
  const { logout, user } = useAuth();
  const [isCollapsed, setIsCollapsed] = useState(false);
  
  const isActive = (href: string) => {
    if (href === "/doctor/dashboard") return pathname === href;
    return pathname.startsWith(href);
  };
  
  useEffect(() => {
    if (pathname.includes("/prescription/new")) {
      setIsCollapsed(true);
    }
  }, [pathname]);

  return (
    <>
      {/* Mobile overlay */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-40 lg:hidden" 
          onClick={onClose}
        />
      )}
      
      {/* Sidebar */}
      <aside
        className={`
          fixed lg:relative inset-y-0 left-0 z-50
          ${isCollapsed ? "lg:w-[80px]" : "lg:w-[240px]"} w-[240px] bg-transparent border-none
          flex flex-col h-full
          transform transition-all duration-300 ease-in-out
          ${isOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0"}
        `}
      >
        {/* Collapse Toggle Button (Desktop Only) */}
        <button
          onClick={() => setIsCollapsed(!isCollapsed)}
          className="hidden lg:flex absolute top-6 -right-3.5 w-7 h-7 bg-slate-900 border border-slate-800 rounded-full items-center justify-center text-slate-500 hover:text-sky-400 hover:border-sky-200 shadow-none z-50 transition-colors"
        >
          {isCollapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
        </button>
        
        {/* Logo Section */}
        <div className={`h-16 px-4 flex items-center ${isCollapsed ? 'lg:justify-center justify-between' : 'justify-between'} border-none shrink-0 bg-transparent`}>
          <Link href="/doctor/dashboard" className={`flex items-center gap-2.5 ${isCollapsed ? 'lg:justify-center' : ''}`}>
            {isCollapsed ? (
              <Image
                src="/images/Oxpecker_icon.png"  
                alt="Oxpecker AI"  
                width={36}
                height={36}
                className="object-contain hidden lg:block transition-all duration-300"
              />
            ) : (
              <Image
                src="/images/Oxpecker_full_size.png"  
                alt="Oxpecker AI"  
                width={140}
                height={36}
                className="object-contain block transition-all duration-300"
              />
            )}
            
            {/* Mobile logo always full */}
            {isCollapsed && (
              <Image
                src="/images/Oxpecker_full_size.png"  
                alt="Oxpecker AI"  
                width={140}
                height={36}
                className="object-contain lg:hidden block transition-all duration-300"
              />
            )}
          </Link>
          <button
            onClick={onClose}
            className="lg:hidden p-1.5 text-slate-500 hover:text-slate-300 hover:bg-slate-800 rounded-lg transition-colors"  
          >
            <X size={18} />
          </button>
        </div>
        
        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto px-4 py-6 space-y-6 scrollbar-hide bg-transparent">
          {navCategories.map((category, idx) => (
            <div key={idx} className="space-y-1">
              <div className={`px-2 text-xs font-bold text-slate-500 uppercase tracking-wider overflow-hidden whitespace-nowrap transition-all duration-300 ${isCollapsed ? 'lg:opacity-0 lg:h-0' : 'opacity-100 pb-2 h-auto'}`}>
                {category.title}
              </div>
              {category.items.map((item) => {
                const active = isActive(item.href);
                return (
                  <Link
                    key={item.href}
                    href={item.href}
                    onClick={onClose}
                    className={`
                      relative flex items-center py-2.5 rounded-xl text-sm font-semibold transition-all duration-200 group
                      ${isCollapsed ? 'lg:justify-center lg:px-0 lg:gap-0 px-3 gap-3' : 'px-3 gap-3'}
                      ${active ? "text-sky-400" : "text-slate-500 hover:text-slate-200"}
                    `}
                    title={isCollapsed ? item.label : undefined}
                  >
                    {active && (
                      <motion.div 
                        layoutId="doctor-active-nav"
                        className="absolute inset-0 bg-slate-900 rounded-xl shadow-none border border-slate-800/60"
                        initial={false}
                        transition={{ type: "spring", stiffness: 350, damping: 30 }}
                      />
                    )}
                    <item.icon size={18} strokeWidth={active ? 2.5 : 2} className={`shrink-0 relative z-10 ${active ? "text-sky-600" : "text-slate-500 group-hover:text-slate-300"}`} />
                    <span className={`relative z-10 overflow-hidden whitespace-nowrap transition-all duration-300 ${isCollapsed ? 'lg:w-0 lg:opacity-0' : 'flex-1 opacity-100'}`}>{item.label}</span>
                    {active && <ChevronRight size={14} className={`text-sky-400 relative z-10 transition-all duration-300 ${isCollapsed ? 'lg:w-0 lg:opacity-0 lg:scale-0' : 'w-auto opacity-100 scale-100'}`} />}
                  </Link>
                );
              })}
            </div>
          ))}
        </nav>
        
        {/* Bottom Section: Fixed Settings & Logout */}
        <div className="px-3 pb-4 space-y-1 shrink-0 border-transparent pt-4 bg-transparent">
          <Link
            href="/doctor/settings"
            onClick={onClose}
            title={isCollapsed ? "Settings" : undefined}
            className={`
              relative flex items-center py-3 rounded-xl border border-transparent transition-all duration-200 group
              ${isActive("/doctor/settings") ? "bg-slate-900 border-sky-500/30" : "hover:bg-slate-900 hover:border-slate-800/60"}
              ${isCollapsed ? 'lg:justify-center lg:px-0 lg:gap-0 px-3 gap-3' : 'px-3 gap-3'}
            `}
          >
            <Settings size={20} strokeWidth={isActive("/doctor/settings") ? 2.5 : 2} className={`shrink-0 ${isActive("/doctor/settings") ? "text-sky-400" : "text-slate-400 group-hover:text-slate-200"}`} />
            <span className={`font-bold overflow-hidden whitespace-nowrap transition-all duration-300 ${isActive("/doctor/settings") ? "text-slate-100" : "text-slate-400 group-hover:text-slate-200"} ${isCollapsed ? 'lg:w-0 lg:opacity-0' : 'flex-1 opacity-100'}`}>Settings</span>
          </Link>
          
          <button
            onClick={() => { logout(); onClose(); }}
            title={isCollapsed ? "Logout" : undefined}
            className={`
              w-full relative flex items-center py-3 rounded-xl border border-transparent transition-all duration-200 group hover:bg-rose-500/10 hover:border-rose-500/20
              ${isCollapsed ? 'lg:justify-center lg:px-0 lg:gap-0 px-3 gap-3' : 'px-3 gap-3'}
            `}
          >
            <LogOut size={20} className="shrink-0 text-slate-500 group-hover:text-rose-400" />
