function parseStructuredBlocks(content: string) {
  const blocks: { type: string; data: any; start: number; end: number }[] = [];
  const regex = /```json:([\w_]+)\s*\n?([\s\S]*?)```/g;
  let match;
  while ((match = regex.exec(content)) !== null) {
    try {
      blocks.push({ type: match[1], data: JSON.parse(match[2].trim()), start: match.index, end: match.index + match[0].length });
    } catch {}
  }
  return blocks;
}

function cleanContent(content: string): string {
  // Remove all markdown json blocks from display
  return content.replace(/```json(?:[^\n]*)\n?([\s\S]*?)```/g, '').trim();
}

export function AIAssistancePanel() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [prescriptionDraft, setPrescriptionDraft] = useState<PrescriptionDraft | null>(null);
  const [isListening, setIsListening] = useState(false);
  const [isVoiceSupported, setIsVoiceSupported] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  // Connect to Prescription Editor Context
  const { data: rxData, updateData: updateRx, addMedicine } = usePrescription();
  const { testReports, patientPrescriptions } = useDoctor();

  // Quick action chips - doctor-focused
  const defaultChips = [
    { icon: ClipboardList, label: "Write Prescription", desc: "Auto-generate Rx from symptoms", prompt: "Please write a complete prescription for the current patient based on their details.", color: "text-sky-400", bg: "bg-sky-500/10" },
    { icon: Pill, label: "Medicine Suggestion", desc: "Get smart medicine recommendations", prompt: "Please suggest appropriate medicines for the current patient's diagnosis and symptoms.", color: "text-emerald-400", bg: "bg-emerald-500/10" },
    { icon: FileSearch, label: "Scan Report", desc: "Upload and analyze lab reports", prompt: "[SCAN_REPORT]", color: "text-purple-400", bg: "bg-purple-500/10" },
    { icon: History, label: "Summarize History", desc: "Quick overview of past visits", prompt: "[SUMMARIZE_HISTORY]", color: "text-amber-400", bg: "bg-amber-500/10" },
  ];

  // Speech Recognition setup
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRecognition) {
        const recognition = new SpeechRecognition();
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = 'bn-BD';

        recognition.onresult = (event: any) => {
          let finalTranscript = '';
          for (let i = event.resultIndex; i < event.results.length; i++) {
            if (event.results[i].isFinal) {
              finalTranscript += event.results[i][0].transcript;
            }
          }
          if (finalTranscript) {
            setInputValue(prev => prev + finalTranscript);
          }
        };

        recognition.onerror = () => setIsListening(false);
        recognition.onend = () => setIsListening(false);
        recognitionRef.current = recognition;
      } else {
        setIsVoiceSupported(false);
      }
    }
  }, []);

  const toggleVoice = () => {
    if (!recognitionRef.current) return;
    if (isListening) {
      recognitionRef.current.stop();
      setIsListening(false);
    } else {
      try {
        recognitionRef.current.start();
        setIsListening(true);
      } catch {}
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, prescriptionDraft]);

  // Real AI send
  const handleSend = async (text: string) => {
    if (!text.trim() || isLoading) return;

    // Handle report scan
    if (text === "[SCAN_REPORT]") {
      fileInputRef.current?.click();
      return;
    }

    let displayUserText = text;
    let actualSystemText = text;

    if (text === "[SUMMARIZE_HISTORY]") {
      displayUserText = "Please summarize the patient's past medical history.";
      
      const pid = rxData?.patientId;
      const tests = pid ? testReports[pid] || [] : [];
      const pastRxs = pid ? patientPrescriptions[pid] || [] : [];
      
      if (tests.length === 0 && pastRxs.length === 0) {
        toast.info("No past medical history found for this patient.");
        return;
      }

      actualSystemText = `Summarize this patient's medical history (Patient ID: ${pid}). 
      Past Prescriptions: ${JSON.stringify(pastRxs)}. 
      Past Test Reports: ${JSON.stringify(tests)}.
      Please provide a concise summary, highlighting chronic conditions, ongoing medications, and important notes. Output in Markdown format.`;
    }

    const userMsg: Message = { id: Date.now().toString(), role: "user", content: displayUserText };
    setMessages((prev) => [...prev, userMsg]);
    setInputValue("");
    setIsLoading(true);

    const botId = (Date.now() + 1).toString();
    setMessages((prev) => [...prev, { id: botId, role: "ai", content: "" }]);

    try {
      // Build dynamic context for EVERY prompt so the AI always knows the patient details
      const pid = rxData?.patientId;
      const currentTests = pid ? testReports[pid] || [] : [];
      const currentPastRxs = pid ? patientPrescriptions[pid] || [] : [];
      
      const dynamicContext = pid ? `\n\n--- CURRENT PATIENT CONTEXT ---\nPatient ID: ${pid}\nName: ${rxData?.patientName}\nChief Complaint: ${rxData?.chiefComplaint}\nDiagnosis: ${rxData?.diagnosis}\nPast Prescriptions: ${JSON.stringify(currentPastRxs)}\nPast Test Reports: ${JSON.stringify(currentTests)}\n---------------------------------` : '';

      const allMessages = [
        { role: "system", content: DOCTOR_SYSTEM_PROMPT + dynamicContext },
        ...messages.filter(m => m.content).map(m => ({
          role: m.role === "user" ? "user" : "assistant",
          content: m.content || "",
        })),
        { role: "user", content: actualSystemText },
      ];

      const response = await fetch("/api/ai/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: allMessages }),
      });

      if (!response.ok) throw new Error("AI request failed");

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      let fullContent = "";

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = decoder.decode(value, { stream: true });
          const lines = chunk.split("\n").filter(l => l.startsWith("data: "));

          for (const line of lines) {
            const data = line.slice(6);
            if (data === "[DONE]") continue;
            try {
              const parsed = JSON.parse(data);
              const content = parsed.content || parsed.choices?.[0]?.delta?.content || "";
              if (content) {
                fullContent += content;
                setMessages(prev =>
                  prev.map(m => m.id === botId ? { ...m, content: fullContent } : m)
                );
              }
            } catch {}
          }
        }
      }

      // Parse prescription draft (resilient regex)
      const prescMatch = fullContent.match(/```json[^\n]*\n?([\s\S]*?)```/);
      if (prescMatch) {
        try {
          const draft = JSON.parse(prescMatch[1].trim());
          setPrescriptionDraft(draft);
        } catch (err) {
          console.error("Failed to parse AI JSON:", err);
        }
      }
    } catch (error: any) {
      setMessages(prev =>
        prev.map(m =>
          m.id === botId
            ? { ...m, content: `⚠️ Error: ${error.message}\n\nPlease ensure your API Key is configured in .env.local` }
            : m
        )
      );
    } finally {
      setIsLoading(false);
    }
  };

  // Report upload handler
  const handleReportUpload = async (file: File) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: "user",
      content: `📎 Report uploaded: **${file.name}** - Analyze, identify issues, and suggest medicines.`,
    };
    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);

    const botId = (Date.now() + 1).toString();
    setMessages(prev => [...prev, { id: botId, role: "ai", content: "🔍 Analyzing report..." }]);

    try {
      const formData = new FormData();
      formData.append("image", file);

      const response = await fetch("/api/ai/analyze-report", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) throw new Error("Report analysis failed");

      const data = await response.json();
      const analysis = data.analysis || "Analysis could not be completed.";

      setMessages(prev =>
        prev.map(m => m.id === botId ? { ...m, content: analysis } : m)
      );

      // Check for prescription draft in report analysis
      const prescMatch = analysis.match(/```json[^\n]*\n?([\s\S]*?)```/);
      if (prescMatch) {
        try {
          setPrescriptionDraft(JSON.parse(prescMatch[1].trim()));
        } catch (err) {
          console.error("Failed to parse report AI JSON:", err);
        }
      }
    } catch (error: any) {
      setMessages(prev =>
        prev.map(m => m.id === botId ? { ...m, content: `⚠️ Report analysis error: ${error.message}` } : m)
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleAction = (action: string) => {
    if (action === "Apply to Prescription") {
      toast.success("Applied to prescription!");
    } else if (action === "Copy") {
      navigator.clipboard?.writeText(messages[messages.length - 1]?.content || "");
      toast.success("Copied to clipboard!");
    }
  };

  const handleApplyPrescription = () => {
    if (prescriptionDraft) {
      // Write directly into prescription editor fields
      const updates: Record<string, any> = {};

      if (prescriptionDraft.chiefComplaint) {
        updates.chiefComplaint = prescriptionDraft.chiefComplaint;
      }
      if (prescriptionDraft.diagnosis) {
        updates.diagnosis = prescriptionDraft.diagnosis;
      }
      if (prescriptionDraft.advice) {
        updates.advice = prescriptionDraft.advice;
      }
      if (prescriptionDraft.followUp) {
        updates.followUp = prescriptionDraft.followUp;
      }
      if (prescriptionDraft.investigations && prescriptionDraft.investigations.length > 0) {
        updates.investigations = prescriptionDraft.investigations.join(", ");
        updates.investigationsList = prescriptionDraft.investigations;
      }

      // Apply text fields
      if (Object.keys(updates).length > 0) {
        updateRx(updates);
      }

      // Add medicines one by one
      if (prescriptionDraft.medicines && prescriptionDraft.medicines.length > 0) {
        prescriptionDraft.medicines.forEach((med, idx) => {
          // Parse dosage like "1+0+1" into M/N/E
          const dosageParts = (med.dosage || "").split("+").map(s => s.trim());
          addMedicine({
            id: `ai-${Date.now()}-${idx}`,
            name: `${med.name} ${med.strength || ""}`.trim(),
            type: "Tab",
            dosageM: dosageParts[0] || "0",
            dosageN: dosageParts[1] || "0",
            dosageE: dosageParts[2] || "0",
            frequency: med.frequency || "",
            duration: med.duration || "",
            notes: `${med.generic || ""} - ${med.instructions || ""}`.trim(),
          });
        });
      }

      toast.success("Applied to prescription! You can now edit the fields.");
      setPrescriptionDraft(null);
    }
  };

  return (
    <div className="flex flex-col h-full bg-transparent rounded-[16px] xl:rounded-[24px] border border-[#E5E7EB] xl:border-none shadow-[0_4px_16px_rgba(15,23,42,0.08)] xl:shadow-none overflow-hidden relative">
      
      {/* Header */}
      <div className="bg-slate-900/80 backdrop-blur-xl border-b border-slate-800/50 px-5 py-3.5 flex items-center justify-between shrink-0 z-10">
        <div className="flex items-center gap-2.5">
          <div className="w-8 h-8 rounded-full bg-[#0a0a0a] overflow-hidden border border-slate-700/50 shadow-sm shrink-0">
            <img src="/dr-pekr.jpg" alt="Dr. pekr" className="w-full h-full object-contain p-0 scale-90" />
          </div>
          <div>
            <h3 className="font-bold text-[15px] text-slate-200 leading-tight">Dr. pekr</h3>
            <p className="text-[11px] font-semibold text-slate-500 flex items-center gap-1">
              <span className="w-1.5 h-1.5 rounded-full bg-[#6DDA6E] inline-block animate-pulse"></span>
              Doctor's Assistant
            </p>
          </div>
        </div>
        <button
          onClick={() => { setMessages([]); setPrescriptionDraft(null); }}
          className="w-7 h-7 rounded-lg bg-slate-800 hover:bg-slate-200 flex items-center justify-center text-slate-400 transition-colors"
          title="New conversation"
        >
          <RefreshCw size={14} />
        </button>
      </div>

      {/* Hidden file input */}
      <input
        type="file"
        ref={fileInputRef}
        className="hidden"
        accept="image/*,.pdf"
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) handleReportUpload(file);
          e.target.value = "";
        }}
      />

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar p-5 flex flex-col gap-4 bg-transparent min-h-0">
        {messages.length === 0 ? (
          /* Default State - Quick Actions */
          <div className="flex flex-col h-full mt-2">
            <h4 className="font-black text-slate-100 text-[18px] mb-1.5 px-1">How can I assist you?</h4>
            <p className="text-[13px] text-slate-400 mb-6 px-1">Select an action to get started.</p>
            
            <div className="flex flex-col gap-3 w-full">
              {defaultChips.map((chip, idx) => (
                <button
                  key={idx}
                  onClick={() => {
                    if (chip.prompt === "[SCAN_REPORT]") {
                      fileInputRef.current?.click();
                    } else {
                      handleSend(chip.prompt);
                    }
                  }}
                  className="flex items-center gap-4 bg-slate-900/60 backdrop-blur-md border border-slate-800/80 hover:border-slate-600 hover:bg-slate-800/80 shadow-sm transition-all px-4 py-4 rounded-[16px] w-full text-left group"
                >
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 transition-colors ${chip.bg} ${chip.color} group-hover:scale-110 duration-300`}>
                    <chip.icon size={18} strokeWidth={2.5} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <h5 className="font-bold text-slate-200 text-[14px] mb-0.5 group-hover:text-white transition-colors">{chip.label}</h5>
                    <p className="text-[12px] text-slate-500 truncate">{chip.desc}</p>
                  </div>
                </button>
              ))}
            </div>
          </div>
        ) : (
          /* Conversation */
          <>
            {messages.map((msg) => (
              <div key={msg.id} className={`flex flex-col ${msg.role === "user" ? "items-end" : "items-start"}`}>
                {msg.role === "user" ? (
                  <div className="bg-slate-700/80 border border-slate-600/50 text-slate-100 px-4 py-2.5 rounded-[16px] rounded-tr-[4px] max-w-[85%] text-[14px] shadow-sm whitespace-pre-wrap">
                    {msg.content?.split(/(\*\*.*?\*\*)/g).map((part, i) =>
                      part.startsWith("**") && part.endsWith("**") ? (
                        <strong key={i}>{part.slice(2, -2)}</strong>
                      ) : (
                        <span key={i}>{part}</span>
                      )
                    )}
                  </div>
                ) : (
                  <div className="w-full bg-slate-900 border border-slate-800 rounded-[14px] shadow-sm overflow-hidden">
                    {!msg.content && (
                      <div className="px-4 py-4 flex items-center gap-2 text-slate-400">
                        <div className="flex gap-1">
                          {[0, 1, 2].map(i => (
                            <span key={i} className="w-2 h-2 bg-blue-400 rounded-full animate-pulse" style={{ animationDelay: `${i * 200}ms` }} />
                          ))}
                        </div>
                        <span className="text-[13px]">Thinking...</span>
                      </div>
                    )}
                    {msg.content && (
                      <div className="px-4 py-3 border-b border-slate-100 last:border-0">
                        {(() => {
                          const structuredBlocks = parseStructuredBlocks(msg.content);
                          const cleanedText = cleanContent(msg.content);
                          return (
                            <div className="space-y-3">
                              {cleanedText && (
                                <div className="prose prose-slate max-w-none text-[14px] text-slate-300 leading-relaxed prose-p:mb-2 prose-headings:font-semibold prose-a:text-sky-400 hover:prose-a:underline prose-code:bg-slate-800 prose-code:px-1 prose-code:py-0.5 prose-code:rounded prose-pre:bg-slate-950 prose-pre:border prose-pre:border-slate-800 prose-pre:text-slate-200">
                                  <ReactMarkdown>{cleanedText}</ReactMarkdown>
                                </div>
                              )}
                              {structuredBlocks.map((block, idx) => (
                                <div key={idx} className="mt-2 w-full">
                                  {block.type === 'doctor_recommendation' && <DoctorRecommendationLoader data={block.data} />}
                                  {block.type === 'hospital_recommendation' && <HospitalRecommendationLoader data={block.data} />}
                                  {block.type === 'medicine_info' && <MedicineRecommendationLoader data={block.data} />}
                                  {block.type === 'emergency_alert' && <EmergencyAlert alert={block.data} />}
                                  {block.type === 'nutrition_analysis' && <NutritionCard data={block.data} />}
                                  {block.type === 'prescription_analysis' && <PrescriptionCard data={block.data} />}
                                  {block.type === 'report_analysis' && <ReportCard data={block.data} />}
                                </div>
                              ))}
                            </div>
                          );
                        })()}
                      </div>
                    )}
                  </div>
                )}
              </div>
            ))}

            {/* Prescription Draft Card */}
            {prescriptionDraft && (
              <div className="w-full bg-slate-900 border-2 border-blue-200 rounded-[14px] shadow-md overflow-hidden">
                <div className="   px-4 py-3 flex items-center justify-between">
                  <div className="flex items-center gap-2 text-white">
                    <Clipboard size={16} />
                    <span className="font-bold text-[14px]">Prescription Draft</span>
                  </div>
                </div>

                <div className="p-4 space-y-2.5 text-[13px]">
                  {prescriptionDraft.chiefComplaint && (
                    <div>
                      <p className="font-bold text-slate-400 text-[11px] uppercase tracking-wider">Chief Complaint</p>
                      <p className="text-slate-300 mt-0.5">{prescriptionDraft.chiefComplaint}</p>
                    </div>
                  )}
                  {prescriptionDraft.diagnosis && (
                    <div>
                      <p className="font-bold text-slate-400 text-[11px] uppercase tracking-wider">Diagnosis</p>
                      <p className="text-slate-200 font-semibold mt-0.5">{prescriptionDraft.diagnosis}</p>
                    </div>
                  )}
                  {prescriptionDraft.medicines && prescriptionDraft.medicines.length > 0 && (
                    <div>
                      <p className="font-bold text-slate-400 text-[11px] uppercase tracking-wider mb-1.5">Rx ({prescriptionDraft.medicines.length})</p>
                      {prescriptionDraft.medicines.map((med, i) => (
                        <div key={i} className="bg-slate-950 rounded-lg p-2 mb-1 border border-slate-100">
                          <p className="font-bold text-slate-200 text-[13px]">{med.name} <span className="font-normal text-slate-400">{med.strength}</span></p>
                          <p className="text-[11px] text-slate-400 italic">{med.generic}</p>
                          <p className="text-[12px] text-sky-400 mt-0.5">{med.dosage} • {med.frequency} • {med.duration} • {med.instructions}</p>
                        </div>
                      ))}
                    </div>
                  )}
                  {prescriptionDraft.investigations && prescriptionDraft.investigations.length > 0 && (
                    <div>
                      <p className="font-bold text-slate-400 text-[11px] uppercase tracking-wider">Investigations</p>
                      <p className="text-slate-300 mt-0.5">{prescriptionDraft.investigations.join(", ")}</p>
                    </div>
                  )}
                  {prescriptionDraft.advice && (
                    <div>
                      <p className="font-bold text-slate-400 text-[11px] uppercase tracking-wider">Advice</p>
                      <p className="text-slate-300 mt-0.5">{prescriptionDraft.advice}</p>
                    </div>
                  )}
                  {prescriptionDraft.followUp && (
                    <div>
                      <p className="font-bold text-slate-400 text-[11px] uppercase tracking-wider">Follow Up</p>
                      <p className="text-slate-300 mt-0.5">{prescriptionDraft.followUp}</p>
                    </div>
                  )}
                </div>

                <div className="px-4 pb-3 flex gap-2">
                  <button
                    onClick={handleApplyPrescription}
                    className="flex-1 h-[36px] bg-[#6DDA6E] text-white text-[12px] font-bold rounded-xl flex items-center justify-center gap-1.5 hover:bg-[#5bc95c] transition-colors shadow-md shadow-[#6DDA6E]/20"
                  >
                    <Check size={14} /> Apply to Prescription
                  </button>
                  <button
                    onClick={() => handleSend("Revise this prescription and suggest better medicines.")}
                    className="h-[36px] px-3 border border-slate-800 text-slate-400 text-[12px] font-bold rounded-xl hover:bg-slate-950 transition-colors flex items-center gap-1"
                  >
                    <RefreshCw size={12} /> Revise
                  </button>
                </div>
              </div>
            )}
          </>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 pb-8 xl:pb-4 bg-slate-900 border-t border-slate-800 mt-auto shrink-0 z-10 sticky bottom-0" style={{ paddingBottom: 'max(env(safe-area-inset-bottom), 1rem)' }}>
        {/* Quick re-access buttons */}
        {messages.length > 0 && (
          <div className="flex gap-1.5 mb-2 overflow-x-auto pb-1 scrollbar-none">
            <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-1 bg-sky-900/30 text-sky-400 text-[11px] font-bold px-2.5 py-1 rounded-lg shrink-0 hover:bg-sky-900/50 transition-colors">
              <Camera size={12} /> Scan Report
            </button>
            <button onClick={() => setInputValue("Write a prescription for: ")} className="flex items-center gap-1 bg-sky-900/30 text-sky-400 text-[11px] font-bold px-2.5 py-1 rounded-lg shrink-0 hover:bg-sky-900/50 transition-colors">
              <ClipboardList size={12} /> Prescription
            </button>
            <button onClick={() => setInputValue("Check drug interactions for: ")} className="flex items-center gap-1 bg-red-900/30 text-red-400 text-[11px] font-bold px-2.5 py-1 rounded-lg shrink-0 hover:bg-red-900/50 transition-colors">
              <AlertCircle size={12} /> Interactions
            </button>
            <button onClick={() => setInputValue("Suggest medicines for: ")} className="flex items-center gap-1 bg-emerald-900/30 text-emerald-400 text-[11px] font-bold px-2.5 py-1 rounded-lg shrink-0 hover:bg-emerald-900/50 transition-colors">
              <Pill size={12} /> Medicines
            </button>
          </div>
        )}

        <div className="relative flex items-center">
          {isVoiceSupported && (
            <button 
              onClick={toggleVoice}
              className={`absolute left-2 w-9 h-9 flex items-center justify-center rounded-full transition-all z-10 ${
                isListening 
                  ? "bg-rose-500 text-white shadow-[0_0_12px_rgba(239,68,68,0.4)] animate-pulse" 
                  : "text-slate-400 hover:text-sky-400 hover:bg-sky-900/20"
              }`}
            >
              {isListening ? <MicOff size={18} /> : <Mic size={18} />}
            </button>
          )}
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSend(inputValue)}
            placeholder="Ask Dr. pekr (e.g. Write prescription...)"
            className={`w-full h-[48px] bg-slate-950/50 hover:bg-slate-950 focus:bg-slate-900 border border-slate-800/60 rounded-full py-2 ${isVoiceSupported ? 'pl-12' : 'pl-5'} pr-14 text-[14px] text-slate-200 focus:outline-none focus:border-blue-400 focus:ring-4 focus:ring-blue-400/10 transition-all placeholder:text-slate-400 font-medium shadow-sm`}
          />
          <button 
            onClick={() => handleSend(inputValue)}
            disabled={!inputValue.trim() || isLoading}
            className="absolute right-1.5 bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-400 hover:to-blue-500 active:scale-95 disabled:opacity-50 text-white w-8 h-8 rounded-full flex items-center justify-center transition-all shadow-md z-10"
          >
            <ArrowUp size={18} strokeWidth={2.5} />
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { Plus, Search, Trash2, GripVertical, Info, Mic, Bot, ChevronDown, Check } from "lucide-react";
import { usePrescription } from "@/context/PrescriptionContext";


const CustomSelect = ({ value, onChange, options, colorClass }: { value: string, onChange: (v: string) => void, options: string[], colorClass: string }) => {
  const [isOpen, setIsOpen] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);
  
  React.useEffect(() => {
    const handleClickOutside = (event: any) => {
      if (ref.current && !ref.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="relative transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] w-full" ref={ref}>
      <div 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-full h-[32px] md:h-8 pl-2 pr-2 bg-slate-950 border border-slate-800 rounded-[6px] text-[12px] font-bold text-slate-300 cursor-pointer transition-all shadow-sm flex items-center justify-between group hover:border-${colorClass}-500/50`}
      >
        <span className="truncate">{value}</span>
        <ChevronDown size={14} className={`text-${colorClass}-500 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 mt-1 w-[140px] max-h-[200px] overflow-y-auto bg-slate-800 border border-slate-700 rounded-lg shadow-2xl z-50 py-1">
          {options.map(opt => (
            <div 
              key={opt} 
              onClick={() => { onChange(opt); setIsOpen(false); }}
              className={`px-3 py-2 text-[12px] font-bold cursor-pointer hover:bg-slate-700 transition-colors ${value === opt ? 'text-sky-400 bg-slate-700/50' : 'text-slate-300'}`}
            >
              {opt}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};


const MedicineAutocomplete = ({ value, onChange, onSelect }: { value: string, onChange: (v: string) => void, onSelect: (name: string, type: string) => void }) => {
  const [suggestions, setSuggestions] = useState<any[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const ref = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const handleClickOutside = (event: any) => {
      if (ref.current && !ref.current.contains(event.target)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  React.useEffect(() => {
    if (!value.trim() || !showSuggestions) {
      setSuggestions([]);
      return;
    }
    
    const fetchSuggestions = async () => {
      try {
        const res = await fetch(`/api/medicines/search?q=${encodeURIComponent(value)}`);
        if (res.ok) {
          const data = await res.json();
          setSuggestions(data.slice(0, 8));
        }
      } catch (err) {
        console.error("Failed to fetch medicines", err);
      }
    };

    const timer = setTimeout(fetchSuggestions, 200);
    return () => clearTimeout(timer);
  }, [value, showSuggestions]);

  const handleSelect = (med: any) => {
    const fullName = `${med.brandName} ${med.strength}`;
    onSelect(fullName, med.dosageForm || "Tablet");
    setShowSuggestions(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!showSuggestions || suggestions.length === 0) return;
    
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlightedIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlightedIndex(prev => (prev > 0 ? prev - 1 : -1));
    } else if (e.key === 'Enter' || e.key === 'Tab') {
      if (highlightedIndex >= 0 && highlightedIndex < suggestions.length) {
        e.preventDefault();
        handleSelect(suggestions[highlightedIndex]);
      } else if (suggestions.length > 0) {
        e.preventDefault();
        handleSelect(suggestions[0]);
      }
    }
  };

  return (
    <div className="relative" ref={ref}>
      <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
      <input 
        type="text" 
        value={value} 
        onChange={(e) => {
          onChange(e.target.value);
          setShowSuggestions(true);
          setHighlightedIndex(-1);
        }}
        onFocus={() => setShowSuggestions(true)}
        onKeyDown={handleKeyDown}
        placeholder="Search medicine..."
        className="w-full h-[36px] md:h-8 pl-8 pr-3 bg-slate-950 border border-slate-800 rounded-[8px] text-[14px] md:text-[13px] font-semibold text-slate-200 focus:outline-none focus:border-sky-500 transition-colors"
        autoComplete="off"
      />
      {showSuggestions && suggestions.length > 0 && (
        <div className="absolute top-full left-0 right-0 mt-1 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl z-50 overflow-hidden max-h-[250px] overflow-y-auto custom-scrollbar">
          {suggestions.map((smed, idx) => (
            <div 
              key={idx}
              onMouseDown={(e) => {
                e.preventDefault(); // Prevent input from losing focus
                handleSelect(smed);
              }}
              className={`px-3 py-2.5 border-b border-slate-800 last:border-0 cursor-pointer flex flex-col gap-0.5 transition-colors ${highlightedIndex === idx ? 'bg-slate-800' : 'hover:bg-slate-800/80'}`}
            >
              <div className="flex items-center justify-between">
                <span className="font-bold text-slate-200 text-[13px]">{smed.brandName} <span className="text-slate-400 font-normal">{smed.strength}</span></span>
                <span className="text-[10px] font-semibold text-sky-400 bg-sky-900/30 px-1.5 py-0.5 rounded-md">{smed.dosageForm}</span>
              </div>
              <span className="text-[11px] text-slate-500 italic truncate">{smed.genericName}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export function MedicineBuilder() {
  const { data, updateData } = usePrescription();
  const medicines = data.medicines;
  
  const setMedicines = (newMedicines: typeof data.medicines) => {
    updateData({ medicines: newMedicines });
  };

  const [searchInput, setSearchInput] = useState("");
  const [suggestions, setSuggestions] = useState<any[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [isSearching, setIsSearching] = useState(false);
  
  React.useEffect(() => {
    if (!searchInput.trim()) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }
    
    const fetchSuggestions = async () => {
      setIsSearching(true);
      try {
        const res = await fetch(`/api/medicines/search?q=${encodeURIComponent(searchInput)}`);
        if (res.ok) {
          const data = await res.json();
          setSuggestions(data.slice(0, 5)); // Limit to 5
          setShowSuggestions(true);
        }
      } catch (err) {
        console.error("Failed to fetch medicines", err);
      } finally {
        setIsSearching(false);
      }
    };

    const timer = setTimeout(fetchSuggestions, 300); // debounce
    return () => clearTimeout(timer);
  }, [searchInput]);
  
  const addMedicineFromSuggestion = (med: any) => {
    setMedicines([...medicines, { 
      id: Date.now(), 
      name: `${med.brandName} ${med.strength}`, 
      type: med.dosageForm || "Tablet", 
      dosageM: "0", dosageN: "0", dosageE: "0", 
      frequency: "Daily", 
      duration: "5 Days", 
      notes: "After meal" 
    }]);
    setSearchInput("");
    setShowSuggestions(false);
  };


  const addEmptyMedicine = () => {
    setMedicines([...medicines, { 
      id: Date.now(), 
      name: "", 
      type: "Tablet", 
      dosageM: "0", dosageN: "0", dosageE: "0", 
      frequency: "Daily", 
      duration: "5 Days", 
      notes: "After meal" 
    }]);
  };

  const addAISuggestion = () => {
    setMedicines([...medicines, { 
      id: Date.now(), 
      name: "Cap. Seclo 20mg", 
      type: "Capsule", 
      dosageM: "1", dosageN: "0", dosageE: "1", 
      frequency: "Daily", 
      duration: "14 Days", 
      notes: "Before meal" 
    }]);
  };

  const removeMedicine = (id: number | string) => {
    setMedicines(medicines.filter(m => m.id !== id));
  };

  const updateMedicine = (id: number | string, field: string, value: string) => {
    setMedicines(medicines.map(m => m.id === id ? { ...m, [field]: value } : m));
  };

  const updateMedicineFields = (id: number | string, updates: Record<string, string>) => {
    setMedicines(medicines.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handleSearchEnter = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && searchInput.trim() !== '') {
      setMedicines([...medicines, { 
        id: Date.now(), 
        name: searchInput, 
        type: "Tablet", 
        dosageM: "0", dosageN: "0", dosageE: "0", 
        frequency: "Daily", 
        duration: "5 Days", 
        notes: "After meal" 
      }]);
      setSearchInput("");
    }
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Medicine Toolbar */}
      <div className="bg-slate-900 border border-slate-800 rounded-[14px] p-2 sm:px-4 sm:py-2.5 flex items-center justify-between shadow-sm">
        <h3 className="font-bold text-[15px] sm:text-[16px] text-slate-100 px-2 sm:px-0">Rx Medicines</h3>
        <div className="flex items-center gap-2 sm:gap-3">
          <button 
            title="Voice Input"
            className="flex items-center justify-center gap-1.5 text-[13px] font-semibold text-slate-400 hover:text-slate-200 bg-slate-800 sm:bg-transparent hover:bg-slate-700 sm:hover:bg-transparent w-[36px] h-[36px] sm:w-auto sm:h-auto rounded-[10px] transition-all active:scale-95"
          >
            <Mic size={18} className="sm:w-4 sm:h-4" /> 
            <span className="hidden sm:inline">Voice Input</span>
          </button>
          
          <button 
            title="AI Suggestion"
            onClick={addAISuggestion} 
            className="flex items-center justify-center gap-1.5 text-[13px] font-semibold text-purple-400 hover:text-purple-300 bg-purple-900/30 sm:bg-transparent hover:bg-purple-800/40 sm:hover:bg-transparent w-[36px] h-[36px] sm:w-auto sm:h-auto rounded-[10px] transition-all active:scale-95"
          >
            <Bot size={18} className="sm:w-4 sm:h-4" /> 
            <span className="hidden sm:inline">AI Suggestion</span>
          </button>
          
          <button 
            title="Add Medicine"
            onClick={addEmptyMedicine} 
            className="flex items-center justify-center gap-1.5 text-[13px] font-bold bg-gradient-to-r from-emerald-400 to-emerald-500 hover:from-emerald-300 hover:to-emerald-400 text-slate-950 shadow-md shadow-emerald-500/20 font-bold  w-[36px] h-[36px] sm:w-auto sm:px-4 rounded-[10px] transition-all shadow-sm active:scale-95"
          >
            <Plus size={20} className="sm:w-4 sm:h-4" /> 
            <span className="hidden sm:inline">Add Medicine</span>
          </button>
        </div>
      </div>

      {/* Medicine List */}
      <div className="flex flex-col gap-3">
        {medicines.map((med) => (
          <div key={med.id} className="relative bg-slate-900 border border-slate-800 hover:border-slate-700 rounded-[14px] p-4 md:p-3 shadow-sm transition-all group flex flex-col md:flex-row md:items-start gap-4 md:gap-3">
            {/* Grip (Desktop only) */}
            <button className="hidden md:block mt-[22px] text-slate-500 hover:text-slate-300 cursor-grab active:cursor-grabbing shrink-0">
              <GripVertical size={18} />
            </button>
            
            {/* Medicine Name */}
            <div className="w-full md:w-[280px] pr-8 md:pr-0 shrink-0">
              <label className="text-[9px] font-bold uppercase text-slate-400 tracking-wider mb-1 block">Medicine Name</label>
              <MedicineAutocomplete 
                value={med.name} 
                onChange={(val) => updateMedicine(med.id, 'name', val)}
                onSelect={(name, type) => updateMedicineFields(med.id, { name, type })}
              />
            </div>

            {/* Dosage + Frequency + Duration */}
            <div className="grid grid-cols-2 md:flex md:flex-nowrap gap-2.5 md:gap-3 flex-1 items-start w-full mt-1 md:mt-0">
              
              <div className="col-span-2 sm:col-span-1 md:w-[120px] md:flex-none">
                <label className="text-[9px] font-bold uppercase text-sky-400 tracking-wider mb-1 block text-left">Dosage (M-N-E)</label>
                <div className="flex items-center gap-1 text-sky-400/40 text-sm font-bold w-full">
                  <button 
                    onClick={() => updateMedicine(med.id, 'dosageM', med.dosageM === '0' ? '1' : '0')}
                    className={`flex-1 md:w-8 h-[32px] md:h-8 rounded-[6px] text-[13px] font-bold text-center transition-all duration-200 hover:scale-[1.05] active:scale-[0.95] focus:outline-none border ${med.dosageM === '0' ? 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-800 hover:text-slate-300' : 'bg-sky-600 border-sky-600 text-white shadow-sm shadow-sky-600/30'}`}
                  >
                    {med.dosageM || '0'}
                  </button>
                  <span>+</span>
                  <button 
                    onClick={() => updateMedicine(med.id, 'dosageN', med.dosageN === '0' ? '1' : '0')}
                    className={`flex-1 md:w-8 h-[32px] md:h-8 rounded-[6px] text-[13px] font-bold text-center transition-all duration-200 hover:scale-[1.05] active:scale-[0.95] focus:outline-none border ${med.dosageN === '0' ? 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-800 hover:text-slate-300' : 'bg-sky-600 border-sky-600 text-white shadow-sm shadow-sky-600/30'}`}
                  >
                    {med.dosageN || '0'}
                  </button>
                  <span>+</span>
                  <button 
                    onClick={() => updateMedicine(med.id, 'dosageE', med.dosageE === '0' ? '1' : '0')}
                    className={`flex-1 md:w-8 h-[32px] md:h-8 rounded-[6px] text-[13px] font-bold text-center transition-all duration-200 hover:scale-[1.05] active:scale-[0.95] focus:outline-none border ${med.dosageE === '0' ? 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-800 hover:text-slate-300' : 'bg-sky-600 border-sky-600 text-white shadow-sm shadow-sky-600/30'}`}
                  >
                    {med.dosageE || '0'}
                  </button>
                </div>
              </div>

              <div className="col-span-1 md:w-[100px] md:flex-none">
                <label className="text-[9px] font-bold uppercase text-fuchsia-400 tracking-wider mb-1 block">Frequency</label>
                <div className="relative transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]">
                  <select 
                    value={med.frequency} onChange={(e) => updateMedicine(med.id, 'frequency', e.target.value)} 
                    className="w-full h-[32px] md:h-8 pl-2 pr-5 bg-fuchsia-900/20 border border-fuchsia-500/30 rounded-[6px] text-[12px] font-bold text-slate-300 focus:outline-none focus:border-fuchsia-500 focus:ring-1 focus:ring-fuchsia-500/50 appearance-none cursor-pointer transition-all truncate shadow-sm"
                  >
                    <option className="bg-slate-900 text-slate-200">Daily</option>
                    <option className="bg-slate-900 text-slate-200">Twice a day</option>
                    <option className="bg-slate-900 text-slate-200">Thrice a day</option>
                    <option className="bg-slate-900 text-slate-200">4 times a day</option>
                    <option className="bg-slate-900 text-slate-200">Alternate days</option>
                    <option className="bg-slate-900 text-slate-200">Weekly</option>
                    <option className="bg-slate-900 text-slate-200">SOS (As needed)</option>
                  </select>
                  <ChevronDown size={14} className="absolute right-1.5 top-1/2 -translate-y-1/2 text-fuchsia-500 pointer-events-none transition-transform" />
                </div>
              </div>

              <div className="col-span-1 md:w-[90px] md:flex-none">
                <label className="text-[9px] font-bold uppercase text-amber-400 tracking-wider mb-1 block">Duration</label>
                <div className="relative transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]">
                  <select 
                    value={med.duration} onChange={(e) => updateMedicine(med.id, 'duration', e.target.value)} 
                    className="w-full h-[32px] md:h-8 pl-2 pr-5 bg-amber-900/20 border border-amber-500/30 rounded-[6px] text-[12px] font-bold text-slate-300 focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500/50 appearance-none cursor-pointer transition-all truncate shadow-sm"
                  >
                    <option className="bg-slate-900 text-slate-200">1 Day</option>
                    <option className="bg-slate-900 text-slate-200">2 Days</option>
                    <option className="bg-slate-900 text-slate-200">3 Days</option>
                    <option className="bg-slate-900 text-slate-200">5 Days</option>
                    <option className="bg-slate-900 text-slate-200">7 Days</option>
                    <option className="bg-slate-900 text-slate-200">10 Days</option>
                    <option className="bg-slate-900 text-slate-200">14 Days</option>
                    <option className="bg-slate-900 text-slate-200">1 Month</option>
                    <option className="bg-slate-900 text-slate-200">2 Months</option>
                    <option className="bg-slate-900 text-slate-200">3 Months</option>
                    <option className="bg-slate-900 text-slate-200">Continue</option>
                  </select>
                  <ChevronDown size={14} className="absolute right-1.5 top-1/2 -translate-y-1/2 text-amber-500 pointer-events-none transition-transform" />
                </div>
              </div>
              
              <div className="col-span-1 md:w-[130px] md:flex-none">
                <label className="text-[9px] font-bold uppercase text-teal-400 tracking-wider mb-1 block">Instructions</label>
                <div className="relative transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]">
                  <select 
                    value={med.notes} onChange={(e) => updateMedicine(med.id, 'notes', e.target.value)} 
                    className="w-full h-[32px] md:h-8 pl-2 pr-5 bg-teal-900/20 border border-teal-500/30 rounded-[6px] text-[12px] font-bold text-slate-300 focus:outline-none focus:border-teal-500 focus:ring-1 focus:ring-teal-500/50 appearance-none cursor-pointer transition-all truncate shadow-sm"
                  >
                    <option className="bg-slate-900 text-slate-200">After meal</option>
                    <option className="bg-slate-900 text-slate-200">Before meal</option>
                    <option className="bg-slate-900 text-slate-200">With meal</option>
                    <option className="bg-slate-900 text-slate-200">Empty stomach</option>
                    <option className="bg-slate-900 text-slate-200">At bedtime</option>
                  </select>
                  <ChevronDown size={14} className="absolute right-1.5 top-1/2 -translate-y-1/2 text-teal-500 pointer-events-none transition-transform" />
                </div>
              </div>

            </div>

            {/* Remove button (absolute top right on mobile, inline on desktop) */}
            <button onClick={() => removeMedicine(med.id)} className="absolute top-4 right-4 md:static md:mt-4 md:w-[40px] md:h-[32px] shrink-0 text-slate-400 hover:text-red-500 transition-colors rounded-[8px] hover:bg-red-900/30 flex items-center justify-center p-1 md:p-0">
              <Trash2 size={16} />
            </button>
          </div>
        ))}
      </div>

      {/* Add New Empty State Input */}
      <div className="relative mt-2">
        <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
        <input 
          type="text"
          value={searchInput}
          onChange={(e) => setSearchInput(e.target.value)}
          onKeyDown={handleSearchEnter}
          onFocus={() => { if (suggestions.length > 0) setShowSuggestions(true); }}
          onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
          placeholder="Search and add another medicine... (Press Enter)"
          className="w-full h-[48px] pl-10 pr-4 bg-slate-950 border border-slate-800 hover:border-slate-700 focus:border-sky-500 focus:bg-slate-900 focus:ring-2 focus:ring-sky-500/20 rounded-[12px] text-[14px] text-slate-300 outline-none transition-colors"
        />
        
        {/* Autocomplete Dropdown */}
        {showSuggestions && suggestions.length > 0 && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl z-50 overflow-hidden">
            {suggestions.map((med, idx) => (
              <div 
                key={idx}
                onMouseDown={(e) => {
                  e.preventDefault();
                  addMedicineFromSuggestion(med);
                }}
                className="px-4 py-3 border-b border-slate-800 last:border-0 hover:bg-slate-800 cursor-pointer flex flex-col gap-0.5 transition-colors"
              >
                <div className="flex items-center justify-between">
                  <span className="font-bold text-slate-200 text-[14px]">{med.brandName} <span className="text-slate-400 font-normal">{med.strength}</span></span>
                  <span className="text-[11px] font-semibold text-sky-400 bg-sky-900/30 px-2 py-0.5 rounded-full">{med.dosageForm}</span>
                </div>
                <span className="text-[12px] text-slate-500 italic">{med.genericName}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { User, Activity, Clock, FileText, Pill, AlertTriangle, X, Eye, Bot, Loader2 } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast } from "sonner";
import { useDoctor } from "@/context/DoctorContext";

