"use client";

import React, { useState, useEffect } from "react";
import { MedicineBuilder } from "./MedicineBuilder";
import { PatientContextSidebar } from "./PatientContextSidebar";
import { usePrescription } from "@/context/PrescriptionContext";
import { Plus, X, Loader2 } from "lucide-react";

interface SmartEditorAreaProps {
  onFinalize: () => void;
}

export function SmartEditorArea({ onFinalize }: SmartEditorAreaProps) {
  const { data, updateData, updateVitals } = usePrescription();
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 800);
    return () => clearTimeout(timer);
  }, []);

  const appendToState = (field: keyof typeof data, newText: string) => {
    const currentVal = data[field] as string;
    updateData({ [field]: currentVal ? `${currentVal}, ${newText}` : newText });
  };

  const [customTest, setCustomTest] = useState("");

  const handleAddInvestigation = (test: string) => {
    const trimmed = test.trim();
    if (trimmed && !data.investigationsList?.includes(trimmed)) {
      updateData({ investigationsList: [...(data.investigationsList || []), trimmed] });
    }
    setCustomTest("");
  };

  const handleRemoveInvestigation = (test: string) => {
    updateData({ investigationsList: (data.investigationsList || []).filter(t => t !== test) });
  };

  return (
    <div className="flex flex-col h-auto xl:h-full bg-slate-950 relative">
      <div className="flex-1 overflow-visible xl:overflow-y-auto custom-scrollbar p-5 lg:p-6">
        
        {isLoading ? (          <div className="w-full flex flex-col gap-5 animate-in fade-in duration-500">
            {/* Patient Info Header Skeleton */}
            <div className="w-full h-[140px] bg-slate-950 border border-slate-800 rounded-[12px] shadow-sm animate-pulse p-4 flex flex-col gap-4">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-slate-700 rounded-full shrink-0" />
                <div className="flex-1 space-y-2">
                  <div className="w-1/3 h-5 bg-slate-700 rounded-md" />
                  <div className="w-1/4 h-4 bg-slate-800 rounded-md" />
                </div>
              </div>
              <div className="flex gap-2">
                <div className="w-20 h-6 bg-slate-700 rounded-md" />
                <div className="w-24 h-6 bg-slate-700 rounded-md" />
              </div>
            </div>

            {/* Text Area Skeleton 1 */}
            <div className="w-full min-h-[100px] p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-3 animate-pulse">
              <div className="w-40 h-5 bg-slate-800 rounded-md" />
              <div className="w-full h-4 bg-slate-950 rounded-md mt-2" />
              <div className="w-3/4 h-4 bg-slate-950 rounded-md" />
            </div>

            {/* Text Area Skeleton 2 */}
            <div className="w-full min-h-[120px] p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-3 animate-pulse">
              <div className="w-36 h-5 bg-slate-800 rounded-md" />
              <div className="w-full h-4 bg-slate-950 rounded-md mt-2" />
              <div className="w-full h-4 bg-slate-950 rounded-md" />
              <div className="w-1/2 h-4 bg-slate-950 rounded-md" />
            </div>

            {/* Vitals Grid Skeleton */}
            <div className="w-full p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-4 animate-pulse">
              <div className="w-32 h-5 bg-slate-800 rounded-md" />
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
                  <div key={i} className="bg-slate-950 border border-slate-800 rounded-[10px] p-3 flex flex-col gap-2 h-[72px]">
                    <div className="w-16 h-3 bg-slate-700 rounded-md" />
                    <div className="w-12 h-5 bg-slate-700 rounded-md" />
                  </div>
                ))}
              </div>
            </div>
            
            {/* Meds Skeleton */}
            <div className="w-full min-h-[160px] p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-3 animate-pulse">
              <div className="w-32 h-5 bg-slate-800 rounded-md" />
              <div className="w-full h-12 bg-slate-950 rounded-lg mt-2" />
              <div className="w-full h-12 bg-slate-950 rounded-lg" />
            </div>
          </div>        ) : (
          <div className="w-full flex flex-col gap-5 animate-in fade-in duration-500">
          
          {/* Patient Info Header */}
          <PatientContextSidebar isDesktop={false} />

          {/* Section 1: CHIEF COMPLAINT */}
          <div className="w-full min-h-[100px] p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-2 group transition-colors hover:border-slate-700">
            <h3 className="text-[16px] font-semibold text-slate-100">CHIEF COMPLAINT</h3>
            <textarea 
              value={data.chiefComplaint}
              onChange={(e) => updateData({ chiefComplaint: e.target.value })}
              placeholder="Describe the patient's primary complaints..."
              className="w-full bg-transparent text-slate-200 text-[15px] leading-[1.6] placeholder:text-slate-500/70 resize-none outline-none focus:ring-0 flex-1"
            />
          </div>

          {/* Section 2: PHYSICAL EXAM */}
          <div className="w-full min-h-[120px] p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-2 group transition-colors hover:border-slate-700">
            <h3 className="text-[16px] font-semibold text-slate-100">PHYSICAL EXAM</h3>
            <textarea 
              value={data.physicalExam}
              onChange={(e) => updateData({ physicalExam: e.target.value })}
              placeholder="Document physical examination findings..."
              className="w-full bg-transparent text-slate-200 text-[15px] leading-[1.6] placeholder:text-slate-500/70 resize-none outline-none focus:ring-0 flex-1"
            />
          </div>

          {/* Section 3: VITALS TODAY */}
          <div className="w-full p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-3 transition-colors hover:border-slate-700">
            <h3 className="text-[16px] font-semibold text-slate-100">VITALS TODAY</h3>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
              {[
                { label: "Blood Pressure", unit: "mmHg", placeholder: "120/80", field: "bp", border: "bg-rose-500", text: "text-rose-400" },
                { label: "Pulse", unit: "bpm", placeholder: "72", field: "pulse", border: "bg-orange-500", text: "text-orange-400" },
                { label: "Temperature", unit: "°F", placeholder: "98.6", field: "temp", border: "bg-amber-500", text: "text-amber-400" },
                { label: "Weight", unit: "kg", placeholder: "70", field: "weight", border: "bg-blue-500", text: "text-blue-400" },
                { label: "Height", unit: "cm", placeholder: "170", field: "height", border: "bg-sky-500", text: "text-sky-400" },
                { label: "BMI", unit: "kg/m²", placeholder: "24.2", field: "bmi", border: "bg-indigo-500", text: "text-indigo-400" },
                { label: "SpO₂", unit: "%", placeholder: "98", field: "spo2", border: "bg-cyan-500", text: "text-cyan-400" },
                { label: "Blood Sugar", unit: "mg/dL", placeholder: "110", field: "bloodSugar", border: "bg-fuchsia-500", text: "text-fuchsia-400" },
              ].map((vital, idx) => (
                <div key={idx} className="bg-slate-900 border border-slate-800 rounded-[10px] p-2.5 flex flex-col justify-center h-[72px] transition-colors hover:border-slate-700 relative overflow-hidden group">
                  <div className={`absolute left-0 top-0 bottom-0 w-1 ${vital.border} opacity-80 group-hover:opacity-100 transition-opacity`} />
                  <span className={`text-[11px] font-bold mb-0.5 uppercase tracking-wider pl-1.5 ${vital.text}`}>{vital.label}</span>
                  <div className="flex items-center gap-1 pl-1.5 z-10">
                    <input 
                      type="text" 
                      value={data.vitals[vital.field as keyof typeof data.vitals]}
                      onChange={(e) => updateVitals({ [vital.field]: e.target.value })}
                      placeholder={vital.placeholder}
                      className="bg-transparent border-none outline-none text-[16px] font-bold text-slate-100 w-full p-0 focus:ring-0 placeholder:text-slate-500"
                    />
                    <span className="text-[11px] text-slate-500 font-bold">{vital.unit}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Section 4: DIAGNOSIS */}
          <div className="w-full min-h-[100px] p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-2 group transition-colors hover:border-slate-700">
            <h3 className="text-[16px] font-semibold text-slate-100">DIAGNOSIS</h3>
            <textarea 
              value={data.diagnosis}
              onChange={(e) => updateData({ diagnosis: e.target.value })}
              placeholder="Enter diagnosis..."
              className="w-full bg-transparent text-slate-200 text-[15px] leading-[1.6] placeholder:text-slate-500/70 resize-none outline-none focus:ring-0 flex-1"
            />
          </div>

          {/* Section 5: INVESTIGATIONS (RX) */}
          <div className="w-full p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-4 transition-colors hover:border-slate-700">
            <h3 className="text-[16px] font-semibold text-slate-100">INVESTIGATIONS (TESTS)</h3>
            
            {/* Added Tests List */}
            {data.investigationsList && data.investigationsList.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {data.investigationsList.map((test, idx) => (
                  <div key={idx} className="flex items-center gap-1.5 px-3 py-1.5 bg-sky-900/30 border border-sky-500/20 text-sky-400 text-[13px] font-bold rounded-lg shadow-sm">
                    <span className="opacity-50 mr-1 text-[11px]">{idx + 1}.</span> {test}
                    <button onClick={() => handleRemoveInvestigation(test)} className="ml-1 p-0.5 hover:bg-sky-600/20 rounded-full transition-colors">
                      <X size={14} />
                    </button>
                  </div>
                ))}
              </div>
            )}

            {/* Custom Test Input */}
            <div className="flex gap-2">
              <input 
                type="text"
                value={customTest}
                onChange={(e) => setCustomTest(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    handleAddInvestigation(customTest);
                  }
                }}
                placeholder="Type a custom test and press Enter..."
                className="flex-1 bg-slate-950 border border-slate-800 rounded-[8px] px-3 py-2 text-[14px] text-slate-200 outline-none focus:border-sky-500 focus:ring-1 focus:ring-sky-500/20 transition-all"
              />
              <button 
                onClick={() => handleAddInvestigation(customTest)}
                disabled={!customTest.trim()}
                className="px-4 bg-sky-600 text-white font-bold text-[13px] rounded-[8px] hover:bg-sky-500 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Add
              </button>
            </div>

            {/* Quick Add Chips */}
            <div className="flex flex-wrap gap-2 pt-2 border-t border-slate-800">
              {["CBC", "Blood Sugar (F)", "Blood Sugar (R)", "Lipid Profile", "ECG", "Chest X-Ray", "Urine RME", "Serum Creatinine"].map((chip, idx) => (
                <button 
                  key={idx} 
                  onClick={() => handleAddInvestigation(chip)}
                  disabled={data.investigationsList?.includes(chip)}
                  className="h-[32px] px-3 bg-slate-950 border border-slate-800 rounded-[8px] text-[12px] font-semibold text-slate-500 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center active:scale-95"
                >
                  + {chip}
                </button>
              ))}
            </div>
          </div>

          {/* Section 6: Rx Medicines */}
          <MedicineBuilder />

          {/* Section 7: ADVICE & DIET */}
          <div className="w-full min-h-[120px] p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-3 group transition-colors hover:border-slate-700">
            <h3 className="text-[16px] font-semibold text-slate-100">ADVICE & DIET</h3>
            <textarea 
              value={data.advice}
              onChange={(e) => updateData({ advice: e.target.value })}
              placeholder="Type advice..."
              className="w-full bg-transparent text-slate-200 text-[15px] leading-[1.6] placeholder:text-slate-500/70 resize-none outline-none focus:ring-0 h-[60px]"
            />
            <div className="flex flex-wrap gap-2 mt-1">
              {["Drink Water", "Exercise", "Reduce Salt", "Avoid Smoking", "Diabetic Diet", "Low Fat Diet"].map((chip, idx) => (
                <button 
                  key={idx} 
                  onClick={() => appendToState("advice", chip)}
                  className="px-3 py-1.5 bg-slate-950 text-slate-500 text-[13px] rounded-lg border border-slate-800 hover:bg-slate-800 transition-colors flex items-center gap-1.5"
                >
                  <Plus size={12} className="text-slate-500" />
                  {chip}
                </button>
              ))}
            </div>
          </div>

          {/* Section 8: FOLLOW-UP */}
          <div className="w-full p-4 bg-slate-900 border border-slate-800 rounded-[12px] shadow-sm flex flex-col gap-3 transition-colors hover:border-slate-700">
            <h3 className="text-[16px] font-semibold text-slate-100">FOLLOW-UP</h3>
            <textarea 
              value={data.followUp}
              onChange={(e) => updateData({ followUp: e.target.value })}
              placeholder="Next visit instructions..."
              className="w-full bg-transparent text-slate-200 text-[15px] leading-[1.6] placeholder:text-slate-500/70 resize-none outline-none focus:ring-0 h-[40px]"
            />
            <div className="flex flex-wrap gap-2 mt-1">
              {["3 Days", "7 Days", "14 Days", "1 Month", "3 Months"].map((chip, idx) => (
                <button 
                  key={idx} 
                  onClick={() => appendToState("followUp", chip)}
                  className="px-3 py-1.5 bg-slate-950 border border-slate-800 rounded-[8px] text-[12px] font-medium text-slate-500 hover:bg-sky-600 hover:text-white hover:border-sky-500 transition-colors active:scale-95"
                >
                  + {chip}
                </button>
              ))}
            </div>
          </div>

        </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { FileText, Download, Eye, ShieldCheck, Activity, ChevronLeft, ChevronRight, Printer, PenTool, Undo2 } from "lucide-react";
import { toast } from "sonner";
import { createPortal } from "react-dom";

type Point = { x: number, y: number };
type Stroke = Point[];

export function TestReportViewer() {
  const [patientName, setPatientName] = useState("New Patient");
  const [mrn, setMrn] = useState("Unknown");
  const [reportFiles, setReportFiles] = useState<{name: string, date: string, type: string, status: string, pages: number}[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [mounted, setMounted] = useState(false);
  
  // PDF Viewer State
  const [selectedReport, setSelectedReport] = useState<any>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [zoom, setZoom] = useState(1);
  
  // Drawing State
  const [isDrawingMode, setIsDrawingMode] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [strokes, setStrokes] = useState<Stroke[]>([]);
  const [currentStroke, setCurrentStroke] = useState<Stroke | null>(null);
  
  useEffect(() => {
    setMounted(true);
    const params = new URLSearchParams(window.location.search);
    const pName = params.get('patientName') || "New Patient";
    let rawId = params.get('patientId');
    
    if (!rawId || rawId.includes('-')) {
      const firstLetter = pName.charAt(0).toUpperCase();
      let hash = 0;
      for (let i = 0; i < pName.length; i++) hash = pName.charCodeAt(i) + ((hash << 5) - hash);
      const num = Math.abs(hash).toString().padStart(6, '0');
      rawId = `${firstLetter} ${num.slice(0,2)} ${num.slice(2,4)} ${num.slice(4,6)}`;
    }
    
    setPatientName(pName);
    setMrn(rawId);

    setTimeout(() => {
      setReportFiles([
        { name: "Complete Blood Count (CBC)", date: new Date().toLocaleDateString('en-GB'), type: "Pathology", status: "Verified", pages: 3 },
        { name: "Lipid Profile", date: new Date().toLocaleDateString('en-GB'), type: "Pathology", status: "Verified", pages: 1 },
        { name: "Chest X-Ray (PA View)", date: new Date(Date.now() - 86400000).toLocaleDateString('en-GB'), type: "Radiology", status: "Verified", pages: 2 },
      ]);
      setIsLoading(false);
    }, 1500);
  }, []);
  
  const handleOpenReport = (report: any) => {
    setSelectedReport(report);
    setCurrentPage(1);
    setIsDrawingMode(false);
    setStrokes([]);
  };

  // Re-draw all strokes when strokes array or zoom changes
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    
    const allStrokes = currentStroke ? [...strokes, currentStroke] : strokes;
    
    ctx.strokeStyle = "#ef4444";
    ctx.lineWidth = 2 * zoom;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    
    allStrokes.forEach(stroke => {
      if (stroke.length === 0) return;
      ctx.beginPath();
      ctx.moveTo(stroke[0].x * zoom, stroke[0].y * zoom);
      for (let i = 1; i < stroke.length; i++) {
        ctx.lineTo(stroke[i].x * zoom, stroke[i].y * zoom);
      }
      ctx.stroke();
    });
  }, [strokes, currentStroke, zoom]);

  // Drawing Handlers
  const startDrawing = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!isDrawingMode) return;
    e.preventDefault();
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    const rect = canvas.getBoundingClientRect();
    let clientX, clientY;
    if ('touches' in e) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = (e as React.MouseEvent).clientX;
      clientY = (e as React.MouseEvent).clientY;
    }
    
    const x = (clientX - rect.left) / zoom;
    const y = (clientY - rect.top) / zoom;
    
    setCurrentStroke([{ x, y }]);
    
    // Begin immediate drawing path
    const ctx = canvas.getContext("2d");
    if (ctx) {
      ctx.beginPath();
      ctx.moveTo(x * zoom, y * zoom);
    }
  };

  const draw = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!isDrawingMode || !currentStroke) return;
    e.preventDefault();
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    const rect = canvas.getBoundingClientRect();
    let clientX, clientY;
    if ('touches' in e) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = (e as React.MouseEvent).clientX;
      clientY = (e as React.MouseEvent).clientY;
    }
    
    const x = (clientX - rect.left) / zoom;
    const y = (clientY - rect.top) / zoom;
    
    const newPoint = { x, y };
    setCurrentStroke(prev => prev ? [...prev, newPoint] : [newPoint]);
    
    // Draw immediately to context for 60fps responsiveness
    const ctx = canvas.getContext("2d");
    if (ctx) {
      ctx.lineTo(x * zoom, y * zoom);
      ctx.strokeStyle = "#ef4444";
      ctx.lineWidth = 2 * zoom;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.stroke();
    }
  };

  const endDrawing = () => {
    if (!isDrawingMode || !currentStroke) return;
    if (currentStroke.length > 0) {
      setStrokes(prev => [...prev, currentStroke]);
    }
    setCurrentStroke(null);
  };
  
  const handleUndo = () => {
    if (strokes.length > 0) {
      setStrokes(strokes.slice(0, -1));
    }
  };
  
  const renderViewer = () => {
    return (
      <div className="fixed inset-0 z-[99999] sm:static sm:z-auto flex-1 flex flex-col bg-slate-800 overflow-hidden sm:h-full">
        <div className="bg-slate-900 border-b border-slate-800 p-4 sm:px-6 sm:py-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 shrink-0 shadow-sm z-10 pt-safe-top">
          <div className="flex items-center gap-3 sm:gap-4 w-full sm:w-auto">
            <button 
              onClick={() => setSelectedReport(null)}
              className="w-8 h-8 sm:w-10 sm:h-10 flex items-center justify-center bg-slate-800 text-slate-600 hover:text-slate-900 rounded-full transition-colors shrink-0"
            >
              <ChevronLeft size={18} className="sm:w-[20px] sm:h-[20px]" />
            </button>
            <div className="min-w-0">
              <h2 className="text-[15px] sm:text-[16px] font-bold text-slate-100 flex items-center gap-2 truncate">
                {selectedReport.name}
              </h2>
              <p className="text-[11px] sm:text-[12px] text-slate-500 font-medium truncate mt-0.5">
                {selectedReport.date} • {selectedReport.type}
              </p>
            </div>
          </div>
          
          {/* Controls in Header */}
          <div className="flex items-center justify-between sm:justify-end gap-2 sm:gap-4 w-full sm:w-auto">
            <div className="flex items-center gap-1.5 sm:gap-3 bg-slate-950 p-1 sm:p-1.5 rounded-xl border border-slate-800">
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="w-7 h-7 sm:w-8 sm:h-8 flex items-center justify-center rounded-lg bg-slate-900 shadow-sm border border-slate-800 text-slate-200 disabled:opacity-40 hover:bg-slate-950 transition-colors"
              >
                <ChevronLeft size={14} strokeWidth={3} />
              </button>
              <span className="text-[12px] sm:text-[13px] font-bold text-slate-600 min-w-[60px] sm:min-w-[70px] text-center">
                Page {currentPage} / {selectedReport.pages}
              </span>
              <button 
                onClick={() => setCurrentPage(p => Math.min(selectedReport.pages, p + 1))}
                disabled={currentPage === selectedReport.pages}
                className="w-7 h-7 sm:w-8 sm:h-8 flex items-center justify-center rounded-lg bg-slate-900 shadow-sm border border-slate-800 text-slate-200 disabled:opacity-40 hover:bg-slate-950 transition-colors"
              >
                <ChevronRight size={14} strokeWidth={3} />
              </button>
            </div>
            
            <div className="flex gap-1.5 sm:gap-2 shrink-0">
              {strokes.length > 0 && (
                <button 
                  onClick={handleUndo}
                  className="w-8 h-8 sm:w-10 sm:h-10 flex items-center justify-center text-slate-500 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                  title="Undo Last Mark"
                >
                  <Undo2 size={16} className="sm:w-[18px] sm:h-[18px]" />
                </button>
              )}
              <button 
                onClick={() => {
                  setIsDrawingMode(!isDrawingMode);
                  if (!isDrawingMode) toast.success("Marking Mode Enabled. Draw directly on the report!");
                }}
                className={`w-8 h-8 sm:w-10 sm:h-10 flex items-center justify-center rounded-lg transition-colors ${isDrawingMode ? 'bg-red-100 text-red-600 ring-2 ring-red-400' : 'text-slate-500 hover:text-slate-100 hover:bg-slate-800'}`}
                title="Mark / Annotate"
              >
                <PenTool size={16} className="sm:w-[18px] sm:h-[18px]" />
              </button>
              <button className="w-8 h-8 sm:w-10 sm:h-10 flex items-center justify-center text-slate-500 hover:text-slate-100 hover:bg-slate-800 rounded-lg transition-colors">
                <Printer size={16} className="sm:w-[18px] sm:h-[18px]" />
              </button>
              <button className="w-8 h-8 sm:w-10 sm:h-10 flex items-center justify-center text-slate-500 hover:text-slate-100 hover:bg-slate-800 rounded-lg transition-colors">
                <Download size={16} className="sm:w-[18px] sm:h-[18px]" />
              </button>
            </div>
          </div>
        </div>

        {/* Workspace Area */}
        <div className="flex-1 overflow-y-auto overflow-x-auto bg-slate-200/80 p-4 sm:p-8 custom-scrollbar flex flex-col relative touch-pan-x touch-pan-y">
          {/* Mobile Zoom Controls (Floating at Top Center) */}
          <div className="sticky top-0 left-0 w-full flex justify-center z-40 px-4 pointer-events-none mb-[-56px]">
            <div className="bg-slate-900/60 backdrop-blur-md border border-white/60 shadow-[0_8px_32px_rgba(0,0,0,0.1)] rounded-full px-1.5 py-1.5 flex items-center gap-1 pointer-events-auto">
              <button 
                onClick={() => setZoom(z => Math.max(0.25, z - 0.25))} 
                className="w-10 h-10 rounded-full flex items-center justify-center text-slate-100 hover:text-sky-400 bg-slate-900/40 hover:bg-slate-900/80 active:scale-95 transition-all"
              >
                <span className="text-xl font-bold leading-none -mt-1">-</span>
              </button>
              <span className="text-[13px] font-bold text-slate-900 w-12 text-center select-none drop-shadow-md">
                {Math.round(zoom * 100)}%
              </span>
              <button 
                onClick={() => setZoom(z => Math.min(2.0, z + 0.25))} 
                className="w-10 h-10 rounded-full flex items-center justify-center text-slate-100 hover:text-sky-400 bg-slate-900/40 hover:bg-slate-900/80 active:scale-95 transition-all"
              >
                <span className="text-xl font-bold leading-none -mt-0.5">+</span>
              </button>
            </div>
          </div>

          <div className="flex-1 flex sm:justify-center min-w-max pb-32 w-fit mx-auto pt-10 sm:pt-4">
            {/* The Document Canvas */}
            <div 
              className={`bg-slate-900 shadow-2xl border border-slate-300/80 ring-1 ring-black/5 rounded-md relative overflow-hidden group origin-top-left sm:origin-top transition-transform duration-200 ease-out ${isDrawingMode ? 'cursor-crosshair touch-none' : ''}`}
              style={{ 
                width: `${794 * zoom}px`, 
                height: `${1123 * zoom}px` 
              }}
            >
              {/* Document Content */}
              <div className="absolute inset-0 p-8 sm:p-12 flex flex-col pointer-events-none" style={{ transform: `scale(${zoom})`, transformOrigin: 'top left', width: '794px', height: '1123px' }}>
                <div className="flex justify-between items-start border-b-2 border-slate-800 pb-6 mb-8">
                  <div>
                    <h1 className="text-2xl font-bold uppercase tracking-widest text-slate-900">Lab Report</h1>
                    <p className="text-slate-500 mt-1">{selectedReport.name}</p>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-slate-100">Page {currentPage} / {selectedReport.pages}</p>
                    <p className="text-slate-500">{selectedReport.date}</p>
                    <p className="font-bold text-slate-100 font-mono bg-slate-800 px-2 py-0.5 rounded-md mt-2 inline-block">
                      ID: {mrn}
                    </p>
                  </div>
                </div>
                
                <div className="flex-1 flex flex-col items-center justify-center opacity-40">
                  <FileText size={64} className="text-slate-300 mb-4" />
                  <p className="text-xl font-bold text-slate-500">Mock Data / Visual Demo</p>
                  <p className="text-sm text-slate-500 mt-2">Actual PDF rendering goes here</p>
                </div>
              </div>

              {/* Drawing Layer */}
              <canvas
                ref={canvasRef}
                width={794}
                height={1123}
                className="absolute top-0 left-0"
                style={{ transform: `scale(${zoom})`, transformOrigin: 'top left', pointerEvents: isDrawingMode ? 'auto' : 'none' }}
                onMouseDown={startDrawing}
                onMouseMove={draw}
                onMouseUp={endDrawing}
                onMouseLeave={endDrawing}
                onTouchStart={startDrawing}
                onTouchMove={draw}
                onTouchEnd={endDrawing}
              />
            </div>
          </div>
        </div>

        {/* Bottom floating pagination */}
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-4 bg-slate-900/90 backdrop-blur-md px-4 sm:px-6 py-2 sm:py-3 rounded-2xl shadow-[0_8px_32px_rgba(0,0,0,0.12)] border border-slate-800/50 pb-safe">
          <button 
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="flex items-center gap-1 sm:gap-2 text-[13px] sm:text-[14px] font-bold text-slate-200 hover:text-sky-400 disabled:opacity-40 transition-colors"
          >
            <ChevronLeft size={18} strokeWidth={3} />
            Prev
          </button>
          <div className="w-px h-6 bg-slate-300"></div>
          <span className="text-[12px] sm:text-[14px] font-bold text-slate-100 tracking-wide whitespace-nowrap">
            Page {currentPage} of {selectedReport.pages}
          </span>
          <div className="w-px h-6 bg-slate-300"></div>
          <button 
            onClick={() => setCurrentPage(p => Math.min(selectedReport.pages, p + 1))}
            disabled={currentPage === selectedReport.pages}
            className="flex items-center gap-1 sm:gap-2 text-[13px] sm:text-[14px] font-bold text-slate-200 hover:text-sky-400 disabled:opacity-40 transition-colors"
          >
            Next
            <ChevronRight size={18} strokeWidth={3} />
          </button>
        </div>
      </div>
    );
  };

  if (!mounted) return null;
  
  return (
    <div className="flex flex-col h-auto xl:h-full bg-slate-950 relative border-x border-slate-800">
      
      {/* Header */}
      {!selectedReport && (
        <div className="bg-slate-900 border-b border-slate-800 p-4 sm:p-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shrink-0 transition-all">
          <div>
            <h2 className="text-[18px] sm:text-xl font-bold text-slate-100 flex items-center gap-2">
              <Activity className="text-sky-400" size={20} />
              Lab Test Reports
            </h2>
            <p className="text-[12px] sm:text-sm text-slate-500 mt-1 sm:mt-1.5 leading-relaxed">
              Reports are automatically forwarded by the Lab using Patient ID: <br className="sm:hidden" /><span className="font-bold font-mono text-slate-200 bg-slate-800 px-2 py-0.5 rounded-md mt-1 sm:mt-0 inline-block">{mrn}</span>
            </p>
          </div>
          
          <div className="flex items-center gap-2 bg-[#22C55E]/10 text-[#22C55E] px-3 py-1.5 sm:px-4 sm:py-2 rounded-xl font-bold text-[13px] sm:text-sm shrink-0 self-start md:self-auto">
            <ShieldCheck size={16} className="sm:w-[18px] sm:h-[18px]" />
            Lab Synced
          </div>
        </div>
      )}

      {/* Main Content */}
      {!selectedReport ? (
        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 sm:p-6 pb-24">
          {isLoading ? (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 animate-in fade-in duration-500">
              {[1, 2, 3, 4].map((i) => (
                <div key={i} className="bg-slate-900 p-5 rounded-2xl border border-slate-800 flex flex-col shadow-sm">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-4 w-full">
                      <div className="w-12 h-12 bg-slate-800 rounded-xl animate-pulse shrink-0" />
                      <div className="flex-1 space-y-2">
                        <div className="h-4 bg-slate-800 rounded-md w-3/4 animate-pulse" />
                        <div className="h-3 bg-slate-950 rounded-md w-1/2 animate-pulse" />
                      </div>
                    </div>
                    <div className="w-16 h-6 bg-slate-950 rounded-md animate-pulse shrink-0 ml-4" />
                  </div>
                  <div className="mt-2 pt-4 border-t border-slate-50 flex items-center justify-end gap-2">
                    <div className="w-24 h-9 bg-slate-950 rounded-lg animate-pulse" />
                    <div className="w-32 h-9 bg-blue-50/50 rounded-lg animate-pulse" />
                  </div>
                </div>
              ))}
            </div>
          ) : reportFiles.length === 0 ? (
            <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-center border-2 border-dashed border-slate-300 rounded-2xl bg-slate-900 p-8">
              <div className="w-20 h-20 bg-slate-950 rounded-full flex items-center justify-center mb-6">
                <FileText size={32} className="text-slate-300" />
              </div>
              <h3 className="text-lg font-bold text-slate-200 mb-2">No Reports Available</h3>
              <p className="text-slate-500 max-w-sm">The pathology lab has not synced any reports for Patient ID <strong>{mrn}</strong> yet.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              {reportFiles.map((file, idx) => (
                <div key={idx} className="bg-slate-900 p-5 rounded-2xl shadow-sm border border-slate-800 flex flex-col hover:border-[#2F80ED]/30 transition-colors group cursor-pointer" onClick={() => handleOpenReport(file)}>
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-blue-50 text-sky-400 rounded-xl flex items-center justify-center shrink-0">
                        <FileText size={24} />
                      </div>
                      <div>
                        <h4 className="font-bold text-slate-100 text-[15px]">{file.name}</h4>
                        <p className="text-[13px] text-slate-500 font-medium mt-0.5">{file.type} • {file.date} • {file.pages} {file.pages > 1 ? 'Pages' : 'Page'}</p>
                      </div>
                    </div>
                    <span className="text-[11px] font-bold text-[#22C55E] bg-[#22C55E]/10 px-2.5 py-1 rounded-md tracking-wide uppercase shrink-0">
                      {file.status}
                    </span>
                  </div>
                <div className="mt-4 pt-4 border-t border-slate-800 flex flex-col sm:flex-row items-stretch sm:items-center justify-end gap-2.5 transition-all">
                  <button 
                    onClick={(e) => { e.stopPropagation(); handleOpenReport(file); }}
                    className="flex justify-center items-center gap-2 text-[13px] font-bold text-sky-400 bg-slate-900 border-2 border-[#2F80ED] hover:border-[#2F80ED] hover:bg-sky-600 hover:text-white active:bg-[#256bbd] active:border-[#256bbd] px-4 py-2.5 rounded-lg transition-all duration-300 transform hover:-translate-y-0.5 shadow-sm hover:shadow-[0_4px_12px_rgba(47,128,237,0.3)] active:scale-[0.97]"
                  >
                    <Eye size={16} />
                    View Report
                  </button>
                  <button 
                    onClick={(e) => { e.stopPropagation(); toast.success("AI is analyzing this report..."); }}
                    className="flex justify-center items-center gap-2 text-[13px] font-bold text-white bg-[#795bff] hover:bg-[#684be3] active:bg-[#5b42c4] px-4 py-2.5 rounded-lg shadow-[0_4px_14px_rgba(121,91,255,0.2)] hover:shadow-[0_0_20px_rgba(121,91,255,0.6)] active:shadow-[0_0_25px_rgba(121,91,255,0.8)] transition-all duration-300 transform hover:-translate-y-0.5 active:translate-y-0.5 active:scale-[0.97]"
                  >
                    Analyze with AI
                  </button>
                </div></div>
              ))}
            </div>
          )}
        </div>
      ) : (
        // Mobile Portal vs Desktop Inline
        <div className="hidden sm:flex flex-1 overflow-hidden">
          {renderViewer()}
        </div>
      )}
      
      {/* Mobile Portal for Viewer */}
      {selectedReport && mounted && createPortal(
        <div className="sm:hidden block z-[99999]">
          {renderViewer()}
        </div>,
        document.body
      )}
    </div>
  );
}

import { useAuth } from "@/context/AuthContext";
"use client";

import React, { useState } from "react";
import { Search, Filter, FileText, AlertCircle, CheckCircle2, ChevronRight, Activity, FlaskConical, Stethoscope } from "lucide-react";
import { ReportPreviewPanel } from "./ReportPreviewPanel";

const mockReports = [
