"use client";

import React, { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";

function AnimatedNumber({ value, className }: { value: number; className?: string }) {
  return (
    <div className={cn("flex items-center", className)}>
      <div className="flex relative items-center">
        {value.toString().split("").map((digit, index) => (
          <SingleNumberHolder key={index} value={digit} index={index} />
        ))}
      </div>
    </div>
  );
}

function SingleNumberHolder({ value, index }: { value: string; index: number }) {
  const [height, setHeight] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  let notANumber = false;

  useEffect(() => {
    if (containerRef.current) {
      setHeight(getComputedStyle(containerRef.current).height);
    }
  }, []);

  if (index === 0) {
    notANumber = isNaN(Number.parseInt(value));
  }

  const vars = {
    init: { opacity: 0 },
    animate: { opacity: 1 },
    exit: { opacity: 0 },
  };

  return (
    <div
      className="relative"
      style={{ height: height || "auto", overflowY: "hidden", overflowX: "clip" }}
      ref={containerRef}
    >
      {notANumber && (
        <motion.span
          initial="init"
          animate="animate"
          exit="exit"
          variants={vars}
          key={value}
          layout="size"
        >
          {value}
        </motion.span>
      )}
      {!notANumber && <RenderStrip value={value} eleHeight={height} />}
    </div>
  );
}

const zeroToNine = Array.from({ length: 10 }, (_, k) => k);

function RenderStrip({ eleHeight, value }: { eleHeight: string | null; value: string }) {
  const heightInNumber = Number.parseInt(eleHeight?.replace("px", "") || "48");
  const negative = heightInNumber * -1;
  const pos = heightInNumber;
  const prev = useRef(value);

  const currentVal = parseInt(value);
  const prevVal = parseInt(prev.current);

  const diff = prevVal - currentVal;
  const dir = currentVal > prevVal ? pos * diff * -1 : negative * diff;

  useEffect(() => {
    prev.current = value;
  }, [value]);

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={value}
        initial={{ y: dir }}
        animate={{ y: 0 }}
        exit={{ y: 0, transition: { duration: 0.1 } }}
        transition={{ duration: 0.5, ease: "easeOut" }}
        className="flex relative flex-col"
      >
        <motion.span
          layout
          key={`negative-${value}`}
          className={cn("flex flex-col items-center absolute bottom-full left-0")}
        >
          {zeroToNine.filter(val => val < currentVal).map((val, idx) => (
            <span key={`${val}_${idx}`}>{val}</span>
          ))}
        </motion.span>

        <span key={`current-${value}`}>{value}</span>

        <motion.span
          layout
          key={`positive-${value}`}
          className={cn("flex flex-col items-center absolute top-full left-0")}
        >
          {zeroToNine.filter(val => val > currentVal).map((val, idx) => (
            <span key={`${val}_${idx}`}>{val}</span>
          ))}
        </motion.span>
      </motion.div>
    </AnimatePresence>
  );
}

function AnimatedScore({ value, duration = 0.2, className }: { value: number; duration?: number; className?: string }) {
  const prevValueRef = useRef(value);

  useEffect(() => {
    prevValueRef.current = value;
  }, [value]);

  const colors = {
    negative: "#10B981",
    positive: "#F43F5E",
    neutral: "#0F172A"
  };

  const transforVal = 80;
  const forwards = {
    init: { y: transforVal * -1, opacity: 0, scale: 0.5, color: colors.negative },
    animate: {
      y: 0,
      opacity: 1,
      scale: [1.7, 1],
      color: [colors.negative, colors.negative, colors.neutral],
      transition: { duration: 0.4, times: [0, 0.7, 1], color: { times: [0, 0.75, 0.9] } },
    },
    exit: {
      y: transforVal,
      opacity: 0,
      scale: 0.5,
      color: colors.positive
    },
  };

  const backwards = {
    init: { y: transforVal, opacity: 0, scale: 0.5, color: colors.positive },
    animate: {
      y: 0,
      opacity: 1,
      scale: [1.7, 1],
      color: [colors.positive, colors.positive, colors.neutral],
      transition: { duration: 0.4, times: [0, 0.7, 1], color: { times: [0, 0.75, 0.9] } },
    },
    exit: {
      y: transforVal * -1,
      opacity: 0,
      scale: 0.5,
      color: colors.negative
    }
  };

  const variants = value >= prevValueRef.current ? forwards : backwards;
  const direction = value >= prevValueRef.current ? "forwards" : "backwards";

  return (
    <div className={cn("relative flex justify-center items-center py-1 px-2 w-full rounded-md", className)}>
      <motion.div layout="size" className="w-fit flex justify-center items-center">
        {value.toString().split("").map((number, index) => (
          <ScoreContainer
            direction={direction}
            duration={duration}
            variants={variants}
            number={number}
            key={index}
          />
        ))}
      </motion.div>
    </div>
  );
}

function ScoreContainer({ number, variants, duration = 0.7, direction }: {
  number: string;
  variants: any;
  duration?: number;
  direction: string;
}) {
  const cached = React.useMemo(() => (
    <div className="relative">
      <AnimatePresence mode="popLayout">
        <motion.div
          animate="animate"
          className="flex justify-center items-center"
          initial="init"
          exit="exit"
          variants={variants}
          key={number.toString()}
          layout="size"
          transition={{ duration, ease: "backInOut" }}
        >
          {number}
        </motion.div>
      </AnimatePresence>
    </div>
  ), [number, direction, variants, duration]);

  return <React.Fragment>{cached}</React.Fragment>;
}

export { AnimatedNumber, AnimatedScore };

"use client";

import React, { createContext, useContext, useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";
import type { User } from "@supabase/supabase-js";

export type UserRole = "patient" | "doctor" | "hospital" | "admin" | "assistant" | null;

export interface AppUser {
  id: string;
  name: string;
  role: UserRole;
  email: string;
  phone?: string;
  date_of_birth?: string;
  gender?: string;
  blood_group?: string;
  address?: string;
  image?: string;
  assistantId?: string;
  doctorId?: string;
}

interface AuthContextType {
  user: AppUser | null;
  role: UserRole;
  isAuthenticated: boolean;
  login: (userData: AppUser) => void;
  logout: () => void;
  updateUser: (userData: AppUser) => void;
  isLoading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<AppUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Initialize from localStorage and check 30-day session expiry
  useEffect(() => {
    try {
      const savedUser = localStorage.getItem("oxpecker_mock_user");
      const lastActivity = localStorage.getItem("oxpecker_last_activity");

      if (savedUser && lastActivity) {
        const THIRTY_DAYS_IN_MS = 30 * 24 * 60 * 60 * 1000;
        const timeSinceLastActivity = Date.now() - parseInt(lastActivity, 10);

        if (timeSinceLastActivity > THIRTY_DAYS_IN_MS) {
          // Session expired due to 30 days of inactivity
          console.log("Session expired. Auto-logging out.");
          localStorage.removeItem("oxpecker_mock_user");
          localStorage.removeItem("oxpecker_last_activity");
          setUser(null);
        } else {
          // Session valid, refresh the activity timer
          setUser(JSON.parse(savedUser));
          localStorage.setItem("oxpecker_last_activity", Date.now().toString());
        }
      }
    } catch (e) {
      console.error("Auth init error:", e);
    } finally {
      setIsLoading(false);
    }
  }, []);
  const router = useRouter();

  const login = (userData: AppUser) => {
    setUser(userData);
    localStorage.setItem("oxpecker_mock_user", JSON.stringify(userData));
    localStorage.setItem("oxpecker_last_activity", Date.now().toString());

    const redirectUrl = typeof window !== "undefined" ? sessionStorage.getItem("redirect_after_login") : null;
    if (redirectUrl) {
      sessionStorage.removeItem("redirect_after_login");
      router.push(redirectUrl);
      return;
    }

    if (userData.role === "doctor") {
      router.push("/doctor/dashboard");
    } else if (userData.role === "hospital") {
      router.push("/hospital/dashboard");
    } else if (userData.role === "assistant") {
      router.push("/assistant");
    } else if (userData.role === "admin") {
      router.push("/admin/dashboard");
    } else {
      router.push("/chat");
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem("oxpecker_mock_user");
    localStorage.removeItem("oxpecker_last_activity");
    router.push("/login");
  };

  const updateUser = (userData: AppUser) => {
    setUser(userData);
    localStorage.setItem("oxpecker_mock_user", JSON.stringify(userData));
    localStorage.setItem("oxpecker_last_activity", Date.now().toString());
  };

  return (
    <AuthContext.Provider value={{ user, role: user?.role || null, isAuthenticated: !!user, login, logout, updateUser, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) throw new Error("useAuth must be used within an AuthProvider");
  return context;
}

